window.__SUM[7]={"LR010943":{"pair":"ACE2 -> SLC6A19","headline":"ACE2 and the transporter B0AT1 form a cryo-EM complex; this is a structural partnership, not a signalling ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"No ligand-to-receptor direction is reported; the structure shows a complex, not signalling [PMID:32132184].","molecular_requirements":"The ACE2-B0AT1 complex is a dimer of heterodimers, with the collectrin-like domain of ACE2 mediating homodimerization [PMID:32132184].","affinity_potency":[],"species_and_systems":"Full-length human ACE2 with the transporter, cryo-EM at an overall resolution of 2.9 angstroms [PMID:32132184].","localisation_and_range":"ACE2 is flagged as a receptor [flag]; the complex is a membrane assembly per the structure.","caveats":"One paper, abstract only, mainly about the SARS-CoV-2 RBD. Many records: BioGRID co-crystal, reconstituted complex and other assays [DB:BioGRID], IntAct EM and co-IP [DB:IntAct], and PDB entries such as [DB:PDB 6M17]. Two other judged rows were abstract-insufficient and three were different-entity.","key_references":[{"PMID":"32132184","why":"Cryo-EM structure of the ACE2-B0AT1 complex"}],"covers":["LR010943"]},"LR005390":{"pair":"ADA -> DPP4","headline":"ADA binds DPP4 directly, shown by a 3.0 angstrom crystal structure; DPP4 acts as ADA receptor in T-cell co-stimulation.","interaction_type":"direct binding","direction_and_effect":"DPPIV acts as a receptor for ADA, mediating co-stimulatory signals in T-lymphocytes [PMID:15213224]. ADA binding could regulate adhesion by abolishing DPPIV tetramerization [PMID:15213224]. UniProt: positive regulator of T-cell coactivation by binding DPP4 [DB:UniProt].","molecular_requirements":"Each beta-propeller domain of the DPPIV dimer binds one ADA; two hydrophobic loops of DPPIV contact charged alpha-helices of ADA, and four N-glycans at Asn229 of DPPIV also contact ADA [PMID:15213224]. UniProt lists the DPP4 extracellular domain as the interaction region [DB:UniProt].","affinity_potency":[],"species_and_systems":"Crystal of human DPPIV with bovine ADA [PMID:15213224]; the human and mouse pairs are ortholog-inferred.","localisation_and_range":"ADA is flagged not secreted and DPP4 transmembrane [flag]; DPPIV is a type II membrane glycoprotein [PMID:15213224].","caveats":"Structure used bovine ADA; the paper is abstract only. Also BioGRID affinity capture-western [DB:BioGRID]. UniProt says its interaction with DPP4 regulates lymphocyte-epithelial adhesion [DB:UniProt].","key_references":[{"PMID":"15213224","why":"Co-crystal structure of human DPPIV with bovine ADA"}],"covers":["LR002064","LR005390"]},"LR003554":{"pair":"ADAM12 -> ITGA9","headline":"Recombinant ADAM-12 disintegrin domain binds integrin alpha9beta1 and supports cell-cell interaction, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520]. The interaction supports cell adhesion and cell-cell interaction [PMID:10944520].","molecular_requirements":"The receptor is the alpha9beta1 heterodimer; the alpha9 chain alone is not tested in the abstract. Cation requirement and activation status resemble integrin-matrix interactions [PMID:10944520].","affinity_potency":[],"species_and_systems":"Recombinant disintegrin domains; species not reported in our evidence.","localisation_and_range":"ADAM12 is flagged secreted [flag]; the paper describes cell-cell adhesion [PMID:10944520].","caveats":"One paper, abstract only; species not recorded.","key_references":[{"PMID":"10944520","why":"RGD-independent binding of alpha9beta1 to ADAM-12 and -15 disintegrin domains"}],"covers":["LR000004","LR003554"]},"LR002069":{"pair":"ADAM17 -> ITGA6","headline":"Co-immunoprecipitation in mouse cells shows integrins alpha6 and beta1 bind ADAM17/TACE via its disintegrin domain; abstract read only.","interaction_type":"direct binding","direction_and_effect":"Integrins alpha6 and beta1 bind TACE (ADAM17) via the disintegrin domain, and mechanical strain enhances the interaction; force on these integrins activates TACE and sheds HB-EGF and TGF-alpha [PMID:23888051].","molecular_requirements":"Binding is via the ADAM17 disintegrin domain; alpha6 and beta1 are both implicated, so the heterodimer alpha6beta1 is the likely unit [PMID:23888051].","affinity_potency":[],"species_and_systems":"Fetal epithelial cells, wild-type and TACE knock-out cells (mouse knock-out cells noted) with TACE constructs [PMID:23888051]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"ADAM17 is flagged non-secreted [flag]; contact/cis interaction at the cell surface.","caveats":"Abstract read only. Direction is the integrin acting on ADAM17 sheddase activity, rather than classic ligand signalling.","key_references":[{"PMID":"23888051","why":"Integrins alpha6/beta1 bind TACE disintegrin domain; strain enhances"}],"covers":["LR002069","LR005395"]},"LR003563":{"pair":"ADAM17 -> ITGB1","headline":"Two abstract-only papers support ADAM17 interaction with beta1 integrins (alpha6beta1 by co-IP, alpha5beta1 by adhesion); IntAct has records.","interaction_type":"direct binding","direction_and_effect":"Integrins alpha6 and beta1 bind TACE (ADAM17) through its disintegrin domain, enhanced by mechanical strain [PMID:23888051]. ADAM-17 fragments also support alpha5beta1-mediated adhesion, RGD and EDTA sensitive [PMID:14970227].","molecular_requirements":"ITGB1 acts together with alpha subunits (alpha6 or alpha5) in these results; beta1 alone is not shown to suffice [PMID:23888051][PMID:14970227].","affinity_potency":[],"species_and_systems":"Co-IP in wild-type and TACE knock-out cells [PMID:23888051]; human recombinant fragments with HeLa cells [PMID:14970227].","localisation_and_range":"ADAM17 is flagged non-secreted [flag]; trans adhesion and cis co-localisation both reported [PMID:14970227].","caveats":"Both papers read as abstracts only. IntAct records (co-IP, ELISA) list ADAM17 with ITGB1 [DB:IntAct].","key_references":[{"PMID":"23888051","why":"Co-IP: alpha6/beta1 bind TACE via disintegrin domain"},{"PMID":"14970227","why":"ADAM-17 adhesion via alpha5beta1"}],"covers":["LR000013","LR003563"]},"LR001628":{"pair":"ADAM23 -> ITGA4","headline":"Human ADAM23 supports integrin alpha4-dependent cell adhesion; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Human ADAM11, ADAM23 and ADAM29 selectively support integrin alpha4-dependent cell adhesion; the disintegrin-like domains of these catalytically inactive ADAMs are ligands [PMID:28913673].","molecular_requirements":"Dependent on alpha4; partner beta chain not stated in our abstract [PMID:28913673].","affinity_potency":[],"species_and_systems":"Human proteins; integrin binding assays with cell adhesion [PMID:28913673]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM23 is flagged secreted and receptor [flag].","caveats":"Abstract read only (evidence sentence is truncated). The paper states ADAMs 'selectively support' adhesion, not affinity.","key_references":[{"PMID":"28913673","why":"Non-catalytic ADAMs incl. ADAM23 are integrin alpha4 ligands"}],"covers":["LR001628","LR005016"]},"LR003572":{"pair":"ADAM9 -> ITGA6","headline":"Murine meltrin gamma (ADAM9) binds integrin alpha6beta1 on human fibroblast lines and drives motility; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"A murine meltrin gamma-Fc fusion binds alpha6beta1 on HT1080 and Wehi 164 cells in solid-phase and antibody-inhibition experiments, and cells on it showed an eight- to tenfold increase in motility compared with laminin [PMID:10825303]. GST-disintegrin also recovered alpha6 from renal lysate [PMID:15361064].","molecular_requirements":"Alpha6 acts as alpha6beta1; binding through the ADAM9 disintegrin domain [PMID:10825303][PMID:15361064].","affinity_potency":[],"species_and_systems":"Mouse ligand fusion with human receptor-bearing cell lines [PMID:10825303]; human recombinant and renal lysate [PMID:15361064]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM9 flagged secreted [flag]; the papers use membrane-anchored ADAM9 and recombinant domains.","caveats":"Both abstract only. One further paper was abstract_insufficient and not shown.","key_references":[{"PMID":"10825303","why":"Meltrin gamma-Fc binds alpha6beta1, increases motility"},{"PMID":"15361064","why":"GST-disintegrin recovers alpha6"}],"covers":["LR000022","LR003572"]},"LR002078":{"pair":"ADGRE5 -> THY1","headline":"CD97 (ADGRE5) binds Thy-1 in adhesion and protein-binding assays (one paper, abstract only).","interaction_type":"direct binding","direction_and_effect":"CD97-expressing cells adhered to Thy-1 on activated dermal endothelial cells, Thy-1 CHO cells and immobilized Thy-1; soluble CD97 bound immobilized Thy-1 [PMID:22210915]. Adhesion was partly blocked by CD97 and Thy-1 antibodies [PMID:22210915].","molecular_requirements":"The CD97 stalk is implicated: stalk antibody blocked more strongly than EGF-domain antibody, binding was calcium independent, and CD97 without stalk or EMR2 failed to bind [PMID:22210915].","affinity_potency":[],"species_and_systems":"Human cells and recombinant proteins; CD97 upregulated on neutrophils of psoriasis patients [PMID:22210915].","localisation_and_range":"Thy-1 is on endothelial cells, so contact-mediated leukocyte-endothelium adhesion [PMID:22210915]. Thy-1 is annotated transmembrane [flag].","caveats":"One paper, abstract only; antibody blocking was partial; no affinity reported [PMID:22210915].","key_references":[{"PMID":"22210915","why":"adhesion and binding assays with stalk mapping"}],"covers":["LR002078","LR005404"]},"LR005408":{"pair":"ADGRL1 -> NRXN3","headline":"Latrophilin-1 ectodomain binds neurexins with nanomolar affinity; evidence is one abstract-only paper that covers neurexins as a group.","interaction_type":"direct binding","direction_and_effect":"Direct binding between the extracellular domains of latrophilin-1 (CL1) and neurexins; CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing both formed stable adhesion, so trans-cellular [PMID:22262843].","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1; those with an SS4 insert do not. The olfactomedin-like domain of CL1 mediates binding [PMID:22262843].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"saturation binding","system":"purified ectodomains","cite":"PMID:22262843"}],"species_and_systems":"Purified ectodomains and cell adhesion assays; species not stated beyond curator label human [PMID:22262843]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both partners are membrane proteins [flag]; interaction is trans-cellular, suggesting juxtacrine signalling [PMID:22262843].","caveats":"Abstract only, and the abstract speaks of neurexins generally, so isoform specificity for NRXN3 is not shown in our evidence. Only the SS4-minus form binds [PMID:22262843]. Ligand-receptor direction is not defined, as both are membrane proteins.","key_references":[{"PMID":"22262843","why":"identifies latrophilin-1/neurexin binding"}],"covers":["LR002082","LR005408"]},"LR003581":{"pair":"ADIPOQ -> ADIPOR2","headline":"AdipoR2 was expression-cloned as an adiponectin receptor; one abstract-only paper plus Reactome and UniProt records.","interaction_type":"direct binding","direction_and_effect":"AdipoR1/R2 overexpression or siRNA suppression supports a role as receptors for globular and full-length adiponectin, mediating increased AMP kinase and PPAR-alpha ligand activities, fatty-acid oxidation and glucose uptake [PMID:12802337]. Activating effect.","molecular_requirements":"Reactome lists an ADIPOQ trimer bound to ADIPOR dimers [DB:Reactome]. Whether one receptor chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cDNAs and cells per curator label [PMID:12802337]. Mouse pair is non-inferred, human pair is ortholog-inferred.","localisation_and_range":"Adiponectin is flagged secreted [flag], so hormonal/endocrine action is implied; the receptor is plasma membrane per Reactome [DB:Reactome].","caveats":"Evidence is functional (gain and loss of function), not a direct binding measurement, in the abstract [PMID:12802337]. Paper covers both AdipoR1 and AdipoR2, not separated. No affinity reported. One further judged row was classed as a different entity.","key_references":[{"PMID":"12802337","why":"expression cloning of AdipoR1 and AdipoR2"}],"covers":["LR000031","LR003581"]},"LR011690":{"pair":"ADM -> CALCRL:GPER1:RAMP3","headline":"No paper evidence for a CALCRL:GPER1:RAMP3 complex; database records cover CALCRL:RAMP3 only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists ADM as full agonist at ADM-CALCRL and ADM-RAMP3 (pKi 8.3 to 9.0) [DB:GtoPdb]. A cryoEM structure of the AM2 receptor G protein complex with adrenomedullin exists [DB:PDB 6UUS]. UniProt says CALCRL with RAMP3 forms a receptor for ADM and intermedin [DB:UniProt].","molecular_requirements":"A role for GPER1 in the complex is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated in our evidence.","localisation_and_range":"ADM flagged secreted [flag].","caveats":"Both judged rows were different_entity. The GPER1 member is unsupported by any record shown.","key_references":[],"covers":["LR011690"]},"LR002087":{"pair":"ADM -> RAMP1","headline":"Evidence is for AM2/IMD binding RAMP-CLR complexes, not adrenomedullin; RAMP1 is a CLR co-receptor, not a stand-alone receptor.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound purified RAMP1-, RAMP2- and RAMP3-CLR ECD complexes, preferring the CGRP and AM2 receptor complexes; a 2.05 Angstrom crystal structure of an RAMP1-CLR ECD with an AM2/IMD antagonist fragment was solved [PMID:30139742]. GtoPdb lists ADM as full agonist at RAMP1 [DB:GtoPdb].","molecular_requirements":"RAMP1 acts only paired with CLR; RAMP1:CLR favours CGRP, RAMP2/RAMP3 favour AM [PMID:30139742].","affinity_potency":[],"species_and_systems":"Purified ECD complexes; species human per curator label [PMID:30139742].","localisation_and_range":"ADM flagged secreted [flag].","caveats":"The paper's own finding is about AM2/IMD, not ADM. For ADM, RAMP1:CLR is the CGRP-preferring receptor, so this pair is weak. Abstract only.","key_references":[{"PMID":"30139742","why":"RAMP-CLR ECD structure and AM2/IMD binding"}],"covers":["LR002087","LR005413"]},"LR001637":{"pair":"ADM2 -> RAMP2","headline":"ADM2 binds RAMP-CLR extracellular complexes including the RAMP2 one; RAMP2 acts with CLR, evidence is one abstract plus database records.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound all three purified RAMP-CLR ECD complexes with a selectivity profile distinct from CGRP and AM [PMID:30139742]. GtoPdb lists a full agonist [DB:GtoPdb]. Reactome records the adrenomedullin receptor binding adrenomedullin and intermedin [DB:Reactome R-HSA-420214].","molecular_requirements":"RAMP2 with CLR; the RAMP1 and RAMP3 complexes were preferred over RAMP2 [PMID:30139742].","affinity_potency":[{"value":"pEC50 7.5-8.3","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Purified recombinant ECD complexes; curators annotate human ligand and receptor. Mouse pair projected from human.","localisation_and_range":"RAMP2 is flagged receptor [flag]; ADM2 flagged secreted [flag].","caveats":"Abstract-only. The crystal structure was with RAMP1, not RAMP2. Three review_only, one abstract_insufficient and one different_entity paper are not shown.","key_references":[{"PMID":"30139742","why":"AM2/IMD binding across RAMP-CLR ECD complexes"}],"covers":["LR001637","LR005025"]},"LR005417":{"pair":"AGRN -> ITGAV","headline":"One 1997 abstract-only paper implicates alpha-v integrin in agrin signalling and adhesion; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Agrin-induced acetylcholine receptor aggregation on cultured myotubes was partially blocked by antibodies to the alpha(v) subunit, and inhibited by alpha(v) antisense oligonucleotides and an alpha(v) binding-site-blocking peptide [PMID:9367446]. Alpha(v)-negative cells did not adhere to agrin but became adherent when alpha(v) was introduced [PMID:9367446]. The curator labels the effect as agonist.","molecular_requirements":"The cells expressing alpha(v) and beta1 adhered to agrin; the authors implicate alpha(v)beta1 as a component or modulator of agrin signalling [PMID:9367446]. Beta1 antibodies blocked completely, alpha(v) only partially [PMID:9367446].","affinity_potency":[],"species_and_systems":"Species not specified in the abstract (curation tags human/human, but the experiments use cultured myotubes and non-muscle cells) [PMID:9367446].","localisation_and_range":"Agrin is described as a basal lamina-associated proteoglycan [PMID:9367446].","caveats":"Abstract read only. The paper says integrins are 'components or modulators' of the pathway, so it is not clear that agrin is a direct ligand of alpha-v. The pair is given as alpha-v alone while the evidence points to alpha-v with beta1. No affinity reported.","key_references":[{"PMID":"9367446","why":"Antibody, antisense and gain-of-function evidence for alpha-v in agrin adhesion and signalling"}],"covers":["LR002091","LR005417"]},"LR003590":{"pair":"AGRN -> MUSK","headline":"Agrin acts via a receptor complex containing MuSK; one 1996 abstract plus database records, with an accessory component required.","interaction_type":"functional only","direction_and_effect":"Agrin acts via a receptor complex that includes MuSK as well as a myotube-specific accessory component [PMID:8653787]. Database records say agrin-LRP4 induces phosphorylation and activation of MUSK [DB:UniProt]. Effect stimulatory.","molecular_requirements":"MuSK alone is not the whole receptor: a myotube-specific accessory component is needed [PMID:8653787]. Reactome and PDB 8S9P show an agrin/LRP4/MuSK complex [DB:Reactome] [DB:PDB 8S9P].","affinity_potency":[],"species_and_systems":"Species not stated in the abstract; curation tags human/human [PMID:8653787]. Both pair entries are ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only evidence; the evidence is for a complex, and the accessory component is unnamed in this paper. No affinity reported.","key_references":[{"PMID":"8653787","why":"Shows agrin acts via a MuSK-containing receptor complex with an accessory component"}],"covers":["LR000040","LR003590"]},"LR002096":{"pair":"AGRP -> SDC1","headline":"Syndecan-1 is reported to potentiate AGRP action via heparan sulfate chains in transgenic mice; modulation, not a signalling receptor.","interaction_type":"functional only","direction_and_effect":"Transgenic hypothalamic syndecan-1 expression produced hyperphagia and maturity-onset obesity resembling reduced alpha-MSH action; via their HS chains syndecans potentiate the action of agouti-related protein and agouti signaling protein, endogenous inhibitors of alphaMSH [PMID:11461706].","molecular_requirements":"Heparan sulfate chains are required for the potentiation [PMID:11461706]. No direct binding to AGRP is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo transgenics [PMID:11461706]. Human pair is ortholog-inferred; mouse is not.","localisation_and_range":"SDC1 is flagged secreted and transmembrane [flag]; the effect is in the hypothalamus [PMID:11461706].","caveats":"Abstract-only. The SDC1 evidence is ectopic transgenic overexpression; the physiological syndecan in hypothalamus is syndecan-3 [PMID:11461706]. Syndecans are modulators rather than receptors that transduce an AGRP signal.","key_references":[{"PMID":"11461706","why":"Hypothalamic syndecan-1 transgene causes hyperphagia and obesity; syndecans potentiate AGRP"}],"covers":["LR002096","LR005422"]},"LR001646":{"pair":"ALKAL2 -> ALK","headline":"ALKAL2 is a high-affinity agonist ligand of ALK, supported by binding, activation and structural papers in human systems.","interaction_type":"direct binding","direction_and_effect":"ALKAL2 (FAM150B) binds ALK with high affinity and activates it in cells with subnanomolar potency [PMID:26630010]. ALKAL1 and ALKAL2 both activate ALK-dependent proliferation, but only ALKAL2 potently activates ALK [PMID:34646012]. FAM150A/B bind the ALK extracellular domain and also 'superactivate' neuroblastoma-derived activated ALK mutants [PMID:26418745].","molecular_requirements":"ALK ectodomain TNF-like plus glycine-rich (TG) region contacts ALKAL2; ALKAL2 uses an amphipathic patch on the ALK TNF-like subdomain (Ser758, Thr967, Leu970, Val972) [PMID:34646012]. ALK-ALKAL1/2 complexes were 1:1, not the canonical 2:2 [PMID:34646012]. ALKAL2 charge-reversal site 1 mutants markedly reduced affinity [PMID:34646012]. Glycosaminoglycan binding to its HBD is described as an additional regulation, as background [PMID:34646012].","affinity_potency":[],"species_and_systems":"Human proteins. Purified human ALK fragments for crystals; PC12 cell neurite outgrowth and ALK phosphorylation with FAM150A/B [PMID:26418745]; NIH/3T3 and Ba/F3 cell assays [PMID:26630010]. Mouse pair inferred by orthology.","localisation_and_range":"ALKAL2 is flagged secreted and ALK transmembrane [flag]; Reactome shows the ALK dimer:ALKAL2 complex at the plasma membrane [DB:Reactome].","caveats":"[PMID:26630010] was read as abstract only; the 'subnanomolar' potency has no numeric value in our evidence. Several PDB structures and IntAct co-IP are recorded [DB:PDB 7LS0] [DB:IntAct].","key_references":[{"PMID":"26630010","why":"First identification of ALKAL2 as high-affinity ALK ligand"},{"PMID":"26418745","why":"FAM150A/B bind and activate ALK, including mutants"},{"PMID":"34646012","why":"Crystal structure of ALK-ALKAL2 and stoichiometry"}],"covers":["LR001646","LR005034"]},"LR007352":{"pair":"AMH -> AMHR2:BMPR1B","headline":"No curated paper evidence; supported only by database records for AMH-AMHR2 and AMH-BMPR1B.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists AMH-AMHR2 and AMH-BMPR1B as agonist interactions [DB:GtoPdb]. UniProt says AMH binds and activates AMHR2, which pairs with type I receptors (ACVR1 and BMPR1A) [DB:UniProt]; BMPR1B is not named there.","molecular_requirements":"AMHR2 is the type II chain; BMPR1B as the type I partner rests only on the GtoPdb record [DB:GtoPdb]. Whether AMHR2 together with BMPR1B is required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; a PDB structure (7L0J) contains one AMH chain and one AMHR2 chain, not BMPR1B [DB:PDB 7L0J]. No experiment species reported for BMPR1B.","localisation_and_range":"AMH is flagged as secreted and the receptor complex as transmembrane [flag].","caveats":"No papers were judged for this pair; the one other row is review-only. Reactome and IntAct records concern AMH with AMHR2, not BMPR1B [DB:Reactome][DB:IntAct]. The complex's type I chain is database-asserted.","key_references":[],"covers":["LR007352"]},"LR010754":{"pair":"AMH -> BMPR1B","headline":"Only a zebrafish abstract reports Amh binding Bmpr2a/Bmpr1bb; weak support for the human pair.","interaction_type":"functional only","direction_and_effect":"In zebrafish, Amh binds Bmpr2a/Bmpr1bb, which activate Smad1/5/9 by phosphorylation and promote circadian gene expression [PMID:40348785]. GtoPdb lists AMH-BMPR1B as an agonist interaction [DB:GtoPdb].","molecular_requirements":"Bmpr2a (type II) and Bmpr1bb (type I) are named together; bmpr2a knockout abolished the Amh effect on clock gene expression [PMID:40348785]. Whether BMPR1B alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Zebrafish pituitary [PMID:40348785]; no human or mammalian experiment in our evidence.","localisation_and_range":"AMH is flagged as secreted [flag]; BMPR1B has no transmembrane flag in this record.","caveats":"Abstract only. The zebrafish genes are paralogs (bmpr1bb) of the human gene, and the result is a signalling readout, not a direct binding measurement. The sentence does not isolate Bmpr1bb from Bmpr2a.","key_references":[{"PMID":"40348785","why":"Zebrafish Amh signalling via Bmpr2a/Bmpr1bb and Smad1/5/9"}],"covers":["LR010754"]},"LR005426":{"pair":"ANG -> EGFR","headline":"Direct binding of ANG to EGFR with a measured Kd, activating EGFR, from one study in human cells.","interaction_type":"direct binding","direction_and_effect":"ANG acts as an EGFR agonist: it induced EGFR phosphorylation, downstream signalling and EGFR dimerization, and cetuximab or erlotinib/gefitinib blocked ANG-mediated activation [PMID:29606349].","molecular_requirements":"Purified ANG formed a complex with recombinant EGFR in cross-linking assays. ANG C-terminus (residues 74-123) and Q93 are needed for binding; EGFR domains I and III are involved, and the epitope partly overlaps the EGF binding region. Binding is independent of ANG catalytic activity [PMID:29606349].","affinity_potency":[{"value":"Kd 41.6 nM","assay":"binding of ANG to EGFR (estimated Kd)","system":"human ANG and EGFR","cite":"PMID:29606349"}],"species_and_systems":"Human ANG and human EGFR; cell lines and recombinant protein [PMID:29606349]. The mouse pair is projected from human evidence.","localisation_and_range":"ANG is flagged as secreted and EGFR as transmembrane [flag]; ANG binds the EGFR extracellular domain [PMID:29606349].","caveats":"Single paper; the curator read the abstract and full-text excerpts. The paper says a co-crystal structure is still worth pursuing, so no structural proof of contact [PMID:29606349]. No databases support this pair. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"29606349","why":"ANG binds and activates EGFR; Kd, binding determinants"}],"covers":["LR002100","LR005426"]},"LR003608":{"pair":"ANGPTL4 -> TEK","headline":"ANGPTL4 binds the TEK (Tie2) receptor and acts as an agonist; supported by binding data, functional data and several databases.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 (angiopoietin-4) bound Tie2 in binding assays, and Tie1 was not bound [PMID:10051567]. Recombinant Ang4 at 400 ng/mL markedly increased Tie2 and Akt phosphorylation in primary human umbilical vein endothelial cells (HUVECs) and induced survival and migration, so it acts as an agonist [PMID:15284220].","molecular_requirements":"Not reported in our evidence beyond Tie2 itself; recombinant Ang3 and Ang4 formed disulfide-linked dimers [PMID:15284220].","affinity_potency":[],"species_and_systems":"Human ANGPTL4 on human endothelial cells (HUVECs). Its mouse counterpart Ang3 acted mainly on mouse endothelium, so activity is species-restricted [PMID:15284220]. The mouse pair here is projected from human evidence.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag]; this implies paracrine signalling onto endothelial cells.","caveats":"Both papers were read as abstracts in our record; the first paper's evidence sentence is a browser-read quote still awaiting spot-check. No affinity is reported in our evidence. GtoPdb lists the pair without action or affinity [DB:GtoPdb]. Also recorded in BioGRID, IntAct (pull down), Reactome and UniProt [DB:BioGRID] [DB:IntAct] [DB:Reactome] [DB:UniProt].","key_references":[{"PMID":"10051567","why":"Binding of angiopoietin-4 to Tie2 but not Tie1"},{"PMID":"15284220","why":"Ang4 drives Tie2 and Akt phosphorylation in HUVECs"}],"covers":["LR000058","LR003608"]},"LR005039":{"pair":"ANGPTL2 -> ITGA5","headline":"ANGPTL2 is associated with integrin alpha5beta1 by co-IP and linked functionally to it; no direct binding assay shown.","interaction_type":"functional only","direction_and_effect":"ANGPTL2 and integrin alpha5beta1 associated by co-immunoprecipitation and co-localization under overexpression [PMID:42609534]. In chondrocytes, changing ANGPTL2 expression altered p38 MAPK activity mediated by integrin alpha5beta1 [PMID:29074299].","molecular_requirements":"The evidence concerns the alpha5beta1 heterodimer; ITGA5 alone is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Human retinal microvascular endothelial cells (HRMECs) and diabetic rat retina [PMID:42609534]; mouse ATDC5 chondrogenic cells and Angptl2 knockout mice [PMID:29074299].","localisation_and_range":"Ligand flagged secreted [flag]; ANGPTL2 also accumulates in cartilage extracellular matrix [PMID:29074299].","caveats":"The first paper was read as an abstract and its association was under overexpression conditions only; the second is a functional readout, not binding. No affinity reported. Three further papers were abstract_insufficient.","key_references":[{"PMID":"42609534","why":"Co-IP and co-localization of ANGPTL2 with integrin alpha5beta1"},{"PMID":"29074299","why":"ANGPTL2 modulates p38 MAPK via integrin alpha5beta1 in chondrocytes"}],"covers":["LR001651","LR005039"]},"LR005435":{"pair":"ANGPTL4 -> ITGA5","headline":"cANGPTL4 binds and activates integrin \u03b15\u03b21; one abstract-level paper plus an IntAct SPR record.","interaction_type":"direct binding","direction_and_effect":"cANGPTL4 binds and activates integrin \u03b15\u03b21-mediated Rac1/PAK signalling first, weakening cell-cell contacts, before declustering VE-cadherin and claudin-5 [PMID:21841165]. The curator effect label is antagonist, though the text says activates (see flag).","molecular_requirements":"The acting ligand is the C-terminal fibrinogen-like domain (cANGPTL4), a proteolytic fragment, not full-length ANGPTL4 [PMID:21841165]. Receptor is the \u03b15\u03b21 heterodimer [PMID:21841165].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; ANGPTL4-knockout mice in vivo [PMID:21841165]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; ITGA5 flagged non-secreted receptor [flag]; endothelial cell-surface binding.","caveats":"One paper, abstract only. An IntAct record (surface plasmon resonance, PMID 21397862) is listed under accession P05556, the same accession shown for the \u03b21 pair, so it may not be \u03b15-specific [DB:IntAct].","key_references":[{"PMID":"21841165","why":"cANGPTL4 binds and activates integrin \u03b15\u03b21 first"}],"covers":["LR002113","LR005435"]},"LR005444":{"pair":"ANGPTL7 -> LAIR1","headline":"ANGPTL7 binds LAIR1-overexpressing cells; binding is described as relatively weak.","interaction_type":"functional only","direction_and_effect":"Angptl1 and Angptl7 bound LAIR1-overexpressing 293T cells [PMID:22660330]. Their binding to LAIR1+ human cord blood cells was relatively weak [PMID:22660330]. Signalling effect is not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human LAIR1 on 293T cells and human cord blood cells [PMID:22660330]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL7 flagged secreted; LAIR1 transmembrane [flag].","caveats":"Weak binding; the study then focused on ANGPTL2 and ANGPTL5 with LILRB2, not on ANGPTL7-LAIR1 [PMID:22660330].","key_references":[{"PMID":"22660330","why":"Angptl7 binds LAIR1 cells, weakly"}],"covers":["LR002125","LR005444"]},"LR001655":{"pair":"ANXA2 -> ROBO4","headline":"Weak, functional-only support that recombinant ANXA2 signals through a Robo4 pathway in brain endothelial cells; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Recombinant ANXA2 reduced trans-endothelial permeability and rescued junctional proteins in human brain endothelial cells damaged by hypoxia plus IL-1beta, in part by modulating signalling via the Robo4-paxillin-ARF6 pathway [PMID:29786451]. Curators label it agonist.","molecular_requirements":"Not reported in our evidence. Effects were also mediated in part through F-actin and VE-cadherin interactions [PMID:29786451].","affinity_potency":[],"species_and_systems":"Human brain endothelial cells in vitro; ANXA2 knockout mice (E15.5 and adult) showed reduced junctional proteins and more tracer leakage [PMID:29786451].","localisation_and_range":"ANXA2 is flagged as secreted [flag]; the paper describes it as an endothelial cell membrane protein [PMID:29786451].","caveats":"No direct binding to Robo4 is shown in the abstract; Robo4 involvement is inferred from pathway modulation, and the effect is only 'in part'. Single paper read as abstract only; no database record.","key_references":[{"PMID":"29786451","why":"Proposes ANXA2 as a Robo4 ligand in cerebral endothelium."}],"covers":["LR001655","LR005042"]},"LR003617":{"pair":"APOB -> LRP2","headline":"One abstract shows a truncated apoB lipoprotein binds megalin (LRP2) but not the LDL receptor.","interaction_type":"direct binding","direction_and_effect":"On ligand blotting of renal cortical membranes, the lipoprotein containing apo B-70.5 bound only to megalin, and megalin mediated its endocytosis in F9 cells [PMID:10330424].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human lipoprotein with rabbit kidney membranes and rabbits in vivo; F9 cells for endocytosis [PMID:10330424]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"ApoB is flagged secreted; megalin carries a receptor flag [flag]. Renal proximal tubular cells removed the particle [PMID:10330424].","caveats":"The ligand tested is truncated apoB-70.5, not full-length apoB-100; the abstract suggests apoB sites recognised by LDLR and megalin may differ [PMID:10330424]. Abstract only.","key_references":[{"PMID":"10330424","why":"Ligand blotting shows apo B-70.5 binds megalin"}],"covers":["LR000068","LR003617"]},"LR005462":{"pair":"APOE -> ABCA1","headline":"Two abstract-level reports of APOE complexing with ABCA1 (human fibroblasts, rat astrocytes); mechanism is lipidation rather than classical signalling.","interaction_type":"direct binding","direction_and_effect":"Purified human plasma apoE3 formed a complex with ABCA1 in normal fibroblasts and competitively inhibited 125I-apoA-I binding to ABCA1 [PMID:14754908]. Endogenous astrocytic apoE co-immunoprecipitated with ABCA1, not in ABCA1-knockout astrocytes, and is involved in generating HDL-like particles [PMID:24814386]. The Tangier mutation C1477R abolished apoE3 binding and efflux [PMID:14754908].","molecular_requirements":"ApoE isoforms bound ABCA1 similarly; lipid association reduced binding [PMID:14754908]. Other subunits not reported in our evidence.","affinity_potency":[{"value":"IC50 2.5 +/- 0.4 microg/ml","assay":"lipid-free apoE3 inhibition of 125I-apoA-I binding to ABCA1","system":"human fibroblasts, stimulated","cite":"PMID:14754908"},{"value":"IC50 12.3 +/- 1.3 microg/ml","assay":"reconstituted HDL inhibition of 125I-apoA-I binding to ABCA1 (comparator)","system":"human fibroblasts, stimulated","cite":"PMID:14754908"}],"species_and_systems":"Human fibroblasts with human apoE3 [PMID:14754908]; rat astrocytes [PMID:24814386]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted, ABCA1 flagged transmembrane receptor [flag].","caveats":"Both papers read as abstracts only. The IC50 values are competition against apoA-I, not a Kd.","key_references":[{"PMID":"14754908","why":"apoE3-ABCA1 complex, competition and Tangier mutant"},{"PMID":"24814386","why":"endogenous apoE co-IP with ABCA1 in rat astrocytes"}],"covers":["LR002145","LR005462"]},"LR003626":{"pair":"APOE -> SCARB1","headline":"One abstract-level cell study shows free apoE binds SR-BI and raises cholesteryl ester uptake.","interaction_type":"direct binding","direction_and_effect":"Free apoE is a ligand for SR-BI; its direct interaction increased cholesteryl ester uptake from low- and high-density lipoproteins [PMID:12138091]. ApoE associated with lipids or lipoproteins did not modulate binding or uptake [PMID:12138091].","molecular_requirements":"Free (lipid-free) apoE is the active form in this study [PMID:12138091].","affinity_potency":[],"species_and_systems":"Human adrenal NCI-H295R cells [PMID:12138091]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted [flag].","caveats":"Abstract only; no affinity reported in our evidence.","key_references":[{"PMID":"12138091","why":"free apoE binds SR-BI"}],"covers":["LR000077","LR003626"]},"LR005471":{"pair":"APP -> CNTN3","headline":"APP binds CNTN3 directly: the APP copper-binding domain contacts CNTN3 Fn(2) in recombinant binding assays; supported by two papers.","interaction_type":"direct binding","direction_and_effect":"APP-AP fusion proteins bound CNTN3-Fc fusions; the CNTN3 second fibronectin domain (Fn(2)) mediates APP binding and the APP copper-binding domain (CuBD) mediates CNTN3 binding [PMID:31318883]. APP and APLP1 interact with CNTN3, whereas APLP2 did not bind CNTN3 [PMID:34958801]. Curators label the effect as agonist, but the papers show binding, not signalling output; contactins are described as forming co-receptor complexes with transmembrane proteins [PMID:34958801].","molecular_requirements":"Binding needs CNTN3 Fn(2) (the six N-terminal Ig domains were dispensable) and the APP CuBD; the APP E1 domain bound like the full ectodomain [PMID:31318883]. Structures of five contactin-amyloid pairs show a conserved Fn2-CuBD interface [PMID:34958801].","affinity_potency":[],"species_and_systems":"Recombinant ectodomain fusion proteins in vitro [PMID:31318883]. Curators record human; BLI work used mouse proteins because human APP(E1) aggregated [PMID:34958801]. Human pair is ortholog-inferred in our database.","localisation_and_range":"CNTNs are GPI-anchored and lack an intracellular region, so they are described as signalling through co-receptors [PMID:34958801]. CNTN3 is not flagged secreted [flag]; APP is flagged secreted and transmembrane [flag].","caveats":"Primary 2022 paper was read as abstract plus excerpts. No CNTN3-specific affinity is given in our evidence. Earlier Fc/AP-based assays reported 17-35 nM for APP/APLP1 with CNTN3-5, while BLI gave much weaker values, attributed by the authors to oligomeric state [PMID:34958801]. IntAct lists a pull-down [DB:IntAct].","key_references":[{"PMID":"31318883","why":"Maps the binding interface (CNTN3 Fn(2), APP CuBD)"},{"PMID":"34958801","why":"Systematic CNTN-amyloid binding and structures"}],"covers":["LR002156","LR005471"]},"LR002159":{"pair":"APP -> DCC","headline":"APP acts as a netrin-1-dependent co-receptor for DCC in commissural axon guidance; one paper read as abstract only.","interaction_type":"functional only","direction_and_effect":"APP interacts with DCC in the presence of netrin-1 and enhances netrin-1-mediated DCC signalling, such as MAPK activation; the authors conclude APP functions as a co-receptor for DCC [PMID:22782894]. Inactivation of APP in mice is associated with reduced commissural axon outgrowth [PMID:22782894].","molecular_requirements":"APP is part of the DCC receptor complex; the interaction requires netrin-1 [PMID:22782894]. Netrin-1 itself also interacts with APP [PMID:22782894].","affinity_potency":[],"species_and_systems":"Commissural axon growth cones; APP-inactivated mice [PMID:22782894]. Other experimental details are not reported in our evidence. Both database species rows are ortholog-inferred.","localisation_and_range":"Described as expressed at the growth cone [PMID:22782894]; APP and DCC are both flagged transmembrane receptor-capable [flag]. Range not reported.","caveats":"APP is a co-receptor here, not a classical ligand, so the ligand-receptor direction is questionable. Single paper, abstract only; no database record. Whether APP and DCC bind directly without netrin-1 is not reported in our evidence.","key_references":[{"PMID":"22782894","why":"APP-DCC complex in netrin-1 axon guidance"}],"covers":["LR002159","LR005474"]},"LR005480":{"pair":"APP -> NOTCH2","headline":"One paper identified Notch2 as an APP partner by crosslinking, mass spectrometry, co-IP and colocalisation.","interaction_type":"direct binding","direction_and_effect":"Notch2 was found as an APP binding partner and confirmed by co-IP; effect and direction are not reported in our evidence [PMID:16118793].","molecular_requirements":"Full-length Notch2 was used in co-IP with APP751 [PMID:16118793].","affinity_potency":[],"species_and_systems":"Membrane-impermeable crosslinking in HEK293 cells and rat E18 neurons, co-IP in HEK293 cells, and APP/CFP-Notch2/YFP colocalisation in COS cells [PMID:16118793]. Mouse pair is ortholog-inferred.","localisation_and_range":"Colocalised on the plasma membrane, with partial intracellular colocalisation [PMID:16118793]; both flagged transmembrane [flag].","caveats":"Abstract only; no database support in the dossier.","key_references":[{"PMID":"16118793","why":"Discovery and confirmation of APP-Notch2 interaction"}],"covers":["LR002165","LR005480"]},"LR008432":{"pair":"ARF4 -> EGFR","headline":"Only BioGRID two-hybrid and co-capture records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Rests on BioGRID two-hybrid and affinity capture-Western [DB:BioGRID]; four judged rows were different_entity.","key_references":[],"covers":["LR008432"]},"LR003635":{"pair":"ARTN -> GFRA3","headline":"Well supported: Artemin signals via GFRalpha3-RET, with a structure and several databases.","interaction_type":"direct binding","direction_and_effect":"Artemin is the ligand for GFRalpha3-RET [PMID:9883723]; a second paper confirmed ARTN signals through the GFRa3-RET complex and a peptide agonist, artefin, induced RET phosphorylation [PMID:30853893].","molecular_requirements":"GFRA3 forms a 2:2:2 ternary complex with ARTN and RET [DB:UniProt]; NCAM acts as an alternative receptor [PMID:30853893].","affinity_potency":[],"species_and_systems":"Recombinant human ARTN, cerebellar granule neurons [PMID:30853893]. Mouse pair is ortholog-inferred.","localisation_and_range":"ARTN flagged secreted [flag]; GFRA3 is a co-receptor [DB:UniProt].","caveats":"No affinity numbers reported. PMID 9883723 is abstract only. Structures are listed [DB:PDB 2GH0] [DB:PDB 6Q2S].","key_references":[{"PMID":"9883723","why":"Artemin identified as GFRalpha3-RET ligand"},{"PMID":"30853893","why":"ARTN signals via GFRa3-RET and NCAM"}],"covers":["LR000086","LR003635"]},"LR002168":{"pair":"ARTN -> NCAM1","headline":"One 2019 paper reports direct ARTN-NCAM binding by SPR and NCAM-dependent neurite outgrowth; a single-study, alternative-receptor claim.","interaction_type":"direct binding","direction_and_effect":"ARTN binds NCAM directly and ARTN-induced neuritogenesis requires NCAM expression and NCAM-associated signalling, so NCAM is proposed as an alternative ARTN receptor (agonist-type effect) [PMID:30853893]. Effects of ARTN and the ARTN-derived peptide artefin were inhibited by abrogating either NCAM or RET [PMID:30853893].","molecular_requirements":"Recombinant NCAM Ig1-3 domains bound ARTN in SPR. The paper links the NCAM-binding site to the heel region of ARTN (via the artefin peptide) [PMID:30853893]. RET is also needed for the full effect, so NCAM and RET both appear required [PMID:30853893].","affinity_potency":[{"value":"low micromolar range (no number given in excerpts)","assay":"surface plasmon resonance, ARTN with NCAM Ig1-3","system":"recombinant rat NCAM Ig1-3 domain","cite":"PMID:30853893"}],"species_and_systems":"Ligand and receptor recorded as human; SPR used recombinant rat NCAM Ig1-3, and neurite outgrowth used cerebellar granule neurons (transfected with a rat neuron kit) [PMID:30853893]. Full text was available.","localisation_and_range":"ARTN is flagged secreted; NCAM1 is flagged both secreted and transmembrane [flag]. Range was not tested in our evidence.","caveats":"Only one paper, and both mouse and human pair records are ortholog-inferred. The affinity is far weaker than the low nanomolar ARTN-GFRalpha3 binding noted in the same paper. Whether NCAM acts alone or only with RET is not resolved.","key_references":[{"PMID":"30853893","why":"SPR binding of ARTN to NCAM and NCAM-dependent neurite outgrowth"}],"covers":["LR002168","LR005482"]},"LR000089":{"pair":"ASIP -> MC1R","headline":"ASIP inhibits agonist-stimulated cAMP at human MC1R in one 1997 paper (abstract only); a potent antagonist here, no affinity number in our evidence.","interaction_type":"functional only","direction_and_effect":"ASIP is an antagonist: purified recombinant ASIP inhibited agonist-stimulated cAMP generation (alpha-MSH, or ACTH for hMC2R) and also inhibited radiolabeled-melanocortin binding to hMCR1-5. At MC1R it is a potent inhibitor (competitive antagonism, seen only at hMC1R among the five subtypes) [PMID:9058374].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence. Degree and mechanism of inhibition vary significantly among the five melanocortin receptor subtypes [PMID:9058374].","affinity_potency":[],"species_and_systems":"Human ASIP and human MC1R stably expressed in L cells and the adrenocortical OS3 cell line [PMID:9058374]. Recombinant cell assays, not in vivo.","localisation_and_range":"ASIP is flagged secreted and the receptor as a transmembrane receptor [flag]; the paper calls agouti protein a paracrine signalling molecule (stated for mouse agouti) [PMID:9058374]. ASIP is flagged as secreted; UniProt also describes ASIP as an antagonist of MC1R [DB:UniProt]. One extra paper was judged review-only and one is pending.","caveats":"Single paper, read as abstract only. No Kd, Ki or IC50 in our evidence, so potency is qualitative. Schild-analysis details are not available beyond the abstract-level curator note. The same paper covers all five melanocortin receptors, so this is one study counted in five pairs.","key_references":[{"PMID":"9058374","why":"Pharmacology of human ASIP at hMC1R-hMC5R: cAMP and binding inhibition"}],"covers":["LR000089"]},"LR003644":{"pair":"AVP -> AVPR1B","headline":"Direct, high-affinity agonist binding of vasopressin to the V1b (V3) receptor in human recombinant systems; coupling to Ca2+ and phospholipase C shown.","interaction_type":"direct binding","direction_and_effect":"AVP acts as a full agonist; GtoPdb lists Type=Agonist, Action=Full agonist [DB:GtoPdb]. AVP evoked a calcium-dependent chloride current in receptor-transfected Xenopus oocytes [PMID:7929452], concentration-dependent [Ca2+]i increases [PMID:9459574], and phospholipase C stimulation in CHO-V3 cells, partially pertussis toxin-sensitive [PMID:9322919]. Native vasopressin stimulated ACTH secretion in rat anterior pituitary [PMID:12446593].","molecular_requirements":"Single-chain GPCR; no co-receptor reported. Potency of PLC stimulation was proportional to receptor density, and cAMP coupling appeared only at high density [PMID:9322919].","affinity_potency":[{"value":"Kd 0.17 nM","assay":"AVP binding, single site","system":"COS-1 cells expressing human V1b","cite":"PMID:7929452"},{"value":"Ki 0.8 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"Kd 0.28 nM","assay":"[3H]AVP saturation binding","system":"COS-1 cells expressing human V1B","cite":"PMID:9459574"},{"value":"Kd 0.25 nM","assay":"[3H]AVP saturation binding","system":"CHO cells expressing hV1B","cite":"PMID:9884074"}],"species_and_systems":"Human receptor in COS-1, CHO and HeLa cells and Xenopus oocytes; rat pituitary and bovine chromaffin cells for native function [PMID:12446593]. Expression was restricted to pituitary by Northern blot [PMID:7929452]. No mouse experiment is in the dossier.","localisation_and_range":"AVP is flagged secreted and V1b as transmembrane [flag]; pituitary expression suggests endocrine action [PMID:7929452].","caveats":"Abstract-only reading for all papers. Some rows only use V1b as comparator [PMID:16158071][PMID:15084136], and one shows a V2 antagonist does not bind V1b [PMID:9864265]. 3 papers were abstract_insufficient.","key_references":[{"PMID":"7929452","why":"Cloning of human V1b; Kd 0.17 nM and oocyte response"},{"PMID":"9322919","why":"CHO-V3 cells: PLC, arachidonic acid, density-dependent signalling"},{"PMID":"9884074","why":"Kd of AVP at three human receptor subtypes"}],"covers":["LR000095","LR003644"]},"LR012374":{"pair":"BAMBI -> FZD4:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD4:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012374"]},"LR002177":{"pair":"BGN -> P2RX7","headline":"Biglycan activates the NLRP3 inflammasome through TLR2/4 and P2X7; evidence is functional, one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Soluble biglycan induces the NLRP3/ASC inflammasome in macrophages, activating caspase-1 and releasing mature IL-1beta; this is brought about by interaction of biglycan with TLR2/4 and purinergic P2X(4)/P2X(7) receptors, which induces receptor cooperativity [PMID:19605353]. Biglycan-deficient mice had lower active caspase-1 and mature IL-1beta in kidney and lung in obstruction and sepsis models [PMID:19605353].","molecular_requirements":"TLR2/4 are also involved, and P2X4 and P2X7 are named together; whether P2X7 alone is sufficient is not reported in our evidence [PMID:19605353].","affinity_potency":[],"species_and_systems":"Macrophages and biglycan-deficient mice (mouse); human and mouse pairs are both ortholog-inferred [PMID:19605353].","localisation_and_range":"Soluble biglycan (secreted flag) acting on macrophage surface receptors [flag][PMID:19605353].","caveats":"Abstract-only. P2X4 and P2X7 are not distinguished in the evidence sentence, and no direct binding or affinity is shown.","key_references":[{"PMID":"19605353","why":"biglycan activates NLRP3 inflammasome via TLR2/4 and P2X4/P2X7"}],"covers":["LR002177","LR005491"]},"LR003653":{"pair":"BMP10 -> ACVR2A","headline":"BMP10 binds ACVR2A with Kd about 1 nM and signals through it; supported by SPR, shRNA and a database record.","interaction_type":"direct binding","direction_and_effect":"BMP10 bound ACVR2A-Fc in surface plasmon resonance, with ACVR2A GBD-Fc inhibiting BMP10 SMAD1/5/8 signalling in HEK293 reporter cells [PMID:35643319]. Knockdown of ActRIIA in MC3T3 cells suppressed BMP10 signalling [PMID:16049014]. BMP10 does not discriminate among ActRIIA, ActRIIB and BMPRII in binding to type II receptors [PMID:22718755]. GtoPdb: agonist [DB:GtoPdb]; BioGRID reconstituted complex [DB:BioGRID].","molecular_requirements":"Type I partners: ALK3 knockdown also suppressed BMP10 signalling [PMID:16049014]; ALK1 ternary complexes studied [PMID:22718755]. BMP10 also binds BMPR2 with high affinity [PMID:35643319].","affinity_potency":[{"value":"KD 1.0E-09 M","assay":"SPR (BMP10 over immobilised ACVR2A-Fc, single curve fit)","system":"recombinant proteins","cite":"PMID:35643319"}],"species_and_systems":"Recombinant human proteins (CHO-expressed receptors) and HEK293 cells [PMID:35643319]; MC3T3 cells [PMID:16049014]; kinetic analysis [PMID:22718755]. Human pair with mouse ortholog-inferred.","localisation_and_range":"BMP10 has a secreted flag and ACVR2A a transmembrane flag [flag].","caveats":"Two of three papers are abstract-only. Evidence for ACVR2A is part of multi-receptor studies; BMP10 binds several type II receptors.","key_references":[{"PMID":"35643319","why":"SPR binding and inhibition data for BMP10-ACVR2A"},{"PMID":"16049014","why":"ActRIIA knockdown suppresses BMP10 signalling"},{"PMID":"22718755","why":"BMP10 type II receptor binding without discrimination"}],"covers":["LR000104","LR003653"]},"LR008261":{"pair":"BMP10 -> ACVR2B:ACVRL1","headline":"Database-asserted only: no judged paper supports this complex pair; records exist for the two chains separately.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP10 as an agonist at both ACVR2B and ACVRL1 as separate records [DB:GtoPdb]. UniProt states BMP10 'acts as a ligand for ACVRL1/ALK1, BMPR1A/ALK3 and BMPR1B/ALK6', leading to SMAD1/5/8 activation [DB:UniProt].","molecular_requirements":"Not reported in our evidence whether ACVR2B and ACVRL1 act together as a complex for BMP10; the records are per chain. BioGRID lists an ACVR2B-BMP10 reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"No experimental paper in the dossier; species not reported beyond the human entity annotation.","localisation_and_range":"BMP10 is annotated as secreted [flag]; range not tested in our evidence.","caveats":"Only one review-only row was judged; there is no curator-verified evidence for the pairing as a complex.","key_references":[],"covers":["LR008261"]},"LR008009":{"pair":"BMP15:GDF9 -> ACVR1B:BMPR1B:BMPR2","headline":"Database-asserted only: no verified paper; records cover GDF9 alone.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF9 as an agonist at ACVR1B, BMPR1B and BMPR2 [DB:GtoPdb]. BioGRID has a reconstituted-complex record for BMPR2-GDF9 [DB:BioGRID].","molecular_requirements":"No record names BMP15 or a BMP15:GDF9 ligand unit, and none shows the three receptor chains acting together.","affinity_potency":[],"species_and_systems":"No paper evidence; species not reported in our evidence.","localisation_and_range":"Ligand members are annotated as secreted [flag].","caveats":"All seven judged rows were abstract_insufficient, so no paper confirms or refutes the pair.","key_references":[],"covers":["LR008009"]},"LR003671":{"pair":"BMP2 -> ENG","headline":"Endoglin interacts with BMP-2 only through type I receptors ALK3/ALK6; indirect, one paper.","interaction_type":"functional only","direction_and_effect":"Endoglin interacts with BMP-2 but requires coexpression of the respective ligand-binding kinase receptor [PMID:9872992]. Its presence did not alter heteromeric signalling complex formation [PMID:9872992].","molecular_requirements":"Endoglin cannot bind BMP-2 on its own; binding requires the type I receptors ALK3 and ALK6 [PMID:9872992].","affinity_potency":[],"species_and_systems":"Affinity labelling in endothelial and leukemic cells; species not reported [PMID:9872992].","localisation_and_range":"Endoglin is a transmembrane glycoprotein [PMID:9872992]; BMP2 flagged secreted [flag].","caveats":"Only one paper, read as abstract. The interaction is accessory/co-receptor-like and not direct binding to endoglin. BioGRID lists affinity capture-western from the same paper [DB:BioGRID].","key_references":[{"PMID":"9872992","why":"endoglin binds BMP-2 via ALK3/ALK6"}],"covers":["LR000122","LR003671"]},"LR011195":{"pair":"BMP4 -> ACVR2B","headline":"No curator-verified paper; support rests on a GtoPdb agonist record only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP4 -> ACVR2B as Agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"BMP4 is flagged secreted and ACVR2B a transmembrane receptor [flag].","caveats":"Five papers were judged abstract_insufficient, none confirmed; one related hMSC paper reported ACVR2B not significant for BMP signalling but is not linked to this pair here.","key_references":[],"covers":["LR011195"]},"LR007118":{"pair":"BMP4 -> ACVR2B:BMPR1A","headline":"Complex not supported: ACVR2B was not required for BMP4 signalling in hMSC (explicit negative); BMPR1A half is supported elsewhere.","interaction_type":"conflicting","direction_and_effect":"In primary human mesenchymal stem cells, ACVR2B was expressed at low levels and not found to play a significant role in BMP signalling, whereas BMPR1A was a type I receptor for osteoinductive BMP-2/4 activity [PMID:18436533]. GtoPdb lists BMP4 as agonist at ACVR2B and BMPR1A separately [DB:GtoPdb]. UniProt notes BMP4 interacts with type I receptor BMPR1A [DB:UniProt].","molecular_requirements":"The BMPR1A chain is supported; the ACVR2B chain is not by the verified paper [PMID:18436533].","affinity_potency":[],"species_and_systems":"Human primary mesenchymal stem cells (negative) [PMID:18436533].","localisation_and_range":"BMP4 flagged secreted; receptors transmembrane [flag].","caveats":"Only evidence is an abstract-only negative for this complex; low expression in that cell type limits the conclusion. The BioGRID record cited is for BMP4-BMPR1B, not this complex [DB:BioGRID 282659].","key_references":[{"PMID":"18436533","why":"Negative result for ACVR2B in hMSC BMP-2/4 signalling"}],"covers":["LR007118"]},"LR003680":{"pair":"BMP4 -> HJV","headline":"HJV (RGMC) binds BMP4 with Kd 4.5 nM by SPR and is a BMP4 co-receptor driving BMP signalling in hepatoma cells.","interaction_type":"direct binding","direction_and_effect":"SPR measured HJV binding to BMP4 with KD 4.5 nM, among the highest of the RGM-BMP pairs; RGMB bound BMP4 more tightly [PMID:23029472]. BMP-2, BMP-4 and BMP-6 are endogenous ligands for HJV in hepatoma-derived cell lines, with agonist effect on hepcidin regulation [PMID:18326817].","molecular_requirements":"HJV selectively used type II receptors ActRIIA and BMPRII, not ActRIIB, and enhanced ActRIIA use by BMP-2/BMP-4; HJV used ALK2/ALK3/ALK6 in vitro [PMID:18326817]. Action was independent of neogenin [PMID:18326817].","affinity_potency":[{"value":"KD 4.5 nM","assay":"surface plasmon resonance","system":"recombinant HJV and BMP4, human (curated)","cite":"PMID:23029472"}],"species_and_systems":"Recombinant SPR [PMID:23029472]; hepatoma-derived cell lines and human liver expression [PMID:18326817].","localisation_and_range":"HJV is flagged secreted and receptor [flag]; BMP4 secreted, so HJV may act as a co-receptor, membrane-bound or soluble.","caveats":"HJV acts as a co-receptor with BMP type I/II receptors, not alone. The functional paper was read as abstract only [PMID:18326817].","key_references":[{"PMID":"23029472","why":"SPR affinities of RGM proteins incl. HJV for BMP4"},{"PMID":"18326817","why":"HJV/BMP-4 signalling and receptor usage in hepatoma cells"}],"covers":["LR000131","LR003680"]},"LR005048":{"pair":"BMP4 -> RGMB","headline":"BMP4 binds RGMB (DRAGON) directly in two papers, with the tightest SPR affinity of the RGMs, Kd 2.6 nM; acts as a BMP co-receptor.","interaction_type":"direct binding","direction_and_effect":"RGMB (DRAGON) enhances BMP signalling; the abstract states it binds BMP2 and BMP4 directly but not BMP7 or other TGF-beta ligands, and the enhancing action is reduced by Noggin, indicating ligand dependence [PMID:15671031]. Curators label the effect agonist [PMID:15671031][PMID:23029472].","molecular_requirements":"DRAGON also associates directly with type I (ALK2, ALK3, ALK6) and type II (ActRII, ActRIIB) BMP receptors; its signalling is reduced by dominant negative Smad1 and ALK3 or ALK6 [PMID:15671031]. The BMP4 binding partner is RGMB itself.","affinity_potency":[{"value":"Kd 2.6 nM","assay":"SPR","system":"RGMB vs BMP4, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human. The 2005 paper used Xenopus embryos for function [PMID:15671031]; the 2012 paper used SPR with recombinant proteins [PMID:23029472]. BioGRID holds a reconstituted-complex record from the 2005 paper [DB:BioGRID]. Mouse pair is projected from human.","localisation_and_range":"DRAGON is described as GPI-anchored [PMID:15671031], i.e. membrane-tethered (juxtacrine); the entity flag marks RGMB as not secreted [flag].","caveats":"Both papers were read as abstracts by the curators (2012 paper also with full-text excerpts). Binding is ligand-selective: BMP7 was not bound in the 2005 paper [PMID:15671031].","key_references":[{"PMID":"15671031","why":"first report of DRAGON/RGMB as BMP co-receptor; direct BMP2/BMP4 binding"},{"PMID":"23029472","why":"SPR affinity of RGMB for BMP4"}],"covers":["LR001662","LR005048"]},"LR007127":{"pair":"BMP5 -> ACVR2B:BMPR1A","headline":"BMP5 to ACVR2B:BMPR1A rests on GtoPdb and UniProt statements only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb]. UniProt (BMP5, P22003) states BMP5 associates with type I receptor BMPR1A and type II receptor BMPR2, not ACVR2B; UniProt also says BMPR1A phosphorylates SMAD1/5/8 [PMID:29321139] [DB:UniProt][PMID:11580864].","molecular_requirements":"Chains in the complex: ACVR2B and BMPR1A; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 3 review_only. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007127"]},"LR010871":{"pair":"BMP5 -> BMPR1A","headline":"BMP5 to BMPR1A rests on GtoPdb and UniProt statements only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb]. UniProt (BMP5, P22003) states BMP5 associates with type I receptor BMPR1A and type II receptor BMPR2 [DB:UniProt][PMID:11580864].","molecular_requirements":"Single receptor chain; coreceptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. One screened paper was abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR010871"]},"LR007136":{"pair":"BMP6 -> ACVR2B:BMPR1A","headline":"Complex pair supported by database records only (GtoPdb, BioGRID, PDB 9N4K, UniProt); no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP6 as an agonist at both ACVR2B and BMPR1A as separate records [DB:GtoPdb]. UniProt says BMP6 may promote HAMP expression via BMPR1A/ALK3 [DB:UniProt].","molecular_requirements":"Both chains are listed separately in GtoPdb; a combined ACVR2B plus BMPR1A complex is not directly shown in our evidence. PDB 9N4K is a cryoEM structure titled ALK2-ActRIIB bound to BMP6, which names ACVR1 (ALK2), not BMPR1A [DB:PDB 9N4K]. BioGRID records ACVR2B-BMP6 affinity capture-western [DB:BioGRID] and BMP6-BMPR1B reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"No paper was judged for this pair (three review-only papers). The structure is of a different type I chain (ALK2); the BioGRID BMPR1B record does not concern BMPR1A. Treat the complex as assembled from per-chain assertions.","key_references":[],"covers":["LR007136"]},"LR002186":{"pair":"BMP6 -> RGMB","headline":"Direct SPR binding of BMP6 to RGMB, Kd 28 nM, in one 2012 paper; intermediate affinity of the three RGMs.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance measured binding of RGMB to BMP6 with K(D) 28 nM; curated effect is agonist [PMID:23029472].","molecular_requirements":"RGM proteins are described as BMP co-receptors; the paper measured RGM protein binding to BMP ligands, and receptor chains needed for signalling are not reported in our evidence [PMID:23029472].","affinity_potency":[{"value":"Kd 28 nM","assay":"surface plasmon resonance","system":"recombinant RGM proteins with BMP ligands","cite":"PMID:23029472"}],"species_and_systems":"Recombinant human proteins per curator; abstract-level curation with full-text excerpts describing SPR (mean of 4-9 experiments) [PMID:23029472]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor is not flagged as secreted [flag]; localisation is otherwise not reported in our evidence.","caveats":"Affinity data are from an in vitro SPR matrix; no cellular signalling result for this pair is reported in our evidence. Compared with other RGMs: HJV 8.1, RGMB 28, RGMA 55 nM for BMP6 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGM proteins for BMP ligands"}],"covers":["LR002186","LR005500"]},"LR007145":{"pair":"BMP7 -> ACVR2B:BMPR1A","headline":"Complex-level evidence is only a functional paper on BMP7 acting via ALK3 (BMPR1A); the ACVR2B chain is untested.","interaction_type":"functional only","direction_and_effect":"BMP7 induces Langerhans cell differentiation and proliferation by activating the BMP type-I receptor ALK3 in the absence of canonical TGF-\u03b21-ALK5 signaling [PMID:24190429]. GtoPdb lists agonist action for ACVR2B and BMPR1A separately [DB:GtoPdb].","molecular_requirements":"The paper implicates ALK3 (BMPR1A) as the type I receptor; it does not report ACVR2B as a partner in our evidence.","affinity_potency":[],"species_and_systems":"Human Langerhans cell precursors in vitro; Bmp7-deficient mice had fewer LCs [PMID:24190429].","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Read as abstract only; the evidence is functional, not binding, and supports only the BMPR1A chain. BioGRID shows BMP7-ACVR2B (affinity capture-Western) and BMPR1B records, but none for the combined complex [DB:BioGRID]. Three papers were review_only.","key_references":[{"PMID":"24190429","why":"BMP7 signals through ALK3 in human Langerhans cell precursors"}],"covers":["LR007145"]},"LR001664":{"pair":"BMP7 -> HJV","headline":"BMP7 binds HJV directly by SPR (Kd 20 nM); single abstract-level paper with full-text support, human proteins.","interaction_type":"direct binding","direction_and_effect":"Curators record the effect as agonist; the paper's abstract describes RGM proteins as co-receptors that enhance cellular responses to BMP ligands, but this paper measured binding only [PMID:23029472].","molecular_requirements":"Binding was measured for the RGM protein alone; type I/II BMP receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 20 nM","assay":"surface plasmon resonance","system":"recombinant human proteins (curator-annotated species)","cite":"PMID:23029472"}],"species_and_systems":"SPR with recombinant proteins; curators annotate both partners as human, mouse pair is ortholog-inferred [PMID:23029472].","localisation_and_range":"BMP7 is flagged secreted and HJV is flagged secreted [flag]; range of action not reported in our evidence.","caveats":"HJV had the highest affinity for BMP7 among the three RGMs [PMID:23029472]. BMP7 had the lowest relative affinity of the BMPs tested for the RGMs, and BMP7-RGM data needed CM4 sensor chips because fitting on CM5 chips was poor [PMID:23029472]. Curator read depth is abstract-only. Only one paper.","key_references":[{"PMID":"23029472","why":"SPR kinetics of all RGM-BMP pairs including BMP7"}],"covers":["LR001664","LR005050"]},"LR007154":{"pair":"BMP8A -> ACVR2B:BMPR1A","headline":"BMP8A -> ACVR2B:BMPR1A is database-asserted only; no paper was verified for this complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8A as an agonist at ACVR2B and at BMPR1A [DB:GtoPdb]; UniProt says BMP8A associates with BMPR1A and BMPR2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"BMP8A is flagged secreted [flag]; range of action not otherwise reported.","caveats":"Three papers were review-only. The complex is assembled from separate chain records; UniProt names BMPR2, not ACVR2B, as the type II partner.","key_references":[],"covers":["LR007154"]},"LR008252":{"pair":"BMP8B -> BMPR1B:BMPR2","headline":"BMP8B -> BMPR1B:BMPR2 is asserted only by GtoPdb agonist records for each chain; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B-BMPR1B and BMP8B-BMPR2 each as Type=Agonist, Action=Agonist [DB:GtoPdb].","molecular_requirements":"Receptor modelled as a type I (BMPR1B) plus type II (BMPR2) complex [flag]; joint requirement is not shown, as GtoPdb lists the chains separately [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence (human entities).","localisation_and_range":"Complex flagged transmembrane and not secreted [flag]; ligand range not reported in our evidence.","caveats":"No curator-verified paper; several candidate papers were judged abstract-insufficient, review-only or about a different entity, so none supports the pair. The GtoPdb record is a database assertion, not an experiment.","key_references":[],"covers":["LR008252"]},"LR007181":{"pair":"C10orf99 -> GPR15","headline":"Supported by one 2026 mouse genetic study and two structures; ligand-receptor pairing in epithelial T cell localisation.","interaction_type":"functional only","direction_and_effect":"Epithelium-derived C10ORF99 (GPR15L) and GPR15 are needed for TCR+ natural intraepithelial lymphocytes in the large intestinal epithelium; the curator labels it agonist [PMID:42229754]. UniProt describes C10orf99 as a chemotactic factor mediating lymphocyte recruitment [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The assay detail describes in vivo mouse genetic analysis [PMID:42229754], although the curator lists the experiment species as human.","localisation_and_range":"C10orf99 is annotated secreted and GPR15 transmembrane [flag]; paracrine from epithelium is implied by the paper.","caveats":"Abstract only. Physical binding is not shown in the paper but PDB structures contain both chains [DB:PDB 8ZQE, DB:PDB 9WXM].","key_references":[{"PMID":"42229754","why":"in vivo requirement for C10ORF99 and GPR15 in colonic IEL localisation"}],"covers":["LR007181"]},"LR005507":{"pair":"C1qa -> Adcy5","headline":"Candidate C1q receptor from an unbiased pull-down screen in human neural stem cells; mouse pair is projected from human evidence.","interaction_type":"functional only","direction_and_effect":"C1q was cross-linked to membrane proteins and ADCY5 was among five transmembrane candidates identified by pull-down and mass spectrometry; the proximity-ligation assay was reported to validate the C1q-ADCY5 interaction and the curator labels it agonist [PMID:32894219].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were in human neural stem cells (hNSC); the mouse pair is ortholog-inferred, not tested in mouse [PMID:32894219].","localisation_and_range":"C1q is annotated secreted [flag]. Cell-surface receptor role is a candidate assignment.","caveats":"Candidate-level evidence; functional validation in the paper was for CD44 only, not for ADCY5. Paper read as abstract and excerpts. ","key_references":[{"PMID":"32894219","why":"screen identifying five candidate C1q receptors in hNSC"}],"covers":["LR005507"]},"LR001673":{"pair":"C1QA -> CD33","headline":"Direct binding of C1q to CD33 shown with purified proteins and cells; binding is through the globular head, and C1q cross-links CD33 and LAIR-1.","interaction_type":"direct binding","direction_and_effect":"C1q cross-links the inhibitory immunoreceptors CD33 and LAIR-1 on monocytes [PMID:28325905]. Binding to CD33 is reported as dose-related with whole C1q and gC1q but not the collagen-like region in slot blots; the curator labels the effect antagonist (inhibitory) [PMID:28325905]. UniProt notes the interaction activates CD33 inhibitory motifs [DB:UniProt].","molecular_requirements":"The globular head (gC1q), not the collagen-like region, binds CD33M [PMID:28325905]. Binding is also reported to cell-surface CD33m and CD33M isoforms [PMID:28325905].","affinity_potency":[],"species_and_systems":"Human proteins and human monocytes; HEK293T cells transfected with CD33 isoforms [PMID:28325905].","localisation_and_range":"C1q annotated secreted [flag].","caveats":"Single paper plus IntAct filter-binding and SPR records [DB:IntAct]; no affinity values in our evidence. Paper abstract authors say natural ligands for CD33 remain elusive.","key_references":[{"PMID":"28325905","why":"binding and cross-linking of C1q with CD33 and LAIR-1"}],"covers":["LR001673"]},"LR002195":{"pair":"C1QA -> CD44","headline":"C1q signalling through CD44 in human neural stem cells, supported by functional knockdown or blockade; direct binding is not shown in our excerpts.","interaction_type":"functional only","direction_and_effect":"CD44 mediates C1q-induced hNSC signalling and chemotaxis in vitro; receptor knockdown or blockade abolished the response [PMID:32894219]. Curator label: stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neural stem cells; the mouse pair is ortholog-inferred [PMID:32894219]. C1q concentrations tested included 28 ng/mL, 400 ng/mL [PMID:32894219].","localisation_and_range":"C1q annotated secreted; CD44 annotated secreted and transmembrane, so soluble and membrane forms are both flagged [flag].","caveats":"Only one paper is shown (two confirmed rows counted). CD44 was one of five screen candidates; no affinity reported.","key_references":[{"PMID":"32894219","why":"CD44 identified and functionally validated for C1q signalling and chemotaxis"}],"covers":["LR002195","LR005509"]},"LR005525":{"pair":"C1QC -> LAIR1","headline":"C1q (via its collagen-like region) binds and activates LAIR-1 on human monocytes; one paper, chain-level row.","interaction_type":"direct binding","direction_and_effect":"The abstract states that C1q CLR engaging and activating LAIR-1 is a non-complement route to immune quiescence, and that C1q crosslinks LAIR-1 and CD33 [PMID:28325905]. The CLR-LAIR-1 activation is stated in the abstract's first sentence; in this paper's excerpts, C1q bound LAIR-1 in a dose-dependent manner on HEK293T lysates, described as previously reported by the authors.","molecular_requirements":"Domain-resolved: the collagen-like region (CLR) of C1q engages LAIR-1, whereas the globular head binds CD33 [PMID:28325905]. This row encodes the C1QC chain of the hexameric C1q; chain-alone activity is not shown.","affinity_potency":[],"species_and_systems":"Human: HEK293T cells transfected with LAIR-1 (slot blot), human monocytes (proximity ligation assay) [PMID:28325905].","localisation_and_range":"C1q secreted (ligand flag), LAIR1 transmembrane (receptor flag) [flag]; C1q bridges LAIR-1 and CD33 on one monocyte [PMID:28325905].","caveats":"The LAIR-1 arm is largely background in this paper (the new claim is CD33); the visible abstract does not give the LAIR-1 measurement. Single paper; chain-level attribution inherited from the complex.","key_references":[{"PMID":"28325905","why":"C1q CLR engages LAIR-1 and bridges it with CD33 on human monocytes"}],"covers":["LR002212","LR005525"]},"LR005534":{"pair":"C1QTNF9 -> ADIPOR1","headline":"CTRP9 (C1QTNF9) signals through ADIPOR1 in endothelial cells; one full-text paper with knockdown and crosslink evidence.","interaction_type":"direct binding","direction_and_effect":"CTRP9 acted as an agonist: it caused vasorelaxation and increased AMPK/Akt/eNOS phosphorylation and NO production, and knockdown of AdipoR1 but not AdipoR2 blocked this [PMID:21836066]. A crosslink study showed AdipoR1 and CTRP9 directly interact, which the authors call first direct evidence that AdipoR1 may function as a CTRP9 binding protein [PMID:21836066].","molecular_requirements":"AdipoR1 alone was required; AdipoR2 knockdown had no significant effect. No co-receptor requirement reported in our evidence. CTRP9 was nearly three-fold more potent than adiponectin in NO production [PMID:21836066].","affinity_potency":[],"species_and_systems":"Murine CTRPs were tested on aortic rings; mechanism was in human umbilical vein endothelial cells (siRNA knockdown) and mouse aortic endothelial cells [PMID:21836066]. The mouse pair is ortholog-inferred.","localisation_and_range":"CTRP9 is flagged as secreted [flag]; range is therefore paracrine/endocrine by annotation only.","caveats":"Single paper; binding rests on a crosslink experiment, with no affinity reported. The authors describe AdipoR1 as a 'likely receptor' [PMID:21836066].","key_references":[{"PMID":"21836066","why":"Knockdown and crosslink evidence for CTRP9-AdipoR1"}],"covers":["LR002222","LR005534"]},"LR003707":{"pair":"C3 -> ITGAM","headline":"The iC3b fragment of C3 binds ITGAM (CD11b) in CR3; supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"iC3b-Sepharose isolated CR3 from human spleen membranes and leukocytes [PMID:4062888]. An anti-alphaM antibody induced adhesion of alphaMbeta2 CHO cells to iC3b [PMID:11073102]. Anti-CD11b blocked platelet-neutrophil complexes, with C3(H2O) antibody inhibiting 75-100% [PMID:26293614]. BioGRID lists affinity capture-Western [DB:BioGRID].","molecular_requirements":"CR3 is the alphaM:beta2 heterodimer; ITGAM acts with ITGB2 [PMID:4062888]. Subunit sufficiency not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins: spleen membranes [PMID:4062888], transfected CHO cells [PMID:11073102], platelets and PMN [PMID:26293614]. Mouse pair is ortholog-inferred.","localisation_and_range":"ITGAM is a cell-surface integrin; contact-dependent (annotation flag [flag]).","caveats":"All three papers abstract only. Ligand is iC3b or C3(H2O), not intact C3. Paper 11073102 concerns an activating antibody.","key_references":[{"PMID":"4062888","why":"iC3b affinity chromatography isolating CR3"},{"PMID":"26293614","why":"C3(H2O) and CD11b in platelet-PMN tethering"}],"covers":["LR000158","LR003707"]},"LR005057":{"pair":"CADM1 -> NECTIN3","headline":"Functional evidence only: a neutralizing anti-nectin-3 antibody blocks CADM1-dependent mast cell-neuron interaction; direct binding not shown here.","interaction_type":"functional only","direction_and_effect":"Mast-cell CADM1 mediated attachment to dorsal root ganglion (DRG) neurites and calcium responses to activated neurites, although neuronal CADM1 was low; nectin-3 was expressed on DRG neurons, and a neutralizing anti-nectin-3 antibody inhibited both attachment and calcium responses. The authors infer heterophilic CADM1-nectin-3 binding [PMID:22703826].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vitro mast cell-DRG co-culture; species not stated in the abstract read, dossier labels it human [PMID:22703826]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"Both flagged membrane-bound [flag]; nectin-3 localised to neuron-neuron contact regions [PMID:22703826]. Contact-dependent between mast cell and neuron.","caveats":"Abstract only; binding is inferred from antibody blockade, not measured [PMID:22703826]. Reactome lists a Necl-2:Nectin-3 trans heterodimer reaction [DB:Reactome].","key_references":[{"PMID":"22703826","why":"Neutralizing nectin-3 antibody blocks CADM1-dependent mast cell-DRG interaction"}],"covers":["LR001681","LR005057"]},"LR001682":{"pair":"CADM3 -> CADM1","headline":"Direct CADM3-CADM1 binding by SPR (Kd 80.1 nM) and heterophilic cell adhesion; well supported.","interaction_type":"direct binding","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with Necl-2 (CADM1) [PMID:15741237]. CADM1-Fc also bound CADM3 in SPRi [PMID:30131958]. Reactome lists a Necl-1:Necl-2 trans heterodimer [DB:Reactome].","molecular_requirements":"Full ectodomains in SPRi; no extra subunit reported [PMID:30131958].","affinity_potency":[{"value":"Kd 80.1 nM","assay":"SPRi, CADM1-Fc analyte with CADM3-Fc","system":"purified Fc fusions","cite":"PMID:30131958"}],"species_and_systems":"Cell-aggregation assays (abstract-level, human-labelled) [PMID:15741237]; recombinant SPRi [PMID:30131958]. Both human and mouse pairs listed, not inferred.","localisation_and_range":"Membrane-bound pair [flag]. Necl-1 is neural-tissue specific, at contact sites among axons, terminals and glia [PMID:15741237]; trans, contact-dependent.","caveats":"The cell-aggregation paper was read as abstract only [PMID:15741237]. Kd is for CADM1-Fc as analyte.","key_references":[{"PMID":"15741237","why":"Heterophilic Necl-1 / Necl-2 adhesion"},{"PMID":"30131958","why":"SPRi Kd 80.1 nM"}],"covers":["LR001682","LR005058"]},"LR005543":{"pair":"CADM3 -> CADM4","headline":"Direct CADM3-CADM4 binding by SPRi, plus axon-Schwann cell adhesion; no Kd in evidence.","interaction_type":"direct binding","direction_and_effect":"Axon-Schwann cell interaction is described as primarily mediated by axonal CADM3 binding CADM4 on myelinating Schwann cells [PMID:33889941]. SPRi detected heterophilic interactions of CADM3 and CADM4 with all CADM members [PMID:30131958]. A CADM3 variant (Tyr172Cys) was ER-retained, had reduced surface expression and reduced co-localisation with CADM4 at contacts [PMID:33889941].","molecular_requirements":"Not reported in our evidence beyond ectodomain-Fc binding.","affinity_potency":[],"species_and_systems":"SPRi with human-labelled Fc ectodomains [PMID:30131958]; human families and Cadm3Y170C mice in the variant study [PMID:33889941]. The binding statement there is background in the abstract.","localisation_and_range":"Both flagged membrane-bound [flag]; axon-Schwann cell contact [PMID:33889941].","caveats":"The second paper was read as abstract only and the CADM3-CADM4 binding is stated as background, not measured [PMID:33889941]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"30131958","why":"SPRi CADM-family binding"},{"PMID":"33889941","why":"CADM3-CADM4 axon-glia adhesion; disease variant reduces co-localisation"}],"covers":["LR002233","LR005543"]},"LR003716":{"pair":"CALCA -> CALCRL","headline":"Alpha-CGRP activates CALCRL as part of the CRLR/RAMP1 receptor; well supported functionally, but abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Alpha-CGRP is an agonist: RAMP1 makes CRLR a CGRP receptor [PMID:9620797][PMID:10347248]. A cloned human CGRP1 receptor gave a 60-fold increase in cAMP on CGRP exposure, competitively inhibited by the antagonist CGRP-(8-37) [PMID:8626685]. Radioligand [125I]halphaCGRP binding was used in RAMP1/CRLR cells [PMID:11693189].","molecular_requirements":"RAMP1 is required: it presents CRLR at the cell surface as a mature glycoprotein and a CGRP receptor [PMID:9620797]. Progressive shortening of the RAMP1 transmembrane domain impaired CRLR association and abolished CGRP receptor function [PMID:12234182]. The cloning paper does not state RAMP1 explicitly [PMID:8626685]. Score as a complex.","affinity_potency":[{"value":"pKd 6.0","assay":"CGRP binding, RAMP1/CRLR (value from curated row)","system":"human","cite":"PMID:9620797"}],"species_and_systems":"Human ligand and receptor in HEK293 cells [PMID:8626685][PMID:11693189]; rat mesenteric artery binding with human ligand [PMID:14668209]. Mouse pair is ortholog-inferred. GtoPdb gives pKi 6.5-6.8 [DB:GtoPdb].","localisation_and_range":"CALCA flagged secreted [flag]; CALCRL is flagged receptor (transmembrane not flagged) [flag]. Range is paracrine/endocrine by annotation.","caveats":"All shown papers are abstract-only. The rat artery paper is about hormonal regulation of receptor expression, and mentions an uncharacterised CGRP-B receptor [PMID:14668209]. CRLR alone is not shown to bind CGRP in our evidence.","key_references":[{"PMID":"9620797","why":"RAMP1 makes CRLR a CGRP receptor"},{"PMID":"8626685","why":"Cloned human CGRP1 receptor, 60-fold cAMP increase"},{"PMID":"12234182","why":"RAMP1 transmembrane domain needed for CGRP receptor function"}],"covers":["LR000171","LR003716"]},"LR009233":{"pair":"CALM1 -> SELL","headline":"Calmodulin binds an L-selectin (SELL) peptide in an NMR structure; peptide-level evidence only.","interaction_type":"direct binding","direction_and_effect":"A solution NMR structure of Ca2+/calmodulin complexed with a peptide representing the calmodulin-binding domain of L-selectin is listed [DB:PDB 2LGF].","molecular_requirements":"Ca2+-dependent; peptide, not full-length SELL [DB:PDB 2LGF].","affinity_potency":[],"species_and_systems":"Human, NMR.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. Peptide-only structure.","key_references":[],"covers":["LR009233"]},"LR008513":{"pair":"CALM3 -> EGFR","headline":"CALM3 and EGFR co-associate in IntAct records from several assays; no curated paper confirms a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; IntAct lists association between the two proteins [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and systems are not reported in our evidence beyond the assay names; the entities are human.","localisation_and_range":"EGFR is flagged as a transmembrane receptor [flag]; CALM3 localisation is not reported in our evidence.","caveats":"Five IntAct records, by anti-bait coimmunoprecipitation, affinity chromatography and ubiquitin reconstruction, are the only support [DB:IntAct]. The one judged paper was assigned to a different entity. Co-association does not show that calmodulin acts as a ligand for EGFR.","key_references":[],"covers":["LR008513"]},"LR008333":{"pair":"CALR -> ITGA3","headline":"One abstract-read paper links calreticulin to integrin alpha3 in cells; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"In RD rhabdomyosarcoma cells, anti-alpha3 integrin antibody transiently enhanced calreticulin-alpha3 integrin interaction; calreticulin antisense oligonucleotides abrogated the interaction and suppressed MMP-2 activation [PMID:11327697].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human RD rhabdomyosarcoma cells (cell line); the paper was read as an abstract only [PMID:11327697].","localisation_and_range":"CALR is flagged secreted [flag]; the paper does not state where the interaction occurs.","caveats":"The antibody-triggered interaction is an indirect cell readout; the abstract does not show purified-protein binding. Only an abstract was read. BioGRID adds an Affinity Capture-Western record [DB:BioGRID]. One judged paper was unresolvable and one concerned a different entity.","key_references":[{"PMID":"11327697","why":"Calreticulin-alpha3 integrin interaction in RD cells, needed for MMP-2 secretion"}],"covers":["LR008333"]},"LR000179":{"pair":"CAMP -> FPR2","headline":"LL-37 (CAMP) activates FPR2 in chemotaxis and calcium assays; two abstract-read papers, human and mouse.","interaction_type":"functional only","direction_and_effect":"LL-37 is chemotactic and induces Ca(2+) mobilization in monocytes and FPRL1-transfected HEK293 cells, with cross-desensitization by an FPRL1-specific agonist [PMID:11015447]. The mouse orthologue CRAMP acts as a full agonist using FPRL1 / mouse FPR2 [PMID:15879124]. GtoPdb lists Agonist, Full agonist [DB:GtoPdb].","molecular_requirements":"Only the receptor chain FPR2 is involved; the active peptide is the cleaved 37-residue LL-37 from the CAMP precursor hCAP18 [PMID:11015447].","affinity_potency":[{"value":"pEC50 6.0","assay":"LL-37 agonist potency, as recorded by curators and GtoPdb","system":"FPRL1-transfected HEK293 cells / human cells","cite":"PMID:11015447"}],"species_and_systems":"Human LL-37 on human monocytes and transfected HEK293 cells [PMID:11015447]; mouse CRAMP on human and mouse leukocytes and HEK293 cells expressing FPRL1 or mouse FPR2, plus mouse air pouch in vivo [PMID:15879124]. The mouse pair is ortholog-inferred in our database.","localisation_and_range":"CAMP is flagged secreted and FPR2 transmembrane [flag]; paracrine chemoattractant action is described [PMID:11015447].","caveats":"Both papers were read as abstracts only; evidence is functional (chemotaxis, calcium flux), not direct binding, and the pEC50 is as recorded and its assay detail is not reported in our evidence. A third confirmed paper was not shown.","key_references":[{"PMID":"11015447","why":"LL-37 uses FPRL1 for chemotaxis and Ca2+ mobilization"},{"PMID":"15879124","why":"Mouse CRAMP uses FPRL1 / mFPR2 as receptor"}],"covers":["LR000179","LR003724"]},"LR005552":{"pair":"CBLN1 -> GRID2","headline":"CBLN1 and GRID2 interact in a trans-synaptic bridge; evidence here is an abstract-level statement of similar binding.","interaction_type":"direct binding","direction_and_effect":"Cbln1 and Cbln2 are reported to have similar binding activities to beta-neurexins and Grid2, and in cerebellum Cbln1 bridges presynaptic beta-neurexins to postsynaptic Grid2 on Purkinje neurons [PMID:22117778]. Effect is synaptic organising (agonist per curators).","molecular_requirements":"CBLN1 acts as a bridge between beta-neurexins and Grid2, so neurexin may be a required partner in the synapse [PMID:22117778]. A PDB structure holds one chain of each partner [DB:PDB 5KCA].","affinity_potency":[],"species_and_systems":"Transgenic and null mice (cerebellum, striatum, thalamus); the species of the binding assays is not reported in our evidence, and the curators recorded human [PMID:22117778]. Human pair is ortholog-inferred, mouse is the direct one.","localisation_and_range":"CBLN1 is flagged secreted and GRID2 transmembrane [flag]; synaptic cleft action across neurons is described [PMID:22117778].","caveats":"The paper (full text available) is mainly about CBLN2 redundancy; the sentence on binding is a summary claim, and no affinity is reported. A second confirmed paper was not shown.","key_references":[{"PMID":"22117778","why":"Cbln1 and Cbln2 bind beta-neurexins and Grid2; redundancy in cerebellum"}],"covers":["LR002242","LR005552"]},"LR002249":{"pair":"CBLN4 -> DCC","headline":"CBLN4 binds DCC directly in several assays, with lower affinity than Netrin-1; supported by one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Protein-microarray screening, cell-surface binding and SPR show CBLN4 binds DCC; CBLN1, CBLN2 and CBLN3 did not bind DCC [PMID:24400119]. Netrin-1 competes with CBLN4 at an overlapping site and binds with about 5-fold higher affinity [PMID:24400119]. Curators label it agonist, but DCC activation by CBLN4 is not shown in the abstract or excerpts.","molecular_requirements":"Binding maps to the membrane-proximal fibronectin domains 4-6 of DCC [PMID:24400119].","affinity_potency":[{"value":"K 117\u00b134 nM","assay":"125I-CBLN4-Fc radioligand cell-binding assay","system":"DCC-transfected HEK293T cells","cite":"PMID:24400119"},{"value":"K 22\u00b16 nM (Netrin-1, for comparison)","assay":"125I-gD-Netrin-1 radioligand assay","system":"DCC-transfected HEK293T cells","cite":"PMID:24400119"}],"species_and_systems":"Recombinant proteins on transfected COS-7 and HEK293T cells; CBLN4-null mice for the in vivo phenotype [PMID:24400119]. The human pair is direct; the mouse pair is projected.","localisation_and_range":"CBLN4 is flagged secreted [flag].","caveats":"CBLN4 also binds the DCC homolog NEO1 with lower affinity, and CBLN4-null mice showed no commissural-axon defect, only a transient increase in wandering brachial-plexus axons [PMID:24400119]. Single paper.","key_references":[{"PMID":"24400119","why":"Microarray, SPR and radioligand data for CBLN4-DCC and comparison with Netrin-1"}],"covers":["LR002249","LR005559"]},"LR003725":{"pair":"CCK -> CCKAR","headline":"Well supported agonist-receptor pair: human CCK1 receptor binding sites mapped by mutagenesis and NMR, plus GtoPdb, PDB structures and Reactome.","interaction_type":"direct binding","direction_and_effect":"CCK acts as an agonist: receptor mutants lose affinity and potency to induce inositol phosphates [PMID:9006937], and GtoPdb lists an agonist interaction [DB:GtoPdb]. Sulfated tyrosine of CCK is crucial for binding [PMID:9603948].","molecular_requirements":"Residues involved include Trp-39/Gln-40 [PMID:9006937], Met-195 [PMID:9603948], Arg197 [PMID:10595537], Arg-336/Asn-333 [PMID:10400673]. Complex structures with both chains are in PDB (e.g. [DB:PDB 7EZH]). Reactome lists a CCKAR,CCKBR:CCK complex [DB:Reactome].","affinity_potency":[{"value":"12.9- and 20.9-fold decrease in affinity and potency (W39F, Q40N mutants)","assay":"mutagenesis, binding and inositol phosphate accumulation","system":"human CCK-A receptor","cite":"PMID:9006937"}],"species_and_systems":"Human receptor mutants; peptides used are CCK-8/CCK-9 analogues rather than full CCK-33; COS-7 cells in [PMID:10595537]. NMR used a receptor fragment (residues 329-357) in micelles [PMID:11300760]. Mouse pair is projected.","localisation_and_range":"CCK is flagged secreted and CCKAR transmembrane [flag].","caveats":"All five papers shown were read as abstracts; most evidence is mutational mapping, not primary affinity measurement. Nonsulfated CCK shows 800-fold lower affinity than sulfated CCK [PMID:10595537].","key_references":[{"PMID":"10595537","why":"Arg197 mutant loses agonist radioligand binding"},{"PMID":"9006937","why":"Trp-39/Gln-40 role in CCK binding and potency"},{"PMID":"10400673","why":"Arg-336 and Asn-333 interact with CCK C-terminus"}],"covers":["LR000180","LR003725"]},"LR005561":{"pair":"CCK -> GPR83","headline":"Reported for proCCK-derived peptides (ProCCK56-62/63) binding GPR83, not for the bioactive CCK peptide; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"ProCCK56-62 and ProCCK56-63 bind GPR83 with high affinity, activate second messenger pathways and induce receptor endocytosis; they couple to Gas at low and Gai at high concentrations [PMID:35605991].","molecular_requirements":"Signalling bias depends on peptide: PEN22 and PEN20 favour Gai, PEN18, PEN19 and ProCCK peptides favour Gas [PMID:35605991].","affinity_potency":[],"species_and_systems":"Peptides identified in mouse brain; curated species human/human [PMID:35605991]. Mouse pair is the non-inferred one.","localisation_and_range":"CCK flagged secreted [flag]; localisation of ProCCK peptides not reported.","caveats":"The abstract states ProCCK56-62 has no homology to the bioactive cholecystokinin domain [PMID:35605991]. No affinity values in our evidence. Abstract only.","key_references":[{"PMID":"35605991","why":"ProCCK peptides bind and activate GPR83"}],"covers":["LR002251","LR005561"]},"LR000188":{"pair":"CCL13 -> ACKR2","headline":"CCL13 is reported to bind ACKR2 (D6) in one full-text paper and database records; no affinity for CCL13 reported.","interaction_type":"direct binding","direction_and_effect":"Binding to the promiscuous receptor D6 is reported for human chemokines; the excerpt names RANTES, MCP3, MCP4 and HCC1 [PMID:9405404]. Signalling effect is not reported in our evidence. UniProt lists CCL13 among ACKR2 ligands [DB:UniProt]; BioGRID has a reconstituted-complex record [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 stably expressed in CHO cells, ligand displacement of 125I-labelled murine MIP-1a [PMID:9405404].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"The excerpt names MCP4 (the curator treats this as CCL13), not CCL13 itself; this naming link is not stated in the excerpt. One paper only.","key_references":[{"PMID":"9405404","why":"D6 binds many CC chemokines incl. MCP4"}],"covers":["LR000188"]},"LR000197":{"pair":"CCL14 -> CCR5","headline":"CCL14 activates CCR5 as the processed HCC-1[9-74] form; functional evidence plus a GtoPdb agonist record.","interaction_type":"functional only","direction_and_effect":"HCC-1[9-74] was a potent agonist of CCR5 (and CCR1, CCR3), and blocked entry of HIV-1 strains using CCR5 as coreceptor [PMID:11085751]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Full-length HCC-1 is a nonfunctional precursor; tumor cell conditioned media converted it to the active form via serine protease-sensitive activity [PMID:11085751].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; CCR5-expressing CHO cells in an aequorin-based assay [PMID:11085751].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Affinity not reported in our evidence; the GtoPdb record cites PMID 16298345, which is not among the curated papers here [DB:GtoPdb]. Only one curated paper, read as an abstract with methods excerpts.","key_references":[{"PMID":"11085751","why":"Isolation of HCC-1[9-74] using a CCR5 bioassay"}],"covers":["LR000197"]},"LR003734":{"pair":"CCL17 -> CCR8","headline":"CCL17 is reported as a CCR8 agonist in one chemotaxis study; a structural paper only asserts it. Secondary to CCR4.","interaction_type":"functional only","direction_and_effect":"TARC induced chemotaxis in CCR8 Jurkat stable transfectants [PMID:9521068]; a structure paper states TARC interacts primarily with CCR4 and to a lesser extent CCR8, without testing it [PMID:12832759].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in Jurkat transfectants; abstract-only [PMID:9521068][PMID:12832759]. Mouse pair projected from human.","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"No binding or affinity for CCR8; the structural paper has no receptor assay. Evidence is limited to abstracts.","key_references":[{"PMID":"9521068","why":"TARC and MIP-1beta chemotaxis via CCR8"},{"PMID":"12832759","why":"Mentions CCR8 as a secondary receptor; structure only"}],"covers":["LR000206","LR003734"]},"LR002258":{"pair":"CCL18 -> ACKR1","headline":"CCL18 binds human ACKR1 (Duffy) weakly; one paper.","interaction_type":"direct binding","direction_and_effect":"Binding only; no signalling reported in our evidence. CCL18 showed weak binding (Ki 100 nM-1 uM class) to Duffy antigen on red blood cells [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 206.2 nM","assay":"radioligand displacement","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human chemokine and human erythrocytes [PMID:15358176].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Single paper; no database support; weak affinity.","key_references":[{"PMID":"15358176","why":"Ki of CCL18 at Duffy antigen"}],"covers":["LR002258"]},"LR003761":{"pair":"CCL2 -> ACKR1","headline":"Direct but non-signalling binding of CCL2 to ACKR1/DARC from two papers; scavenger-type atypical receptor.","interaction_type":"direct binding","direction_and_effect":"DARC bound CCL2 in competition binding, but DARC-bound CCL2 failed to induce a significant cytosolic calcium rise in CCR2B-expressing cells; DARC knockout mice showed no change in lymph node leukocyte composition or lymphocyte migration [PMID:13679391].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 34.9 nM","assay":"125I-CXCL8 displacement on erythrocytes","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human ligand and receptor in binding [PMID:13679391][PMID:15358176]; knockout data are from mice [PMID:13679391]. A mouse interaction record also exists.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Binds selected inflammatory but not homeostatic chemokines [PMID:15358176]. The affinity is taken from a curator note for a displacement table row; which chemokine row it covers is not stated in the abstract. Effect described as neutral, not signalling [PMID:13679391]. BioGRID records a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"13679391","why":"DARC binds CCL2 but not lymphoid chemokines; non-signalling"},{"PMID":"15358176","why":"Duffy antigen displacement binding, Ki 34.9 nM"}],"covers":["LR000240","LR003761"]},"LR003743":{"pair":"Ccl21b -> Ccr7","headline":"Mouse pair inferred from well-supported human CCL21-CCR7 evidence; a mouse CCR7 and mouse 6CK/SLC chemotaxis study adds partial direct support.","interaction_type":"direct binding","direction_and_effect":"CCL21 (SLC/6Ckine) is a CCR7 agonist: calcium mobilisation and chemotaxis in CCR7-expressing L1.2 cells [PMID:9507024] and chemotaxis of cells transfected with mouse or human CCR7 [PMID:9585422]. GtoPdb has CCL21B-CCR7 agonist records [DB:GtoPdb].","molecular_requirements":"CCR7 alone sufficed in transfected cells. NMR mapping puts the CCR7 N-terminus on CCL21's N-loop and third beta-strand [PMID:22221265].","affinity_potency":[{"value":"IC50 0.5 nM","assay":"SLC-SEAP binding competed by SLC","system":"murine L1.2 cells expressing human CCR7","cite":"PMID:9507024"}],"species_and_systems":"Most experiments used human CCL21 and human CCR7 [PMID:9507024][PMID:22221265][PMID:11970971]. PMID:9585422 excerpts describe mouse 6CK/SLC and mouse CCR7 in L1/2 cells, so some mouse evidence exists, but it is not tied to Ccl21b.","localisation_and_range":"Ligand flagged secreted and receptor flagged a receptor [flag]; no transmembrane flag is given.","caveats":"The mouse pair is projected from human. Abstract-only reads except PMID:9585422. PMID:11970971 gave no receptor-blockade control. Paralogs of mouse Ccl21 are not distinguished in the papers. One paper is still pending.","key_references":[{"PMID":"9507024","why":"IC50 0.5 nM binding and signalling at CCR7"},{"PMID":"9585422","why":"CCR7 agonist activity with mouse and human CCR7"},{"PMID":"22221265","why":"binding interface mapped by NMR"}],"covers":["LR003743"]},"LR003752":{"pair":"CCL28 -> CCR3","headline":"CCL28 supports migration through CCR3 in one abstract-read paper (human); GtoPdb lists it as an agonist. Thinly supported.","interaction_type":"functional only","direction_and_effect":"CCL28 supports migration through CCR3 as well as CCR10 and attracts eosinophils [PMID:10975800]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins [PMID:10975800]. The mouse pair is ortholog-inferred from human.","localisation_and_range":"CCL28 is flagged as secreted and CCR3 as transmembrane [flag].","caveats":"Only one paper, read as abstract only, with a functional readout; no direct binding or affinity in our evidence. The mouse pair has no mouse experiment.","key_references":[{"PMID":"10975800","why":"CCL28 supports migration via CCR3 and attracts eosinophils"}],"covers":["LR000231","LR003752"]},"LR008603":{"pair":"CCL3L3 -> CCR3","headline":"LD78beta (mapped to CCL3L3) binds CCR3 and mobilises calcium in its full-length form only; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Full-length LD78beta(1-70) at 30 ng/ml competed with [125I]RANTES for CCR3 binding and mobilised calcium in CCR3 transfectants [PMID:11449371].","molecular_requirements":"The CD26-processed LD78beta(3-70) shows a 30-fold decrease in CCR3 affinity [PMID:11449371]. Contrary to LD78alpha, LD78beta binds CCR3 [PMID:11449371].","affinity_potency":[],"species_and_systems":"Human proteins, CCR3 transfectants [PMID:11449371]. BioGRID lists this under CCL3L1 - CCR3 [DB:BioGRID].","localisation_and_range":"CCL3L3 is flagged as secreted and CCR3 as transmembrane [flag].","caveats":"One paper, abstract only; no absolute affinity in our evidence. BioGRID attributes the record to CCL3L1, so the CCL3L3 assignment rests on the curators' mapping.","key_references":[{"PMID":"11449371","why":"Full-length LD78beta binds CCR3; processed loses 30-fold"}],"covers":["LR008603"]},"LR003770":{"pair":"CCL5 -> ACKR1","headline":"CCL5 binds ACKR1 (DARC) with strong, direct binding in human erythrocytes; ACKR1 is a non-signalling chemokine-binding receptor.","interaction_type":"direct binding","direction_and_effect":"CCL5 is among inflammatory chemokines selectively bound by DARC, not lymphoid chemokines [PMID:13679391, PMID:15358176]. Curator notes describe DARC as a non-signalling atypical (scavenger/decoy) receptor, so CCL5 binding is not agonism [PMID:13679391]. In that paper DARC-bound CCL2 failed to give a significant Ca2+ signal [PMID:13679391].","molecular_requirements":"Not reported in our evidence; ACKR1 acts on its own in the binding assays.","affinity_potency":[{"value":"Ki 5.6 nM","assay":"competition displacement of 125I-CXCL8","system":"human erythrocytes, human DARC","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes, lymph node high endothelial venules and inflamed synovial endothelium [PMID:15358176, PMID:13679391, PMID:12081195]. A mouse interaction is also listed but no mouse experiment is shown.","localisation_and_range":"ACKR1 is transmembrane [flag]; binding was seen on erythrocyte and endothelial surfaces, where it can present or clear chemokine (curator notes) [PMID:12081195].","caveats":"Papers other than PMID:15358176 were read as abstracts only. In PMID:12081195 RANTES evidence is indirect (cross-displacement of 125I-IL-8, with blocking anti-DARC antibody tested on IL-8 only). No database record supports the pair.","key_references":[{"PMID":"15358176","why":"Ki 5.6 nM, human erythrocyte displacement; CCL5 binds endothelium"},{"PMID":"13679391","why":"Competitive binding with 20 chemokines; CCL5 binds DARC"},{"PMID":"12081195","why":"In situ binding on synovial endothelium"}],"covers":["LR000260","LR003770"]},"LR000269":{"pair":"CCL7 -> CCR3","headline":"MCP-3 (CCL7) binds human CCR3 with Kd 2.7 nM in three papers, but is a weaker activator than eotaxin or RANTES.","interaction_type":"direct binding","direction_and_effect":"CCR3 bound MCP-3 with Kd 2.7 nM; eotaxin, RANTES and, to a lesser extent, MCP-3 stimulated a Ca2+ flux [PMID:8642344]. CKR-3 transfectants bound MCP-3 and migrated to it in chemotaxis [PMID:8676064]. An antagonistic anti-CCR3 antibody showed over 95% of eosinophil responses to MCP-3 and other CC chemokines were CCR3-mediated [PMID:9005985]. GtoPdb: full agonist, pKi 8.6 to 9.2 [DB:GtoPdb].","molecular_requirements":"CCR3 alone suffices in transfectants; MCP-3 is only a partial/lesser activator versus eotaxin [PMID:8642344].","affinity_potency":[{"value":"Kd 2.7 nM","assay":"radioligand binding","system":"CCR3 in AML14.3D10 cells (human)","cite":"PMID:8642344"},{"value":"pKi 8.6 to 9.2","assay":"GtoPdb binding range","system":"human CCR3","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor; transfectants and primary human eosinophils [PMID:8642344][PMID:9005985]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR3 flagged transmembrane receptor [flag].","caveats":"Two of three papers read as abstracts; first is full text. CCR3 is promiscuous so the pair is individually low-specificity.","key_references":[{"PMID":"8642344","why":"CCR3 cloned; MCP-3 Kd 2.7 nM"},{"PMID":"8676064","why":"CKR-3 binds and chemotaxes to MCP-3"},{"PMID":"9005985","why":"Over 95% of eosinophil MCP-3 response via CCR3"}],"covers":["LR000269","LR003779"]},"LR000278":{"pair":"CCL8 -> ACKR1","headline":"Human ACKR1 (Duffy) binds CCL8 weakly (Ki 151 nM) in one paper and moderately in a second competition assay.","interaction_type":"direct binding","direction_and_effect":"CCL8 bound Duffy on erythrocytes in the weak-binding category (Ki 100 nM to 1 uM) [PMID:15358176]. In DARC-expressing cells, 125I-CXCL1 binding was moderately inhibited by CCL17 and CCL8 and strongly by CCL7, CCL5 and CCL2 [PMID:13679391]. Signalling not reported for CCL8.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 151.0 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes and DARC-expressing cells [PMID:15358176][PMID:13679391]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL8 flagged secreted; ACKR1 flagged transmembrane receptor [flag].","caveats":"The 2003 evidence is a browser-read results sentence, unverified. The 2004 evidence sentence ('those that showed strong binding') does not match the weak-binding category in the curator's assay detail.","key_references":[{"PMID":"15358176","why":"CCL8 weak binder at Duffy, Ki 151.0 nM"},{"PMID":"13679391","why":"CCL8 moderately inhibits CXCL1 binding to DARC"}],"covers":["LR000278","LR003788"]},"LR002267":{"pair":"CCL8 -> CCR8","headline":"Mouse CCL8 is a CCR8 agonist in mouse Th2 cells; the human pair is inferred from this mouse evidence.","interaction_type":"functional only","direction_and_effect":"Mouse CCL8 acts as an agonist for CCR8 but not CCR2; it induced pertussis-toxin-sensitive chemotaxis and calcium flux in mouse Th2 cells, and Ccr8- and Ccl8-deficient mice had less eosinophilic skin inflammation [PMID:21217759]. GtoPdb lists CCL8-CCR8 as an agonist [DB:GtoPdb]; UniProt says CCR8 binds a variety of chemokines including CCL8 [DB:UniProt].","molecular_requirements":"CCR8 alone was identified as the receptor on CCL8-responsive Th2 cells; no co-receptor is reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used mouse CCL8 and mouse cells and mice [PMID:21217759]. The human pair is ortholog-inferred, so human direct binding is not shown here (the paper does report human CCR8 marks an IL-5-enriched Th2 subset).","localisation_and_range":"Secreted ligand acting on a transmembrane receptor [flag]; skin-homing paracrine axis [PMID:21217759].","caveats":"Evidence is functional (chemotaxis, calcium flux, knockouts), not a direct binding measurement; the paper was read as abstract plus full-text excerpts. No affinity is reported in our evidence.","key_references":[{"PMID":"21217759","why":"Mouse CCL8 is a CCR8 but not CCR2 agonist; Ccl8 and Ccr8 knockout phenotypes"}],"covers":["LR002267","LR005568"]},"LR005066":{"pair":"CCN1 -> SDC4","headline":"CCN1 acts through syndecan-4 together with integrin alpha6beta1 to induce fibroblast apoptosis; functional evidence only.","interaction_type":"functional only","direction_and_effect":"CCN1 induces fibroblast apoptosis through its adhesion receptors, integrin alpha6beta1 and the heparan sulfate proteoglycan syndecan-4, via transcription-independent p53 activation of Bax [PMID:16275757]. Endothelial cell adhesion to CCN1 promotes survival instead [PMID:16275757].","molecular_requirements":"Syndecan-4 is paired with integrin alpha6beta1 in the reported mechanism; syndecan-4 alone is not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Rat1a fibroblasts and human skin fibroblasts (HSF), with HUVEC for the survival contrast, CCN1 as an adhesion substrate [PMID:16275757].","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Evidence is functional; no direct binding measure or affinity for syndecan-4 is in our evidence. Outcome is cell-type dependent (apoptosis in fibroblasts, survival in endothelial cells). Abstract plus full-text excerpts.","key_references":[{"PMID":"16275757","why":"CCN1 induces fibroblast apoptosis through alpha6beta1 and syndecan-4"}],"covers":["LR001697","LR005066"]},"LR005570":{"pair":"CCN1 -> TLR2","headline":"CCN1 binds TLR2 directly (SPR KD 227 nM) and activates MyD88-dependent inflammatory signalling; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant TLR2 bound immobilized CCN1 in a dose-dependent manner and CCN1 bound TLR2 directly, activating MyD88-dependent signaling and cytokine expression [PMID:32144270]. Induction of Tnfa and Il6 was reduced in Tlr2-deficient macrophages and abolished in Myd88-deficient cells, so CCN1 acts as a DAMP-like agonist [PMID:32144270].","molecular_requirements":"A CCN1 double mutant (DM) lost TLR2 binding yet still bound TLR4, so the TLR2 binding site is separable [PMID:32144270]. No co-receptor is reported for TLR2.","affinity_potency":[{"value":"KD 227 nM","assay":"surface plasmon resonance, TLR2 immobilized, CCN1 as analyte","system":"recombinant human TLR2","cite":"PMID:32144270"}],"species_and_systems":"Human recombinant TLR2 in binding assays; functional work in mouse bone-marrow-derived macrophages and mice [PMID:32144270]. The species of CCN1 protein is not stated in the excerpt.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Single paper, also reporting TLR4 binding (KD 291 nM). Cytokine induction was reduced, not absent, in Tlr2-deficient cells, so TLR4 contributes [PMID:32144270].","key_references":[{"PMID":"32144270","why":"Direct CCN1-TLR2 binding by solid-phase and SPR; MyD88-dependent activation"}],"covers":["LR002269","LR005570"]},"LR000386":{"pair":"CCN2 -> LRP6","headline":"CTGF is reported to bind the Wnt co-receptor LRP6 and to regulate Wnt signalling in Xenopus; abstract-level.","interaction_type":"functional only","direction_and_effect":"CTGF regulates signalling through the Wnt pathway in Xenopus embryos, in accord with its ability to bind LRP6 [PMID:15105373]. Whether it enhances or inhibits Wnt signalling is not stated in our evidence.","molecular_requirements":"The interaction likely involves the C-terminal domain of CTGF, which is distinct from its BMP4- and TGF-beta-interacting domain [PMID:15105373].","affinity_potency":[],"species_and_systems":"Xenopus embryos for function; binding species not specified beyond human recombinant annotation by the curators [PMID:15105373]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Binding is stated but its assay is not described in our evidence; domain assignment is 'likely' only. LRP6 is a co-receptor, so a ligand role is not established.","key_references":[{"PMID":"15105373","why":"CTGF binding to LRP6 and Wnt regulation in Xenopus"}],"covers":["LR000386","LR003892"]},"LR002276":{"pair":"CCN3 -> ITGA5","headline":"CCN3 binds integrin alpha5beta1 directly (EC50-type half-maximal binding 50 nM); supported by full text and databases.","interaction_type":"direct binding","direction_and_effect":"CCN3 is an agonist: it supports HUVEC adhesion and drives migration dependent on alpha5beta1 and alphavbeta3 [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522].","molecular_requirements":"The receptor is the alpha5beta1 heterodimer; both UniProt and the paper describe ITGA5:ITGB1 [DB:UniProt][PMID:12695522]. Adhesion also used heparan sulfate proteoglycans [PMID:12695522].","affinity_potency":[{"value":"50 nM","assay":"half-maximal binding (EC50), solid-phase ELISA with immobilized alpha5beta1","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"Single primary paper; UniProt and GtoPdb records cite the same paper (and UniProt also PMID 15611078) [DB:UniProt][DB:GtoPdb]. GtoPdb entry reports Action=Binding with pKd units but no value is shown in our evidence [DB:GtoPdb].","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002276","LR005577"]},"LR005075":{"pair":"Cd200 -> Cd200r2","headline":"One FACS binding report supports mouse Cd200 binding to Cd200r2; read from abstract only.","interaction_type":"direct binding","direction_and_effect":"FITC-labelled CD200Fc bound COS7 cells transfected with each CD200R isoform, including R2 per the curator [PMID:15187158]. Functional effects differ between isoforms; anti-CD200 R2/R3 mAbs had a significantly lesser effect than anti-R1/R4 on cytokine production and CTL suppression [PMID:15187158].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse pair; COS7 cells transfected with the receptor [PMID:15187158].","localisation_and_range":"Cd200r2 carries no secreted or transmembrane flag [flag]; otherwise not reported in our evidence.","caveats":"Single paper read as abstract only; one further paper was judged abstract_insufficient. Universal claim ('all isoforms') rather than isoform-specific data; no affinity reported.","key_references":[{"PMID":"15187158","why":"FACS binding of CD200Fc to all CD200R isoforms"}],"covers":["LR005075"]},"LR001709":{"pair":"CD209 -> ICAM3","headline":"DC-SIGN (CD209) binds ICAM-3 with high affinity; but CD209 is the receptor on dendritic cells and ICAM3 sits on T cells, so this row is reversed.","interaction_type":"direct binding","direction_and_effect":"DC-SIGN on dendritic cells binds ICAM-3 on resting T cells and mediates transient adhesion; anti-DC-SIGN antibodies inhibit DC-induced T cell proliferation [PMID:10721994]. A related paper says L-SIGN behaves like DC-SIGN with high affinity for ICAM-3, but its own subject is the paralogue [PMID:11257134].","molecular_requirements":"UniProt records describe a Ca2+-requiring, integrin-independent interaction through mannose-like carbohydrates [DB:UniProt]; Reactome lists a CD209:ICAM3:Ca+2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human; both curator labels human [PMID:10721994].","localisation_and_range":"Both partners are flagged transmembrane [flag]; cell-cell contact between dendritic cell and T cell [PMID:10721994].","caveats":"Both papers abstract-level; no numeric affinity ('high affinity' only). PMID:11257134 mainly concerns L-SIGN. IntAct solid-phase assay also lists the pair [DB:IntAct].","key_references":[{"PMID":"10721994","why":"Identification of DC-SIGN as ICAM-3 receptor"}],"covers":["LR001709"]},"LR002285":{"pair":"CD24 -> SIGLEC5","headline":"Thin evidence: one abstract-only paper in which CD24 glycoforms supported Siglec-5 binding, as a side readout.","interaction_type":"direct binding","direction_and_effect":"Direction and effect not reported in our evidence. Affinity-purified CD24 glycoforms, whether SN3b-epitope positive or negative, supported Siglec-5 binding [PMID:20351695].","molecular_requirements":"Siglec-5 binding did not require the SN3b sialic-acid epitope on CD24 [PMID:20351695]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD24 and Siglec-5 per curated species fields; affinity-purified glycoforms and tissue microarrays [PMID:20351695].","localisation_and_range":"CD24 is flagged membrane-bound [flag]; range not otherwise reported.","caveats":"Single paper, read as abstract only. Its main subject is mapping anti-CD24 antibody epitopes; Siglec-5 binding is a secondary readout. No affinity, no functional effect and no database record.","key_references":[{"PMID":"20351695","why":"Siglec-5 binds CD24 glycoforms regardless of SN3b epitope"}],"covers":["LR002285"]},"LR005084":{"pair":"CD34 -> SELE","headline":"Human CD34 on HSPCs is a major vascular selectin ligand; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD34-positive HSPC fractions bound E- and P-selectin whereas CD34-negative fractions did not, and a proteomics screen identified CD34 as a major vascular selectin ligand; knockdown implicates it in the first step of cell migration [PMID:29296932].","molecular_requirements":"Not reported in our evidence; the paper notes glycoforms of CD34 may matter [PMID:29296932].","affinity_potency":[],"species_and_systems":"Human hematopoietic stem/progenitor cells from human tissue [PMID:29296932]; mouse pair projected.","localisation_and_range":"CD34 is flagged transmembrane, not secreted; SELE membrane-bound [flag]; interaction is cell-cell adhesion on vascular beds.","caveats":"Abstract only; the paper reports selectins jointly (E- and P-selectin) and E-selectin-specific data are not separated in the abstract. No affinity reported. Title also implicates CD44.","key_references":[{"PMID":"29296932","why":"CD34 on human HSPCs as vascular selectin ligand"}],"covers":["LR001717","LR005084"]},"LR001718":{"pair":"CD38 -> PECAM1","headline":"Soluble CD38 acts on CD31 (PECAM1) on human sperm, shown by proximity ligation and signalling; single paper.","interaction_type":"functional only","direction_and_effect":"Soluble CD38 in seminal plasma increased sperm capacitation through interaction with CD31 on sperm; CD31 was tyrosine phosphorylated by Src and signalled via Erk1/2, giving acrosome reaction and hypermotility, blocked by Src/Ras/MEK inhibitors [PMID:26407101].","molecular_requirements":"Shc, SHP-2, Grb2, SOS and Src associated with phosphorylated CD31 [PMID:26407101]. Other requirements not reported.","affinity_potency":[],"species_and_systems":"Human sperm, recombinant sCD38 (e.g. 600 ng/ml) [PMID:26407101]; mouse pair projected. UniProt describes CD38/CD31 signalling in T lymphocytes [DB:UniProt].","localisation_and_range":"CD38 flagged secreted and transmembrane [flag]; the paper uses a soluble form from seminal plasma acting paracrine on sperm [PMID:26407101].","caveats":"A proximity ligation assay indicates proximity but no binding constant is reported. The mouse pair is inferred from human data.","key_references":[{"PMID":"26407101","why":"sCD38 activates CD31 on sperm"}],"covers":["LR001718","LR005085"]},"LR002294":{"pair":"CD5 -> CD5","headline":"Homophilic CD5 binding is shown by SPR with soluble protein; weak, species-specific and apparently inhibitory.","interaction_type":"direct binding","direction_and_effect":"CD5 binds CD5 homophilically; engagement of human CD5 domain 1 appears inhibitory, since blocking it by mutation or CD5 mAb increased antigen-specific mouse T cell responses [PMID:20952682].","molecular_requirements":"Only CD5 domain 1 is involved; human CD5 domain 1 is necessary and dominant for the interaction in chimaera experiments [PMID:20952682]. Protein purified at pH 2.5 lost specificity, so purification at neutral pH matters [PMID:20952682].","affinity_potency":[],"species_and_systems":"SPR at 37 C with His-tagged soluble human, rat and mouse CD5 on CD5CD4 fusion chips; human CD5 binds only human CD5, while mouse and rat CD5 cross-react [PMID:20952682]. The mouse pair is ortholog-inferred.","localisation_and_range":"Soluble extracellular region binding; annotation flags mark CD5 as secreted [flag]. Cell-surface homophilic contact is implied by the authors' framing but not shown in the excerpts.","caveats":"Interaction is weak with rapid dissociation and no affinity value is given [PMID:20952682]. Only one of two confirmed papers is displayed. A UniProt record concerns CD5 signalling and not this binding [DB:UniProt].","key_references":[{"PMID":"20952682","why":"SPR shows species-specific homophilic CD5 binding via domain 1"}],"covers":["LR002294","LR005593"]},"LR000287":{"pair":"CD55 -> ADGRE5","headline":"Well supported direct CD55-CD97 binding, low affinity, calcium-dependent, mediated by CD55 SCR and CD97 EGF domains.","interaction_type":"direct binding","direction_and_effect":"CD97 binds the complement regulator CD55 as a cellular ligand: a blocking mAb recognised the NH2-terminal SCR of CD55, and CD55-negative erythrocytes failed to adhere to CD97 transfectants [PMID:9064337].","molecular_requirements":"Interaction is mediated solely by CD97 EGF domains and CD55 SCR domains, is Ca2+-dependent and unaffected by EGF-domain glycosylation [PMID:11297558]. The CD97-related EMR2 binds CD55 with a K(D) at least an order of magnitude weaker [PMID:11297558].","affinity_potency":[{"value":"86 microm","assay":"binding dissection; assay not named for this value in abstract (SPR used elsewhere in the study)","system":"CD97 EGF and CD55 SCR modules","cite":"PMID:11297558"}],"species_and_systems":"Human proteins and cells in PMID 9064337 and 11297558; a mouse CD97-murine DAF interaction study is also listed [PMID:10540231]. Structure PDB 7DO4 exists [DB:PDB 7DO4].","localisation_and_range":"Both are membrane proteins by flags (also flagged secreted) [flag]; erythrocytes and lymphocytes adhered to CD97-transfected COS cells, so cell-contact adhesion [PMID:9064337].","caveats":"Affinity is low with fast off-rate (at least 0.6 s(-1)) [PMID:11297558]. PMID 12417446 is expression-based and only asserts the binding from earlier work. All papers abstract-level; the mouse paper abstract is truncated in the dossier. Reactome and IntAct also record it [DB:Reactome][DB:IntAct].","key_references":[{"PMID":"9064337","why":"First cellular ligand for CD97: CD55, specificity controls"},{"PMID":"11297558","why":"Domain dissection, affinity and Ca2+ dependence"},{"PMID":"10540231","why":"Mouse CD97 and murine DAF interaction"}],"covers":["LR000287"]},"LR001727":{"pair":"CD6 -> ALCAM","headline":"Established heterophilic CD6-CD166 binding backed by structures, SPR mutagenesis and database records.","interaction_type":"direct binding","direction_and_effect":"CD6 membrane-proximal domain binds the N-terminal IgSF domain of CD166 (ALCAM); the interaction regulates T-cell activation [PMID:26146185]. Heterodimers form at the expense of CD6 and CD166 homodimers [PMID:26146185].","molecular_requirements":"CD6 domain 3 carries the CD166 binding face; domains 1 and 2 made no detectable difference to CD166 binding by SPR [PMID:26146185]. CD166 domain 1 is the binding site [PMID:26146185].","affinity_potency":[],"species_and_systems":"Human recombinant proteins, crystal structures and SPR; human CD166 reported to bind human, mouse and rat CD6 with the same affinity (data not shown) [PMID:26146185]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both transmembrane by flags (also flagged secreted) [flag]; cell-cell contact interaction.","caveats":"The CD6 SNP S351N adds glycosylation and weakens CD166 binding 10-fold [PMID:26146185]. No Kd is given in the shown text. Only one of two confirmed papers is displayed. Database support: BioGRID, IntAct, UniProt [DB:BioGRID][DB:IntAct][DB:UniProt].","key_references":[{"PMID":"26146185","why":"Crystal structures, binding site mapping, homophilic competition"}],"covers":["LR001727","LR005092"]},"LR005093":{"pair":"CD80 -> CD274","headline":"CD80 and PD-L1 interact according to databases and one mouse tumour study showing trans interaction; the literature on cis versus trans is conflicted.","interaction_type":"conflicting","direction_and_effect":"Blocking PD-L1/CD80 interactions in mice augmented antitumour immunity by expanding IFN-gamma-producing CD8+ T cells and IFN-gamma-dependent NOS2-expressing tumour-associated macrophages [PMID:37036990]. The paper reports that cis PD-L1/CD80 interactions may have the opposite effect on antitumour immunity, with a net benefit of blockade [PMID:37036990]. UniProt notes this interaction blocks PD-L1/PD-1 binding [DB:UniProt]. Which partner is ligand is not defined; both are annotated as receptors [flag].","molecular_requirements":"Trans interaction effects required tumour MHC-I expression and T-cell CD28 expression [PMID:37036990].","affinity_potency":[],"species_and_systems":"Mouse tumour models (MC38 and B16) for the paper [PMID:37036990]; the mouse pair is the direct one and the human pair is ortholog-inferred. Databases include surface plasmon resonance, protein array and cross-linking records [DB:IntAct] and a structure [DB:PDB 7TPS].","localisation_and_range":"Both partners are annotated as secreted, receptor and transmembrane [flag]. The paper concerns cell-cell (trans) contact between tumour and T cells, versus same-cell (cis) contact on antigen-presenting cells [PMID:37036990].","caveats":"Only one paper, read as an abstract with full-text excerpts. Previous reports claimed that only cis interactions exist, which this paper disputes [PMID:37036990]. The paper used antibody blockade and genetically engineered mice, not a binding assay. No affinity in our evidence. Species of the experiment is not listed in the curator fields.","key_references":[{"PMID":"37036990","why":"Mouse study showing trans PD-L1/CD80 interactions and the effect of blockade"}],"covers":["LR001728","LR005093"]},"LR001736":{"pair":"CD99 -> PILRA","headline":"CD99 is a glycosylated ligand for PILR-alpha, shown by SPR with a Kd of about 2.2 \u03bcM.","interaction_type":"direct binding","direction_and_effect":"Inhibitory PILR-alpha binds CD99 with low affinity; activating PILR-beta binds about 40 times more weakly [PMID:18234675]. Reactome records PILRA,PILRB binding CD99 [DB:Reactome].","molecular_requirements":"Requires CD99 O-glycosylation; PILR-alpha binds each of the two O-glycosylated sites (Thr-45, Thr-50) independently and equivalently [PMID:18234675].","affinity_potency":[{"value":"Kd approximately 2.2 \u03bcM","assay":"SPR","system":"PILRalpha with CD99, human","cite":"PMID:18234675"}],"species_and_systems":"Human recombinant proteins, SPR [PMID:18234675]; mouse pair is the record's other species.","localisation_and_range":"Membrane-bound CD99; contact-dependent.","caveats":"Abstract only; low affinity with fast dissociation [PMID:18234675].","key_references":[{"PMID":"18234675","why":"SPR of PILR-CD99 binding"}],"covers":["LR001736","LR005101"]},"LR005606":{"pair":"CDH11 -> CDH8","headline":"Cadherin-11 and cadherin-8 are a preferred heterophilic type II cadherin pair in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On the cadherin-8 surface, cadherin-11 gave the strongest observed interaction, followed by homophilic cadherin-8 binding [PMID:29742438].","molecular_requirements":"They form one specificity group and prefer heterophilic binding to each other over all other cadherins [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"Heterophilic cadherin-8/-11 SPR"}],"covers":["LR002308","LR005606"]},"LR005615":{"pair":"CDH6 -> CDH10","headline":"Type II cadherin heterophilic pair: cadherin-6 binds cadherin-10 in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On cadherin-6 surfaces cadherin-6 analyte was strongest, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002317","LR005615"]},"LR006812":{"pair":"CDNF -> HSPA5","headline":"Single abstract-level co-IP report of direct CDNF-HSPA5 binding, with GtoPdb and PDB records; no affinity reported.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation showed a direct CDNF-HSPA5 interaction; HSPA5 overexpression counteracted CDNF's suppression of astrocyte and CD8+ T-cell activation, so the effect is inhibitory and HSPA5-dependent [PMID:41504843]. GtoPdb lists a Binding action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the two partners; PDB lists two structures containing a chain of each partner [DB:PDB 9H0C] [DB:PDB 9I5Y].","affinity_potency":[],"species_and_systems":"Human CDNF and HSPA5 (curated); CDNF was delivered via exosomes from overexpressing BMSCs, with in vivo work in a rat chronic constriction injury model [PMID:41504843].","localisation_and_range":"Not reported in our evidence beyond the exosome-delivery context [PMID:41504843].","caveats":"Only one paper, read as abstract only; the co-IP does not show whether other factors are needed. No affinity reported.","key_references":[{"PMID":"41504843","why":"Co-IP of CDNF-HSPA5 and HSPA5-dependent immunosuppression"}],"covers":["LR006812"]},"LR005624":{"pair":"CELSR3 -> CELSR3","headline":"Homophilic CELSR3 interaction implied by one neurite-growth paper; no direct binding assay in our evidence.","interaction_type":"functional only","direction_and_effect":"Celsr3 was activated by homophilic interaction but suppressed neurite growth, opposite to Celsr2 [PMID:17618280]. Effect direction differs between the two paralogues [PMID:17618280].","molecular_requirements":"Opposite functions of Celsr2 and Celsr3 trace to a single amino acid difference in the transmembrane domain; signalling may involve second messengers [PMID:17618280].","affinity_potency":[],"species_and_systems":"Rat neuron coculture and gene silencing; the curator labels the experiment species as mouse, which conflicts with the rat neurons named in the assay text [PMID:17618280].","localisation_and_range":"Membrane-bound seven-pass cadherin, so homophilic contact (juxtacrine) [flag] [PMID:17618280].","caveats":"Abstract only; no binding measurement or database record. One additional review-only row not shown. Paralog issue: the same paper covers CELSR2 and CELSR3 with opposing effects.","key_references":[{"PMID":"17618280","why":"Celsr2 and Celsr3 homophilic activation with opposing neurite effects"}],"covers":["LR002335","LR005624"]},"LR000296":{"pair":"CGA -> FSHR","headline":"FSH (CGA alpha chain with FSHB) binds FSHR; structure and photoaffinity labeling support it, but CGA is only one chain.","interaction_type":"direct binding","direction_and_effect":"A 2.9-A crystal structure shows human FSH bound to the FSHR extracellular hormone-binding domain, with a conformational change implicated in activation [PMID:15662415]. A peptide mimic of FSHR exoloop 3 photoaffinity-labeled FSH alpha but not FSH beta [PMID:12374801]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Functional ligand is the CGA:FSHB heterodimer; UniProt describes FSHR binding the CGA/FSHB heterodimer [DB:UniProt]. CGA is shared with LH, hCG and TSH [PMID:12374801].","affinity_potency":[],"species_and_systems":"Human proteins; abstract-only papers [PMID:15662415] [PMID:12374801]. Mouse pair is ortholog-inferred.","localisation_and_range":"CGA is flagged secreted; FSHR is transmembrane [flag].","caveats":"Specificity comes from the beta chain, not CGA alone. No affinity reported (GtoPdb units '-') [DB:GtoPdb]. Structures: [DB:PDB 1XWD] [DB:PDB 4AY9]. Two further judged rows not shown, one pending.","key_references":[{"PMID":"15662415","why":"Crystal structure of FSH bound to FSHR ectodomain"},{"PMID":"12374801","why":"FSHR exoloop 3 labels the FSH alpha subunit"}],"covers":["LR000296","LR003803"]},"LR002339":{"pair":"CGB1 -> LHCGR","headline":"CGB1 as half of hCG on LHCGR: one paper on LH/hCG, not specific to this beta gene.","interaction_type":"direct binding","direction_and_effect":"LH and hCG bound wild-type and exon-10-deleted LHR with similar affinity; exon 10 deletion impaired LH but not hCG action [PMID:12727981]. Effect labelled agonist.","molecular_requirements":"LH and hCG are heterodimers of CGA with LHB or CGB, so a single beta-subunit entity is half of the hormone [PMID:12727981].","affinity_potency":[],"species_and_systems":"Human LHR in stable COS-7 cells [PMID:12727981].","localisation_and_range":"Secreted ligand [flag].","caveats":"Abstract only; paper does not name CGB1 specifically; no affinity value; no database records.","key_references":[{"PMID":"12727981","why":"LH and hCG bind LHR with similar affinity; exon 10 affects activation"}],"covers":["LR002339"]},"LR003806":{"pair":"CHAD -> ITGA2","headline":"Chondroadherin binds integrin alpha2beta1 by affinity purification; the evidence is for the heterodimer, not ITGA2 alone.","interaction_type":"direct binding","direction_and_effect":"Annotated stimulatory [flag]. Adhesion of cells to chondroadherin was partially inhibited by an anti-alpha2 antibody (per curator note) and alpha2beta1 was identified as a chondroadherin-binding integrin [PMID:9281592].","molecular_requirements":"The identified receptor is the alpha2beta1 heterodimer; ITGB1 is required as partner in the evidence. Adhesion needed Mg2+ or Mn2+ but not Ca2+ [PMID:9281592].","affinity_potency":[],"species_and_systems":"Affinity purification of cell-surface proteins on chondroadherin-Sepharose; the abstract and excerpts describe bovine chondrocytes, while the curator note describes human fibroblasts [PMID:9281592].","localisation_and_range":"Chondroadherin is a cartilage matrix protein flagged secreted [flag][PMID:9281592]; likely matrix-bound adhesion ligand.","caveats":"Evidence is from a single 1997 paper read as abstract (full-text excerpts available). No affinity reported. Species in the paper is inconsistent between abstract (bovine) and curator note (human).","key_references":[{"PMID":"9281592","why":"Chondroadherin affinity purification identifies alpha2beta1"}],"covers":["LR000300","LR003806"]},"LR002348":{"pair":"CLCF1 -> SORL1","headline":"SorLA binds the CLC:CLF-1 heterodimer through CLF-1, with nanomolar affinity by SPR; it acts as an endocytic regulator rather than a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"CLC:CLF-1 bound immobilised sorLA by surface plasmon resonance, and sorLA can downregulate the CNTFR-alpha pool; the curator labels the effect antagonist [PMID:26858303]. sorLA may also concentrate the tripartite complex on membranes [PMID:26858303].","molecular_requirements":"Binding is via CLF-1: CLC alone did not engage sorLA, and binding was blocked by sorLA propeptide and RAP, indicating the Vps10p-D beta-propeller [PMID:26858303]. The CLC:CLF-1:CNTFR-alpha tripartite complex links to sorLA [PMID:26858303].","affinity_potency":[{"value":"Kd 5 \u00b1 2.9 nM","assay":"SPR, CLC:CLF-1 on immobilised soluble sorLA","system":"purified proteins","cite":"PMID:26858303"},{"value":"Kd 0.3 \u00b1 0.3 nM","assay":"SPR, CLC:CLF-1 to sCNTFR-alpha (comparison)","system":"purified proteins","cite":"PMID:26858303"}],"species_and_systems":"Human proteins, recombinant; SH-SY5Y cells used for pSTAT3 [PMID:26858303]. Mouse pair is ortholog-inferred.","localisation_and_range":"sorLA is flagged a transmembrane receptor and the ligand secreted [flag]; sorLA also binds the soluble complex.","caveats":"Ligand entity is the CLC:CLF-1 heterodimer; the binding site is on CLF-1 (CRLF1), so CLCF1 alone is not shown to bind. IntAct lists the SPR record [DB:IntAct].","key_references":[{"PMID":"26858303","why":"SPR binding of CLC:CLF-1 to sorLA via CLF-1"}],"covers":["LR002348","LR005630"]},"LR005633":{"pair":"CLEC4G -> TYROBP","headline":"LSECtin associates with DAP12 (TYROBP) as a signalling partner in human DCs; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"LSECtin associates with DAP12 and signals via Syk; anti-LSECtin mAb or Ebola GP induces TNF-\u03b1 and IL-6, abolished by LSECtin silencing [PMID:26943817]. TYROBP is the signalling adaptor, so this is a receptor-adaptor association rather than a classical ligand binding to a receptor.","molecular_requirements":"DAP12 is required: LSECtin failed to induce TNF-\u03b1 and IL-6 in DAP12-knockdown MDDCs; mutation of key tyrosines in the DAP12 ITAM abrogated signalling; the LSECtin transmembrane region (amino acids 32-43) was required for the association [PMID:26943817].","affinity_potency":[],"species_and_systems":"Human MDDCs, HEK293 co-IP, and Jurkat transfectants [PMID:26943817]. Mouse pair is ortholog-inferred.","localisation_and_range":"CLEC4G is not flagged secreted [flag]; membrane-bound receptor on myeloid cells.","caveats":"Co-immunoprecipitation shows association of LSECtin with DAP12; this is not a ligand-receptor binding by an extracellular ligand. The paper's ligand for LSECtin is Ebola GP, and one mutation pair (N256D, N274D) abolished GP1-Fc binding [PMID:26943817].","key_references":[{"PMID":"26943817","why":"LSECtin associates with DAP12 and signals through Syk"}],"covers":["LR002352","LR005633"]},"LR002357":{"pair":"CLU -> LRP2","headline":"Clusterin binds LRP2/megalin (gp330) directly with Kd 14.2 nM and is endocytosed; two abstract-only papers plus database records.","interaction_type":"direct binding","direction_and_effect":"gp330 (LRP2) bound apoJ/clusterin with high affinity, and only gp330-expressing cells endocytosed and degraded 125I-apoJ, so LRP2 acts as an uptake receptor [PMID:7768901]. A second paper reports a separate LRP-2 binding class on clusterin [PMID:11772027].","molecular_requirements":"LRP (LRP1) showed no binding to apoJ in either assay type, so the binding is gp330-specific; competed by apoE, lipoprotein lipase and RAP [PMID:7768901]. Clusterin has three independent binding-site classes, one for LRP-2; recombinant Pichia clusterin with truncated alpha C-terminus and beta N-terminus still used it [PMID:11772027].","affinity_potency":[{"value":"Kd 14.2 nM","assay":"solid-phase binding assay","system":"purified gp330 and apoJ (human milk-derived apoJ)","cite":"PMID:7768901"}],"species_and_systems":"Human clusterin and receptor per the dossier [PMID:7768901][PMID:11772027]; cultured cell lines and F9 cells for uptake.","localisation_and_range":"Clusterin is flagged secreted [flag]; receptor-mediated endocytosis by epithelial cells [PMID:7768901].","caveats":"Both papers abstract-only. Databases: BioGRID (reconstituted complex) and UniProt list the interaction [DB:BioGRID 298080][DB:UniProt P10909]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"7768901","why":"gp330 binds apoJ, Kd 14.2 nM, and mediates endocytosis; LRP1 does not bind"},{"PMID":"11772027","why":"Clusterin has a discrete LRP-2 binding site"}],"covers":["LR002357","LR005637"]},"LR005642":{"pair":"CNIH2 -> GRIA1","headline":"CNIH2 is an AMPA receptor auxiliary partner; GluA1 specifically required, shown by knockout and co-IP; one full-text paper.","interaction_type":"functional only","direction_and_effect":"CNIH-2 and CNIH-3 deletion eliminated surface GluA1-containing AMPARs and reduced synaptic transmission; CNIH-2 knock-down had no effect in GluA1 KO slices [PMID:23522044]. This is an auxiliary-subunit trafficking relationship, not a secreted ligand.","molecular_requirements":"GluA1 is required: CNIH-2 co-immunoprecipitated with GluA1 from GluA2 KO lysates but not with GluA2 from GluA1 KO lysates; TARP \u03b3-8 probably prevents CNIH association with non-GluA1 subunits [PMID:23522044].","affinity_potency":[],"species_and_systems":"Mouse hippocampal slices and neurons; rat dissociated neurons for shRNA; HEK cells [PMID:23522044]. Dossier lists the species as human; mouse pair is the non-inferred one.","localisation_and_range":"Neither partner flagged secreted [flag]; intracellular and membrane trafficking partnership in neurons, not intercellular signalling.","caveats":"The dossier effect 'agonist' reflects the full text: CNIH slows AMPAR deactivation in heterologous cells [PMID:23522044]. BioGRID, Reactome and UniProt records exist [DB:BioGRID 3339420][DB:UniProt P42261]. Should not be treated as a cell-cell ligand-receptor pair.","key_references":[{"PMID":"23522044","why":"CNIH-2/-3 determine surface GluA1-containing AMPARs"}],"covers":["LR002362","LR005642"]},"LR001754":{"pair":"CNTN1 -> PTPRZ1","headline":"Well-supported direct binding with a cocrystal structure; PTPRZ binds CNTN1 specifically and the complex affects oligodendrocyte maturation.","interaction_type":"direct binding","direction_and_effect":"PTPRZ carbonic-anhydrase-like domain binds CNTN1 Ig repeats, and PTPRZ-CNTN1 binding inhibits OPC proliferation and promotes maturation into oligodendrocytes (effect recorded as antagonist) [PMID:21969550].","molecular_requirements":"The carbonic anhydrase-like domain of PTPRZ binds the second and third Ig repeats of CNTN1 [PMID:20133774][PMID:21969550]. PTPRZ binds only CNTN1 among contactins [PMID:20133774]. Tenascin-C and PTPzeta/RPTPbeta both bind F3, possibly exclusively [PMID:10103110].","affinity_potency":[],"species_and_systems":"Human proteins in crystal structures [PMID:20133774][PMID:21969550]; mouse brain affinity isolation [PMID:10103110]; PTPRZ-deficient mice for OPC analysis [PMID:21969550]. PDB 3S97 and IntAct X-ray record the complex [DB:PDB 3S97][DB:IntAct].","localisation_and_range":"CNTN1 is surface-expressed on OPCs (contact-mediated) [PMID:21969550]; PTPRZ1 carries secreted and transmembrane flags [flag].","caveats":"All papers are abstract-only. Affinity is described as highest for F3-PTPzeta/RPTPbeta in one paper but no number is reported [PMID:10103110].","key_references":[{"PMID":"21969550","why":"Cocrystal structure and OPC function"},{"PMID":"20133774","why":"Structures and CNTN specificity"},{"PMID":"10103110","why":"F3 binds PTPzeta/RPTPbeta directly"}],"covers":["LR001754","LR005112"]},"LR003815":{"pair":"CNTN2 -> CNTN1","headline":"Heterophilic TAG-1/F3 binding is conditional: absent between soluble proteins, seen only when TAG-1 is membrane-presented.","interaction_type":"direct binding","direction_and_effect":"Soluble F3 (CNTN1)-Fc did not bind soluble preclustered TAG-1-Fc, but bound TAG-1 when it was presented in membrane-associated form [PMID:12139915]. Effect direction recorded as agonist.","molecular_requirements":"Binding requires TAG-1 in membrane-associated form [PMID:12139915]. In bead assays TAG-1-Fc did not form mixed aggregates with F3-Fc beads [PMID:12139915].","affinity_potency":[],"species_and_systems":"Human proteins, Fc-chimeric beads and transfected CHO cells [PMID:12139915]. Mouse pair is inferred.","localisation_and_range":"CNTN2 is flagged secreted and CNTN1 transmembrane [flag]; the paper's data indicate membrane-bound contact-dependent binding [PMID:12139915].","caveats":"A single paper; its own bead assay is negative for the soluble pair. The 'agonist' label has no functional readout in our evidence.","key_references":[{"PMID":"12139915","why":"Conditional TAG-1 binding to F3"}],"covers":["LR000309","LR003815"]},"LR002366":{"pair":"CNTN2 -> CNTN2","headline":"Homophilic CNTN2 self-association shown by bead aggregation in one paper.","interaction_type":"direct binding","direction_and_effect":"TAG-1-Fc displays homophilic interactions by forming self-aggregates of moderate size (14 beads) [PMID:12139915]. Isolated Ig domains gave few small aggregates [PMID:12139915].","molecular_requirements":"Fibronectin repeats mediate homophilic aggregation by the abstract's statement [PMID:12139915].","affinity_potency":[],"species_and_systems":"Human TAG-1 Fc chimeras on beads [PMID:12139915]. Mouse pair inferred.","localisation_and_range":"Adhesion in trans between cells (paper context); CNTN2 carries a secreted flag [flag].","caveats":"Single paper; self-binding, so ligand/receptor direction is not meaningful. No affinity reported.","key_references":[{"PMID":"12139915","why":"TAG-1 bead homophilic aggregation"}],"covers":["LR002366","LR005646"]},"LR005651":{"pair":"CNTN5 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN5; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN5 is annotated secreted and PTPRG non-secreted [flag].","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN5 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR002371","LR005651"]},"LR009116":{"pair":"COL11A1 -> DDR1","headline":"A purified type V/XI hybrid collagen binds DDR1; COL11A1 is one component, so the evidence is for the hybrid, not COL11A1 alone.","interaction_type":"direct binding","direction_and_effect":"The DDR ligand purified from A204 cells was a hybrid collagen of two a1(XI) chains and one a2(V) chain and showed marked binding to DDR1 and DDR2; commercial human type V collagen also induced DDR1 phosphorylation [PMID:9659900].","molecular_requirements":"The binding activity resides in the hybrid type V/XI preparation; COL11A1 a1 chains are part of it, but COL11A1 homotrimer activity is not reported in our evidence [PMID:9659900].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; cells in culture and purified collagen [PMID:9659900].","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag]; it is a matrix ligand.","caveats":"Evidence is for a hybrid collagen, not COL11A1 alone. Some commercial collagens lacked detectable activity, which the authors attribute to inactivation during purification or storage [PMID:9659900].","key_references":[{"PMID":"9659900","why":"Collagens as DDR ligands, including the type V/XI hybrid"}],"covers":["LR009116"]},"LR002375":{"pair":"COL11A1 -> DDR2","headline":"DDR2 mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI; one abstract-level functional paper.","interaction_type":"functional only","direction_and_effect":"DDR2 and integrin a2b1, but not integrin a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024]. Collagen XI in collagen I matrices inhibited CAF-mediated remodeling and migration [PMID:36233024].","molecular_requirements":"DDR2 is one of two receptors identified; neither was shown alone to be sufficient in our evidence [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs from non-small cell lung cancer settings; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the abstract says collagen type XI without naming the chain (COL11A1 or COL11A2), and the binding is a cell-based readout rather than purified-protein binding [PMID:36233024].","key_references":[{"PMID":"36233024","why":"DDR2 and a2b1 mediate CAF binding to collagen XI"}],"covers":["LR002375","LR005654"]},"LR005660":{"pair":"COL17A1 -> LAIR1","headline":"Direct binding of LAIR-1 to collagen XVII shown in one full-text paper; inhibitory receptor, human with cross-species binding.","interaction_type":"direct binding","direction_and_effect":"Collagen XVII is a ligand for LAIR-1: human, rat and mouse LAIR-1-IgG bound collagen XVII-transfected Ba/F3 cells, blocked by anti-LAIR-1 antibodies [PMID:16754721]. LAIR-1 cross-linking is known to inhibit immune cell function, and collagens directly inhibit immune cell activation in vitro; the curator records this as antagonist [PMID:16754721].","molecular_requirements":"Binding depends on the conserved Gly-Pro-Hyp collagen repeat, so the effect is pan-collagen rather than specific to this chain; binding was divalent-cation independent [PMID:16754721]. LAIR-2 also bound collagen XVII [PMID:16754721]. Subunit requirements for LAIR-1 beyond the single chain: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human collagen XVII and LAIR-1-IgG fusion proteins on transfected Ba/F3 and K562 cells; mouse and rat LAIR-1 bound human collagen XVII, so the mouse pair is inferred from human evidence [PMID:16754721]. Affinity values in this paper (surface plasmon resonance) were for collagens I and III, not collagen XVII.","localisation_and_range":"Collagen XVII is a transmembrane collagen in this paper (cell-surface ligand on transfected cells); the entity flag lists it as secreted [flag] [PMID:16754721]. Cells expressing collagen XVII and LAIR-1 formed aggregates, consistent with contact-dependent signalling [PMID:16754721].","caveats":"Single paper. No affinity measured for collagen XVII itself. The curator notes the evidence is motif-level and shared by all collagen rows.","key_references":[{"PMID":"16754721","why":"Collagen XVII binds LAIR-1; Gly-Pro-Hyp dependent; inhibitory function"}],"covers":["LR002381","LR005660"]},"LR003824":{"pair":"COL18A1 -> GPC4","headline":"Endostatin (collagen XVIII fragment) binds glypicans as a low-affinity, heparan sulfate-dependent receptor in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Alkaline phosphatase-tagged endostatin bound glypican-1 and glypican-4 overexpressed in NIH 3T3 cells; glypicans were identified as lower-affinity endostatin receptors, with antisense data suggesting they mediate endostatin activity [PMID:11336704]. The authors propose glypican acts as a presenting co-receptor passing endostatin to a high-affinity receptor [PMID:11336704]. Curator records agonist.","molecular_requirements":"Heparan sulfate chains are critical for binding; heparinase or salt treatment reduced binding, and GPI-linkage matters (PI-PLC reduces binding) [PMID:11336704]. The ligand acting is endostatin, the collagen XVIII fragment, not intact COL18A1 [PMID:11336704].","affinity_potency":[{"value":"Kd 200 pM","assay":"Scatchard analysis of AP-endostatin binding (lower-affinity site)","system":"cow pulmonary arterial endothelial (CPAE) cells","cite":"PMID:11336704"}],"species_and_systems":"Human and mouse endostatin tested; curator records human ligand and human GPC4 sequence. Binding quantified in cow endothelial cells and NIH 3T3 overexpressing cells; human and mouse pair rows partly ortholog-projected [PMID:11336704].","localisation_and_range":"Receptor is a GPI-anchored cell-surface proteoglycan [PMID:11336704] (entity flag lists it as secreted [flag]). Ligand is a secreted fragment, so action is paracrine or autocrine.","caveats":"Low affinity and glycan-mediated, so other heparan sulfate proteoglycans may bind similarly. The paper contrasts earlier work showing heparinase-resistant binding in situ [PMID:11336704]. Only one paper.","key_references":[{"PMID":"11336704","why":"Glypicans identified as low-affinity endostatin receptors"}],"covers":["LR000318","LR003824"]},"LR003833":{"pair":"COL1A1 -> ITGA2","headline":"Type I collagen binds integrin alpha2 (alpha2beta1) directly by SPR with sub-micromolar Kd; supported by functional papers, some abstract-only.","interaction_type":"direct binding","direction_and_effect":"Collagen engagement of alpha2beta1 supports platelet adhesion (both alpha1(I) and alpha2(I) chains) [PMID:2156854] and ITGA2-collagen interaction drives ovarian cancer peritoneal metastasis [PMID:33026975]. The stimulatory effect is the annotated modulatory effect.","molecular_requirements":"Recombinant alpha2 I-domain alone bound type I collagen in SPR [PMID:16043429]. The binding entity in functional papers is the alpha2beta1 heterodimer [PMID:2156854]; ITGA2 is stored here without ITGB1.","affinity_potency":[{"value":"Kd 0.3 uM (range 0.15-1.75 uM)","assay":"SPR (BIAcore), two affinity classes","system":"recombinant human alpha2 I-domain, purified fibrillar collagen I","cite":"PMID:16043429"}],"species_and_systems":"Human recombinant I-domain SPR [PMID:16043429]; human platelets [PMID:2156854]; bovine chondrocyte membranes on collagen-Sepharose [PMID:7688313]; human ovarian cancer cells and patient material [PMID:33026975]. Mouse pair is ortholog-inferred.","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Chain-level: whole-collagen assays do not separate COL1A1 from COL1A2. PMID:7688313, PMID:2156854 and PMID:33026975 were read as abstracts (33026975 also has full-text excerpts); the PMID:33026975 abstract refers to 'collagens' as a class. In PMID:7688313 alpha2 was not visualised in human fetal cartilage sections, so the authors question its need in intact cartilage. BioGRID lists co-purification from PMID:2156854 [DB:BioGRID].","key_references":[{"PMID":"16043429","why":"SPR binding of alpha2 I-domain to collagen I with Kd"},{"PMID":"2156854","why":"Platelet adhesion via alpha2beta1 to collagen I chains"},{"PMID":"33026975","why":"ITGA2-collagen interaction in ovarian cancer metastasis"}],"covers":["LR000327","LR003833"]},"LR002384":{"pair":"COL1A1 -> LAIR1","headline":"Collagens, including type I, are high-affinity ligands of inhibitory LAIR-1; one paper plus a BioGRID complex record.","interaction_type":"direct binding","direction_and_effect":"Collagens are high-affinity ligands for the inhibitory receptor LAIR-1, and LAIR-1 cross-linking inhibits immune cell function; recorded as antagonist [PMID:16754721].","molecular_requirements":"Depends on the conserved Gly-Pro-Hyp collagen repeats, shared across collagens [PMID:16754721].","affinity_potency":[],"species_and_systems":"Human leukocytes and purified collagens; human, rat and mouse LAIR-1-IgG bound transfected cells in the full-text excerpts [PMID:16754721]. Reconstituted complex in BioGRID [DB:BioGRID].","localisation_and_range":"LAIR1 is flagged transmembrane [flag]; COL1A1 secreted/matrix [flag], so contact-dependent with matrix.","caveats":"Abstract-level read (full text available). Paper concerns collagens generally; the excerpt shown highlights collagen XVII. No affinity value in our evidence. COL1A1 is not separated from COL1A2.","key_references":[{"PMID":"16754721","why":"Collagens are high-affinity ligands for LAIR-1"}],"covers":["LR002384","LR005663"]},"LR003842":{"pair":"COL2A1 -> ITGA1","headline":"SPR shows recombinant alpha1 I domain binds collagen II with micromolar-to-submicromolar affinity; alpha1 chain only, no beta1 tested.","interaction_type":"direct binding","direction_and_effect":"Recombinant integrin alpha1 I domain bound fibrillar collagen types I-III, including type II, with similar affinities [PMID:16043429]. Direction: collagen to integrin; the dossier carries a 'Stimulatory' label [flag].","molecular_requirements":"Only the isolated alpha1 I domain was tested; beta1 co-expression or requirement is not reported in our evidence [PMID:16043429]. Collagen I was the assembled heterotrimer; II and III are homotrimers.","affinity_potency":[{"value":"KD1 0.15-0.32 uM; KD2 5.5-7.3 uM","assay":"SPR (BIAcore), alpha1 I domain over collagens I-III","system":"recombinant human proteins","cite":"PMID:16043429"}],"species_and_systems":"Recombinant human I domains and purified collagens [PMID:16043429]; the mouse pair is ortholog-inferred.","localisation_and_range":"Collagen is a secreted matrix protein [flag]; binding is to ECM (inferred).","caveats":"Full text read. The two KD values are two affinity classes reported across the three collagen types, not specific to collagen II. A second confirmed paper is counted but not shown; one abstract was insufficient.","key_references":[{"PMID":"16043429","why":"SPR of alpha1 I domain to collagens I-III with KDs"}],"covers":["LR000336","LR003842"]},"LR002393":{"pair":"COL3A1 -> LAIR1","headline":"Collagens, including III, are high-affinity ligands of inhibitory receptor LAIR-1; full text shows binding to collagens I and III.","interaction_type":"direct binding","direction_and_effect":"Collagens are high-affinity LAIR-1 ligands and directly inhibit immune cell activation in vitro [PMID:16754721]. hLAIR-1 IgG bound collagens I and III by BIAcore, and both human and mouse LAIR-1 IgG immunoprecipitated human collagen III [PMID:16754721]. Curator label: antagonist (inhibitory receptor).","molecular_requirements":"Interaction depends on the conserved Gly-Pro-Hyp repeats; a single triple-helical collagen III molecule interacted with about 9.7 LAIR-1 proteins [PMID:16754721]. No co-receptor reported.","affinity_potency":[],"species_and_systems":"Human LAIR-1 IgG; mouse and rat LAIR-1 IgG also tested; K562, RBL-2H3 and Ba/F3 transfectants [PMID:16754721]; mouse pair projected.","localisation_and_range":"LAIR1 flagged transmembrane, not secreted; collagen III is a secreted matrix ligand [flag].","caveats":"Pan-collagen motif, not a collagen III-specific interaction. A numeric affinity is not given in the excerpt. A second confirmed paper is counted but not shown.","key_references":[{"PMID":"16754721","why":"Collagens are high-affinity LAIR-1 ligands"}],"covers":["LR002393","LR005672"]},"LR003851":{"pair":"COL4A1 -> ITGA2","headline":"Collagen-integrin alpha2 link supported by a functional ovarian cancer paper that does not separate collagen chains.","interaction_type":"functional only","direction_and_effect":"ITGA2 on ovarian cancer cells triggers adhesion to collagen, migration and peritoneal metastasis; ITGA2-collagen interaction drives this [PMID:33026975].","molecular_requirements":"The binding entity is the ITGA2:ITGB1 heterodimer per the curator note; ITGA2 is stored alone [PMID:33026975].","affinity_potency":[],"species_and_systems":"Human ovarian cancer cell lines (gene-edited) and patient samples, plus in vivo metastasis [PMID:33026975].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"The paper says 'collagens' as a class, so COL4A1 is not separated from COL1/COL3 chains; COL4A1 is only noted as expressed in cancer cells. Evidence is functional, not direct binding. Two other papers were abstract_insufficient.","key_references":[{"PMID":"33026975","why":"ITGA2-collagen adhesion drives ovarian cancer peritoneal metastasis"}],"covers":["LR000345","LR003851"]},"LR010664":{"pair":"COL4A3 -> ITGAV:ITGB8","headline":"Weak: tumstatin paper names alphaVbeta3, not ITGB8; this complex is not evidenced.","interaction_type":"functional only","direction_and_effect":"Col IValpha3-null mice show accelerated tumour growth rescued by tumstatin, which requires alphaVbeta3 integrin [PMID:12842087].","molecular_requirements":"The abstract names alphaVbeta3, not ITGB8, so the ITGAV:ITGB8 complex is not supported by this paper [PMID:12842087].","affinity_potency":[],"species_and_systems":"Mouse knockout models [PMID:12842087].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; no binding assay; ITGB8 not mentioned; one other paper was abstract_insufficient. Treat as unsupported.","key_references":[{"PMID":"12842087","why":"Tumstatin acts via alphaVbeta3, not ITGB8"}],"covers":["LR010664"]},"LR000359":{"pair":"COL5A1 -> SDC3","headline":"Likely mis-assigned: syndecan-3 binding is to the alpha4(V) chain N-terminal domain in rat cells.","interaction_type":"direct binding","direction_and_effect":"Syndecan-3 was isolated by affinity chromatography on immobilised alpha4(V) N-terminal domain, supporting Schwann cell adhesion [PMID:11751872].","molecular_requirements":"Binding depends on a heparan sulfate / heparin-binding region of alpha4(V)-NTD absent in other type V collagen NTDs [PMID:11751872].","affinity_potency":[{"value":"IC50 ~30 ng/ml","assay":"heparin inhibition of Schwann cell adhesion","system":"rat Schwann cells on alpha4(V)-NTD","cite":"PMID:11751872"}],"species_and_systems":"Rat Schwann cells [PMID:11751872]; human and mouse pairs are projections.","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"The relevant chain is alpha4(V), not COL5A1; heparin inhibited adhesion with IC50 ~30 ng/ml [PMID:11751872]. Abstract only.","key_references":[{"PMID":"11751872","why":"Schwann cell syndecan-3 binds alpha4(V) NTD"}],"covers":["LR000359","LR003865"]},"LR009062":{"pair":"COL9A3 -> MAG","headline":"Old solid-phase study shows soluble MAG binds collagen type IX; COL9A3 chain-level specificity is not resolved.","interaction_type":"direct binding","direction_and_effect":"Soluble MAG binds several collagens including type IX, with a kd of 5.7 X 10(-8) M for collagen type IX [PMID:2446864]. Binding of labelled MAG to collagen G was inhibited by unlabeled MAG and collagen G but not heat-denatured collagen [PMID:2446864]. Direction is receptor-to-collagen binding; signaling effect is not reported.","molecular_requirements":"The paper tested collagen type IX as a whole; whether the COL9A3 chain, or the intact heterotrimer, is required is not reported in our evidence [PMID:2446864].","affinity_potency":[{"value":"kd of 5.7 X 10(-8) M","assay":"solid-phase binding of soluble MAG to purified collagen type IX","system":"MAG from adult mouse brain","cite":"PMID:2446864"}],"species_and_systems":"Soluble MAG from adult mouse brain with purified collagens; the pair is listed as human [PMID:2446864].","localisation_and_range":"MAG flagged secreted and receptor [flag]; soluble MAG binds heparin and collagens, consistent with matrix binding [PMID:2446864].","caveats":"Single 1987 abstract; binding to type IX, not specific chains. Heparin and sulfated polysaccharides blocked MAG-collagen binding [PMID:2446864]. One review-only row.","key_references":[{"PMID":"2446864","why":"Solid-phase binding of soluble MAG to collagens incl. type IX, with kd"}],"covers":["LR009062"]},"LR002429":{"pair":"COLEC12 -> PILRA","headline":"COLEC12 is reported as a novel PILR\u03b1 binding partner, dependent on sialylated O-glycans; supported by SPR in IntAct and Reactome.","interaction_type":"direct binding","direction_and_effect":"COLEC12 and NPDC1 were identified as novel PILR\u03b1 binding partners; PILR\u03b1 is described as an inhibitory receptor [PMID:22396535]. Sialylated O-glycans on the ligands are compulsory for PILR\u03b1 binding [PMID:22396535].","molecular_requirements":"Binding requires sialylated O-glycans on COLEC12 and conserved PILR\u03b1 arginine (Arg-133 mouse, Arg-126 human) [PMID:22396535].","affinity_potency":[],"species_and_systems":"Both mouse and human PILR\u03b1 were tested by mutagenesis; human pair is primary, mouse is ortholog-inferred [PMID:22396535]. IntAct records surface plasmon resonance [DB:IntAct].","localisation_and_range":"Ligand is not flagged secreted; PILR\u03b1 is flagged both secreted and transmembrane [flag]. Binding is to a membrane-type ligand, range not otherwise reported.","caveats":"Abstract read only. Reactome lists the binding reaction, citing this paper among others [DB:Reactome]. No affinity in our evidence.","key_references":[{"PMID":"22396535","why":"Identifies COLEC12 as PILR\u03b1 ligand; sialylated O-glycan dependence"}],"covers":["LR002429","LR005708"]},"LR000368":{"pair":"CORT -> SSTR2","headline":"Cortistatin binds SSTR2 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 9.45","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst2 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.8-9.3","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR2 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. One further paper pending.","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000368","LR003874"]},"LR009323":{"pair":"CP -> SLC40A1","headline":"Supported only by database records of a ceruloplasmin-ferroportin complex; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; the one judged paper was review_only.","molecular_requirements":"Reactome lists SLC40A1:CP:6Cu2+ and a CP-mutant version at the plasma membrane [DB:Reactome R-HSA-904825][DB:Reactome R-HSA-9631864].","affinity_potency":[],"species_and_systems":"IntAct records a co-immunoprecipitation (physical association); species not reported in our evidence [DB:IntAct EBI-2931412].","localisation_and_range":"Not reported in our evidence beyond the Reactome plasma membrane complex [DB:Reactome R-HSA-904825].","caveats":"No curator-verified paper; no secreted or receptor flags in the dossier, so ligand-receptor direction is unsupported.","key_references":[],"covers":["LR009323"]},"LR005714":{"pair":"Cr2 -> Fcer2a","headline":"CD21 (Cr2) reported as a ligand for CD23 (Fcer2a); one abstract-level binding paper, in human cells, projected to mouse.","interaction_type":"direct binding","direction_and_effect":"CD23-liposomes bound CD21 on B cells and CD21-transfected BHK-21 cells, blocked by anti-CD21 and anti-CD23 antibodies; soluble CD23 or anti-CD21 increased IL-4-induced IgE production, so CD21 engagement is agonist-like [PMID:1386409]. UniProt states CD21 acts as a ligand for CD23 [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond a CD21 subtype reacting with CD23-liposomes on Western blot [PMID:1386409].","affinity_potency":[],"species_and_systems":"Experiments used human cells (B cells, mononuclear cells) and transfected BHK-21 cells [PMID:1386409]. The mouse pair is inferred from human evidence.","localisation_and_range":"Cr2 is flagged membrane-bound and non-secreted, while Fcer2a is flagged secreted [flag], consistent with a contact interaction but this is only an annotation flag.","caveats":"Single paper, read as abstract only. No affinity reported. The mouse pair has no mouse experiments in our evidence.","key_references":[{"PMID":"1386409","why":"Shows CD23-liposome binding to CD21 and effect on IgE production"}],"covers":["LR005714"]},"LR004823":{"pair":"CRIPTO -> ACVR2B","headline":"Cripto-ActRIIB evidence conflicts: ternary complex with activin reported, but isolated CFC domain does not bind ActRIIB.","interaction_type":"conflicting","direction_and_effect":"Cripto formed a complex with activin and ActRII/IIB by co-immunoprecipitation [PMID:12682303]; the same paper reports Cripto blocks activin signalling. The synthetic Cripto CFC domain explicitly did not recognise ActRIIB [PMID:19035567].","molecular_requirements":"Cripto-ActRIIB association depends on activin being present in the complex [PMID:12682303]. Reactome lists ACVR1C:ACVR2B:EGF-CFC complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species of the co-IP is unspecified in the curated row [PMID:12682303]; the CFC domain was human and synthetic [PMID:19035567]. Human and mouse pairs are both projected.","localisation_and_range":"CRIPTO is flagged secreted [flag].","caveats":"Both papers read as abstracts only. The negative result concerns only the isolated CFC domain, not full-length Cripto. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"12682303","why":"Complex of Cripto, activin and ActRII/IIB"},{"PMID":"19035567","why":"CFC domain does not bind ActRIIB"}],"covers":["LR001428","LR004823"]},"LR011843":{"pair":"CRLF2 -> CRLF2:IL7R:TSLP","headline":"CRLF2:IL7R with TSLP is a receptor-complex entry supported by PDB and Reactome only.","interaction_type":"database-asserted only","direction_and_effect":"Structure of human TSLP with TSLPR and IL-7Ralpha [DB:PDB 5J11] and with mouse IL-7Ralpha [DB:PDB 5J12]. Reactome lists an IL7R:TSLP:CRLF2 complex [DB:Reactome].","molecular_requirements":"The complex requires TSLPR (CRLF2) with IL-7Ralpha and TSLP [DB:PDB 5J11, DB:Reactome].","affinity_potency":[],"species_and_systems":"Human structures; one with mouse IL-7Ralpha [DB:PDB 5J12].","localisation_and_range":"CRLF2 is flagged secreted and receptor [flag].","caveats":"No confirmed papers; two abstracts were insufficient and one concerned a different entity. Not a ligand-receptor pair in the usual sense.","key_references":[],"covers":["LR011843"]},"LR000377":{"pair":"CSF2 -> CSF2RB","headline":"GM-CSF contacts the common beta chain only together with the alpha chain; supported by mutagenesis and kinetics.","interaction_type":"direct binding","direction_and_effect":"Betac interacts directly with GM-CSF during formation of the high-affinity receptor [PMID:8278375]. Betac residues Tyr365, His367 and Ile368 are required for GM-CSF and IL-5 but not IL-3 high-affinity binding, and interact with Glu21 of GM-CSF [PMID:7957082]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Betac alone has no detectable cytokine-binding activity; interaction occurs only in the presence of the alpha chain, which GM-CSF needs [PMID:8278375]. GMRbeta facilitates ligand acquisition (higher k(on) for alpha/beta than alpha) [PMID:10572088]. Betac is shared with IL-3 and IL-5 receptors [PMID:7957082].","affinity_potency":[],"species_and_systems":"Human proteins; mutagenesis and binding assays with radiolabelled cytokines [PMID:7957082]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond the ligand secreted annotation [flag].","caveats":"Abstracts only. Betac is not a standalone GM-CSF receptor, so a CSF2->CSF2RB edge should be read as part of the alpha/beta complex. Rows 10572088 list species unspecified. Two papers were abstract_insufficient and one pending.","key_references":[{"PMID":"8278375","why":"His-367 of betac critical for high-affinity GM-CSF binding"},{"PMID":"7957082","why":"Betac residues interacting with Glu21 of GM-CSF"},{"PMID":"10572088","why":"Kinetic role of beta in high-affinity binding"}],"covers":["LR000377","LR003883"]},"LR006803":{"pair":"CSF3 -> CSF2RA","headline":"No paper evidence that G-CSF engages CSF2RA; only a GtoPdb agonist entry.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CSF3-CSF2RA as agonist [DB:GtoPdb]; no paper shown supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Judged rows were different_entity, review_only and abstract_insufficient, none confirmed.","key_references":[],"covers":["LR006803"]},"LR002447":{"pair":"CSPG4 -> ITGA3","headline":"CSPG4 (NG2) forms a cell-surface complex with alpha3beta1 integrin and galectin-3; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Soluble NG2 induces endothelial motility, network formation in vitro and corneal angiogenesis in vivo; transmembrane signalling via alpha3beta1 drives motility, so NG2 acts as an agonist [PMID:15181153].","molecular_requirements":"NG2, galectin-3 and alpha3beta1 form a complex on the cell surface; galectin-3-dependent oligomerization may potentiate alpha3beta1 activation [PMID:15181153]. The ITGA3 chain is only evidenced as part of the alpha3beta1 heterodimer.","affinity_potency":[],"species_and_systems":"Endothelial cells in vitro and mouse cornea in vivo; the human and mouse pairs are both ortholog-inferred [PMID:15181153].","localisation_and_range":"CSPG4 is flagged secreted and transmembrane [flag]; the paper used soluble NG2 acting on the cell surface [PMID:15181153].","caveats":"Single paper read as abstract only; evidence is complex formation, not a measured pairwise binding of NG2 to ITGA3 alone. Whether the endothelial cells were human or mouse is not reported in our evidence beyond curator labels.","key_references":[{"PMID":"15181153","why":"NG2 forms a complex with galectin-3 and alpha3beta1 on endothelial cells"}],"covers":["LR002447","LR005723"]},"LR005723":{"pair":"CSPG4 -> ITGA3","headline":"CSPG4 (NG2) forms a cell-surface complex with alpha3beta1 integrin and galectin-3; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Soluble NG2 induces endothelial motility, network formation in vitro and corneal angiogenesis in vivo; transmembrane signalling via alpha3beta1 drives motility, so NG2 acts as an agonist [PMID:15181153].","molecular_requirements":"NG2, galectin-3 and alpha3beta1 form a complex on the cell surface; galectin-3-dependent oligomerization may potentiate alpha3beta1 activation [PMID:15181153]. The ITGA3 chain is only evidenced as part of the alpha3beta1 heterodimer.","affinity_potency":[],"species_and_systems":"Endothelial cells in vitro and mouse cornea in vivo; the human and mouse pairs are both ortholog-inferred [PMID:15181153].","localisation_and_range":"CSPG4 is flagged secreted and transmembrane [flag]; the paper used soluble NG2 acting on the cell surface [PMID:15181153].","caveats":"Single paper read as abstract only; evidence is complex formation, not a measured pairwise binding of NG2 to ITGA3 alone. Whether the endothelial cells were human or mouse is not reported in our evidence beyond curator labels.","key_references":[{"PMID":"15181153","why":"NG2 forms a complex with galectin-3 and alpha3beta1 on endothelial cells"}],"covers":["LR002447","LR005723"]},"LR001763":{"pair":"CTHRC1 -> ROR2","headline":"CTHRC1 binds Ror2 and enhances Wnt-Fzd/Ror2 interaction; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cell-surface-anchored Cthrc1 bound to Wnt proteins, Fzd proteins, and Ror2 and enhanced Wnt-Fzd/Ror2 interaction by forming a Cthrc1-Wnt-Fzd/Ror2 complex; in HEK293T cells Cthrc1 activated the PCP pathway but suppressed the canonical pathway [PMID:18606138].","molecular_requirements":"Ror2 acts as a co-receptor in a Cthrc1-Wnt-Fzd/Ror2 complex [PMID:18606138].","affinity_potency":[],"species_and_systems":"HEK293T cells, with mouse knockout genetics for Cthrc1 phenotypes; both pairs are not ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted; ROR2 flagged transmembrane [flag]; paper describes cell-surface-anchored Cthrc1 [PMID:18606138].","caveats":"Single paper; overexpression system; no affinity.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Ror2 and Fzd to form a Wnt complex"}],"covers":["LR001763","LR005121"]},"LR002456":{"pair":"CXCL10 -> ACKR1","headline":"CXCL10 binds human ACKR1 (Duffy) on erythrocytes, but only weakly, in a single full-text study.","interaction_type":"direct binding","direction_and_effect":"CXCL10 displaced radiolabelled CXCL8 from human erythrocyte Duffy antigen, placed by the paper in its weak-binding category [PMID:15358176]. Signalling effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 622.4 nM","assay":"125I-CXCL8 competition displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human ligand and receptor, native erythrocytes [PMID:15358176]. The mouse interaction is projected from human evidence, not tested here.","localisation_and_range":"CXCL10 is flagged secreted and ACKR1 transmembrane [flag].","caveats":"Weak binder (Ki 100 nM to 1 uM tier) compared with strong binders in the same study [PMID:15358176]. Only one paper; binding measured by displacement of a different chemokine.","key_references":[{"PMID":"15358176","why":"Chemokine binding profile of human Duffy antigen"}],"covers":["LR002456","LR005732"]},"LR005732":{"pair":"CXCL10 -> ACKR1","headline":"CXCL10 binds human ACKR1 (Duffy) on erythrocytes, but only weakly, in a single full-text study.","interaction_type":"direct binding","direction_and_effect":"CXCL10 displaced radiolabelled CXCL8 from human erythrocyte Duffy antigen, placed by the paper in its weak-binding category [PMID:15358176]. Signalling effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 622.4 nM","assay":"125I-CXCL8 competition displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human ligand and receptor, native erythrocytes [PMID:15358176]. The mouse interaction is projected from human evidence, not tested here.","localisation_and_range":"CXCL10 is flagged secreted and ACKR1 transmembrane [flag].","caveats":"Weak binder (Ki 100 nM to 1 uM tier) compared with strong binders in the same study [PMID:15358176]. Only one paper; binding measured by displacement of a different chemokine.","key_references":[{"PMID":"15358176","why":"Chemokine binding profile of human Duffy antigen"}],"covers":["LR002456","LR005732"]},"LR007172":{"pair":"CXCL10 -> DPP4","headline":"No papers support CXCL10 as a ligand of DPP4; the only record is an IntAct enzymatic study.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no direction or effect is given.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human only; no experiments in our evidence.","localisation_and_range":"CXCL10 is flagged secreted and DPP4 transmembrane [flag].","caveats":"Support is a single IntAct record described as an \"enzymatic study\" [DB:IntAct]; no papers were confirmed (review-only and abstract-insufficient rows). This looks like enzyme-substrate processing, not receptor signalling.","key_references":[],"covers":["LR007172"]},"LR000395":{"pair":"CXCL11 -> ACKR3","headline":"CXCL11 binds and signals via arrestin at ACKR3, an atypical scavenger receptor; supported by binding, mutagenesis and functional papers, mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"ACKR3 (CXCR7) binds CXCL11 with high affinity as a second ligand beside CXCL12; 125I-labelled CXCL11 and CXCL12 compete each other on cells [PMID:16940167]. ACKR3 does not trigger G-protein activation but recruits arrestin and internalises and degrades CXCL11, so it scavenges the chemokine [PMID:29180449][PMID:20161793]. Ca2+ mobilisation or migration was not caused by ligand activation [PMID:16940167]. CXCL11 caused beta-arrestin 2 recruitment comparable in efficacy to CXCL12 [PMID:29386406]. GtoPdb lists CXCL11 as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain. CXCL11 primary binding depends on the ACKR3 N terminus and some extracellular-loop positions, with a binding mode different from CXCL12 [PMID:27875312]. An N-terminally truncated CXCL11 (3-73) had reduced potency and efficacy for arrestin recruitment [PMID:29386406].","affinity_potency":[{"value":"EC50 2.9 nM","assay":"beta-arrestin 2 recruitment (PRESTO-Tango)","system":"human ACKR3, cell system","cite":"PMID:29386406"},{"value":"IC50 39.1 nM","assay":"125I-CXCL12 displacement by unlabelled CXCL11 (wild-type ACKR3, table)","system":"cells expressing ACKR3-YFP","cite":"PMID:29180449"}],"species_and_systems":"Human ligand and receptor in transfected or cultured cells (MCF-7, MDA MB 435s transfectants, 293 cells) [PMID:16940167][PMID:29386406]; the mouse interaction is listed but no mouse-specific experiment is shown.","localisation_and_range":"CXCL11 is flagged secreted and ACKR3 as a transmembrane receptor [flag], so paracrine action on membrane ACKR3.","caveats":"Four of five papers were read as abstracts only. ACKR3 is atypical: no G-protein signalling, mainly scavenging and arrestin recruitment. Little CXCR7 down-regulation was seen on cells after CXCL12 in one paper [PMID:20161793]. The 29386406 data are CXCL11 (3-73) comparisons within a vascular study.","key_references":[{"PMID":"16940167","why":"Shows CXCL11 binds CXCR7 with high affinity by competition binding (full text)"},{"PMID":"27875312","why":"Mutational mapping of CXCL11 binding to ACKR3"},{"PMID":"29386406","why":"Arrestin recruitment EC50 for CXCL11 at ACKR3"}],"covers":["LR000395","LR003901"]},"LR003905":{"pair":"CXCL12 -> CXCR3","headline":"Only weak, abstract-level evidence: CXCR3 has 'very modest affinity' for SDF-1alpha; activation by CXCL12 is not shown.","interaction_type":"direct binding","direction_and_effect":"The paper reports that CXCR3 has very modest affinity for SDF-1alpha and little or no affinity for other CXC chemokines, versus Ki 0.14 and 4.9 nM for IP10 and MIG [PMID:9660793]. GtoPdb lists it as Agonist, full agonist [DB:GtoPdb], but the abstract does not show CXCL12-induced activation.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 6.4","assay":"competition binding","system":"CXCR3 heterologously expressed in transfected cells","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and receptor in transfected cells; endogenous receptor on activated T cells was described as similar; mouse pair projected from human [PMID:9660793].","localisation_and_range":"CXCL12 is flagged secreted and CXCR3 transmembrane [flag].","caveats":"Abstract only. The curator calls this weak and likely non-physiological. The 'agonist' label rests on GtoPdb and the curator, not on a demonstrated response in the paper.","key_references":[{"PMID":"9660793","why":"CXCR3 pharmacology; modest SDF-1alpha affinity"}],"covers":["LR000400","LR003905"]},"LR002465":{"pair":"CXCL13 -> ACKR1","headline":"One full-text paper: CXCL13 binds the Duffy antigen (ACKR1) weakly, per the curator; homeostatic chemokines bound poorly.","interaction_type":"direct binding","direction_and_effect":"Duffy antigen on human erythrocytes bound chemokines in radioligand displacement; homeostatic chemokines did not bind with high affinity [PMID:15358176]. The curator records weak binding for this pair; signalling effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 304.5 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes and synovial tissue; human chemokine and receptor. The mouse pair is projected from human [PMID:15358176].","localisation_and_range":"CXCL13 is flagged secreted and ACKR1 transmembrane [flag].","caveats":"The paper's weak category is Ki 100 nM to 1 uM; the Ki is taken from the curator's note since Table 1 is not in the excerpts. Evidence sentence is generic. Dossier text does not name CXCL13 itself.","key_references":[{"PMID":"15358176","why":"Duffy antigen chemokine binding profile"}],"covers":["LR002465","LR005739"]},"LR001772":{"pair":"CXCL14 -> CXCR4","headline":"CXCL14 binds CXCR4 with high affinity but does not activate it; reported as a positive allosteric modulator of CXCL12 responses. Two papers.","interaction_type":"direct binding","direction_and_effect":"CXCL14 did not trigger chemotaxis, Ca2+ mobilisation, ERK1/2 or Rac1 signalling in CXCR4 cells, yet bound CXCR4 with high affinity, induced CXCR4 redistribution, enhanced HIV-1 infection by >3-fold and synergised with subactive CXCL12 [PMID:28360196]. The authors call it a positive allosteric modulator. A second paper reports CXCL14 as a platelet chemoattractant acting via CXCR4 with direct interaction shown by immunoprecipitation [PMID:32239134].","molecular_requirements":"CXCL14 synergy needed CXCL12 at subactive concentrations with 100-300 nM CXCL14 [PMID:28360196]; the two chemokines may use partially distinct CXCR4 sites [PMID:28360196].","affinity_potency":[{"value":"KD 8.0 \u00d7 10\u22129 M","assay":"surface plasmon resonance, CXCL14 on immobilised CXCR4","system":"purified/immobilised CXCR4","cite":"PMID:28360196"}],"species_and_systems":"Primary human lymphoid cells and cell lines; mouse 300-19 pre-B cells transfected with CXCR4 [PMID:28360196]; murine CXCR4-deficient platelets and human iPSC-derived platelets [PMID:32239134]. Mouse pair is projected from human.","localisation_and_range":"CXCL14 flagged secreted and CXCR4 transmembrane [flag]; platelet-released chemokine acting paracrine/autocrine [PMID:32239134].","caveats":"Both papers read as abstracts (full text excerpts for the first). Not a classical agonist: no signalling alone [PMID:28360196]. IntAct lists a coimmunoprecipitation [DB:IntAct]. The platelet paper is abstract-only.","key_references":[{"PMID":"28360196","why":"Binding with KD, lack of activation, synergy with CXCL12 and HIV-1 enhancement"},{"PMID":"32239134","why":"CXCL14 platelet migration via CXCR4 with co-immunoprecipitation"}],"covers":["LR001772","LR005129"]},"LR005129":{"pair":"CXCL14 -> CXCR4","headline":"CXCL14 binds CXCR4 with high affinity but does not activate it; reported as a positive allosteric modulator of CXCL12 responses. Two papers.","interaction_type":"direct binding","direction_and_effect":"CXCL14 did not trigger chemotaxis, Ca2+ mobilisation, ERK1/2 or Rac1 signalling in CXCR4 cells, yet bound CXCR4 with high affinity, induced CXCR4 redistribution, enhanced HIV-1 infection by >3-fold and synergised with subactive CXCL12 [PMID:28360196]. The authors call it a positive allosteric modulator. A second paper reports CXCL14 as a platelet chemoattractant acting via CXCR4 with direct interaction shown by immunoprecipitation [PMID:32239134].","molecular_requirements":"CXCL14 synergy needed CXCL12 at subactive concentrations with 100-300 nM CXCL14 [PMID:28360196]; the two chemokines may use partially distinct CXCR4 sites [PMID:28360196].","affinity_potency":[{"value":"KD 8.0 \u00d7 10\u22129 M","assay":"surface plasmon resonance, CXCL14 on immobilised CXCR4","system":"purified/immobilised CXCR4","cite":"PMID:28360196"}],"species_and_systems":"Primary human lymphoid cells and cell lines; mouse 300-19 pre-B cells transfected with CXCR4 [PMID:28360196]; murine CXCR4-deficient platelets and human iPSC-derived platelets [PMID:32239134]. Mouse pair is projected from human.","localisation_and_range":"CXCL14 flagged secreted and CXCR4 transmembrane [flag]; platelet-released chemokine acting paracrine/autocrine [PMID:32239134].","caveats":"Both papers read as abstracts (full text excerpts for the first). Not a classical agonist: no signalling alone [PMID:28360196]. IntAct lists a coimmunoprecipitation [DB:IntAct]. The platelet paper is abstract-only.","key_references":[{"PMID":"28360196","why":"Binding with KD, lack of activation, synergy with CXCL12 and HIV-1 enhancement"},{"PMID":"32239134","why":"CXCL14 platelet migration via CXCR4 with co-immunoprecipitation"}],"covers":["LR001772","LR005129"]},"LR005741":{"pair":"CXCL14 -> GPR85","headline":"One abstract-only 2018 breast-cancer paper reports CXCL14 binding GPR85 on fibroblasts; no affinity or independent support.","interaction_type":"functional only","direction_and_effect":"CXCL14 secreted by HIC1-deleted breast cancer cells bound GPR85 on mammary fibroblasts and activated them via ERK1/2, Akt and neddylation pathways; activated fibroblasts promoted progression through CCL17/CCR4 [PMID:30204129].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse mammary gland with conditional HIC1 deletion and breast cancer cells with mammary fibroblasts [PMID:30204129]; the dossier labels the experiment species human/human. Mouse pair is projected from human.","localisation_and_range":"Paracrine, tumour cell to fibroblast, in the microenvironment [PMID:30204129]; CXCL14 flagged secreted [flag].","caveats":"Single abstract-only paper; binding is stated, not quantified. BioGRID records an affinity capture-western from the same paper [DB:BioGRID]. No second source.","key_references":[{"PMID":"30204129","why":"CXCL14-GPR85 signalling between breast cancer cells and fibroblasts"}],"covers":["LR002467","LR005741"]},"LR003914":{"pair":"CXCL5 -> CXCR2","headline":"Well supported agonist: high-affinity binding and potent signalling at CXCR2, with GtoPdb record and structures.","interaction_type":"direct binding","direction_and_effect":"Agonist at IL8RB (CXCR2) in calcium flux, EC50 11 nM [PMID:8702798]; radiolabelled IL-8 was displaced from CXCR2 by ENA-78 [PMID:9692902]. Neutrophil data say all three CXC chemokines bind CXCR-2 with high affinity [PMID:10593335]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor requirement reported. PDB 8XWS and 8XX7 contain a CXCL5 chain and a CXCR2 chain [DB:PDB 8XWS].","affinity_potency":[{"value":"EC50 11 nM","assay":"calcium flux at IL8RB","system":"HEK293 transfectants","cite":"PMID:8702798"},{"value":"pIC50 6.9 to 9.0","assay":"GtoPdb affinity range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human HEK293 transfectants [PMID:8702798]; the human row of PMID:9692902 was propagated from a mouse-row curation; species of 10593335 is unspecified in the curation.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"All papers abstract-only. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"8702798","why":"EC50 at IL8RB"},{"PMID":"9692902","why":"Displacement and migration at CXCR2"},{"PMID":"10593335","why":"High-affinity CXCR-2 binding on neutrophils"}],"covers":["LR000414","LR003914"]},"LR002474":{"pair":"DAG1 -> CELSR3","headline":"Dystroglycan binds the Celsr3 LG1 domain in vitro and the pair matters for axon guidance in vivo; one paper.","interaction_type":"direct binding","direction_and_effect":"Dystroglycan is reported to act mainly as an extracellular scaffold, non-cell-autonomously and without its intracellular domain; Celsr3 is a binding partner needed for specific axon guidance events in vivo [PMID:30758284]. Agonist/antagonist role not reported in our evidence.","molecular_requirements":"Dystroglycan-Fc bound Celsr3-LG1 but not Celsr3-LG2; AP-Celsr3-LG1 pulled down endogenous glycosylated Dystroglycan from brain lysate. The full-length Celsr3 extracellular domain could not be produced, so binding used isolated LG domains [PMID:30758284].","affinity_potency":[],"species_and_systems":"Recombinant fusion proteins, brain lysate and COS7 cells expressing full-length Dystroglycan (5 nM AP-Celsr3-LG1); in vivo axon guidance. Curator-recorded experiment species is human; the mouse pair is the species-native record, human is ortholog-projected [PMID:30758284].","localisation_and_range":"Dystroglycan is flagged secreted, transmembrane and receptor [flag]; Celsr3 is flagged transmembrane [flag]. Direction is ambiguous: both partners carry receptor flags.","caveats":"Domain-fragment binding only; no affinity reported in our evidence; one paper (abstract plus excerpts).","key_references":[{"PMID":"30758284","why":"Dystroglycan-Celsr3 LG1 binding and in vivo axon guidance role"}],"covers":["LR002474","LR005748"]},"LR005750":{"pair":"DAG1 -> NRXN2","headline":"Dystroglycan binds the second LNS domain of neurexin-2alpha in vitro; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Direction and effect not reported in our evidence; the paper reports Ca2+-dependent complex formation [PMID:11470830].","molecular_requirements":"The second LNS domain of neurexins 1alpha, 2alpha and 3alpha formed tight Ca2+-dependent complexes with dystroglycan; only alpha-neurexins with LNS2 or LNS6 captured it [PMID:11470830].","affinity_potency":[],"species_and_systems":"Ig/GST-neurexin LNS fusion proteins with rat/mouse brain homogenate; neurexin 1alpha Ig bound DG+/- but not DG-/- ES cells [PMID:11470830]. Human pair is ortholog-projected.","localisation_and_range":"Neurexin-2 is flagged transmembrane [flag]; dystroglycan is flagged secreted and transmembrane [flag].","caveats":"Single paper; no affinity reported; neurexin-2 evidence is by extension from the shared LNS2 domain result.","key_references":[{"PMID":"11470830","why":"Alpha-neurexin LNS2 domains bind dystroglycan"}],"covers":["LR002476","LR005750"]},"LR003923":{"pair":"DCN -> ERBB4","headline":"ErbB4 involvement in decorin signalling is inferred from phosphorylation patterns; no binding shown.","interaction_type":"functional only","direction_and_effect":"Decorin effects appear to involve ErbB4 activation, which would block ErbB2/ErbB3 heterodimer phosphorylation; ErbB2 down-regulation and growth suppression occurred in breast carcinoma cells [PMID:10942781].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human breast carcinoma cells, de novo and recombinant decorin [PMID:10942781].","localisation_and_range":"Decorin flagged secreted; ERBB4 transmembrane receptor [flag].","caveats":"Abstract hedges ('appear to involve'); no direct binding, no affinity, one paper, no database record. Support is weak.","key_references":[{"PMID":"10942781","why":"Inferred ErbB4 activation by decorin"}],"covers":["LR000426","LR003923"]},"LR002483":{"pair":"DEFB106B -> CCR2","headline":"NMR model of human beta-defensin 6 with a CCR2 N-terminal peptide supports binding; abstract-only and no functional readout.","interaction_type":"direct binding","direction_and_effect":"NMR of hBD6 with peptides from the CCR2 extracellular domain (Nt-CCR2, with or without sulfation on Tyr26 and Tyr28) gives a complex model with a contiguous binding surface on hBD6 (alpha-helix and beta2-beta3 loop) [PMID:23938203]. UniProt records the interaction as well [DB:UniProt]. Agonism or antagonism is not reported in our evidence.","molecular_requirements":"Only the receptor N-terminal peptide was used, not full-length CCR2, so whether other CCR2 regions or subunits are needed is not reported [PMID:23938203].","affinity_potency":[],"species_and_systems":"Human hBD6 and a synthetic CCR2 peptide, in vitro NMR [PMID:23938203].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only. hBD6 is encoded by the near-identical duplicated loci DEFB106A and DEFB106B and the paper does not distinguish them, so the evidence applies to both. The peptide complex is not proof of binding to intact cell-surface CCR2. UniProt support cites the same paper [DB:UniProt]. No affinity reported.","key_references":[{"PMID":"23938203","why":"NMR hBD6/Nt-CCR2 complex"}],"covers":["LR002483"]},"LR003932":{"pair":"DKK1 -> KREMEN1","headline":"Well supported direct high-affinity binding and a crystal structure; Kremen1 acts with DKK1 to block Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Kremen1 and Kremen2 are high-affinity Dkk1 receptors that cooperate with Dkk1 to block Wnt/beta-catenin signalling [PMID:12050670]. Krm1 is described as a co-receptor for Dkk proteins [PMID:27524201].","molecular_requirements":"DKK1 CRD2 is required and sufficient for binding to KRM1; SPR measured low micromolar affinity between full-length DKK1 and KRM1ECD [PMID:27524201]. UniProt notes interaction with DKK1 [DB:UniProt].","affinity_potency":[{"value":"low micromolar","assay":"surface plasmon resonance","system":"full-length DKK1 and immobilized human KRM1ECD","cite":"PMID:27524201"}],"species_and_systems":"Recombinant human ectodomain structures [PMID:27524201]; the 2002 abstract does not name species [PMID:12050670]. Database: PDB 5FWW, IntAct [DB:PDB 5FWW] [DB:IntAct].","localisation_and_range":"KREMEN1 is flagged as a receptor, not secreted [flag].","caveats":"The 2002 paper's evidence sentence concerns both Kremen1 and Kremen2 and was read as abstract only. The structure paper's affinity is a low micromolar range, not a precise value. One row pending.","key_references":[{"PMID":"12050670","why":"Kremen1/2 are high-affinity Dkk1 receptors"},{"PMID":"27524201","why":"Kremen1 ectodomain structure; DKK1 CRD2 binding by SPR"}],"covers":["LR000440","LR003932"]},"LR008360":{"pair":"DKK2 -> LRP5","headline":"Structural evidence from one paper that DKK proteins bind LRP5/6 ectodomains; DKK2-specific data are limited.","interaction_type":"direct binding","direction_and_effect":"Dickkopf-related proteins inhibit Wnt signalling by directly binding the ectodomains of LRP5/6; crystal structures of LRP6 ectodomain with DKK1 provide the basis [PMID:22589387].","molecular_requirements":"The structural work described is for DKK1-LRP6, not DKK2-LRP5; DKK2-LRP5 specifics are not reported in our evidence [PMID:22589387].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human recombinant structures.","localisation_and_range":"DKK2 flagged secreted; LRP5 flagged receptor and transmembrane [flag].","caveats":"The evidence sentence is a general statement and the abstract is a short commentary on DKK1-LRP6 structures, so the DKK2-LRP5 link is by family analogy. One further row was abstract-insufficient.","key_references":[{"PMID":"22589387","why":"Commentary on DKK-LRP5/6 binding based on DKK1-LRP6 structures"}],"covers":["LR008360"]},"LR001781":{"pair":"DKK4 -> LRP6","headline":"Dkk4 binds LRP6 E1E2 through CRD2 and inhibits Wnt signalling; one structural paper.","interaction_type":"direct binding","direction_and_effect":"Dkk4 CRD2 mediates high-affinity binding to LRP6 E1E2; refolded Dkk4 and Dkk2 bound cells expressing full-length LRP6 by FACS, and Dkk4 inhibited Wnt1 and Wnt3a reporter activity but appeared less potent than Dkk1 [PMID:29925589]. Curator effect: antagonist.","molecular_requirements":"The N-terminal region with the NXI(R/K) motif alone bound LRP6 E1E2 with only moderate affinity [PMID:29925589]. Kremen proteins can join in Dkk-Krm-LRP5/6 ternary complexes [PMID:29925589].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells; human pair not ortholog-inferred, mouse pair ortholog-inferred [PMID:29925589].","localisation_and_range":"LRP6 is a transmembrane receptor [flag]; ligand in solution.","caveats":"One paper; no affinity number in our evidence. Assay labelled structural.","key_references":[{"PMID":"29925589","why":"Dkk4 CRD2 high-affinity binding to LRP6 E1E2"}],"covers":["LR001781","LR005137"]},"LR000449":{"pair":"DLL1 -> NOTCH2","headline":"DLL1 binds and activates NOTCH2 in mouse and human cell assays; well supported.","interaction_type":"direct binding","direction_and_effect":"Delta1 bound endogenous Notch2 on BaF3 cells, inducing Notch2 cleavage within 15 min, nuclear translocation, hyperphosphorylation and RBP-Jkappa reporter activation [PMID:10958687]. DLL1 is equally effective in activating NOTCH1 and NOTCH2 [PMID:30289388]; without Fringes DLL1 activates NOTCH2 similarly or slightly more than NOTCH1, and LFNG enhances NOTCH2 activation by DLL1 [PMID:32820046]. Effect: agonist.","molecular_requirements":"Lunatic fringe enhances DLL1-NOTCH2 activation; NOTCH2 is less Fringe-sensitive than NOTCH1 [PMID:32820046]. BioGRID lists affinity-capture and reconstituted complex records [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Mouse BaF3 cells [PMID:10958687]; human cell-based assays [PMID:32820046, PMID:30289388]. Human pair ortholog-inferred, mouse pair direct.","localisation_and_range":"Membrane-bound DSL ligand acting at cell surface contact; DLL1 flagged secreted and transmembrane [flag].","caveats":"Binding paper is abstract-only. No affinities reported in our evidence. One review-only and one pending paper not shown.","key_references":[{"PMID":"10958687","why":"Delta1 binds endogenous Notch2 and triggers cleavage"},{"PMID":"30289388","why":"DLL1 equally activates NOTCH1 and NOTCH2"},{"PMID":"32820046","why":"Fringe modulation of DLL1-NOTCH2"}],"covers":["LR000449","LR003941"]},"LR003941":{"pair":"DLL1 -> NOTCH2","headline":"DLL1 binds and activates NOTCH2 in mouse and human cell assays; well supported.","interaction_type":"direct binding","direction_and_effect":"Delta1 bound endogenous Notch2 on BaF3 cells, inducing Notch2 cleavage within 15 min, nuclear translocation, hyperphosphorylation and RBP-Jkappa reporter activation [PMID:10958687]. DLL1 is equally effective in activating NOTCH1 and NOTCH2 [PMID:30289388]; without Fringes DLL1 activates NOTCH2 similarly or slightly more than NOTCH1, and LFNG enhances NOTCH2 activation by DLL1 [PMID:32820046]. Effect: agonist.","molecular_requirements":"Lunatic fringe enhances DLL1-NOTCH2 activation; NOTCH2 is less Fringe-sensitive than NOTCH1 [PMID:32820046]. BioGRID lists affinity-capture and reconstituted complex records [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Mouse BaF3 cells [PMID:10958687]; human cell-based assays [PMID:32820046, PMID:30289388]. Human pair ortholog-inferred, mouse pair direct.","localisation_and_range":"Membrane-bound DSL ligand acting at cell surface contact; DLL1 flagged secreted and transmembrane [flag].","caveats":"Binding paper is abstract-only. No affinities reported in our evidence. One review-only and one pending paper not shown.","key_references":[{"PMID":"10958687","why":"Delta1 binds endogenous Notch2 and triggers cleavage"},{"PMID":"30289388","why":"DLL1 equally activates NOTCH1 and NOTCH2"},{"PMID":"32820046","why":"Fringe modulation of DLL1-NOTCH2"}],"covers":["LR000449","LR003941"]},"LR002492":{"pair":"DMP1 -> ITGAV","headline":"Supported by an abstract-only human cell study showing DMP1 signalling via alphaVbeta3 integrin; chain-level evidence.","interaction_type":"functional only","direction_and_effect":"DMP1 acts via alphaVbeta3 integrin: it stimulates focal adhesion kinase phosphorylation, activates ERK and JNK, and the effect is blocked by anti-alphaVbeta3 antibody [PMID:21642437]. Direction is agonist.","molecular_requirements":"The alphaVbeta3 heterodimer is the implicated receptor; the paper does not resolve which chain contacts DMP1 [PMID:21642437].","affinity_potency":[],"species_and_systems":"Human mesenchymal stem cells and osteoblast-like cells [PMID:21642437].","localisation_and_range":"DMP1 annotated secreted [flag]; an extracellular matrix protein signalling via the cell surface [PMID:21642437].","caveats":"Abstract only. Evidence rests on an antibody block of the heterodimer, not a binding assay, so the ITGAV chain-specific contribution is not shown. Another paper is also counted as confirmed but not shown.","key_references":[{"PMID":"21642437","why":"DMP1 signals via alphaVbeta3 integrin in human cells"}],"covers":["LR002492","LR005760"]},"LR005138":{"pair":"DNAJB11 -> PRTG","headline":"One abstract-only paper identifies ERdj3 (DNAJB11) as a putative PRTG ligand that antagonises neuronal differentiation.","interaction_type":"functional only","direction_and_effect":"ERdj3 was identified as a putative PRTG ligand by yeast two-hybrid screening and an in situ binding assay; purified ERdj3 reduced neurogenesis in P19 cells, an effect blocked by anti-PRTG antibody or purified PRTG ectodomain [PMID:20335479]. Forced ERdj3 expression in chick neural tube impaired neuronal differentiation [PMID:20335479].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"P19 embryonal carcinoma cells, chick neural tube, mouse embryo PRTG expression; the dossier labels experiment species as human [PMID:20335479].","localisation_and_range":"DNAJB11 annotated secreted [flag]; the paper describes it as normally ER-resident and acting extracellularly here.","caveats":"Described as 'putative'. Abstract only; no affinity. The only evidence is from one group.","key_references":[{"PMID":"20335479","why":"Identifies ERdj3 as a PRTG ligand"}],"covers":["LR001782","LR005138"]},"LR001790":{"pair":"DSC2 -> DSG4","headline":"DSC2 -> DSG4: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001790","LR005146"]},"LR005147":{"pair":"Dsc3 -> Dsg1a","headline":"Dsc3 -> Dsg1a: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: mouse (ortholog-projected). The mouse pair is projected from human evidence; no mouse experiment is in our evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR005147"]},"LR000458":{"pair":"EDA -> EDAR","headline":"EDA (A1 isoform) binds and activates EDAR; binding and co-precipitation shown, abstracts only.","interaction_type":"direct binding","direction_and_effect":"EDA-A1 binds only EDAR [PMID:11039935]; EDAR co-precipitated ectodysplasin, confirming a ligand-receptor pair [PMID:11309369].","molecular_requirements":"Ligand must be furin-cleaved to release soluble ectodysplasin; EDA patient missense mutations affect the recognition sequence [PMID:11309369].","affinity_potency":[],"species_and_systems":"Human; mouse pair is ortholog-inferred.","localisation_and_range":"Released by proteolytic shedding as a soluble ligand [PMID:11309369]; adjacent expression in developing human skin.","caveats":"PMID:11039935 shows EDA-A1 binds only EDAR and EDA-A2 only XEDAR, so isoform matters. Abstracts only; affinity not reported in our evidence.","key_references":[{"PMID":"11309369","why":"EDAR co-precipitates ectodysplasin"},{"PMID":"11039935","why":"EDA-A1 binds only EDAR"}],"covers":["LR000458","LR003949"]},"LR003950":{"pair":"EDIL3 -> ITGAV","headline":"EDIL3 acts through integrin alphaVbeta3 in endothelial and VSMC assays; ITGAV alone is not isolated.","interaction_type":"functional only","direction_and_effect":"Del1 promoted alphavbeta3-dependent endothelial attachment and migration, blocked by an anti-alphavbeta3 antibody; an RGD-to-RAD mutant was inactive [PMID:10196194]. Del1 mediates VSMC adhesion, migration and proliferation via alpha(v)beta(3) [PMID:11959660].","molecular_requirements":"The receptor is the alphaVbeta3 heterodimer; this row records the alphaV chain only [PMID:10196194]. RGD motif required.","affinity_potency":[],"species_and_systems":"Human Del1 on chicken CAM (primary cells) [PMID:10196194]; VSMC adhesion assays [PMID:11959660].","localisation_and_range":"Del1 described as an extracellular matrix protein [PMID:10196194].","caveats":"Both papers abstract only; no binding measurement.","key_references":[{"PMID":"10196194","why":"Del1 RGD-dependent alphavbeta3 adhesion and angiogenesis"},{"PMID":"11959660","why":"Del1 acts on VSMC via alpha(v)beta(3)"}],"covers":["LR000459","LR003950"]},"LR005156":{"pair":"EDIL3 -> ITGB3","headline":"Del1 drives alphaVbeta3-dependent endothelial adhesion and HSC regulation via beta3; functional only.","interaction_type":"functional only","direction_and_effect":"Del1 promoted alphavbeta3-dependent endothelial attachment, clustering and FAK/MAPK/Shc phosphorylation, blocked by an anti-alphavbeta3 antibody; an RAD mutant was inactive [PMID:10196194]. Del-1 effects on HSCs were mediated by beta3 integrin [PMID:28846069].","molecular_requirements":"alphaVbeta3 heterodimer; RGD motif needed [PMID:10196194].","affinity_potency":[],"species_and_systems":"Chick CAM and endothelial cells [PMID:10196194]; mouse HSC niche [PMID:28846069].","localisation_and_range":"Secreted extracellular matrix protein [PMID:10196194].","caveats":"Both abstract only; no direct binding measurement in our evidence.","key_references":[{"PMID":"10196194","why":"Del1 ligates alphavbeta3 in endothelial adhesion"},{"PMID":"28846069","why":"Beta3 integrin mediates Del-1 HSC effects"}],"covers":["LR001800","LR005156"]},"LR010763":{"pair":"EFEMP2 -> LINGO1","headline":"Database-only: a two-hybrid pooling physical association; no ligand-receptor evidence.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper evidence. The only record is an IntAct physical association by two hybrid pooling (EBI-756337) [DB:IntAct]. Direction and effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human yeast two-hybrid pooling record [PMID:16189514] via [DB:IntAct]; no other system reported.","localisation_and_range":"Not reported in our evidence; no localisation flags for the ligand.","caveats":"Rests on one high-throughput two-hybrid record, which does not establish that LINGO1 is a receptor for EFEMP2. No papers were judged for this pair.","key_references":[],"covers":["LR010763"]},"LR000467":{"pair":"EFNA1 -> EPHA1","headline":"Ephrin-A1 is the preferred ligand of EphA1 in binding and cell assays, mostly from abstracts.","interaction_type":"direct binding","direction_and_effect":"Soluble recombinant and native mouse EphA1 show preferential binding to ephrin A1 [PMID:11519828]; ephrin-A1 stimulates T-lymphocyte migration with PI3K associating with EphA1 [PMID:17634955]; ephrin-A1 stimulation triggers EphA1 interaction with integrin-linked kinase, and EphA1 activation inhibits cell spreading and migration via RhoA-ROCK [PMID:19118217].","molecular_requirements":"Downstream ILK interaction uses the EphA1 C-terminal SAM domain and depends on ephrin-A1 stimulation but not EphA1 kinase activity [PMID:19118217].","affinity_potency":[],"species_and_systems":"Mouse EphA1 [PMID:11519828]; human cells [PMID:17634955][PMID:19118217]. Both human and mouse pairs listed non-inferred.","localisation_and_range":"EFNA1 and EPHA1 are annotated both receptor and transmembrane; EFNA1 also annotated secreted [flag], which conflicts with a membrane-bound juxtacrine ligand. Contact-dependent signalling is not stated in the papers shown.","caveats":"A mass-spectrometry pull-down with ephrin-A1 Fc yielded only 2 unique EphA1 spectra versus 423 for EphA2, so EphA1 capture was weak [PMID:22568954]. Another paper reads B61 binding affinity as decreasing across receptors; the EphA1 value is not in our excerpt [PMID:8755474]. Most papers read as abstracts only.","key_references":[{"PMID":"11519828","why":"mouse EphA1 binds ephrin A1"},{"PMID":"19118217","why":"ephrin-A1 stimulation of EphA1, ILK coupling"},{"PMID":"17634955","why":"ephrin-A1 migration signal in T cells"}],"covers":["LR000467","LR003958"]},"LR000485":{"pair":"EFNA3 -> EPHA3","headline":"Ephrin-A3 binds EphA3, among its best EphA partners; a cis-inhibitory mode is also described.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A3 AP binds best to EphA3, EphA5 and EphA7 [PMID:22568954]. Coexpressed (cis) ephrin-A3 inhibits EphA2 and EphA3 binding ephrins in trans and activation; an EphA3 mutation found in lung cancer enhances cis interaction with ephrin-A3 [PMID:24348920].","molecular_requirements":"Not reported beyond the pair itself.","affinity_potency":[],"species_and_systems":"ELISA, species unspecified [PMID:22568954]; human cancer cells [PMID:24348920]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both are flagged membrane-bound [flag]; the cis mechanism is described as same-cell association [PMID:24348920].","caveats":"Evidence on effect conflicts in direction: trans binding versus cis inhibition of activation. The 22568954 result was a browser read with an unverifiable quote. A BioGRID reconstituted-complex record exists [DB:BioGRID].","key_references":[{"PMID":"22568954","why":"ELISA binding ranking"},{"PMID":"24348920","why":"Cis ephrin-A3 inhibits EphA3 trans-activation"}],"covers":["LR000485","LR003976"]},"LR000494":{"pair":"EFNA4 -> EPHA4","headline":"Ephrin-A4 binds EphA4 in rat striatum and by ELISA; IntAct has ELISA and SPR records.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 selectively bind EphA4 but not EphA7 in rat striatal tissue [PMID:10366629]. Ephrin-A4 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat postnatal striatum [PMID:10366629]; ELISA, species unspecified [PMID:22568954]. Human pair is ortholog-inferred.","localisation_and_range":"EFNA4 flagged secreted and transmembrane; EPHA4 flagged membrane-bound [flag].","caveats":"10366629 was an abstract-only read; 22568954 a browser read with an unverifiable quote. IntAct lists ELISA and surface plasmon resonance records [DB:IntAct] (no values in our evidence).","key_references":[{"PMID":"10366629","why":"Ephrin-A4 binds EphA4 in rat striatum"},{"PMID":"22568954","why":"ELISA of ephrin-A4 Fc across EphA receptors"}],"covers":["LR000494","LR003985"]},"LR002528":{"pair":"EGFL7 -> NOTCH2","headline":"Secreted EGFL7 binds human NOTCH2 by co-IP and acts as a Notch antagonist; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Secreted EGFL7 binds a Notch region involved in ligand-mediated activation and acts as an antagonist of Notch signalling; EGFL7 expression in neural stem cells decreased Notch-specific signalling [PMID:19503073].","molecular_requirements":"Not reported in our evidence beyond Notch receptors binding EGFL7 via EGF-like domains; control receptors with EGF-like domains did not interact [PMID:19503073].","affinity_potency":[],"species_and_systems":"Endogenous human NOTCH2 co-immunoprecipitated recombinant human EGFL7 in cell lines; tagged proteins in HEK293 cells [PMID:19503073]. BioGRID lists a two-hybrid record [DB:BioGRID].","localisation_and_range":"EGFL7 is secreted [flag] and the Notch receptor is transmembrane [flag]; binding was retained with the two proteins on apposing cells [PMID:19503073].","caveats":"One paper supports all three Notch paralogs, and this row has no independent confirmation. No affinity reported in our evidence.","key_references":[{"PMID":"19503073","why":"EGFL7 binds Notch1-4 and antagonises Notch signalling"}],"covers":["LR002528","LR005796"]},"LR002537":{"pair":"EPHA10 -> EFNA3","headline":"EPHA10-EFNA3 rests only on a UniProt function statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 binds EFNA3, EFNA4 and EFNA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EPHA10 is flagged secreted in our annotation [flag], unusual for an Eph receptor; EFNA3 flags are non-secreted transmembrane [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; support is a single database sentence. No affinity data.","key_references":[],"covers":["LR002537","LR005805"]},"LR005813":{"pair":"EPHA3 -> EFNA1","headline":"EPHA3-EFNA1 rests on BioGRID and UniProt records; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EPHA3-EFNA1 as a reconstituted complex [DB:BioGRID]. UniProt states EFNA1 acts as a ligand for EPHA3, inhibiting epithelial-to-mesenchymal transition of cardiac cells and playing a role in heart development [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; the mouse pair is recorded as non-inferred and the human pair as ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; database support only. No affinity values.","key_references":[],"covers":["LR002545","LR005813"]},"LR002546":{"pair":"EPHA3 -> EFNA2","headline":"EPHA3-EFNA2 rests on one UniProt sentence; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA2 binds EPHA3, EPHA4 and EPHA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; the mouse pair is non-inferred and the human pair ortholog-inferred.","localisation_and_range":"EPHA3 is flagged secreted, EFNA2 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Four judged rows were review-only or abstract-insufficient. Single database statement, no affinity data.","key_references":[],"covers":["LR002546","LR005814"]},"LR005822":{"pair":"EPHA4 -> EFNA5","headline":"EphA4 binds ephrin-A5 with crystal structures and ELISA data; well supported structurally.","interaction_type":"direct binding","direction_and_effect":"Crystal structures of the complete EphA4 ectodomain and its complexes with ephrin-A5 show ligand binding promotes conformational change in the EphA4 ligand-binding domain, allowing signalling clusters at cell-cell contacts [PMID:23959867]. Ephrin-A5 Fc binds EphA receptors with high apparent affinity in ELISA [PMID:22568954]. Effect: agonist per the curator [PMID:23959867].","molecular_requirements":"A receptor-receptor contact between the EphA4 ligand-binding domain and its own membrane-proximal fibronectin domain is important for efficient activation [PMID:23959867]. EphA4 is activated by both A- and B-class ephrins [PMID:23959867].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in the structural paper [PMID:23959867]; ELISA species unspecified [PMID:22568954]. PDB 4BK5, 4BKA, 4M4R show the pair [DB:PDB 4BK5].","localisation_and_range":"Neither partner is flagged secreted [flag]; the paper describes clusters at sites of cell-cell contact [PMID:23959867]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Structural paper read as abstract; the ELISA paper was browser-read with an unverified quote (spot-check pending). No numeric affinity in our evidence.","key_references":[{"PMID":"23959867","why":"EphA4 ectodomain and EphA4/ephrin-A5 structures"},{"PMID":"22568954","why":"ELISA: ephrin-A5 Fc binds EphA receptors"}],"covers":["LR002554","LR005822"]},"LR002555":{"pair":"EPHA4 -> EFNB2","headline":"EPHA4-EFNB2 is supported by crystal structure, NMR and UniProt records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the EphA4-ephrinB2 complex is recorded [DB:PDB 2WO2]; IntAct lists x-ray crystallography and NMR [DB:IntAct]. UniProt states EFNB2 binds EPHA4, EPHA3 and EPHB4 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity data. Cross-subclass (A receptor, B ephrin) binding.","key_references":[],"covers":["LR002555","LR005823"]},"LR002573":{"pair":"EPHA8 -> EFNA2","headline":"UniProt asserts an EPHA8-EFNA2 interaction; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA2 entry) states it interacts with EPHA8 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only a UniProt subunit sentence; no assay or affinity in our evidence.","key_references":[],"covers":["LR002573","LR005841"]},"LR002591":{"pair":"EPHB3 -> EFNB1","headline":"Eph B3-ephrin-B1 pair supported by an IntAct co-IP and UniProt statements; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNB1 entry) states it can also bind EPHB2 and EPHB3 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct lists an anti-tag coimmunoprecipitation [DB:IntAct EBI-54525293], which does not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002591","LR005859"]},"LR000539":{"pair":"F10 -> ITGAM","headline":"Factor X binds Mac-1 (ITGAM) on stimulated human monocytes with Kd 21.8-44.9 nM; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"125I-factor X bound saturably to ADP- or ionomycin-stimulated human monocytes and was cross-linked to its receptor, immunoprecipitated by anti-alpha subunit Mac-1 antibody OKM10 [PMID:2835359]. Direction effect not reported.","molecular_requirements":"Binding requires Ca2+ and stimulation of monocytes [PMID:2835359]. Alpha chain antibody pulls down the complex; the beta chain role is not reported in our evidence.","affinity_potency":[{"value":"Kd 21.8-44.9 nM","assay":"saturable 125I-factor X binding","system":"ADP- or ionomycin-stimulated human monocytes","cite":"PMID:2835359"}],"species_and_systems":"Human factor X and human monocytes [PMID:2835359]. Mouse pair is projected from human evidence [flag].","localisation_and_range":"F10 flagged secreted; cell-surface binding on monocytes [flag; PMID:2835359].","caveats":"Single 1988 abstract; evidence is for the Mac-1 heterodimer, so the alpha chain alone is not shown to suffice.","key_references":[{"PMID":"2835359","why":"Saturable factor X binding to Mac-1 on monocytes, Kd 21.8-44.9 nM"}],"covers":["LR000539","LR004030"]},"LR000548":{"pair":"F2 -> GP1BA","headline":"Thrombin binds the GPIbalpha ectodomain directly (Kd 1 uM); structures exist, but the second paper is indirect.","interaction_type":"direct binding","direction_and_effect":"Glycocalicin (soluble GPIbalpha ectodomain) bound thrombin at exosite II and reduced fibrinopeptide A release from fibrinogen by about 50% through a noncompetitive allosteric mechanism [PMID:11024046]. Reactome lists thrombin binding to GP1b:IX:V [DB:Reactome R-HSA-429529]. Direction as receptor signalling is not shown in our evidence.","molecular_requirements":"Binding maps to thrombin exosite II, confirmed with thrombin mutants and competition binding; exosite I mutations had little effect [PMID:11024046]. A 1985 study placed thrombin and von Willebrand factor binding sites in the same 45-kDa GPIb region and proposed a second thrombin receptor, possibly GPV [PMID:2933256]. Co-crystal structures exist [DB:PDB 1OOK] [DB:PDB 1P8V] [DB:IntAct].","affinity_potency":[{"value":"Kd 1 microm","assay":"solution binding of glycocalicin to thrombin, physiological ionic strength","system":"purified proteins","cite":"PMID:11024046"},{"value":"Kd 0.19 microm","assay":"same, at 100 mm NaCl (salt-dependent)","system":"purified proteins","cite":"PMID:11024046"}],"species_and_systems":"The 1985 paper's species is labelled mouse in the curation row, while its text mentions human leukocyte elastase and platelets [PMID:2933256]; the binding work used purified proteins [PMID:11024046]. Species of the purified proteins is not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"GP1BA is annotated as a transmembrane receptor and F2 as secreted [flag], so thrombin acts on platelet surface from plasma; glycocalicin is the soluble fragment [PMID:11024046].","caveats":"Both papers were read as abstracts only. The 1985 paper used enzymatic and antibody perturbation of platelets, not direct binding [PMID:2933256]. The Kd is salt-dependent.","key_references":[{"PMID":"11024046","why":"Kd and exosite II mapping of thrombin-GPIbalpha binding"},{"PMID":"2933256","why":"Early platelet study localising thrombin site to GPIb 45-kDa region"}],"covers":["LR000548","LR004039"]},"LR007064":{"pair":"F2 -> GP1BA:GP1BB","headline":"No papers for the complex; support is structural and pathway database records for thrombin with GPIbalpha.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond database records: Reactome lists thrombin binding to GP1b:IX:V [DB:Reactome R-HSA-429529] and IntAct records an X-ray crystallography interaction [DB:IntAct EBI-297118].","molecular_requirements":"PDB entries show thrombin with GPIbalpha chains only (e.g. 1OOK, described as the complex of GPIb-alpha and alpha-thrombin) [DB:PDB 1OOK] [DB:PDB 1P8V]. Whether GP1BB contributes is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human only; no experimental paper in this dossier [DB:PDB 1OOK].","localisation_and_range":"GP1BA is annotated transmembrane [flag]; thrombin is secreted [flag].","caveats":"Rests on databases alone. Structures contain GPIbalpha, not GP1BB, so the complex-level pair is inferred from the GPIbalpha interaction. Both judged papers were different_entity.","key_references":[],"covers":["LR007064"]},"LR002609":{"pair":"FAM3B -> FGFR1","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR1-specific evidence is direct ectodomain binding.","interaction_type":"direct binding","direction_and_effect":"FAM3B protein bound the ectodomain of FGFR1 in solution and full-length FGFR1 in Xenopus embryos, activated ERK in HEK293T cells (blocked by four FGFR inhibitors), and drove posterior-development phenotypes in Xenopus [PMID:33975953]. A negative control, beta-Klotho ectodomain, did not bind [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR1 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is annotated secreted [flag] and was detected in culture medium of HEK293T cells [PMID:33975953]; FGFR1 is annotated a transmembrane receptor [flag].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002609","LR005876"]},"LR001808":{"pair":"FAM3D -> FPR1","headline":"FAM3D acts as an agonist of FPR1 and FPR2 on human neutrophils, shown functionally with antagonists.","interaction_type":"functional only","direction_and_effect":"FAM3D induced Mac-1 activation and adhesion in human neutrophils, and this was inhibited by the FPR1 antagonist cyclosporin H, the FPR2 antagonist WRW, or the dual antagonist Boc-PLPLP; FAM3D deficiency reduced neutrophil recruitment and aneurysm in mice [PMID:29853563]. It signals through Gi protein and beta-arrestin pathways [PMID:29853563].","molecular_requirements":"The effect depended on both FPR1 and FPR2; blocking either reduced Mac-1 activation [PMID:29853563]. Ability of FPR1 alone to respond: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neutrophils and HUVECs; elastase- and CaPO4-induced mouse aneurysm models, FAM3D knockout mice [PMID:29853563]. The dossier includes human and mouse pairs.","localisation_and_range":"FAM3D is annotated secreted and FPR1 transmembrane [flag]; endothelial cells release FAM3D to act on neutrophils [PMID:29853563].","caveats":"Single paper, read in the abstract and excerpts; no direct binding or affinity shown, only antagonist inhibition. The paper cites earlier work calling FAM3D a dual FPR agonist [PMID:29853563].","key_references":[{"PMID":"29853563","why":"FAM3D activates neutrophil Mac-1 via FPR1/FPR2 in aortic aneurysm"}],"covers":["LR001808","LR005164"]},"LR005165":{"pair":"FAM3D -> FPR2","headline":"FAM3D acts as an agonist at FPR2 (and FPR1) in neutrophils; functional evidence from one full-text paper.","interaction_type":"functional only","direction_and_effect":"FAM3D is reported as a dual agonist of FPR1 and FPR2 that induces Mac-1-mediated neutrophil recruitment through FPR-related Gi protein and beta-arrestin signaling [PMID:29853563]. The FPR2 antagonist WRW13 (5 \u03bcmol/L) significantly inhibited FAM3D-induced Mac-1 activation and neutrophil adhesion [PMID:29853563].","molecular_requirements":"The effect depended on both FPR1 and FPR2; inhibiting either one blocked FAM3D-induced Mac-1 activation, and the dual antagonist Boc-PLPLP also blocked it [PMID:29853563]. FPR2 alone is therefore not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Experiments used human neutrophils (flow cytometry, antagonists) and FAM3D-knockout mice with elastase- or CaPO4-induced aneurysm [PMID:29853563]. Mouse pair is listed separately in the dossier, not as an ortholog projection.","localisation_and_range":"FAM3D is flagged secreted; FPR2 is flagged transmembrane receptor [flag]. Endothelial cell-derived FAM3D induced neutrophil recruitment [PMID:29853563].","caveats":"Single paper. No direct binding measurement (no Kd or binding assay) in our evidence; support is antagonist inhibition and signaling readouts. Receptor identity relies on pharmacology and the paper's statement that FPR1 and FPR2 are the functional receptors.","key_references":[{"PMID":"29853563","why":"Full-text study: FAM3D activates neutrophil Mac-1 via FPR1/FPR2, Gi and beta-arrestin signaling."}],"covers":["LR001809","LR005165"]},"LR000557":{"pair":"FBLN2 -> ITGB3","headline":"Fibulin-2 binds beta3 integrins (strongly alpha IIb beta 3), with cell-adhesion support and a species caveat.","interaction_type":"direct binding","direction_and_effect":"Mouse fibulin-2 bound alpha IIb beta 3 almost as strongly as fibrinogen [PMID:7543056]. Mouse fibulin-2 adhesion of HEL cells was mediated by beta3 integrins [PMID:10848816].","molecular_requirements":"RGD site of fibulin-2 is involved; human fibulin-2 with RSS bound less strongly [PMID:7543056]. The beta3 chain's partner (alpha IIb or alpha V) changes affinity [PMID:7543056].","affinity_potency":[],"species_and_systems":"Recombinant proteins and purified integrins [PMID:7543056]; HEL cell adhesion assays and mouse bone marrow culture [PMID:10848816].","localisation_and_range":"FBLN2 is flagged secreted [flag]; localised with fibronectin in bone marrow stroma [PMID:10848816].","caveats":"HEL cells did not adhere to human fibulin-2, and mouse megakaryocytes did not adhere to mouse fibulin-2, so adhesion is species- and cell-type-dependent [PMID:10848816]. Both papers abstract only. The adhesion paper does not show direct binding.","key_references":[{"PMID":"7543056","why":"Purified integrin binding by fibulin-2."},{"PMID":"10848816","why":"Fibulin-2 adhesion via beta3 integrins, species caveats."}],"covers":["LR000557","LR004048"]},"LR004049":{"pair":"FBN1 -> ITGA5","headline":"Fibrillin-1 supports adhesion via integrin alpha5 beta1; functional evidence, with affinity stated as low elsewhere.","interaction_type":"functional only","direction_and_effect":"Human dermal fibroblasts adhered to fibrillin-1 fragments and microfibrils via RGD and cations, with strong alpha 5 beta 1 interactions and some alpha v beta 3 contribution [PMID:12807887]. In HUVECs the fibrillin-1 fragment PF14 acted via alpha v beta 3 and alpha 5 beta 1 integrins to raise calcium [PMID:20686071].","molecular_requirements":"The receptor is the alpha5 beta1 heterodimer; an RGD-independent adhesion sequence was also found in fibrillin [PMID:12807887]. UniProt lists ITGA5:ITGB1 as a fibrillin-1 receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human fibroblasts and HUVECs with recombinant fragments or microfibrils [PMID:12807887] [PMID:20686071]. Reactome has a fibrillin-1 integrin binding reaction [DB:Reactome].","localisation_and_range":"FBN1 is flagged secreted and not transmembrane [flag]; microfibrils are matrix structures [PMID:12807887].","caveats":"Both papers abstract only and functional; direct binding is not shown in these two. No affinity reported in our evidence for this pair.","key_references":[{"PMID":"12807887","why":"Fibroblast adhesion to fibrillin-1 via alpha5beta1."},{"PMID":"20686071","why":"Endothelial signaling by fibrillin-1 fragment via alpha5beta1 and alphaVbeta3."}],"covers":["LR000558","LR004049"]},"LR008207":{"pair":"FBN1 -> ITGA5:ITGB1","headline":"One paper links a fibrillin-1 fragment to alpha5 beta1 signaling in endothelial cells; complex-level evidence is thin.","interaction_type":"functional only","direction_and_effect":"The RGD-containing fibrillin-1 fragment PF14 raised calcium in HUVECs through alpha v beta 3 and alpha 5 beta 1 integrins, and enhanced proliferation and migration [PMID:20686071]. UniProt states ITGA5:ITGB1 acts as a fibrillin-1 receptor [DB:UniProt].","molecular_requirements":"The complex members are ITGA5 and ITGB1 [flag]; the paper implicates the alpha5 beta1 heterodimer together with alpha v beta 3, not a single chain [PMID:20686071].","affinity_potency":[],"species_and_systems":"Human umbilical venous endothelial cells; effect confirmed in bovine aortic endothelial cells [PMID:20686071]. Reactome records fibrillin-1 integrin binding [DB:Reactome].","localisation_and_range":"FBN1 is flagged secreted, not transmembrane [flag]; it is an extracellular matrix microfibril component [PMID:20686071].","caveats":"Single paper, abstract only, with antagonist/pathway evidence rather than direct binding. Affinity not reported in our evidence.","key_references":[{"PMID":"20686071","why":"Fibrillin-1 fragment PF14 signals through alpha5beta1 and alphaVbeta3 in HUVECs."}],"covers":["LR008207"]},"LR002618":{"pair":"FCER2 -> ITGAX","headline":"CD23 binds CD11c-CD18 (CD11c is the alpha chain) in transfected cells and activates monocytes; single 1995 paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD23 liposomes bound COS cells expressing CD11c-CD18, inhibited by anti-CD11c and anti-CD23 mAbs; CD23 or anti-CD11c raised nitrite-oxidative products, IL-1 beta, IL-6 and TNF alpha in monocytes [PMID:7621072]. Labelled agonist.","molecular_requirements":"CD11c-CD18 heterodimer tested; CD11a-CD18 did not bind [PMID:7621072]. Alpha-chain-alone sufficiency not reported.","affinity_potency":[],"species_and_systems":"Human CD23, COS transfectants and human monocytes.","localisation_and_range":"CD23 flagged secreted and transmembrane [flag].","caveats":"Abstract-only read; no affinity reported.","key_references":[{"PMID":"7621072","why":"CD23 binding to CD11c-CD18 and monocyte activation"}],"covers":["LR002618"]},"LR000566":{"pair":"FGA -> ITGAM","headline":"Fibrinogen alphaEC domain and fibrinogen support alphaM-beta2 (Mac-1) adhesion in cells; functional, two abstract-level papers.","interaction_type":"functional only","direction_and_effect":"Recombinant alphaEC supported strong adhesion and migration of cells expressing alphaMbeta2, inhibited by anti-alphaM, anti-beta2 and neutrophil inhibitory factor [PMID:11588042]. Airway eosinophil adhesion to fibrinogen was blocked by anti-alphaMbeta2 and needs an activated alphaM [PMID:16601240].","molecular_requirements":"Evidence is for the alphaM-beta2 heterodimer. alphaM I domain binds alphaEC dose-dependently and saturably [PMID:11588042]. alphaEC is a domain of the fibrinogen-420 splice form [PMID:11588042].","affinity_potency":[],"species_and_systems":"Human U937, THP-1, neutrophils and transfectants (curator fields human) [PMID:11588042]; eosinophil species not recorded [PMID:16601240].","localisation_and_range":"FGA flagged secreted; ITGAM flagged not secreted [flag].","caveats":"Both abstract only; adhesion readouts rather than purified binding. The eosinophil assay used whole fibrinogen, not FGA specifically.","key_references":[{"PMID":"11588042","why":"alphaEC binds alphaM and alphaX I domains"},{"PMID":"16601240","why":"eosinophil adhesion to fibrinogen via alphaMbeta2"}],"covers":["LR000566"]},"LR000593":{"pair":"FGF1 -> CD44","headline":"Direct cell-surface binding of FGF1 to CD44 from one abstract-read proximity-labelling study; proposed as a reservoir, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"An APEX2-FGF1 proximity-labelling screen in RPE1 cells identified CD44 and CSPG4 as FGF1 interactors; FGF1 co-localized with both at the cell surface and binds CD44 through its heparin-binding moiety [PMID:29812912]. They are proposed as storage molecules forming an FGF1 reservoir rather than direct signalling receptors [PMID:29812912].","molecular_requirements":"FGF1 binds via its heparin-binding moiety, and CD44 is a proteoglycan co-receptor-like partner; the method was validated by detecting FGFR4 [PMID:29812912]. Whether a signalling complex forms is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human FGF1 and human RPE1 cells [PMID:29812912]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 is flagged secreted and CD44 flagged both secreted and transmembrane [flag]; the paper places the interaction at the cell surface [PMID:29812912].","caveats":"Abstract only; proximity labelling does not prove direct binding strength, no affinity reported. Curated as agonist but the paper frames CD44 as a non-signalling reservoir [PMID:29812912]. No database records.","key_references":[{"PMID":"29812912","why":"APEX2-FGF1 proximity labelling identifies CD44 and CSPG4"}],"covers":["LR000593","LR004077"]},"LR002627":{"pair":"FGF1 -> SDC2","headline":"FGF1 and SDC2 rest on one IntAct co-immunoprecipitation record; curated papers were insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"not reported in our evidence","affinity_potency":[],"species_and_systems":"Only an IntAct record from an anti-tag coimmunoprecipitation is available [DB:IntAct]; the experimental species are not reported in our evidence. The mouse pair is projected from human.","localisation_and_range":"SDC2 is flagged as a transmembrane receptor and FGF1 as secreted [flag].","caveats":"No curator-verified paper: two papers were judged abstract-insufficient. Support is a database assertion only [DB:IntAct]. Syndecan is a heparan sulfate proteoglycan, but our evidence does not say whether binding is direct or through heparan sulfate.","key_references":[{"PMID":"28514442","why":"source publication of the IntAct record (not curator-verified)"}],"covers":["LR002627","LR005893"]},"LR004058":{"pair":"FGF10 -> FGFR1","headline":"FGF10 weakly activates FGFR1b in a mitogenic assay; a weak, isoform-restricted functional signal.","interaction_type":"functional only","direction_and_effect":"In BaF3 cells FGF10 showed weak activity toward FGFR1b and did not activate the other FGFR-expressing lines tested [PMID:16597617]. UniProt lists FGF10 among weaker in vitro FGFR1 partners [DB:UniProt].","molecular_requirements":"Activity was seen with the FGFR1b splice form only; the dossier does not report activity on FGFR1c [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cell mitogenic assay with relative mitogenic activity against FGF1 as readout; species of constructs not reported [PMID:16597617]. Mouse pair projected from human.","localisation_and_range":"FGF10 flagged secreted; FGFR1 membrane receptor [flag]. Paracrine action is inferred from the flag.","caveats":"Described as weak. Full text read in a browser, quote unverified. A BioGRID protein-peptide record also exists [DB:BioGRID]. This is a weaker pair than FGF10-FGFR2.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity panel"}],"covers":["LR000574","LR004058"]},"LR000575":{"pair":"FGF10 -> FGFR2","headline":"FGF10 binds and activates FGFR2b specifically, supported by a co-crystal structure and binding data.","interaction_type":"direct binding","direction_and_effect":"FGF10 and FGF7 activate only the b isoform of FGFR2 [PMID:12591959]. FGF10 is a potent keratinocyte mitogen and bound the KGFR (FGFR2b) with high affinity but not detectably FGFR1c or FGFR2c [PMID:9582367]. FGF10 strongly activated FGFR2b in BaF3 cells [PMID:16597617]. Agonist.","molecular_requirements":"Isoform specificity comes from the alternatively spliced D3 domain: FGF10 contacts two b-specific loops, and FGF10 binding rotates Ig domain 2 [PMID:12591959]. Mitogenic activity differed from KGF in its heparin sensitivity [PMID:9582367].","affinity_potency":[{"value":"active from 0.1 nM, maximal at around 5 nM","assay":"mitogenesis of Balb/MK keratinocytes (potency, not binding)","system":"recombinant FGF-10 on mouse keratinocytes","cite":"PMID:9582367"}],"species_and_systems":"Crystal structure of the FGFR2b ligand-binding region with FGF10 [PMID:12591959] (PDB 1NUN) [DB:PDB 1NUN]. Recombinant human FGF10 on mouse cells [PMID:9582367]. BaF3 panel [PMID:16597617]. Mouse pair is projected.","localisation_and_range":"FGF10 flagged secreted [flag]; paracrine signalling from mesenchyme to epithelium is not stated in our evidence.","caveats":"Specific to FGFR2b, not FGFR2c: a gene-level FGF10-FGFR2 pair hides this. Two papers were abstract-only [PMID:12591959][PMID:9582367].","key_references":[{"PMID":"12591959","why":"co-crystal structure, b-isoform specificity"},{"PMID":"9582367","why":"high-affinity binding of FGF-10 to FGFR2b, no FGFR1c/2c"},{"PMID":"16597617","why":"strong FGFR2b activation in BaF3"}],"covers":["LR000575","LR004059"]},"LR004076":{"pair":"Fgf15 -> Klb","headline":"Mouse Fgf15 (ortholog of FGF19) binds KLB directly; supported by a single abstract-level binding paper.","interaction_type":"direct binding","direction_and_effect":"FGF19 and FGF21, but not FGF1, bound KLB [PMID:22442730]. KLB acts as a co-receptor that allows FGF19 to engage FGFR1 or FGFR4 [PMID:22442730].","molecular_requirements":"KLB co-receptor with FGFR1 or FGFR4; FGF19 binds FGFR1/FGFR4 only in presence of KLB [PMID:22442730].","affinity_potency":[],"species_and_systems":"Evidence is written for human FGF19, the ortholog of mouse Fgf15; the mouse pair is projected from human. Binding kinetics and mouse in vivo experiments [PMID:22442730].","localisation_and_range":"Fgf15 flagged secreted; KLB flagged a receptor [flag].","caveats":"Single paper, abstract-only read with some full-text excerpts; the direct-binding statement for FGF19-KLB is brief. KLB is a co-receptor, not a signalling receptor by itself; no affinity value in the dossier.","key_references":[{"PMID":"22442730","why":"FGF19 and FGF21 bind KLB; KLB needed for FGFR binding"}],"covers":["LR004076"]},"LR004067":{"pair":"FGF17 -> FGFR4","headline":"FGF17 activates the two-Ig-domain form of FGFR4 in BaF3 cells; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 activated the two Ig-like domain forms of FGFR4 (4delta) in addition to FGFR1c, 2c and 3c [PMID:16597617]. Agonist.","molecular_requirements":"The active form is the two Ig-like domain FGFR4 variant, which may differ from the canonical receptor [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF17 flagged secreted; FGFR4 flagged secreted and transmembrane [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFR4 delta"}],"covers":["LR000583","LR004067"]},"LR000584":{"pair":"FGF18 -> FGFR1","headline":"FGF18 activates FGFR1c in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-like domain form of FGFR4 [PMID:16597617]. Agonist.","molecular_requirements":"c isoform [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF18 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified; one abstract-insufficient paper not shown [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000584","LR004068"]},"LR004094":{"pair":"FGF2 -> FGFR3","headline":"FGF2 binds FGFR3 poorly yet activates it; evidence is mixed and mostly abstract-level.","interaction_type":"direct binding","direction_and_effect":"FGFR3 bound FGF8 and FGF9 well but FGF2 poorly [PMID:10574949]. Even so, fgf2 bound to FGFR3c produced higher activation-loop tyrosine phosphorylation than fgf1 despite lower binding strength [PMID:21894939]. FGF2 was reported to prefer c splice forms in BaF3 assays [PMID:8663044].","molecular_requirements":"Splice form FGFR3c was studied; the activity tracks the c form [PMID:21894939][PMID:8663044]. Heparin requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; HEK 293T cells expressing FGFR3c with ligand over 5 ng/ml to 5000 ng/ml [PMID:21894939]; soluble FGFR3 binding domain [PMID:10574949]. IntAct surface plasmon resonance [DB:IntAct].","localisation_and_range":"FGF2 annotated secreted, FGFR3 transmembrane [flag].","caveats":"Binding is weak relative to FGFR1 [PMID:10574949] and to fgf1 [PMID:21894939], so FGFR3 may be a low-affinity partner. Two of three papers abstract only. No affinity value in our evidence.","key_references":[{"PMID":"21894939","why":"FGF2 vs FGF1 on FGFR3c: weaker binding, higher phosphorylation"},{"PMID":"10574949","why":"FGFR3 binds FGF2 poorly"}],"covers":["LR000610","LR004094"]},"LR001817":{"pair":"FGF20 -> FGFR3","headline":"FGF20 is reported in a mitogenic screen to act on FGFR3b-expressing cells; single indirect source.","interaction_type":"functional only","direction_and_effect":"FGF9, 16 and 20 consistently showed activity toward FGFR3b-expressing cells in the BaF3 mitogenic assay [PMID:16597617].","molecular_requirements":"Only the b splice form of FGFR3 is named in the quote; other isoforms are not reported in our evidence [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cells engineered to express FGFRs; species unspecified [PMID:16597617]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF20 flagged secreted, FGFR3 transmembrane [flag].","caveats":"One paper, a subfamily-level statement not specific to FGF20; no binding data. A review row is not shown. The excerpt was browser-read and flagged unverifiable.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenic screen of the FGF family"}],"covers":["LR001817","LR005172"]},"LR002636":{"pair":"FGF21 -> KLB","headline":"FGF21 binds KLB directly in cell binding assays, supported also by structure and SPR records.","interaction_type":"direct binding","direction_and_effect":"Both FGF19 and FGF21, but not FGF1, show binding affinity to KLB [PMID:22442730]. KLB is described as an indispensable co-receptor for FGF21 engagement of FGFRs [PMID:22442730]. Curators label it agonist [PMID:22442730].","molecular_requirements":"KLB alone binds FGF21: 1 ug/ml FGF21 competed with 125I-FGF19 on KLB-only cells with over 90% efficiency [PMID:22442730]. KLB acts together with FGFR1 for FGF21 [PMID:22442730]; a PDB entry shows beta-Klotho with FGF21CT [DB:PDB 5VAQ].","affinity_potency":[{"value":"about 150 ng/ml","assay":"half-maximum competition of FGF21 against 125I-FGF19 (measured on FGFR1-KLB cells, not KLB alone)","system":"T-Rex 293 cells expressing FGFR1 and KLB","cite":"PMID:22442730"}],"species_and_systems":"Human reagents per curators; recombinant cell-based assays plus mouse signaling [PMID:22442730]. Human pair is ortholog-inferred, mouse pair is not.","localisation_and_range":"FGF21 flagged secreted [flag]; KLB flagged receptor [flag].","caveats":"Binding is shown by competition because iodinated FGF21 was inactive [PMID:22442730]. KLB is a co-receptor, not a signalling receptor on its own in this evidence.","key_references":[{"PMID":"22442730","why":"FGF21 and FGF19 binding to KLB, with FGF1 negative control"}],"covers":["LR002636","LR005902"]},"LR005174":{"pair":"FGF22 -> FGFRL1","headline":"FGFRL1 binds FGF22 with high affinity but lacks a kinase domain and acts as a decoy that antagonizes FGF signaling.","interaction_type":"direct binding","direction_and_effect":"Soluble FGFRL1 ectodomain and the membrane-bound receptor bind FGF22 among other FGFs with high affinity, by ligand dot blot, cell-based binding and surface plasmon resonance [PMID:19920134]. FGFRL1 is proposed as a decoy receptor and antagonizes FGFR signaling in Xenopus embryos [PMID:19920134].","molecular_requirements":"The intracellular domain lacks the split tyrosine kinase domain needed for signal transduction [PMID:19920134]. The ectodomain is shed from C2C12 myoblasts and HEK293 cells [PMID:19920134].","affinity_potency":[],"species_and_systems":"Human reagents per curators; C2C12 and HEK293 cells and Xenopus embryos [PMID:19920134].","localisation_and_range":"Both shed soluble and membrane-bound forms bind FGF22, so action can be at the cell surface or at a distance [PMID:19920134].","caveats":"Abstract-only reading; no numeric affinity given for FGF22 specifically. Antagonism was shown for FGFR signaling generally, not FGF22 specifically [PMID:19920134]. Mouse pair is projected from human.","key_references":[{"PMID":"19920134","why":"Shed and membrane FGFRL1 bind FGF22; decoy function"}],"covers":["LR001819","LR005174"]},"LR000638":{"pair":"FGF8 -> FGFR2","headline":"FGF8 activates FGFR2c in BaF3 assays; a PDB structure and BioGRID record exist.","interaction_type":"functional only","direction_and_effect":"FGF8 subfamily members specifically activated FGFRs 1c, 2c and 3c and FGFR4 (4\u0394) [PMID:16597617]; FGFs 4, 5, 6 and 8 specifically activate c splice forms [PMID:8663044]. The pair is annotated stimulatory.","molecular_requirements":"c splice form of FGFR2 is responsive [PMID:16597617]. A PDB entry 2FDB contains a chain of each partner [DB:PDB 2FDB]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:16597617][PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Both papers are the same BaF3 mitogenic format with browser-read quotes pending spot-check; no direct binding assay or affinity in our evidence. The PDB detail does not state species.","key_references":[{"PMID":"16597617","why":"FGF8 subfamily activates FGFR2c"},{"PMID":"8663044","why":"FGF8 activates c splice forms"}],"covers":["LR000638","LR004122"]},"LR005903":{"pair":"FGFBP1 -> NRP1","headline":"FGFBP1 bound NRP1 on an optical biosensor; one paper, binding only.","interaction_type":"direct binding","direction_and_effect":"FGF-binding protein interacted with neuropilin-1 immobilised on a biosensor [PMID:15695515]. Effect on signalling is not reported for FGFBP1.","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on NRP1 [PMID:15695515].","affinity_potency":[],"species_and_systems":"Human proteins; recombinant biosensor assay [PMID:15695515]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"FGFBP1 is flagged secreted; NRP1 transmembrane [flag].","caveats":"Single paper. Strong binding for FGF-1, 2, 4 and 7 is stated in the full text; FGFBP1 is only listed among interacting proteins, and the solution assay was shown for FGF-2, FGF-4 and HGF/SF, not FGFBP1 [PMID:15695515]. Kinetic constants quoted are for other ligands. Heparin-mediated bridging is possible.","key_references":[{"PMID":"15695515","why":"Biosensor screen of heparin-binding proteins on NRP1"}],"covers":["LR002637","LR005903"]},"LR000647":{"pair":"FGG -> ITGB2","headline":"Eosinophil adhesion to fibrinogen depends on alphaMbeta2 (beta2 chain); one functional paper.","interaction_type":"functional only","direction_and_effect":"Airway eosinophil adhesion to fibrinogen was alphaMbeta2-mediated and blocked by anti-alphaMbeta2 [PMID:16601240].","molecular_requirements":"ITGB2 acts as the beta chain with ITGAM (alphaMbeta2); the assay used whole fibrinogen [PMID:16601240].","affinity_potency":[],"species_and_systems":"Eosinophils; organism not stated in the dossier abstract [PMID:16601240]. Mouse pair ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"One paper, abstract only, adhesion not binding; chain attribution follows the resource encoding. No database records.","key_references":[{"PMID":"16601240","why":"Eosinophil adhesion to fibrinogen via alphaMbeta2"}],"covers":["LR000647","LR004131"]},"LR009404":{"pair":"FGL1 -> EGFR","headline":"FGL1 (hepassocin) activates EGFR signalling in hepatocytes; direct binding not shown.","interaction_type":"functional only","direction_and_effect":"Hepassocin induced EGFR phosphorylation in human L02 hepatocytes with Src activation, driving ERK-dependent proliferation [PMID:24768768].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human L02 hepatocyte line and primary hepatocytes [PMID:24768768].","localisation_and_range":"FGL1 is flagged secreted and EGFR transmembrane [flag].","caveats":"One paper, abstract only. Pathway activation does not prove direct binding; the curator notes medium confidence. No database records.","key_references":[{"PMID":"24768768","why":"Hepassocin induces EGFR phosphorylation and ERK activation"}],"covers":["LR009404"]},"LR002645":{"pair":"FLRT1 -> UNC5C","headline":"FLRT1 binds UNC5C directly in a full-text extracellular binding screen; one paper, no affinity reported.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. In stripe assays FLRT1 elicited attraction (16%) or repulsion (5%) in a small share of neurons, and Unc5C repelled 11% [PMID:26633812]; whether the FLRT1-UNC5C pair drives these responses was not tested in our evidence.","molecular_requirements":"Purified ectodomains were used for the ELISA titrations and full-length proteins for the cell aggregation assay; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding screen used purified ectodomains and CHO.K1 cells; neurite assays used mouse retinal neurons. The record covers a human and a mouse pair; the paper's species labels in the curated row are human for both partners [PMID:26633812].","localisation_and_range":"Both partners carry transmembrane flags and the cell aggregation assay indicates interaction between opposing cell surfaces (contact-mediated) [PMID:26633812]; FLRT1 is also flagged secreted [flag].","caveats":"Single paper only; the pair-specific functional effect is not shown. Retinal neurons repelled by Unc5C expressed FLRT2 but not FLRT1 or FLRT3 [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Full-text screen showing all FLRT x Unc5 pairs bind near saturation."}],"covers":["LR002645","LR005911"]},"LR005912":{"pair":"FLRT1 -> UNC5D","headline":"FLRT1 binds UNC5D directly in a full-text extracellular binding screen; one paper, no affinity reported.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. In stripe assays FLRT1 elicited attraction (16%) or repulsion (5%) in a small share of neurons, and Unc5D repelled 12% [PMID:26633812]; the pair-specific effect was not tested in our evidence.","molecular_requirements":"Purified ectodomains were used for the ELISA titrations and full-length proteins for the cell aggregation assay; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding screen used purified ectodomains and CHO.K1 cells; neurite assays used mouse retinal neurons. The record covers a human and a mouse pair; the paper's species labels in the curated row are human for both partners [PMID:26633812].","localisation_and_range":"Both partners carry transmembrane flags and the cell aggregation assay indicates interaction between opposing cell surfaces (contact-mediated) [PMID:26633812]; FLRT1 is also flagged secreted [flag].","caveats":"Single paper only; no affinity and no pair-specific functional result.","key_references":[{"PMID":"26633812","why":"Full-text screen showing all FLRT x Unc5 pairs bind near saturation."}],"covers":["LR002646","LR005912"]},"LR002654":{"pair":"FLRT2 -> UNC5C","headline":"FLRT2 and UNC5C are a repulsive pair in retinal neurons, shown in both orientations in one paper.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. Neurons expressing FLRT2 are repelled by Unc5C stripes, and neurons expressing Unc5C are repelled by FLRT2 stripes; full-length FLRT2-myc transfection repelled neurons from Unc5C stripes [PMID:26633812]. FLRT2 and Unc5C expression is complementary in vivo [PMID:26633812].","molecular_requirements":"Not reported in our evidence beyond ectodomain interaction.","affinity_potency":[],"species_and_systems":"Mouse retinal neurons in culture and mouse retina in vivo; binding on purified ectodomains and CHO.K1 cells [PMID:26633812]. Human version is ortholog-inferred.","localisation_and_range":"Interaction between opposing cell surfaces (contact-mediated); FLRT2 also flagged secreted [flag; PMID:26633812].","caveats":"Single paper. Neurons transfected with Unc5C-FLAG were not repelled by Unc5C stripes [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Screen plus FLRT2-Unc5C bidirectional repulsion."}],"covers":["LR002654","LR005920"]},"LR005921":{"pair":"FLRT2 -> UNC5D","headline":"FLRT2 binds UNC5D directly; supported by a binding screen and a repulsion study, plus BioGRID reconstituted-complex records.","interaction_type":"direct binding","direction_and_effect":"UNC5D binds FLRT2 specifically, and shed FLRT2/3 ectodomains act as repulsive guidance cues for Unc5-positive neurons; deleting FLRT2 or Unc5D makes SVZ neurons migrate prematurely to the cortical plate, while Unc5D overexpression has the opposite effect [PMID:21673655]. In a 126 x 126 extracellular screen, all twelve FLRT x Unc5 combinations bound near saturation [PMID:26633812].","molecular_requirements":"Ectodomains are sufficient for binding in the screen (purified ectodomains) [PMID:26633812]; no subunit or co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Screen used purified ectodomains, CHO.K1 aggregation and mouse retina [PMID:26633812]; the 2011 paper studied developing mouse neocortex neurons (read as abstract only, species not stated in the abstract) [PMID:21673655]. Dossier lists human and mouse interactions; the human one is ortholog-inferred.","localisation_and_range":"FLRT2 is annotated secreted and transmembrane [flag]; shed ectodomains act as repulsive cues [PMID:21673655], so both soluble and contact modes are possible. UNC5D is a transmembrane receptor [flag].","caveats":"The 2011 paper was read as abstract only. No affinity reported in our evidence. BioGRID lists reconstituted-complex records [DB:BioGRID].","key_references":[{"PMID":"21673655","why":"Unc5D binds FLRT2 specifically; repulsion and migration phenotypes"},{"PMID":"26633812","why":"Binding screen showing all FLRT x Unc5 pairs bind"}],"covers":["LR002655","LR005921"]},"LR007208":{"pair":"FLRT3:TENM2 -> ADGRL2","headline":"Database-only: UniProt text for FLRT3 and latrophilins, no curated paper evidence for this complex.","interaction_type":"database-asserted only","direction_and_effect":"No papers are available. UniProt states FLRT3 interacts with ADGRL1/LPHN1 and LPHN2 via the olfactomedin-like domain (by similarity) [DB:UniProt].","molecular_requirements":"A joint FLRT3:TENM2 complex acting on ADGRL2 is not shown in our evidence; the record covers FLRT3 only.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"FLRT3 secreted/transmembrane and TENM2 transmembrane by annotation [flag].","caveats":"Three judged rows are pending and no papers shown. The single UniProt record is by similarity and does not mention TENM2.","key_references":[],"covers":["LR007208"]},"LR004139":{"pair":"FN1 -> COL13A1","headline":"Direct binding of the type XIII collagen ectodomain to fibronectin is shown by SPR, from one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"By surface plasmon resonance, the recombinant COL13A1 ectodomain interacted with immobilized fibronectin [PMID:11956183]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Fibronectin binding mapped to the collagenous domains of the ectodomain, which forms 240-kDa trimers [PMID:11956183].","affinity_potency":[{"value":"KD in the nanomolar range","assay":"surface plasmon resonance","system":"recombinant shed ectodomain on immobilized fibronectin","cite":"PMID:11956183"}],"species_and_systems":"Human, per curator fields; recombinant ectodomain purified from insect cell culture; mouse pair orthology-inferred [PMID:11956183].","localisation_and_range":"COL13A1 is flagged transmembrane; the ectodomain is shed [PMID:11956183]; FN1 secreted [flag].","caveats":"Single paper read as an abstract only; no exact KD value in our evidence.","key_references":[{"PMID":"11956183","why":"SPR binding of the collagen XIII ectodomain to fibronectin"}],"covers":["LR000655","LR004139"]},"LR002663":{"pair":"FN1 -> DPP4","headline":"Fibronectin binding sites for DPPIV were mapped to FNIII repeats 13-15 in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"DPPIV bound fibronectin type III repeats 13, 14 and 15 via the consensus motif T(I/L)TGLX(P/R)G(T/V)X, confirmed by motif swapping; peptides from FNIII14 blocked DPPIV/poly-FN adhesion and impeded pulmonary metastasis [PMID:12716896]. Adhesion-type interaction.","molecular_requirements":"Polymeric fibronectin on cell surfaces binds lung endothelial DPPIV [PMID:12716896].","affinity_potency":[],"species_and_systems":"Human proteins per curator fields; the metastasis experiment is in vivo, species not stated in our evidence; mouse pair is orthology-inferred [PMID:12716896].","localisation_and_range":"DPPIV flagged transmembrane, FN1 secreted [flag]; poly-FN decorates cell surfaces [PMID:12716896].","caveats":"One paper, abstract only; no affinity values.","key_references":[{"PMID":"12716896","why":"maps DPPIV binding motif in fibronectin type III repeats"}],"covers":["LR002663","LR005929"]},"LR005930":{"pair":"FN1 -> FLRT2","headline":"FLRT2 co-immunoprecipitates and colocalizes with fibronectin in chondroprogenitor cells; direct contact is not shown.","interaction_type":"direct binding","direction_and_effect":"FLRT2 colocalized with fibronectin on the cell surface and in ECM, associated with Fn-coated beads, and decreased when Fn fibril formation was blocked; co-immunoprecipitation showed they interact directly or indirectly [PMID:24585683].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"ATDC5 chondroprogenitor cell line; curator fields list human, and the mouse pair is not orthology-inferred [PMID:24585683].","localisation_and_range":"FLRT2 is flagged secreted and transmembrane, FN1 secreted [flag]; FLRT2 was found in the ECM [PMID:24585683].","caveats":"Single abstract-only paper; co-immunoprecipitation cannot separate direct from indirect binding, and the curator label of direct binding is stronger than the text.","key_references":[{"PMID":"24585683","why":"FLRT2-fibronectin colocalization and co-IP in ATDC5 cells"}],"covers":["LR002664","LR005930"]},"LR007019":{"pair":"FN1 -> ITGA2B:ITGB3","headline":"Fibronectin-alphaIIbbeta3 binding is supported by one confirmed paper and several structural and database records.","interaction_type":"direct binding","direction_and_effect":"A fibronectin peptide from the 29-kDa C-terminal heparin-binding fragment bound directly to alphaIIbbeta3 and blocked fibronectin fragment binding to stimulated platelets and ADP-induced aggregation [PMID:8663002]. Crystal structures with chains of both partners are recorded [DB:PDB 4MMX], and IntAct lists solid-phase and X-ray records [DB:IntAct]. Adhesion-type interaction.","molecular_requirements":"Both alphaIIb and beta3 are needed as the heterodimer; BioGRID lists reconstituted-complex records for each chain with FN1 [DB:BioGRID]. The new site is RGD-independent [PMID:8663002].","affinity_potency":[],"species_and_systems":"Human platelets and human fibronectin fragments [PMID:8663002].","localisation_and_range":"FN1 flagged secreted; integrin flagged transmembrane [flag]; matrix-to-cell contact.","caveats":"Only one confirmed paper, read as an abstract. 2 review-only and 2 abstract-insufficient papers were not used.","key_references":[{"PMID":"8663002","why":"novel non-RGD fibronectin site binds alphaIIbbeta3 on platelets"}],"covers":["LR007019"]},"LR008225":{"pair":"FN1 -> ITGA9:ITGB1","headline":"Alpha9beta1 mediates adhesion to the fibronectin EIIIA segment; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Either alpha9beta1 or alpha4beta1 can mediate cell adhesion to the EIIIA segment [PMID:11839764].","molecular_requirements":"EIIIA-segment specific: the segment is present only in alternatively spliced FN1 [PMID:11839764].","affinity_potency":[],"species_and_systems":"Labelled human for ligand and receptor [PMID:11839764]; cell system not detailed in our evidence.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Single abstract-only paper; assay is cell adhesion, not purified binding. Database records listed are for FN1-ITGB1 and do not address alpha9 [DB:BioGRID].","key_references":[{"PMID":"11839764","why":"Cell adhesion to EIIIA via alpha9beta1 or alpha4beta1"}],"covers":["LR008225"]},"LR004148":{"pair":"FN1 -> ITGB1","headline":"Fibronectin binds beta1 integrins, with cryo-EM and SPR data, but papers span several alpha partners.","interaction_type":"direct binding","direction_and_effect":"FN1 acts on alpha5beta1 with structural opening of the integrin [PMID:33962943]; muscle-secreted FN1 acts via hepatic alpha5beta1 [PMID:36812915]. Annotated stimulatory [flag].","molecular_requirements":"ITGB1 requires an alpha partner. Cryo-EM of human alpha5beta1 with fibronectin shows interactions at the RGD loop, synergy site and a new site [PMID:33962943]. Other papers show alpha3beta1 binding depends on the ninth type III repeat [PMID:26318455], alpha4beta1 for CS-1 [PMID:9842903], alpha8beta1 [PMID:7626807], and alpha5beta1 for hESC adhesion [PMID:18599809].","affinity_potency":[],"species_and_systems":"Human cryo-EM [PMID:33962943]; hESC [PMID:18599809]; human T cells [PMID:9842903]; human chondrocytes [PMID:7688313]; exercised mice [PMID:36812915].","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Many rows are abstract-only and concern different alpha chains, so this pair does not say which alpha is needed. PMID:7688313 only shows anti-beta1 blocking of chondrocyte adhesion. Databases support FN1-ITGB1 [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"33962943","why":"Cryo-EM structure of alpha5beta1 with fibronectin"},{"PMID":"26318455","why":"SPR of alpha3beta1 binding to fibronectin fragments"},{"PMID":"36812915","why":"In vivo mouse role of FN1 via alpha5beta1"}],"covers":["LR000664","LR004148"]},"LR000665":{"pair":"FN1 -> ITGB3","headline":"Fibronectin binds beta3 integrins (alphavbeta3, alphaIIbbeta3) in several assays; support is multi-paper but mostly integrin-complex level.","interaction_type":"direct binding","direction_and_effect":"Purified alphavbeta3 bound fibronectin among other ligands [PMID:1694173]. A fibronectin-derived peptide (Ala1704-Glu1718) bound directly to alphaIIbbeta3 and inhibited fibronectin-fragment binding to platelets [PMID:8663002]. In mouse trophoblast cells an anti-alphaIIb antibody blocked fibronectin-driven outgrowth, an agonist-type adhesion effect [PMID:15031111].","molecular_requirements":"The receptor is the integrin heterodimer: alphaV-beta3 [PMID:1694173, PMID:11423542] or alphaIIb-beta3 [PMID:8663002, PMID:28092265], not beta3 alone. The fibronectin synergy site reinforces alphaIIbbeta3 binding [PMID:28092265]. A C-terminal heparin-binding site acts in addition to RGD [PMID:8663002].","affinity_potency":[],"species_and_systems":"Human purified/platelet systems [PMID:1694173, PMID:8663002]; mouse trophoblast with human fibronectin [PMID:15031111]; Fn1 synergy-site mutant mice [PMID:28092265]. Structures (PDB 4MMX, 6NAJ) are listed [DB:PDB 4MMX].","localisation_and_range":"Fibronectin is flagged secreted [flag]; it acts as an adhesive matrix ligand (matrix-bound, contact-dependent), inferred from paper context.","caveats":"Several papers were read as abstracts only. Affinity not reported in our evidence. 8663002 is a competition readout flagged borderline and concerns alphaIIbbeta3. 1694173 is mainly about alphavbeta5. Database support: BioGRID, IntAct, Reactome [DB:Reactome R-HSA-349593].","key_references":[{"PMID":"11423542","why":"alphav-beta3 adhesion to fibronectin versus vitronectin"},{"PMID":"8663002","why":"Fibronectin peptide binds alphaIIbbeta3 directly"},{"PMID":"28092265","why":"Fibronectin synergy site and beta3 integrins in mice"}],"covers":["LR000665","LR004149"]},"LR001826":{"pair":"FNDC5 -> ITGAV","headline":"Irisin (FNDC5) binds alphaV-class integrins; binding plus functional and mouse knockout evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Irisin binds alphaV-class integrins; chemical inhibition of alphaV integrins blocked irisin signalling in osteocytes and fat cells, and irisin increased osteocyte survival and sclerostin production [PMID:30550785]. Agonist-type effect.","molecular_requirements":"Interaction mapped to alphaV/beta5 integrin, so the receptor is the integrin heterodimer [PMID:30550785].","affinity_potency":[],"species_and_systems":"Recombinant irisin in cultured cells and mice; FNDC5-null mice were protected from ovariectomy-induced bone loss [PMID:30550785].","localisation_and_range":"FNDC5 flagged secreted [flag]; irisin is described as a muscle-secreted hormone (endocrine) [PMID:30550785].","caveats":"Single paper, abstract-level curation plus excerpts; no affinity values reported in our evidence. No database record.","key_references":[{"PMID":"30550785","why":"Irisin binds alphaV integrins"}],"covers":["LR001826","LR005181"]},"LR008423":{"pair":"FPR2 -> ANXA1","headline":"Database-asserted only: UniProt notes ANXA1 binding to FPR2.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states binding of ANXA1 to the FPR2 homodimer activates p38 MAPK signalling, HSPB1 phosphorylation and IL10 production in monocytes [DB:UniProt].","molecular_requirements":"not reported in our evidence; UniProt notes FPR2 homodimerization is potentiated by ANXA1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond UniProt annotation.","localisation_and_range":"FPR2 flagged transmembrane receptor; ANXA1 flagged secreted [flag].","caveats":"No curator-verified papers (two pending). Support rests on UniProt only. Stored receptor-first.","key_references":[],"covers":["LR008423"]},"LR005183":{"pair":"FSTL1 -> DIP2A","headline":"DIP2A is identified as an FSTL1 receptor in endothelial cells and cardiac myocytes; co-IP plus knockdown evidence.","interaction_type":"direct binding","direction_and_effect":"DIP2A bound FSTL1 by co-immunoprecipitation; DIP2A siRNA reduced FSTL1 binding to cells, and reduced FSTL1-stimulated survival, migration, network formation and Akt phosphorylation [PMID:20054002]. In cardiac myocytes, DIP2A ablation reduced protection against hypoxia/reoxygenation apoptosis [PMID:20054002]. Agonist.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial cell membrane fraction and cultured cardiac myocytes; both human and mouse pairs are ortholog-inferred [PMID:20054002].","localisation_and_range":"DIP2A is on the endothelial cell surface; FSTL1 is flagged secreted [PMID:20054002, flag].","caveats":"One paper, abstract only; no affinity values. UniProt wording is that DIP2A 'may act' as a receptor [DB:UniProt]. IntAct also lists a competition binding and two-hybrid record [DB:IntAct].","key_references":[{"PMID":"20054002","why":"DIP2A identified as FSTL1 receptor"}],"covers":["LR001828","LR005183"]},"LR004157":{"pair":"GALP -> GALR1","headline":"Human GALP binds GALR1 in transfected human cells (IC50 77 nM); a single abstract-level paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"GALP acts as an agonist at GALR1; competition binding in SH-SY5Y cells showed lowest affinity of the three subtypes [PMID:15944009]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. GALP(3-32) is at least as potent as full-length GALP(1-60) in the same study [PMID:15944009].","affinity_potency":[{"value":"IC50 = 77 nM","assay":"competition ligand binding","system":"human neuroblastoma SH-SY5Y cells transfected with the receptor, human GALP(1-60)","cite":"PMID:15944009"}],"species_and_systems":"Human receptor in transfected human SH-SY5Y cells; the dossier lists the ligand species as porcine for the experiment. The mouse pair is projected from human evidence.","localisation_and_range":"GALP is flagged as secreted and the receptor as a transmembrane receptor [flag].","caveats":"Single paper, abstract only; other papers are pending. GALP shares its N-terminal 13 residues with galanin, so cross-reactivity with galanin receptors is expected, not specific [PMID:15944009].","key_references":[{"PMID":"15944009","why":"Ligand binding of human GALP(1-60) at GalR1, GalR2 and GalR3"}],"covers":["LR000673","LR004157"]},"LR000674":{"pair":"GALP -> GALR2","headline":"Human GALP binds GALR2 in transfected human cells (IC50 28 nM); a single abstract-level paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"GALP acts as an agonist at GALR2; competition binding in SH-SY5Y cells showed intermediate affinity of the three subtypes [PMID:15944009]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. GALP(3-32) is at least as potent as full-length GALP(1-60) in the same study [PMID:15944009].","affinity_potency":[{"value":"IC50 = 28 nM","assay":"competition ligand binding","system":"human neuroblastoma SH-SY5Y cells transfected with the receptor, human GALP(1-60)","cite":"PMID:15944009"}],"species_and_systems":"Human receptor in transfected human SH-SY5Y cells; the dossier lists the ligand species as porcine for the experiment. The mouse pair is projected from human evidence.","localisation_and_range":"GALP is flagged as secreted and the receptor as a transmembrane receptor [flag].","caveats":"Single paper, abstract only; other papers are pending. GALP shares its N-terminal 13 residues with galanin, so cross-reactivity with galanin receptors is expected, not specific [PMID:15944009].","key_references":[{"PMID":"15944009","why":"Ligand binding of human GALP(1-60) at GalR1, GalR2 and GalR3"}],"covers":["LR000674","LR004158"]},"LR004166":{"pair":"GAST -> CCKBR","headline":"Functional agonist evidence from gastrin I in CHO cells expressing human CCK-B receptor; direct gastrin binding is not shown.","interaction_type":"functional only","direction_and_effect":"Gastrin I markedly augmented phosphoinositide hydrolysis and cytosolic free calcium in CHO cells expressing the human CCK-B receptor, and dose-dependently increased [3H]thymidine incorporation [PMID:8349705]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[],"species_and_systems":"Human brain CCK-B receptor expressed in CHO cells; human ligand [PMID:8349705]. The mouse pair is projected from human evidence.","localisation_and_range":"GAST is flagged secreted and CCKBR transmembrane [flag].","caveats":"Human CCK-B receptor had slightly but significantly higher affinity for CCK-8 than for gastrin I, so CCK is the preferred ligand in that system [PMID:8349705]. The cloning paper did not test gastrin binding directly; identity of the CCK-B and gastrin receptors was inferred from sequence and Southern blots [PMID:7681836]. Both papers are abstract-only. The ligand entity is named desulfated gastrin-14, but the paper tested gastrin I; sulfation state is not reported in our evidence. Structures exist [DB:PDB 7F8V].","key_references":[{"PMID":"8349705","why":"Gastrin I activates signalling and growth via human CCK-B receptor"},{"PMID":"7681836","why":"Cloning of the human CCK-B/gastrin receptor, gastrin not directly tested"}],"covers":["LR000682","LR004166"]},"LR000683":{"pair":"GCG -> GCGR","headline":"Well-established agonist pair with a receptor crystal structure and database support; the structure paper models, not solves, glucagon binding.","interaction_type":"direct binding","direction_and_effect":"Glucagon binding to GCGR triggers glucose release from the liver during fasting [PMID:23863937]. GtoPdb lists glucagon as a full agonist [DB:GtoPdb].","molecular_requirements":"The crystal structure of the human GCGR seven-transmembrane domain at 3.4 A, with mutagenesis and a hybrid glucagon model, shows the ~12 kDa extracellular domain positioned by a stalk on TM1 to capture glucagon and insert its N-terminus into the transmembrane domain [PMID:23863937]. PDB complexes exist [DB:PDB 5YQZ] [DB:PDB 6LMK]. IntAct lists saturation binding [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human GCGR structure and mutagenesis [PMID:23863937]; the mouse pair is projected from human evidence.","localisation_and_range":"GCG is flagged secreted and GCGR transmembrane [flag].","caveats":"Only two papers are confirmed; three were abstract-insufficient and one review-only. The structure paper's glucagon complex is a model. No affinity values are reported in our evidence; GtoPdb gives pEC50 units without a value shown [DB:GtoPdb].","key_references":[{"PMID":"23863937","why":"Crystal structure of the human GCGR transmembrane domain with glucagon model"}],"covers":["LR000683","LR004167"]},"LR002672":{"pair":"GDF1 -> ACVR1B","headline":"Weak functional evidence only: a GDF3 paper cites GDF1 as using ALK4 (ACVR1B); GtoPdb asserts agonism.","interaction_type":"functional only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at this receptor [DB:GtoPdb]. The only paper states that GDF3 signalling, 'similar to GDF1', is mediated by ALK4, ActRIIA, ActRIIB and Cripto in Smad-dependent reporter assays [PMID:17936261].","molecular_requirements":"Type I ALK4, type II ActRIIA/ActRIIB and the co-receptor Cripto are named; native GDF1 was incapable of signalling in heterologous cells unless a heterologous prodomain, Furin or Nodal co-expression was used [PMID:17936261].","affinity_potency":[],"species_and_systems":"Mouse is the species with primary evidence; the human pair is ortholog-projected. The abstract does not state the cell species [PMID:17936261].","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"Abstract-only. GDF1 receptor usage is background in a paper about GDF3, not its own result [PMID:17936261]. Native GDF1 is poorly processed, so potency is not reported in our evidence.","key_references":[{"PMID":"17936261","why":"GDF3 (and, by reference, GDF1) use ALK4, ActRIIA/B and Cripto"}],"covers":["LR002672","LR005937"]},"LR007226":{"pair":"GDF11 -> ACVR2B:TGFBR1","headline":"Genetic evidence in mice supports ACVR2B with ALK5 in GDF11 signalling; PDB 6MAC shows the ternary assembly.","interaction_type":"functional only","direction_and_effect":"An Alk5 heterozygous mutation, not Alk4 or Alk7, potentiated Gdf11-null-like phenotypes in an Acvr2b-null background [PMID:16845371].","molecular_requirements":"Both a type II (ACVR2B) and a type I (ALK5/TGFBR1) chain are implicated [PMID:16845371]; PDB 6MAC has chains of O95390 and P36897 [DB:PDB 6MAC]; IntAct SPR O95390-Q13705 [DB:IntAct].","affinity_potency":[],"species_and_systems":"Mouse genetics [PMID:16845371].","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"Abstract-only paper; genetic interaction rather than binding. Affinity not reported.","key_references":[{"PMID":"16845371","why":"Alk5 and Acvr2b genetic interaction in GDF11 signalling"}],"covers":["LR007226"]},"LR002681":{"pair":"GDF11 -> TGFBR1","headline":"In mice, GDF11 signals through ALK5 (TGFBR1) alongside ALK4; supported by genetics and a PDB structure.","interaction_type":"functional only","direction_and_effect":"GDF11 predominantly uses ALK4 and ALK5 to activate a Smad3-dependent reporter, and Alk5 mutant embryos show patterning defects resembling Gdf11-null mutants [PMID:16845371].","molecular_requirements":"A type II receptor is involved: the interaction was genetic with Acvr2b [PMID:16845371]; PDB 6MAC has chains of O95390 and P36897 [DB:PDB 6MAC].","affinity_potency":[],"species_and_systems":"Mouse reporter assays and embryos [PMID:16845371]; both pairs ortholog-inferred.","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"Abstract-only paper; no affinity in our evidence.","key_references":[{"PMID":"16845371","why":"ALK5 mediates GDF11 signalling in embryogenesis"}],"covers":["LR002681","LR005946"]},"LR004175":{"pair":"GDF2 -> ACVR2A","headline":"BMP-9 binds the type-II receptor ActRIIA weakly; signalling through it is shown in endothelial and ovarian cells, with ALK1 or ALK2 as the type-I partner.","interaction_type":"direct binding","direction_and_effect":"BMP-9 acts as an agonist: knockdown of ActRIIA and/or BMPRII reduced BMP9-induced BRE-luciferase reporter activity in IOSE397 ovarian surface epithelial cells [PMID:19996292]. In endothelial cells, BMP9 induction of EphrinB2 depended on Alk1 and at least one of BMPRII or ActRII [PMID:22622516]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"ActRIIA acts as a type-II receptor alongside a type-I receptor: ALK1 in endothelial cells [PMID:22622516], or an ALK2/ActRIIA/BMPRII complex in IOSE397 cells [PMID:19996292]. BMPRII can substitute for ActRIIA in the endothelial readout [PMID:22622516].","affinity_potency":[],"species_and_systems":"Binding was reported in transfected COS cells (weak for ActR-II, high for ALK1 and endoglin) [PMID:17311849]. The curator-verified BMP9 papers are largely human cell systems (IOSE397 ovarian cells, endothelial cells); the mouse pair is projected from human evidence.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"Binding to ActRIIA is weak compared with ALK1 [PMID:17311849]. Two of the four papers were read as abstracts only [PMID:17311849][PMID:22622516]. The 22718755 abstract reports type-II discrimination by BMP9 but does not give ActRIIA values in our evidence [PMID:22718755]. BioGRID lists reconstituted-complex records [DB:BioGRID].","key_references":[{"PMID":"19996292","why":"ActRIIA/BMPRII knockdown reduces BMP9 reporter activity (full text)"},{"PMID":"17311849","why":"BMP-9 binding to ActR-II in COS cells"},{"PMID":"22622516","why":"BMP9 signalling needs Alk1 plus BMPRII or ActRII"}],"covers":["LR000691","LR004175"]},"LR000692":{"pair":"GDF2 -> ACVR2B","headline":"BMP-9 binds ActRIIB directly, with a crystal structure and cell-free binding data; the binding is weaker than to ALK1.","interaction_type":"direct binding","direction_and_effect":"BMP-9 is an agonist-type ligand in a ternary complex with ALK1 and ActRIIB [PMID:22718755][DB:PDB 4FAO]. Activin A competed with BMP-9 for binding to recombinant ACVR2A and ACVR2B in a cell-free assay, and activin A inhibited BMP-9 signalling in myeloma cells [PMID:26047946].","molecular_requirements":"Crystal structure of a ternary complex of BMP9 with the extracellular domains of ALK1 and ActRIIB [PMID:22718755]. BMP-9 also bound ActR-IIB in HUVECs [PMID:17311849].","affinity_potency":[],"species_and_systems":"Crystal structure and ELISA-type binding used recombinant extracellular domains [PMID:22718755][PMID:26047946]; HUVEC cross-linking [PMID:17311849]; myeloma cell lines for function [PMID:26047946]. Species of the structure is not stated for this row.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"BMP-9 binds ActR-IA, ActR-IIA and ActR-IIB only weakly by BIAcore [PMID:15851468]. Activin A competes for the same receptor [PMID:26047946]. Two binding sentences were read from a browser and are marked unverified [PMID:15851468][PMID:17311849]; the 22718755 and 15851468 papers are abstract-level in the dossier.","key_references":[{"PMID":"22718755","why":"Crystal structure of BMP9-ALK1-ActRIIB ternary complex"},{"PMID":"26047946","why":"Direct BMP-9 binding to recombinant ACVR2B; activin A competition"},{"PMID":"15851468","why":"BIAcore: weak BMP-9 binding to ActR-IIB"}],"covers":["LR000692","LR004176"]},"LR004184":{"pair":"GDF5 -> BMPR2","headline":"GDF5 binds the type II receptor BMPR-II, shown in two abstract-level papers and database records; BMPR-II works with BMPR-IB.","interaction_type":"direct binding","direction_and_effect":"GDF-5 bound BMPR-II in transfected COS-1 cells, and 125I-GDF-5 bound BMPR-IB and BMPR-II in non-transfected cells [PMID:8702914]. CDMP-1 and CDMP-2 had affinity for BMPR-IB and BMPR-II [PMID:9525338]. Signalling is stimulatory, with BMPR-IB transducing a transcriptional signal in the presence of BMPR-II [PMID:8702914] [PMID:9525338].","molecular_requirements":"BMPR-II acts as a type II partner of BMPR-IB; ActR-II and ActR-IIB also bound GDF-5 [PMID:8702914]. Whether BMPR-II alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat ROB-C26 cells and COS-1 transfectants [PMID:8702914]; ATDC5, ROB-C26, MC3T3-E1, primary chondrocytes [PMID:9525338]. The human pair has direct records; the mouse pair is ortholog-inferred. Database records: BioGRID reconstituted complex [DB:BioGRID], IntAct SPR [DB:IntAct], UniProt subunit note [DB:UniProt].","localisation_and_range":"Ligand is flagged secreted [flag], so signalling is expected to be paracrine; not otherwise reported in our evidence.","caveats":"Both papers were read as abstracts only. One further paper was judged a different entity and one is pending. No affinity is reported for BMPR-II in our evidence.","key_references":[{"PMID":"8702914","why":"GDF-5 binds BMPR-II and cooperates with BMPR-IB"},{"PMID":"9525338","why":"Independent binding and reporter evidence"}],"covers":["LR000700","LR004184"]},"LR007235":{"pair":"GDF6 -> ACVR2A:BMPR1A","headline":"No paper confirms this combination; only database annotation of the chains, with no direct evidence for the complex.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in any verified paper in our evidence. UniProt says GDF6 seems to positively regulate chondrogenic differentiation through BMPR1A, BMPR1B, BMPR2 and ACVR2A subunits, activating SMAD1-SMAD5-SMAD8 [DB:UniProt]. A BioGRID record concerns GDF6 with BMPR1B only [DB:BioGRID].","molecular_requirements":"Complex requirement is untested: no curator-verified paper covers ACVR2A and BMPR1A together.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"All judged papers (3) were review_only. Both chains are named in UniProt, but only as a list of possible subunits.","key_references":[],"covers":["LR007235"]},"LR007244":{"pair":"GDF7 -> BMPR1A:BMPR2","headline":"GDF7 -> BMPR1A:BMPR2: functional evidence only, from one abstract-only paper; chains not shown together.","interaction_type":"functional only","direction_and_effect":"ALK3 conferred GDF7 signalling; BMPRII and ActRIIA shRNA suppressed it [PMID:16049014]. GtoPdb lists agonist records for the individual chains [DB:GtoPdb].","molecular_requirements":"Complex of BMPR1A (ALK3) and BMPR2. Evidence comes from separate manipulations (receptor overexpression or shRNA of one chain), not from a test of the assembled pair [PMID:16049014]. Whether one chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 transfectants and MC3T3 cells with shRNA and Smad1/5/8 reporters; curator species fields are blank or human, abstract-only [PMID:16049014].","localisation_and_range":"Ligand is flagged secreted and the receptor complex as transmembrane [flag], implying paracrine signalling to a cell-surface receptor; not otherwise reported in our evidence.","caveats":"Single abstract-only paper. No binding or affinity data for the assembled complex in our evidence. Direct binding of GDF7 to the individual chains is documented in other rows, not this one.","key_references":[{"PMID":"16049014","why":"Receptor overexpression and shRNA define the type I and type II requirements for GDF7."}],"covers":["LR007244"]},"LR002690":{"pair":"GDF7 -> BMPR1B","headline":"GDF7 binds BMPR1B (ALK6) directly with high affinity and functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ALK6 (BMPR1B) with high affinity, similar to rhBMP13 (GDF6) (numeric KD not in our excerpts) [PMID:21702718]. ALK6 overexpression in COS7 cells conferred GDF7 signalling [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type I receptor; a type II receptor partner is implicated: BMPRII and ActRIIA shRNA suppressed GDF7 signalling [PMID:16049014].","affinity_potency":[],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. Numeric affinities are not in the excerpts. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR002690","LR005955"]},"LR004193":{"pair":"GDF9 -> TGFBR1","headline":"Functional evidence that GDF9 signals through ALK5 (TGFBR1) in the presence of BMPRII; binding to ALK5 not measured.","interaction_type":"functional only","direction_and_effect":"GDF-9 is an agonist: it stimulated the ALK5-responsive CAGA-luciferase reporter and Smad2/Smad3 phosphorylation in P19 cells, blocked by Smad7; ALK5 overexpression made Cos7 cells responsive; ALK5 siRNA or Smad7 suppressed the response in rat granulosa cells [PMID:14684852]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"GDF-9 binds the BMP-activated type II receptor, and its downstream actions are mediated by the type I receptor ALK5 and Smad2/3 [PMID:14684852].","affinity_potency":[],"species_and_systems":"P19 cells, Cos7 reconstitution and rat granulosa cells; the curators record human ligand and receptor [PMID:14684852]. The mouse pair is ortholog-inferred.","localisation_and_range":"GDF9 is flagged as secreted and non-transmembrane [flag], so signalling is paracrine/autocrine; the receptor is flagged transmembrane [flag].","caveats":"Abstract only; direct GDF-9/ALK5 binding was not measured, and ALK5 is also the type I receptor of TGF-beta per the curator note [PMID:14684852].","key_references":[{"PMID":"14684852","why":"GDF-9 signalling needs ALK5 and Smad2/3"}],"covers":["LR000709","LR004193"]},"LR000719":{"pair":"GIP -> GIPR","headline":"GIP binds GIPR directly, shown by a crystal structure of the extracellular domain and binding assays.","interaction_type":"direct binding","direction_and_effect":"GIP(1-42) is an agonist of the GIP receptor; GtoPdb lists agonist [PMID:17715056][PMID:7589426][DB:GtoPdb]. Stably transfected cells showed coupling to adenylate cyclase [PMID:7589426].","molecular_requirements":"The receptor extracellular domain binds GIP in an alpha-helical conformation in a surface groove, mostly hydrophobic; N-terminal ligand residues stay free for other receptor parts [PMID:17715056]. The entire GIP(1-31) sequence is important for recognition, and hybrids with GLP-1 had minimal GIPR binding [PMID:8795084].","affinity_potency":[{"value":"Kd 1.93 +/- 0.2 x 10(-8) M","assay":"binding to cloned receptor, human GIP 1-42","system":"stably transfected fibroblast (CHL) cells, human receptor","cite":"PMID:7589426"},{"value":"Kd 1.13 +/- 0.1 x 10(-8) M","assay":"porcine truncated GIP 1-30","system":"same","cite":"PMID:7589426"}],"species_and_systems":"Human receptor and ligand in recombinant systems; RINm5F insulinoma cells in the hybrid study [PMID:8795084]. Mouse pair is ortholog-inferred. Structures: [DB:PDB 2QKH].","localisation_and_range":"Ligand secreted, receptor transmembrane [flag].","caveats":"All papers read as abstracts only. PMID 12627975 tests GIP analogues, with native GIP1-42 and GIP1-30 as references; PMID 8795084 is a negative-result style hybrid study.","key_references":[{"PMID":"17715056","why":"Crystal structure of GIPR ECD with GIP(1-42)"},{"PMID":"7589426","why":"GIPR cloned; Kd for GIP 1-42 and 1-30"},{"PMID":"8795084","why":"GIP sequence requirements for receptor binding"}],"covers":["LR000719","LR004202"]},"LR007028":{"pair":"GJA1 -> GJA1","headline":"Homomeric connexin 43 (GJA1) pairing rests on database records only; no paper confirmed it here.","interaction_type":"database-asserted only","direction_and_effect":"Not a directional ligand-receptor pair; BioGRID lists co-fractionation and affinity capture-MS between GJA1 and itself [DB:BioGRID][PMID:11739633][PMID:35391932]. Reactome has Cx43 hemi-channel and connexon complexes [DB:Reactome][PMID:24243840].","molecular_requirements":"Reactome describes Cx43 hemichannels and connexons in membrane and Golgi complexes [DB:Reactome]; stoichiometry not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane [flag]; contact-type gap-junction class from the pair annotation.","caveats":"Five papers were judged different_entity and none confirmed. Self-association and channel assembly are not ligand-receptor signalling.","key_references":[],"covers":["LR007028"]},"LR007037":{"pair":"GJC1 -> GJC1","headline":"GJC1 - GJC1 rests on database records only; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a hemi-connexin 45 complex at the plasma membrane [DB:Reactome][PMID:24243840]. Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners are flagged transmembrane (gap-junction class) [flag].","caveats":"Three papers different_entity, one review_only, one abstract_insufficient; none confirmed. Self-association is not ligand-receptor signalling.","key_references":[],"covers":["LR007037"]},"LR010556":{"pair":"GLS2:SLC1A1 -> GRIN1:GRIN2D","headline":"Protein-association records only; no paper confirms GLS2:SLC1A1 -> GRIN1:GRIN2D as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010556"]},"LR009008":{"pair":"GNAI2 -> F2R","headline":"GNAI2-F2R is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists affinity capture-Western [DB:BioGRID][PMID:8982657]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR009008"]},"LR002708":{"pair":"GPR15LG -> SUSD2","headline":"GPR15LG (CSBF/C10orf99) binds SUSD2 with sub-nanomolar competition IC50 and inhibits colon cancer cell growth; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CSBF/C10orf99 interacts with SUSD2 to inhibit colon cancer cell growth and induce G1 arrest by down-regulating cyclin D and CDK6; this is blocked by soluble sSUSD2-Fc [PMID:25351403]. It induced dose-dependent internalisation of SUSD2-EGFP [PMID:25351403]. Curators label it antagonist, meaning growth inhibition.","molecular_requirements":"Co-immunoprecipitation and FRET (efficiency 15.2%) support direct contact; the soluble extracellular region of SUSD2 (sSUSD2-Fc) binds the ligand [PMID:25351403].","affinity_potency":[{"value":"IC50 0.28 nM","assay":"125I-CSBF competition binding","system":"sSUSD2-Fc","cite":"PMID:25351403"}],"species_and_systems":"Human proteins; colon cancer cell lines (including LoVo) and purified sSUSD2-Fc [PMID:25351403].","localisation_and_range":"Classical secreted protein of about 6.5 kDa [PMID:25351403]; flagged as secreted [flag].","caveats":"One paper only. Gal1 was a comparison ligand with IC50 0.19 nM [PMID:25351403]. Activity curve was bell-shaped, optimal near 10 ng/ml.","key_references":[{"PMID":"25351403","why":"Binding IC50, co-IP, FRET and growth inhibition for CSBF/C10orf99 with SUSD2"}],"covers":["LR002708","LR005973"]},"LR000728":{"pair":"GRP -> GRPR","headline":"GRP is a well-supported high-affinity agonist of GRPR, shown by binding and functional assays in human cells.","interaction_type":"direct binding","direction_and_effect":"GRP is an agonist at the human GRP receptor: binding activates phospholipase C and raises [3H]inositol phosphate [PMID:7838118]. GRP is the natural GRPR ligand, with >650-fold higher affinity than for hNMB receptors [PMID:21729729]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond receptor and peptide; GRP(1-27) was used in the full-text study [PMID:21729729].","affinity_potency":[{"value":"IC50 0.17\u20130.19 nM","assay":"radioligand competition binding","system":"human GRPR in Balb 3T3 transfectants and native HuTu-80 cells","cite":"PMID:21729729"},{"value":"EC50 13.6 nM","assay":"[3H]inositol phosphate generation","system":"human GRPR in stably transfected BALB/3T3 cells","cite":"PMID:7838118"}],"species_and_systems":"Human receptors in transfected and native cell lines [PMID:7838118] [PMID:21729729]. Rat GRPR pharmacology did not correlate with human (r=0.131), so rat data should not be extrapolated [PMID:21729729]. Mouse pair is ortholog-inferred.","localisation_and_range":"GRP is flagged secreted; GRPR is flagged as a transmembrane receptor [flag].","caveats":"One of the confirmed papers uses GRP-GRPR only as a reference system for antagonist work [PMID:19463875]. Several papers were read as abstracts only.","key_references":[{"PMID":"21729729","why":"GRP IC50 0.17-0.19 nM at human GRPR"},{"PMID":"7838118","why":"Cloned human GRPR, GRP potency and PLC activation"},{"PMID":"19463875","why":"Human bombesin receptor antagonist pharmacology"}],"covers":["LR000728","LR004210"]},"LR001835":{"pair":"HAVCR1 -> CD300LB","headline":"TIM1 (HAVCR1) binds LMIR5/CD300b in mouse cell-based assays; one paper, human pair projected from mouse.","interaction_type":"direct binding","direction_and_effect":"LMIR5-Fc stained TIM1-expressing Ba/F3 cells, and coimmunoprecipitation showed physical interaction of LMIR5 with TIM1 [PMID:20566714]. The authors call TIM1 an endogenous ligand for the DAP12-coupled activating receptor LMIR5; TIM1 or TIM4 stimulation induced LMIR5-mediated mast cell activation [PMID:20566714].","molecular_requirements":"The Ig-like domain of LMIR5 bound TIM1 near the phosphatidylserine-binding site; among LMIR family members only LMIR5 bound TIM1, and LMIR5 also bound TIM4 [PMID:20566714]. Coreceptor or subunit requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used mouse proteins and cells (Ba/F3, mast cells, mice, dorsal air pouch, kidney ischemia/reperfusion) [PMID:20566714]. The human pair is ortholog-inferred, so no human experiment is in our evidence.","localisation_and_range":"HAVCR1 is flagged as a membrane receptor, not secreted [flag]; contact-dependent signalling is implied but TIM1-Fc was also used as a soluble probe [PMID:20566714].","caveats":"Single paper; judged from abstract by the curators, with full-text excerpts available. Affinity not reported in our evidence. TIM1-Fc also stained parental Ba/F3 cells, suggesting other TIM1 ligands exist [PMID:20566714].","key_references":[{"PMID":"20566714","why":"Expression cloning, Fc-binding, coIP and in vivo LMIR5 deficiency"}],"covers":["LR001835","LR005190"]},"LR000737":{"pair":"HBEGF -> ERBB2","headline":"HB-EGF stimulates ERBB2 phosphorylation in cells, but direct ERBB2 binding is not shown.","interaction_type":"functional only","direction_and_effect":"Recombinant HB-EGF stimulated tyrosine phosphorylation of ErbB1 and ErbB2 and SMC migration, while neuregulin-1 did not [PMID:12958167]. Blocking ErbB1 or ErbB2 reduced EC-stimulated SMC migration by 70-90% [PMID:12958167].","molecular_requirements":"ErbB1 and ErbB2 were both present in the smooth muscle cells, which lacked ErbB3 and ErbB4 [PMID:12958167]; whether ErbB2 acts alone or with ErbB1 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Primary human endothelial and smooth muscle cells [PMID:12958167]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted/transmembrane flags [flag]; paracrine from endothelium to smooth muscle in this study [PMID:12958167].","caveats":"Abstract only; phosphorylation readout cannot separate direct ErbB2 binding from transactivation via ErbB1. One further judged row is pending.","key_references":[{"PMID":"12958167","why":"HB-EGF drives ErbB1/ErbB2 phosphorylation in SMC"}],"covers":["LR000737","LR004219"]},"LR012446":{"pair":"HHIP -> PTCH1:SMO","headline":"No curator-confirmed evidence; only two IntAct NMR records and three pending papers.","interaction_type":"database-asserted only","direction_and_effect":"Annotated modulatory effect is inhibitory, but no curator-verified paper supports the direction [flag].","molecular_requirements":"The receptor is a PTCH1:SMO complex entry; which subunit HHIP contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the IntAct records come from PMID 19561609 [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"All three papers are still pending, so there is no verified literature. The IntAct NMR records (Q96QV1-Q13635) are listed against PMID 19561609, but the dossier does not show that they involve a PTCH1:SMO complex [DB:IntAct][PMID:19561609].","key_references":[],"covers":["LR012446"]},"LR002717":{"pair":"HLA-A -> KIR2DS2","headline":"HLA-A*11:01 is a cognate ligand of activating KIR2DS2, shown by crystal structure and tetramer binding; one paper.","interaction_type":"direct binding","direction_and_effect":"HLA-A*11:01 was identified as the cognate ligand for the activating KIR2DS2 [PMID:24550293]. Activating effect is implied by the receptor class.","molecular_requirements":"Residues Tyr45 and Asp72 play a specificity-determining role; binding is altered by changes at peptide position p8, so it depends on the bound peptide sequence [PMID:24550293].","affinity_potency":[],"species_and_systems":"Human proteins; crystal structure at 2.5-angstrom resolution, tetramer binding on live cells, and NMR [PMID:24550293].","localisation_and_range":"Both are annotated as transmembrane or receptors [flag]; contact-dependent.","caveats":"One paper, read as an abstract. Binding is allotype- and peptide-specific, so other HLA-A alleles may not bind.","key_references":[{"PMID":"24550293","why":"KIR2DS2-HLA-A*11:01 structure and ligand identification"}],"covers":["LR002717"]},"LR000746":{"pair":"HLA-A -> KIR3DL1","headline":"HLA-A*2402 is a KIR3DL1 ligand with allotype- and peptide-dependent binding; inhibitory; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"HLA-A*2402 is a ligand for KIR3DL1; HLA-A*2402-expressing targets resisted lysis by NK cells expressing KIR3DL1*001 or *005, an inhibitory effect [PMID:17182537].","molecular_requirements":"Only Bw4-positive tetramers bind KIR3DL1. Binding depends on the bound peptide, HLA allotype and KIR3DL1 allotype together [PMID:17182537].","affinity_potency":[],"species_and_systems":"Human tetramers and human NK cells [PMID:17182537].","localisation_and_range":"Both annotated as transmembrane or receptors [flag]; contact-dependent.","caveats":"The pair record's modulatory_effect is Stimulatory, while the paper shows an inhibitory effect. 3 of 4 HLA-A*2402 tetramers bound; binding is not general across HLA-A. Paper read as an abstract. Two further papers were review-only.","key_references":[{"PMID":"17182537","why":"HLA-A*2402 tetramers bind KIR3DL1 allotypes"}],"covers":["LR000746"]},"LR000755":{"pair":"HLA-C -> KIR2DL1","headline":"Well-established direct binding of HLA-C (C2 group) to inhibitory KIR2DL1, with crystal structure and multiple binding assays in human systems.","interaction_type":"direct binding","direction_and_effect":"KIR2DL1 is an inhibitory NK receptor that engages HLA-C [PMID:11323700]. Binding of KIR2DL1 to peptide-loaded HLA-Cw4 was sufficient to induce tyrosine phosphorylation of KIR2DL1 [PMID:12794140]. An scFv masking HLA-Cw6 residues 77/80 restored NK lysis of K562 targets [PMID:15607823].","molecular_requirements":"KIR2DL1 binds HLA-C alleles of group C2 (Lys80) [PMID:28352266]; the structure shows a KIR2DL1 pocket hosting HLA-Cw4 Lys80 [PMID:11323700]. A disulfide-linked KIR2DL1 dimer bound HLA-Cw4 at one dimer to one HLA-Cw4, more tightly than monomer [PMID:11009104]. Glycosylation mutants of HLA-Cw4/Cw6 reduced KIR2DL1-Ig binding [PMID:11163076]. Binding was peptide-dependent, with most peptides supporting KIR2DL1-C2 binding and two promoting cross-reactive binding to C1 [PMID:28352266].","affinity_potency":[],"species_and_systems":"Human proteins, transfectants and NK cells; crystal structure and native gel shift of refolded proteins [PMID:11323700][PMID:10429675].","localisation_and_range":"Both partners are annotated transmembrane [flag]; contact-dependent.","caveats":"Most papers were read as abstracts. No numeric affinity in our evidence. The evidence sentence for PMID:12454284 is a control (HLA-Cw6 bound KIR2DL1-Ig, HLA-G did not bind KIR2DL4-Ig) and PMID:9768753 refers to receptors by the older name NKAT1.","key_references":[{"PMID":"11323700","why":"Crystal structure of KIR2DL1 bound to HLA-Cw4"},{"PMID":"10429675","why":"Refolded HLA-Cw4 binds KIR2DL1 directly"},{"PMID":"11009104","why":"1:1 dimer to HLA-Cw4 stoichiometry"}],"covers":["LR000755"]},"LR008342":{"pair":"HLA-DQA2 -> LAG3","headline":"No verified primary paper; only a generic Reactome record that LAG3 binds MHC class II.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records 'LAG3 (CD233) binds MHC II' [DB:Reactome R-HSA-8856157]. Effect: not reported in our evidence.","molecular_requirements":"Chain requirement: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence (pair is human).","localisation_and_range":"Not reported in our evidence.","caveats":"Two papers judged review-only; none verified. DQA2-specific binding is not shown.","key_references":[],"covers":["LR008342"]},"LR002726":{"pair":"HLA-DRA -> CD4","headline":"Structures of CD4 mutant with HLA-DR1 and a UniProt note support interaction; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states HLA-DRA interacts (via alpha-2 domain) with CD4 (via Ig-like V-type domain) [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"UniProt places the contact in the DRA alpha-2 domain and the CD4 Ig-like V-type domain [DB:UniProt]. PDB 3S4S and 3S5L are listed as 'Crystal structure of CD4 mutant bound to HLA-DR1' [DB:PDB 3S4S][DB:PDB 3S5L].","affinity_potency":[],"species_and_systems":"Human proteins by the PDB titles; details not reported in our evidence.","localisation_and_range":"HLA-DRA is flagged not secreted [flag].","caveats":"The one judged paper was abstract-insufficient. The structures use a CD4 mutant. No affinity in our evidence.","key_references":[],"covers":["LR002726"]},"LR011519":{"pair":"HLA-DRB3 -> CD4","headline":"Database-asserted only: UniProt notes DRB3 beta-2 domain interacts with CD4; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states HLA-DRB3 interacts (via beta-2 domain) with the CD4 coreceptor (via Ig-like V-type domain) [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Beta-2 domain of DRB3 and Ig-like V-type domain of CD4 per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Three paper rows are still pending (unjudged); support rests on a UniProt annotation.","key_references":[],"covers":["LR011519"]},"LR007253":{"pair":"HLA-E -> KLRC3:KLRD1","headline":"Direct binding of HLA-E to the activating NKG2E/CD94 heterodimer from one paper; database records are generic CD94 ones.","interaction_type":"direct binding","direction_and_effect":"NKG2E/CD94 bound HLA-E with affinity indistinguishable from NKG2A/CD94 [PMID:15728498]. Effect labelled activating [PMID:15728498].","molecular_requirements":"Requires KLRC3 (NKG2E) plus KLRD1 (CD94) [PMID:15728498]. Peptide influenced affinity [PMID:15728498]. Database records name KLRD1 with KLRC1/KLRC2, not KLRC3 [DB:UniProt][DB:Reactome R-HSA-198914].","affinity_potency":[],"species_and_systems":"Human; purified complexes [PMID:15728498].","localisation_and_range":"HLA-E secreted and transmembrane per flags; complex transmembrane [flag].","caveats":"Only one verified paper, abstract only, no numeric affinity. BioGRID/IntAct/PDB entries concern CD94 with other NKG2 chains rather than NKG2E. Two papers review-only, one abstract-insufficient.","key_references":[{"PMID":"15728498","why":"NKG2E/CD94 binds HLA-E with high affinity"}],"covers":["LR007253"]},"LR000764":{"pair":"HLA-G -> KLRC1","headline":"Functional NK-clone data link CD94/NKG2A to HLA-G recognition, but the HLA-E co-expression issue weakens it; no direct binding.","interaction_type":"functional only","direction_and_effect":"CD94/NKG2A+ clones showed markedly reduced cytolysis of HLA-G transfected 221 cells [PMID:9295021]. The curated row direction is agonist for a NKG2A-negative activating pattern, which is not NKG2A itself [PMID:9295021].","molecular_requirements":"Requires CD94/NKG2A complex (companion KLRD1 row) [PMID:9295021]. Crystal structures list HLA-G as the source of the leader peptide in HLA-E complex [DB:PDB 3CDG].","affinity_potency":[],"species_and_systems":"Human NK clones and transfected 221 cells [PMID:9295021].","localisation_and_range":"HLA-G flagged secreted [flag].","caveats":"Functional only; HLA-G is not a verified direct ligand here. Sibling dossier notes that HLA-G transfectants likely co-expressed HLA-E and HLA-G peptide presented by HLA-E explains the PDB records; PDB 3CDG is not HLA-G binding NKG2A directly. Abstract only.","key_references":[{"PMID":"9295021","why":"NK clones with CD94/NKG2A show reduced lysis of HLA-G targets"}],"covers":["LR000764"]},"LR005192":{"pair":"HMGB1 -> HAVCR2","headline":"TIM-3 binds HMGB1 and sequesters it in tumour dendritic cells; one full-text mouse-based paper, functional rather than structural.","interaction_type":"functional only","direction_and_effect":"TIM-3 interacted with HMGB1 and interfered with recruitment of nucleic acids into dendritic-cell endosomes, reducing the efficacy of DNA vaccination and chemotherapy [PMID:22842346]. This is an inhibitory, sequestering role, not activating signalling.","molecular_requirements":"The Q62A substitution near the FG loop largely abrogated HMGB1 binding, so the metal-ion-dependent ligand-binding site of TIM-3 is needed. Binding was partly suppressed by RAGE-Fc or galectin-9 and blocked by anti-TIM-3 mAb [PMID:22842346].","affinity_potency":[],"species_and_systems":"Mouse tumours and tumour-associated dendritic cells, with TIM-3 expression also seen in patients with cancer [PMID:22842346]. The curated receptor species is mouse; the human pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; it is released from dying tumour cells [PMID:22842346].","caveats":"TIM-3 bound HMGB1 with an affinity said to be similar to RAGE, but no value is given in our evidence. Single paper; one more row was review-only.","key_references":[{"PMID":"22842346","why":"TIM-3 binds HMGB1 and blunts nucleic-acid immunity"}],"covers":["LR001843","LR005192"]},"LR002735":{"pair":"HMGB1 -> ITGAV","headline":"HMGB1 binds soluble integrin alphavbeta3 (not alphavbeta5) and blocks efferocytosis; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"HMGB1 bound soluble alphavbeta3, suppressed the MFG-E8-alphavbeta3 interaction, decreased macrophage engulfment of apoptotic cells and inhibited ERK phosphorylation and Rac-1 activation [PMID:20826760]. This is an antagonistic, blocking effect.","molecular_requirements":"ITGAV acts as part of the alphavbeta3 heterodimer. No binding to soluble alphavbeta5 was seen, so the beta3 partner matters [PMID:20826760].","affinity_potency":[],"species_and_systems":"Macrophages with apoptotic neutrophils or thymocytes and soluble integrins; species not stated in the abstract. Curated as human; the mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; the integrin is membrane-bound on macrophages [PMID:20826760].","caveats":"One abstract-only paper; no affinity. Evidence is for the alphavbeta3 complex, not ITGAV alone.","key_references":[{"PMID":"20826760","why":"HMGB1 binds alphavbeta3 and blocks efferocytosis"}],"covers":["LR002735","LR005983"]},"LR001844":{"pair":"HP -> CD163","headline":"Evidence concerns haptoglobin-HMGB1 complexes signalling via CD163; haptoglobin alone binding CD163 is database-supported.","interaction_type":"functional only","direction_and_effect":"Haptoglobin-HMGB1 complexes induce heme oxygenase-1 and IL-10 in wild-type but not CD163-deficient macrophages; loss of haptoglobin or CD163 enhances mortality in mouse sepsis models [PMID:27294203]. Reactome lists haptoglobin:hemoglobin binding CD163 [DB:Reactome].","molecular_requirements":"The paper's active ligand is the haptoglobin-HMGB1 complex, not haptoglobin alone [PMID:27294203]. Haptoglobin-hemoglobin binding of CD163 is described in Reactome [DB:Reactome]; PDB lists structures with chains of P00738 and Q86VB7 [DB:PDB 8XMP].","affinity_potency":[],"species_and_systems":"Macrophages and mouse sepsis models; curated as human proteins [PMID:27294203]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Paper read as abstract only. CD163 uptake of haptoglobin is described in the paper as established background, not tested here [PMID:27294203].","key_references":[{"PMID":"27294203","why":"Haptoglobin-HMGB1 complexes act via CD163 in macrophages and mouse sepsis"}],"covers":["LR001844","LR005193"]},"LR002744":{"pair":"HP -> CD22","headline":"Haptoglobin was identified as a sialic-acid-dependent binder of CD22 in a 1995 affinity-adsorption study.","interaction_type":"direct binding","direction_and_effect":"Soluble CD22Rg adsorbed three plasma polypeptides eluted with alpha2-6-sialyllactose, whose N-terminal sequences were IgM and haptoglobin subunits [PMID:7706301]. CD22 is a B-cell receptor recognising sialic acid [PMID:7706301].","molecular_requirements":"Binding is sialic-acid dependent (alpha2-6 linkage); sialidase and periodate treatment abolished the CD22 interactions described for IgM [PMID:7706301]. Haptoglobin-specific controls are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human plasma and endothelial cells, chimeric CD22Rg protein [PMID:7706301]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted; CD22 is flagged as a transmembrane receptor [flag].","caveats":"Abstract-only reading; the binding is lectin-glycan recognition rather than a classic protein-protein contact, and most of the follow-up in the paper concerns IgM. No affinity reported.","key_references":[{"PMID":"7706301","why":"CD22Rg affinity adsorption identifies haptoglobin and IgM subunits"}],"covers":["LR002744","LR005992"]},"LR004229":{"pair":"HP -> ITGB2","headline":"Haptoglobin binds the CD11b/CD18 integrin on monocytic cells; evidence is chain-level for ITGB2 (CD18) from one 1996 paper.","interaction_type":"direct binding","direction_and_effect":"Haptoglobin binds purified CD11b/CD18, indicating direct binding; anti-CD11b mAb44 inhibits haptoglobin binding to THP1/U937 cells, and an anti-CD18 mAb partly inhibits it [PMID:8786317]. Binding was increased by Ca2+/ADP and inhibited by fibrinogen [PMID:8786317].","molecular_requirements":"The functional receptor is the CD11b/CD18 heterodimer; the CD18 antibody inhibited only partly, so the beta chain alone is not shown sufficient [PMID:8786317]. No interference from anti-CD11a or anti-CD11c mAbs [PMID:8786317].","affinity_potency":[{"value":"Kd 6.5 x 10(-6)","assay":"radioiodinated haptoglobin binding, one receptor class, 1.7 x 10(5) sites per cell (low affinity)","system":"human THP1 cells","cite":"PMID:8786317"}],"species_and_systems":"Human haptoglobin and human monocytic cell lines (THP1, U937), monocytes and granulocytes [PMID:8786317]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Abstract-only reading. The affinity was measured on whole cells, not on the single chain. One further row is pending.","key_references":[{"PMID":"8786317","why":"Haptoglobin binds CD11b/CD18 on THP1 cells and purified integrin"}],"covers":["LR000770","LR004229"]},"LR000773":{"pair":"HSP90B1 -> TLR2","headline":"Gp96 activates dendritic cells through TLR2 in mouse experiments; functional evidence only.","interaction_type":"functional only","direction_and_effect":"The Gp96-TLR2/4 interaction activates NF-kappaB reporters and MAPK/MSK, and induces IkappaBalpha degradation; bone-marrow dendritic cells from TLR4-mutant C3H/HeJ mice, and more markedly from C3H/HeJ TLR2-/- mice, fail to respond [PMID:11912201].","molecular_requirements":"Response requires Gp96 endocytosis; the paper names TLR2 and TLR4 together as a pathway [PMID:11912201].","affinity_potency":[],"species_and_systems":"Mouse dendritic cells and TLR-expressing cell lines [PMID:11912201]. The mouse pair is ortholog-inferred.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; described as an ER-resident protein acting after release [PMID:11912201].","caveats":"Abstract-only reading; no direct binding or affinity reported, and the effect is not separated between TLR2 and TLR4.","key_references":[{"PMID":"11912201","why":"Gp96 activates DCs via TLR2/4; knockout cells fail to respond"}],"covers":["LR000773","LR004232"]},"LR002753":{"pair":"HSPA4 -> LRP1","headline":"Mouse-cell evidence only, from an abstract: released Hsp70 acts via TLR4 and CD91 (LRP1) to drive migration. Human pair is ortholog-projected.","interaction_type":"functional only","direction_and_effect":"Hsp70 released in membrane vesicles by mouse mesoangioblasts interacts in an autocrine manner with TLR4 and CD91 to stimulate migration [PMID:27925208]. Downstream involvement of PI3K/AKT and NF-kB is reported [PMID:27925208].","molecular_requirements":"TLR4 and CD91 are named together, and whether LRP1 acts alone or with TLR4 is not reported in our evidence [PMID:27925208].","affinity_potency":[],"species_and_systems":"Mouse mesoangioblasts in vitro; the human interaction is inferred from ortholog projection, and the mouse pair is a direct entry [PMID:27925208].","localisation_and_range":"HSPA4 is flagged secreted [flag]; the paper describes release on membrane vesicles with autocrine action [PMID:27925208].","caveats":"Read as abstract only. The paper's protein is called Hsp70, which the dossier assigns to HSPA4; no binding or affinity data.","key_references":[{"PMID":"27925208","why":"Autocrine vesicle-released Hsp70 acting via TLR4 and CD91 on mouse mesoangioblast migration"}],"covers":["LR002753","LR006000"]},"LR010637":{"pair":"HTR2C -> LIN7C","headline":"Database-only record of a physical interaction between HTR2C and LIN7C (a PDZ-type adaptor); not a ligand-receptor pair as judged by curators.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect is reported in our evidence. Records: BioGRID reconstituted complex [DB:BioGRID] and IntAct direct interaction by holdup assay [DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and systems of the database records are not reported in our evidence.","localisation_and_range":"not reported in our evidence.","caveats":"No curated papers (2 judged rows were different_entity). Both records likely reflect receptor-scaffold binding, not a ligand-receptor relationship.","key_references":[],"covers":["LR010637"]},"LR007091":{"pair":"IAPP -> CALCR:RAMP2","headline":"Database-asserted only: UniProt describes CALCR with RAMP2 as an amylin receptor (AMYR2) and PDB holds amylin-receptor structures; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Together with CALCR, RAMP2 acts as a receptor complex for amylin [DB:UniProt]. GtoPdb lists agonist (full agonist) records for IAPP-CALCR [DB:GtoPdb].","molecular_requirements":"Requires CALCR plus RAMP2 per UniProt [DB:UniProt]; a PDB entry shows a pramlintide analogue complex with the human Amylin3 receptor, not specifically RAMP2 [DB:PDB 8F0K].","affinity_potency":[],"species_and_systems":"Species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"IAPP is flagged secreted and the complex transmembrane [flag].","caveats":"No curated paper supports this complex: one row was different_entity and one abstract_insufficient. GtoPdb records are for IAPP-CALCR, not the complex.","key_references":[],"covers":["LR007091"]},"LR000782":{"pair":"IBSP -> ITGAV","headline":"Bone sialoprotein signals through integrin alphaVbeta3 for migration in breast cancer cells; evidence is functional, from one abstract.","interaction_type":"functional only","direction_and_effect":"Integrin-blocking antibodies showed BSP-RGD-induced migration used alpha(v)beta3, whereas adhesion and proliferation were alpha(v)beta5-mediated; effect is stimulatory [PMID:9699501]. UniProt says ITGAV:ITGB3 is a receptor for IBSP promoting adhesion and migration [DB:UniProt]; Reactome lists the complex [DB:Reactome].","molecular_requirements":"The receptor is the ITGAV:ITGB3 heterodimer; ITGAV alone is not shown to bind. The RGD domain of BSP supplied most activity [PMID:9699501].","affinity_potency":[],"species_and_systems":"MDA-MB-231 human breast cancer cells with human BSP fragments and peptides [PMID:9699501]. Mouse pair is ortholog-inferred.","localisation_and_range":"IBSP is described as a secreted glycoprotein of bone matrix [PMID:9699501].","caveats":"Abstract read only. Antibody blocking shows involvement, not direct binding. Same paper also supports ITGB5, so subunit-level assignment is by the integrin pair.","key_references":[{"PMID":"9699501","why":"Blocking-antibody dissection of alphavbeta3 and alphavbeta5 use"}],"covers":["LR000782","LR004240"]},"LR010790":{"pair":"ICAM1 -> ITGAM:ITGB2","headline":"ICAM-1 binds Mac-1 in adhesion assays; additional papers name only ITGB2, and no affinity is reported.","interaction_type":"functional only","direction_and_effect":"ICAM-1-expressing CHO cells adhered to purified Mac-1, blocked by CDR peptides [PMID:9488691]; an activating mAb induced alphaMbeta2-transfected CHO adhesion to ICAM-1 [PMID:11073102]. In melanoma, ITGB2 blocking antibody inhibited ICAM-1-dependent adhesion [PMID:41413567]. UniProt says ITGAM:ITGB2 is a signalling receptor for ICAM1 [DB:UniProt].","molecular_requirements":"Both alphaM and beta2 chains form Mac-1, and binding needs activation [PMID:11073102]. PMID:41413567 and PMID:41761123 name only ITGB2, which could also reflect LFA-1.","affinity_potency":[],"species_and_systems":"Human CHO transfectants and purified Mac-1 [PMID:9488691, PMID:11073102]; human and murine melanoma lines and mice [PMID:41413567]; gastric cancer transwell co-culture [PMID:41761123].","localisation_and_range":"Cell-contact adhesion; complex is flagged transmembrane [flag].","caveats":"Papers were abstract-only except the full-text excerpts of the 2025 melanoma and 2026 gastric studies. The latter also rests on single-cell inference of ITGB2-ICAM1. Three more papers were abstract_insufficient and one different_entity.","key_references":[{"PMID":"9488691","why":"Purified Mac-1 binding of ICAM-1 cells"},{"PMID":"11073102","why":"Activation-dependent ICAM-1 adhesion"},{"PMID":"41413567","why":"ITGB2 blockade inhibits ICAM-1 adhesion in melanoma"}],"covers":["LR010790"]},"LR000791":{"pair":"ICAM3 -> CLEC4M","headline":"L-SIGN (CLEC4M) binds ICAM-3 in vitro per two papers, but one reports only submicromolar affinity; direct-binding support, moderate.","interaction_type":"direct binding","direction_and_effect":"L-SIGN has high affinity for ICAM-3 and behaves like DC-SIGN [PMID:11257134]; in a separate study DC-SIGNR bound ICAMs with submicromolar affinity similar to nonspecific glycoprotein interactions, and oligomerisation did not increase ICAM-3 affinity [PMID:15795245].","molecular_requirements":"Not reported in our evidence beyond the oligomerisation result [PMID:15795245].","affinity_potency":[],"species_and_systems":"Human proteins and cells; L-SIGN is expressed by liver sinusoidal endothelial cells and not by monocyte-derived dendritic cells [PMID:11257134].","localisation_and_range":"Membrane lectin binding cell-surface ICAM-3; the authors suggest a role in antigen clearance and leukocyte-endothelial adhesion [PMID:11257134].","caveats":"Both papers read as abstracts, one with full-text excerpts. The two papers disagree on how strong the binding is [PMID:11257134][PMID:15795245]. IntAct has a solid-phase assay record [DB:IntAct].","key_references":[{"PMID":"11257134","why":"L-SIGN binds ICAM-3 and gp120; liver sinusoidal expression"},{"PMID":"15795245","why":"Submicromolar DC-SIGNR/ICAM-3 affinity"}],"covers":["LR000791"]},"LR004256":{"pair":"ICAM4 -> ITGB3","headline":"One human transfectant study supports activated alphaIIbbeta3 binding to ICAM-4; human pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Activated alphaIIbbeta3 binds recombinant ICAM-4-Fc specifically and dose dependently, and cell-surface ICAM-4 interacts with cell-surface alphaVbeta3 [PMID:15355350]. UniProt describes ICAM4 as a ligand for ITGA2B:ITGB3 in erythrocyte-platelet adhesion [DB:UniProt].","molecular_requirements":"beta3 pairs with alphaIIb or alphaV; the beta3 binding sites span the first and second Ig-like domains of ICAM-4, with different contact sites per alpha chain [PMID:15355350]. Only the activated alphaIIbbeta3 bound.","affinity_potency":[],"species_and_systems":"Human ICAM-4 and integrin transfectants [PMID:15355350]; no mouse experiments.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only. Affinity not reported.","key_references":[{"PMID":"15355350","why":"beta3 integrin specificity and ICAM-4 binding residues"}],"covers":["LR000802","LR004256"]},"LR002762":{"pair":"ICAM5 -> ITGB1","headline":"beta1 integrins co-purify with ICAM-5 from mouse brain and regulate spine maturation; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"beta1 integrins were immunoprecipitated with ICAM-5 from mouse brain, and antibodies to ICAM-5 and beta1 integrins altered spine maturation [PMID:23015592].","molecular_requirements":"The binding region in ICAM-5 maps to its first two Ig domains; which alpha partner is needed is not reported in our evidence [PMID:23015592].","affinity_potency":[],"species_and_systems":"Mouse brain and neurons [PMID:23015592]; the human interaction is ortholog-inferred.","localisation_and_range":"ICAM5 carries a secreted flag only [flag]; the paper notes shedding of the ICAM-5 ectodomain promotes spine maturation, and beta1 integrins lie juxtaposed to filopodia tips [PMID:23015592].","caveats":"One paper, abstract only; a second confirmed row is not shown. Co-immunoprecipitation from tissue does not prove direct contact. Affinity not reported.","key_references":[{"PMID":"23015592","why":"beta1 integrins as ICAM-5 binding partners in synapse formation"}],"covers":["LR002762","LR006008"]},"LR004265":{"pair":"IFNA1 -> IFNAR1","headline":"Direct binding of IFNA1 to the IFNAR1 chain alone is shown, with low (micromolar-range) affinity.","interaction_type":"direct binding","direction_and_effect":"IFNA1 is an agonist of IFNAR1 in GtoPdb [DB:GtoPdb]. In mouse cells expressing bovine IFNAR, human IFN alpha1 acted at low concentrations as a competitive antagonist to IFN alpha2 and alpha8 [PMID:7932753].","molecular_requirements":"IFNAR1 is one chain of a heterodimer with IFNAR2 [PMID:17174979]. This is chain-level evidence for IFNAR1 alone; competitive 1:1 binding was seen to ifnar1-EC and ifnar2-EC [PMID:17174979].","affinity_potency":[{"value":"IFNAR1 affinities 0.5-5 \u03bcM for alpha-IFNs (class statement)","assay":"binding of isolated receptor chains","system":"human alpha-IFN subtypes, isolated chains","cite":"PMID:21856167"},{"value":"KD in the \u03bcM range; IFN\u03b11 higher affinity than IFN\u03b12","assay":"real-time RIfS/TIRFS binding","system":"ifnar1-EC","cite":"PMID:17174979"}],"species_and_systems":"Human IFNs on human receptor extracellular domains [PMID:17174979] [PMID:21856167]; human IFN on mouse cells with bovine IFNAR [PMID:7932753].","localisation_and_range":"IFNA1 flagged secreted (paracrine/endocrine) [flag].","caveats":"Two papers are abstract only; the affinity range is a class statement not specific to IFNA1 [PMID:21856167]. The 17174979 row is a browser-read quote with spot-check pending. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"17174979","why":"Real-time binding of several IFNs to ifnar1-EC"},{"PMID":"21856167","why":"Affinities of 12 alpha-IFN subtypes to IFNAR1/2"},{"PMID":"7932753","why":"Human IFN\u03b11 on cells expressing bovine IFNAR"}],"covers":["LR000813","LR004265"]},"LR000809":{"pair":"IFNA16 -> IFNAR1","headline":"IFNA16 binds IFNAR1 only on class-wide evidence from one abstract; the chain is the weak-affinity subunit.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM [PMID:21856167]. GtoPdb lists IFNA16 as an agonist at IFNAR1 [DB:GtoPdb].","molecular_requirements":"IFNAR1 binds about 1000-fold more weakly than IFNAR2 per the curator's reading; IFNAR2 is the tighter chain [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA16. Binding is to the isolated chain, not the functional heterodimer.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000809"]},"LR007271":{"pair":"IFNA16 -> IFNAR1:IFNAR2","headline":"IFNA16 to the IFNAR1:IFNAR2 heterodimer rests on class-wide binding data for each chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM and IFNAR2 at 0.4-5 nM [PMID:21856167]. GtoPdb lists IFNA16 as an agonist at both chains [DB:GtoPdb].","molecular_requirements":"Both chains are listed; each binds separately, IFNAR2 much more tightly [PMID:21856167]. Binding to the assembled heterodimer is not reported in our evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"},{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single verified paper, abstract only, class-wide values with no value for IFNA16; one further row was review only.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR007271"]},"LR000818":{"pair":"IFNA2 -> IFNAR2","headline":"IFNA2 binds IFNAR2 directly with nanomolar affinity; supported by binding, NMR and crystal structure studies.","interaction_type":"direct binding","direction_and_effect":"IFNalpha2 binds ifnar2-EC 1:1 with KD 10 nM, and the soluble domain inhibits IFNalpha2 antiviral activity [PMID:10339405]. NMR maps the IFN-alpha2 binding site on IFNAR2-EC [PMID:11888273]. Crystal structures of ternary IFNalpha2-IFNAR1-IFNAR2 complexes exist [PMID:21854986]. GtoPdb lists agonist action [DB:GtoPdb].","molecular_requirements":"IFNAR2 alone binds IFNalpha2 with high affinity; IFNAR1 binds on the opposing side of the ligand in the ternary complex [PMID:21854986], with much weaker affinity [PMID:21856167]. IFN signalling uses the IFNAR1/IFNAR2 heterodimer [PMID:21854986].","affinity_potency":[{"value":"10 nM","assay":"binding of refolded ifnar2 extracellular domain to IFNalpha2 (BIAcore SPR and fluorescence de-quenching)","system":"purified human proteins","cite":"PMID:10339405"},{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and receptor; recombinant extracellular domains, NMR and crystal structures [PMID:10339405, PMID:11888273, PMID:21854986].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Papers were mainly read as abstracts; PMID:21854986 had full-text excerpts. PMID:21856167 gives class-wide values and names IFNA2 only as a comparison subtype. One further paper was pending and one abstract_insufficient.","key_references":[{"PMID":"10339405","why":"IFNAR2-EC binds IFNalpha2 1:1 at KD 10 nM."},{"PMID":"21854986","why":"Crystal structures of ternary IFNalpha2 complexes."},{"PMID":"11888273","why":"NMR of IFNAR2-EC with IFN-alpha2."}],"covers":["LR000818"]},"LR011717":{"pair":"IFNA21 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA21 to a complex listing IFNA2, IFNAR1 and IFNAR2 rests only on GtoPdb; no paper was verified.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA21 as an agonist at IFNAR1 and at IFNAR2 [DB:GtoPdb]. No curator-verified paper supports the pair.","molecular_requirements":"The receptor entry includes IFNA2 as a member alongside IFNAR1 and IFNAR2, which is unexpected for a receptor complex; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experiment in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Judged papers were all abstract_insufficient or about a different entity, so none confirms the pair. Support is from GtoPdb records for the individual chains only; affinity not given (units '-') [DB:GtoPdb].","key_references":[],"covers":["LR011717"]},"LR000827":{"pair":"IFNA8 -> IFNAR1","headline":"IFNA8 binds IFNAR1 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA8 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb]. In mouse cells expressing bovine IFNAR, binding of human IFN alpha1, alpha2 and alpha8 increased, with increased activity only for alpha2 and alpha8 [PMID:7932753].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains [PMID:21856167]; human IFN on mouse cells expressing bovine IFNAR [PMID:7932753].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA8 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167]. The second paper used human IFNs on mouse cells with bovine IFNAR, an abstract-only reading, and names IFNAR generally rather than IFNAR1 specifically [PMID:7932753].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"},{"PMID":"7932753","why":"human IFN alpha8 binding increased on mouse cells expressing bovine IFNAR"}],"covers":["LR000827"]},"LR007280":{"pair":"IFNB1 -> IFNAR1:IFNAR2","headline":"IFNB1 binds the IFNAR1:IFNAR2 type I receptor, shown by competition binding and receptor-chain studies.","interaction_type":"direct binding","direction_and_effect":"IFN-beta is an agonist at IFNAR1 and IFNAR2 [DB:GtoPdb]. Unlabelled Hu-IFN-beta blocked binding of labelled Hu-IFN-alpha A to human cells in cross-linking and saturation binding assays [PMID:1834641].","molecular_requirements":"IFNAR-2 binds all type I IFNs alone but with lower affinity and different specificity than the IFNAR-1/IFNAR-2 complex; IFNAR-1 has low intrinsic binding but shapes affinity and specificity [PMID:11278538]. Both chains therefore matter for the full complex.","affinity_potency":[],"species_and_systems":"Human cells and human IFNs [PMID:1834641]; mutagenesis used bovine IFNAR-1 with human IFNs [PMID:11278538]. Human pair only.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The receptor is flagged transmembrane [flag].","caveats":"Both papers are abstract-only readings. The first is a competition assay with IFN-alpha as the labelled probe, and the second concerns the type I family generally with bovine IFNAR-1 mutagenesis. Reactome also records IFN alpha/beta binding to IFNAR2 [DB:Reactome].","key_references":[{"PMID":"1834641","why":"IFN-beta competes for the alpha/beta receptor"},{"PMID":"11278538","why":"IFNAR-1 and IFNAR-2 roles in type I IFN binding"}],"covers":["LR007280"]},"LR011726":{"pair":"IFNK -> IFNA2:IFNAR1:IFNAR2","headline":"IFN-kappa to a complex listing IFNA2, IFNAR1 and IFNAR2: no paper evidence, only GtoPdb agonist records for the single chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNK-IFNAR1 and IFNK-IFNAR2 as Agonist [DB:GtoPdb]. No papers are attached to this complex row.","molecular_requirements":"The receptor is listed with members IFNA2, IFNAR1 and IFNAR2 [flag]; IFNA2 is a secreted ligand, so its role as a receptor subunit is not supported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IFNK is flagged secreted and non-transmembrane [flag].","caveats":"Rests on database records alone; three attached rows were abstract_insufficient and none were verified.","key_references":[],"covers":["LR011726"]},"LR001853":{"pair":"IFNK -> IFNAR1","headline":"Recombinant human IFN-kappa binds IFNAR1 with affinity similar to other type I IFNs; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"IFN-kappa is an agonist on IFNAR; GtoPdb lists Agonist [DB:GtoPdb]. It is a type I interferon family member that signals through the common IFNAR1/IFNAR2 receptor complex and has about 1000-fold lower cellular potency than IFNalpha2 and IFNomega [PMID:30171073].","molecular_requirements":"IFN-kappa shows affinities for the IFNAR1 chain that are similar to other IFN subtypes, but weak affinity for IFNAR2 [PMID:30171073]. The functional receptor is the IFNAR1/IFNAR2 complex.","affinity_potency":[],"species_and_systems":"Recombinant human IFN-kappa, protein-affinity characterisation [PMID:30171073]. The mouse pair is projected from human (ortholog inferred), not tested. Numeric Kd values are not in the abstract.","localisation_and_range":"IFNK is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only read; no numeric affinity is given in our evidence. One other row was review_only.","key_references":[{"PMID":"30171073","why":"affinity characterisation of IFN-kappa and IFN-epsilon"}],"covers":["LR001853","LR005201"]},"LR000836":{"pair":"IFNL3 -> IFNLR1","headline":"IFN-lambda3 binds IFNLR1 and then recruits IL-10Rbeta; a crystal structure with an engineered ligand confirms the complex, with affinities.","interaction_type":"direct binding","direction_and_effect":"IFN-lambda3 is an agonist; GtoPdb lists Agonist [DB:GtoPdb]. The engineered H11 variant elicited increased anti-proliferative and antiviral activities in vitro and in vivo [PMID:28329704].","molecular_requirements":"IFN-lambda3 first binds IFN-lambda R1; IL-10Rbeta binds only the binary complex, with very low affinity. IL-10Rbeta binding to IFN-lambda3 was not detected without IFN-lambda R1 [PMID:28329704]. A ternary complex needs both chains.","affinity_potency":[{"value":"KD ~850 nM","assay":"surface plasmon resonance (Figure S1D), wild-type IFN-lambda3 for IFN-lambda R1","system":"recombinant proteins","cite":"PMID:28329704"},{"value":"KD ~150 nM","assay":"surface plasmon resonance, engineered H11 variant for IFN-lambda R1","system":"recombinant proteins","cite":"PMID:28329704"},{"value":"titration midpoint of approximately 400 nM","assay":"yeast display, IFN-lambda3 binding to IFN-lambda R1","system":"yeast-displayed IFN-lambda3","cite":"PMID:28329704"}],"species_and_systems":"Species not stated in the dossier for this paper; recombinant proteins, yeast display and crystal structure [PMID:28329704].","localisation_and_range":"IFNL3 is flagged secreted and non-transmembrane [flag].","caveats":"The structure and the tighter affinities are for the engineered H11 variant, not wild-type. Abstract plus excerpts only.","key_references":[{"PMID":"28329704","why":"ternary-complex structure and affinities"}],"covers":["LR000836"]},"LR004274":{"pair":"IGF2 -> IGF2R","headline":"IGF2 binds the mannose 6-phosphate/IGF-II receptor with high affinity; two verified classic papers map and demonstrate the binding.","interaction_type":"direct binding","direction_and_effect":"The receptor binds IGF-II with high affinity; purified human receptor fragments cross-linked 125I-IGF-II [PMID:7797478]. Rat placental receptor bound 125I-IGF-II, and Man-6-P increased apparent affinity by about two times [PMID:2964083]. UniProt agrees [DB:UniProt].","molecular_requirements":"Repeat 11 (amino acids 1508-1650) of the receptor is sufficient for IGF-II binding, and residues 1508-1566 are proposed to form the binding site; repeat 10 alone failed [PMID:7797478]. Mannose-6-phosphate sites are cooperative with the IGF-II site [PMID:2964083].","affinity_potency":[],"species_and_systems":"Human purified receptor and fusion proteins [PMID:7797478]; rat cDNA and rat placental receptor [PMID:2964083]. The mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted; IGF2R is flagged transmembrane [flag].","caveats":"Both papers were read as abstracts only; no numeric affinity is reported in our evidence. The receptor also binds Man-6-P proteins, so it is not IGF-II-specific. The interaction is annotated stimulatory, but IGF2R is known in these papers only as a binder, not a signaling effect.","key_references":[{"PMID":"7797478","why":"Maps IGF-II binding site to repeat 11"},{"PMID":"2964083","why":"One receptor binds IGF-II and Man-6-P"}],"covers":["LR000842","LR004274"]},"LR002771":{"pair":"IGF2 -> ITGB3","headline":"Integrin alphavbeta3 binds IGF2 in one verified study; ITGB3 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alphavbeta3 heterodimer was tested; blocking antibody 7E3 (anti-beta3) reduced adhesion to IGF2 [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002771","LR006017"]},"LR010970":{"pair":"IGFBP4 -> IGF2","headline":"Database-supported IGFBP4-IGF2 binding, classed as ligand-ligand; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory, class Ligand-Ligand; Reactome lists an IGF:IGFBP4 complex [DB:Reactome]. UniProt: IGFBP4 binds IGF2 more than IGF1 [DB:UniProt].","molecular_requirements":"No subunit requirements reported.","affinity_potency":[],"species_and_systems":"Human only; BioGRID lists a reconstituted complex and IntAct an anti-tag co-immunoprecipitation [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both partners are annotated as secreted [flag].","caveats":"No curator-verified paper (four candidates judged as a different entity, one review only). Database records only; no affinity.","key_references":[],"covers":["LR010970"]},"LR000845":{"pair":"IGFBP4 -> LRP6","headline":"One abstract-level study: IGFBP-4 interacts with the Wnt co-receptor LRP6 and blocks Wnt3A binding.","interaction_type":"direct binding","direction_and_effect":"IGFBP-4 physically interacted with LRP6 and inhibited Wnt3A binding to it, inhibiting canonical Wnt signalling [PMID:18528331]. Curator effect: antagonist.","molecular_requirements":"Interaction reported with both Frizzled 8 and LRP6 as a Wnt receptor/co-receptor pair; whether LRP6 alone suffices is not reported in our evidence [PMID:18528331].","affinity_potency":[],"species_and_systems":"Mouse cardiogenesis model per curator note; IntAct lists anti-tag co-immunoprecipitation from the same paper [PMID:18528331][DB:IntAct]. The human pair is marked as projected from mouse.","localisation_and_range":"IGFBP4 is annotated as secreted; LRP6 as transmembrane [flag].","caveats":"Abstract-only read; co-immunoprecipitation evidence, no affinity. The IntAct record derives from the same paper, so it is not independent.","key_references":[{"PMID":"18528331","why":"IGFBP-4 binds LRP6 and Frizzled 8, blocks Wnt3A"}],"covers":["LR000845","LR004277"]},"LR011177":{"pair":"IGFBP6 -> IGF1","headline":"Reactome-only support for IGFBP6-IGF1 complex; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory; Reactome lists an IGF:IGFBP6 complex in the extracellular region [DB:Reactome].","molecular_requirements":"No subunit requirements reported.","affinity_potency":[],"species_and_systems":"Human only; no assay detail beyond Reactome complex records.","localisation_and_range":"IGF1 is annotated as secreted [flag]; IGFBP6 has no localisation flag.","caveats":"No curator-verified paper: one review only, four judged as a different entity and two abstracts insufficient. Support rests on Reactome alone; no affinity.","key_references":[],"covers":["LR011177"]},"LR002780":{"pair":"IGHG1 -> FCGR3A","headline":"Antibody-blocking assay and structures support IgG1 engagement of FcgammaRIIIa; no affinity in our evidence.","interaction_type":"functional only","direction_and_effect":"IgG1 antibodies of the 3+, 1-, 2- GM allotype blocked almost all valine-containing FcgammaRIIIa on NK cells, inhibiting by 93% their ability to mediate HuHMFG1-dependent ADCC [PMID:24701371]. IgG engagement of Fc gamma receptors triggers ADCC [PMID:24701371].","molecular_requirements":"UniProt says Fc glycans matter: afucosylated glycans show up to 100-fold higher affinity for FCGR3A [DB:UniProt]. Valine allotype receptors were tested [PMID:24701371].","affinity_potency":[],"species_and_systems":"Human NK cells in an ADCC inhibition assay against DU145 prostate cancer cells; structures with chains of both proteins are deposited [PMID:24701371][DB:PDB 3AY4].","localisation_and_range":"IGHG1 is annotated as secreted [flag].","caveats":"The curated paper is a functional blocking assay, not a binding measurement, and was read as abstract only; the curator assay_class is direct_binding, which overstates it.","key_references":[{"PMID":"24701371","why":"IgG1 allotype blocks FcgammaRIIIa and inhibits ADCC"}],"covers":["LR002780"]},"LR004283":{"pair":"IL10 -> IL10RA","headline":"IL-10 binds IL10RA (IL-10R1) with sub-nanomolar affinity, shown by crystal structure and binding assays.","interaction_type":"direct binding","direction_and_effect":"A 2.9 A crystal structure shows IL-10 bound to soluble IL-10R1 [PMID:11485736]. Soluble human IL-10 receptor inhibits 125I-hIL-10 binding and antagonises hIL-10 effects on proliferation and cytokine synthesis [PMID:7759550]. Mouse IL-10R expressed in Ba/F3 cells binds IL-10 and the cells proliferate [PMID:8248239]. GtoPdb lists IL-10 as an agonist [DB:GtoPdb].","molecular_requirements":"The complex has two IL-10s and four sIL-10R1 molecules [PMID:11485736]; IL-10R1 is the high-affinity chain and must recruit the low-affinity IL-10R2 chain before signalling [PMID:11485736]. Soluble receptor is monomeric [PMID:7759550].","affinity_potency":[{"value":"Kd 563 +/- 59 pM","assay":"soluble receptor binding","system":"human IL-10 and soluble receptor from myeloma cells","cite":"PMID:7759550"},{"value":"approximately 70 pM","assay":"binding on Ba/F3 transfectants","system":"mouse IL-10R in Ba/F3 cells","cite":"PMID:8248239"},{"value":"pEC50 9.699999809265137 to 10.300000190734863","assay":"GtoPdb affinity","system":"not stated","cite":"PMID:19161426"}],"species_and_systems":"Human proteins in the structure and Kd [PMID:11485736] [PMID:7759550]; mouse cells for the 70 pM value [PMID:8248239].","localisation_and_range":"IL10 is flagged secreted [flag]; paracrine or endocrine range from annotation only.","caveats":"All papers are abstract only. A 2001 crystallisation paper adds no new structure [PMID:11717514]. IL10RA alone binds IL-10 but does not signal without IL10RB [PMID:11485736].","key_references":[{"PMID":"11485736","why":"2.9 A structure of IL-10 with IL-10R1"},{"PMID":"7759550","why":"Kd 563 pM and 2:4 stoichiometry"},{"PMID":"8248239","why":"Mouse IL-10R binds IL-10 at about 70 pM"}],"covers":["LR000853","LR004283"]},"LR000854":{"pair":"IL10 -> IL10RB","headline":"IL10RB is an accessory signalling chain for IL-10; evidence is functional and from an abstract.","interaction_type":"functional only","direction_and_effect":"Co-expressing CRFB4 (IL10RB) with IL-10R1 makes hamster cells sensitive to IL-10, whereas IL-10R1 alone binds but does not signal [PMID:9312047]. The IL-10:CRFB4 complex was detected by cross-linking to labelled IL-10 [PMID:9312047]. GtoPdb lists IL-10 as an agonist for IL10RB [DB:GtoPdb].","molecular_requirements":"IL10RB works with IL10RA as an accessory chain essential for the active receptor [PMID:9312047]. Reactome shows IL10RB binding the IL10 dimer:IL10RA complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human IL-10 and receptor chains in hamster cells and human PBMCs [PMID:9312047]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL10 is flagged secreted [flag]; range from annotation only.","caveats":"Abstract only; IL10RB is the second chain and does not bind IL-10 alone in the evidence shown. No affinity for IL10RB is reported.","key_references":[{"PMID":"9312047","why":"CRFB4 (IL10RB) is the IL-10R2 accessory chain"}],"covers":["LR000854","LR004284"]},"LR004292":{"pair":"IL13 -> IL13RA2","headline":"IL13 binds IL13RA2 with very high affinity, shown by crystal structure and ITC/SPR; functions as a decoy.","interaction_type":"direct binding","direction_and_effect":"IL-13Ralpha2 lacks canonical Jak/STAT signaling and the abstract indicates a decoy function [PMID:20223216]. UniProt: IL13RA2 is a decoy that inhibits IL-13 and IL-4 signalling and internalises IL13, though it can also signal via AP-1 leading to TGFB1 [DB:UniProt].","molecular_requirements":"IL13RA2 alone binds IL13; it uses the same two-site binding mode as IL13RA1 with extra peripheral residues [PMID:20223216]. It binds IL-13 but not IL-4 and does not pair with IL4R in COS-7 beyond a small number of receptors [PMID:8663118] [DB:UniProt].","affinity_potency":[{"value":"4.7 pM","assay":"displacement isothermal titration calorimetry","system":"soluble IL-13 and IL-13R alpha2 extracellular domains, human","cite":"PMID:20223216"},{"value":"over 5,000-fold higher affinity than IL-13R alpha1","assay":"ITC","system":"soluble human proteins","cite":"PMID:20223216"}],"species_and_systems":"Human recombinant proteins (insect cell expressed) [PMID:20223216]; COS-7 cells transfected with receptor cDNA [PMID:8663118]. Mouse pair inferred from human.","localisation_and_range":"Receptor flagged transmembrane; ligand secreted [flag].","caveats":"The femtomolar statement in the abstract differs from the 4.7 pM measured by ITC in the full text; both are as reported [PMID:20223216]. Signalling role conflicts between sources (decoy vs AP-1 signalling) [DB:UniProt]. 8663118 read as abstract only.","key_references":[{"PMID":"20223216","why":"Crystal structure and affinity of IL-13/IL-13Ralpha2"},{"PMID":"8663118","why":"Cloning; IL-13 binding to COS-7 cells, not IL-4"}],"covers":["LR000862","LR004292"]},"LR000863":{"pair":"IL13 -> IL2RG","headline":"IL13 engages IL2RG only as part of an IL4R alpha/IL2R gamma heterodimer in one functional study; weak and chain-only.","interaction_type":"functional only","direction_and_effect":"IL13 mimics IL4 in inducing heterodimerization of IL2R gamma and IL4R alpha in cells expressing both, with marked JAK3 and STAT6 activation [PMID:8920992].","molecular_requirements":"Both IL4R alpha and IL2R gamma are required for JAK3 and proliferative responses in BA/F3 reconstitution [PMID:8920992]. IL2RG alone is not shown to bind IL13.","affinity_potency":[],"species_and_systems":"BA/F3 reconstituted cells; species of cells not reported in our evidence [PMID:8920992]. Mouse pair inferred from human.","localisation_and_range":"Not reported in our evidence.","caveats":"Functional readout, no direct binding. The abstract says the paper contradicts prior reports that IL13 does not use IL2R gamma [PMID:8920992]. Abstract only.","key_references":[{"PMID":"8920992","why":"IL13 induces IL2Rgamma/IL4Ralpha heterodimerization and JAK3/STAT6 activation"}],"covers":["LR000863","LR004293"]},"LR008234":{"pair":"IL15 -> IL15RA:IL2RB:IL2RG","headline":"Trimeric IL15 receptor complex is asserted by databases only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist [DB:GtoPdb]; UniProt says IL15 is expressed with high-affinity IL15RA and delivers signals to target cells [DB:UniProt]; Reactome has IL15 receptor reactions [DB:Reactome].","molecular_requirements":"Three subunits IL15RA, IL2RB and IL2RG; structures [DB:PDB 2Z3Q] [DB:PDB 2Z3R] [DB:PDB 4GS7]. Per-subunit necessity not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human database records.","localisation_and_range":"IL15 flagged secreted [flag].","caveats":"One paper abstract-insufficient and one review-only; no confirmed paper. Database-only support.","key_references":[],"covers":["LR008234"]},"LR006029":{"pair":"IL17A -> IL17RD","headline":"IL-17RD directly binds IL-17A (not IL-17F or the A/F heterodimer) and acts as a second IL-17A receptor; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17RD directly bound IL-17A but not IL-17F or IL-17A/F, and IL-17A-induced gene expression was defective in Il17rd-deficient keratinocytes [PMID:31175175]. Il17rd deficiency in nonhemopoietic cells attenuated imiquimod-induced psoriasis-like skin inflammation [PMID:31175175].","molecular_requirements":"IL-17RD formed a heterodimer with IL-17RA [PMID:31175175]. IL-17RC and IL-17RD differentially activate IL-17A signalling, and compound mutation produced complete deficits in keratinocytes; IL-23 induction depends on both [PMID:31175175].","affinity_potency":[],"species_and_systems":"Curators recorded human for ligand and receptor, but the abstract also describes Il17rd-deficient keratinocytes and mouse psoriasis-model work; the species of each experiment is not stated in the abstract [PMID:31175175].","localisation_and_range":"Not reported in our evidence beyond IL-17A being annotated as secreted and IL-17RD as a receptor [flag].","caveats":"Single paper read as an abstract only; no affinity reported. The human pair is ortholog-inferred while the mouse pair is not.","key_references":[{"PMID":"31175175","why":"Direct IL-17A binding to IL-17RD and Il17rd-deficient phenotypes"}],"covers":["LR002786","LR006029"]},"LR000872":{"pair":"IL17F -> IL17RA","headline":"IL-17F binds IL-17RA with lower affinity than IL-17A, within an IL-17RA/IL-17RC receptor; evidence is one abstract-only SPR paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17F bound IL-17RA with a different affinity from IL-17A and from the heterodimer in SPR; IL-17F activity was inhibited by soluble IL-17RC, not IL-17RA [PMID:18684971]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"IL-17RA works in an IL-17RA/IL-17RC complex [PMID:18684971]. UniProt notes IL17RA and IL17RC chains cannot distinguish IL17A and IL17F [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells [PMID:18684971]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17F annotated as secreted and non-transmembrane [flag]; IL-17RA as a receptor [flag].","caveats":"Abstract-only; no affinity values are given. Soluble IL-17RC rather than IL-17RA blocked IL-17F, suggesting IL-17RA is not the main binder [PMID:18684971].","key_references":[{"PMID":"18684971","why":"SPR comparison of IL-17A, F and A/F to IL-17RA and IL-17RC"}],"covers":["LR000872","LR004302"]},"LR011735":{"pair":"IL1B -> IL1B:IL1R2:IL1RAP","headline":"Database-asserted only, with structures of related complexes; no verified paper, and the complex lists IL1B as a receptor member.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL1B-IL1RAP as agonist [DB:GtoPdb]; UniProt calls IL1R2 a non-signaling receptor for IL1A, IL1B and IL1RN [DB:UniProt]; PDB 3O4O is a structure with IL1B and IL1R2 chains [DB:PDB 3O4O].","molecular_requirements":"IL1RAP associates with secreted ligand-bound IL1R2 and raises affinity of secreted IL1R2 for IL1B per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"No experiments from curated papers in our evidence.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"No curator-verified paper in our evidence; support rests on database records only. Two papers are pending. Affinity not reported.","key_references":[],"covers":["LR011735"]},"LR000881":{"pair":"IL1B -> IL1R1","headline":"IL-1beta binds IL1R1; structural and genetic evidence (human crystal structure, mouse knockout), IL1RAP raises affinity.","interaction_type":"direct binding","direction_and_effect":"IL-1beta acts as an agonist at type I IL-1R: a 2.5 A crystal structure shows binding with 1:1 stoichiometry [PMID:9062193]; all IL-1 agonists bound AcP-deficient cells through IL1R1 but did not activate NF-kappaB or AP-1 [PMID:9820540].","molecular_requirements":"IL1RAP is needed for signalling, and murine IL-1beta affinity was reduced by 70-fold without AcP [PMID:9820540]. The structure uses the receptor extracellular domain (s-IL1R) alone [PMID:9062193].","affinity_potency":[],"species_and_systems":"Human ligand and receptor ectodomain in the structure [PMID:9062193]; mouse AcP-deficient fibroblasts and mice [PMID:9820540].","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers abstract only. No Kd is reported in our evidence. One further paper is pending.","key_references":[{"PMID":"9062193","why":"Crystal structure of IL-1beta bound to IL1R1 ectodomain"},{"PMID":"9820540","why":"IL1RAP effect on IL-1beta affinity and signalling"}],"covers":["LR000881","LR004311"]},"LR006038":{"pair":"IL1RAP -> PTPRD","headline":"IL1RAP and PTPRD bind directly, with crystal structures and neuronal assays; trans-synaptic adhesion.","interaction_type":"direct binding","direction_and_effect":"PTPdelta binds IL-1RAcP trans-synaptically and bidirectionally induces pre- and postsynaptic differentiation [PMID:25908590]. IL-1RAcP interacted with PTPdelta through the extracellular domain in cortical neurons [PMID:22357843]. An interactome screen also reports IL1RAP interacting with all three LAR-PTPRs [PMID:32822567].","molecular_requirements":"Crystal structure of the complex shows the PTPdelta Ig1-Fn2 domains bind IL-1RAcP extracellular domain 1:1; Ig1-Ig2 of PTPdelta is insufficient, and IL-1RAcP Ig1 contacts PTPdelta Ig2/Ig3 while Ig3 of IL-1RAcP does not [PMID:25908590]. Splice inserts of PTPdelta tune binding; absence of meA gave threefold reduced affinity [PMID:25908590]. W27A mutation of IL-1RAcP reduced affinity sevenfold [PMID:25908590].","affinity_potency":[],"species_and_systems":"Crystallography on recombinant human domains and neuronal assays [PMID:25908590]; cultured cortical neurons [PMID:22357843]; SPR/ELISA screen of human proteins [PMID:32822567]. Mouse is the non-inferred species in the database record.","localisation_and_range":"Both are membrane proteins [flag]; interaction is across the synapse (trans, contact-dependent) [PMID:25908590].","caveats":"Direction is arbitrary: the interaction is bidirectional adhesion, not a classic secreted ligand. Two abstracts were read as abstract only [PMID:22357843]. Affinity values are in tables not shown in our evidence.","key_references":[{"PMID":"25908590","why":"Crystal structures of PTPdelta with IL-1RAcP"},{"PMID":"22357843","why":"IL-1RAcP interacts with PTPdelta in cortical neurons"},{"PMID":"32822567","why":"Interactome screen reporting IL1RAP with LAR-PTPRs"}],"covers":["LR002795","LR006038"]},"LR007307":{"pair":"IL1RAP -> PTPRF","headline":"IL1RAP binds PTPRF in a human cell-surface interactome study with SPR; single paper.","interaction_type":"direct binding","direction_and_effect":"The paper states IL1RAP is known to interact with all three LAR-PTPRs, and shows SPR for the pair [PMID:32822567]. SPR sensorgrams for PTPRF-Fc binding IL1RAP-Fc are shown (analyte 2-2048 nM) [PMID:32822567]. IntAct also records solid phase assay and SPR [DB:IntAct]. Effect direction is not reported in our evidence.","molecular_requirements":"Ectodomain-Fc fusions were used; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ectodomain-Fc proteins, ELISA screen with SPR validation [PMID:32822567].","localisation_and_range":"Both flagged as membrane proteins [flag]; trans-synaptic LAR-PTPR interactions with IL1RAP are described [PMID:32822567].","caveats":"One primary paper; the evidence sentence cites earlier work (known interaction), so the screen result itself is only shown in a figure not in our evidence. Another judged paper was abstract_insufficient. No affinity values reported.","key_references":[{"PMID":"32822567","why":"Human IgSF interactome with SPR"}],"covers":["LR007307"]},"LR004319":{"pair":"IL20 -> IL22RA1","headline":"IL-20 signals through the type II IL-20R complex (IL22RA1 plus IL20RB); binding and signalling shown in transfected cells, read from abstracts only.","interaction_type":"direct binding","direction_and_effect":"IL-20 and mda-7 bind the IL-22R/IL-20Rbeta complex, causing STAT3 phosphorylation [PMID:11564763]; IL-20 and IL-24 both signal through IL-22R/IL-20RB in reporter, proliferation and STAT assays [PMID:12351624]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"IL22RA1 acts as part of a heterodimer with IL20RB (type II IL-20R) [PMID:11564763]. Evidence is for the complex, not IL22RA1 alone. Reactome records IL20:IL22RA1:JAK1:IL20RB [DB:Reactome R-HSA-9009224].","affinity_potency":[],"species_and_systems":"Transfected receptor complexes in cell lines; species of cells not stated in the abstracts. Mouse pair is projected from human evidence.","localisation_and_range":"IL-20 is flagged secreted [flag]; receptor is membrane-bound by inference only.","caveats":"Both papers read as abstracts only. Binding is to the two-chain complex, so a single IL22RA1 row inherits complex-level evidence. IntAct lists an SPR record for the pair [DB:IntAct].","key_references":[{"PMID":"11564763","why":"binding of IL-20 to type II complex with STAT3 activation"},{"PMID":"12351624","why":"reporter/proliferation/STAT assays with IL22RA1/IL20RB"}],"covers":["LR000889","LR004319"]},"LR000890":{"pair":"IL21 -> IL21R","headline":"IL-21 binds IL-21R independently of the common gamma chain; human cell evidence from one abstract plus database records.","interaction_type":"direct binding","direction_and_effect":"IL-21 binds IL-21R on gamma(c)-deficient cells but cannot signal there; signalling is restored when gamma(c) is transfected [PMID:11418623]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"IL-21R alone is enough for ligand binding; the common gamma chain is required for signalling (JAK1, JAK3, STAT1, STAT3 activation) [PMID:11418623]. A structure with chains of both partners exists [DB:PDB 8ENT].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in ED40515(-) and gamma(c)-transfected EDgamma-16 cells [PMID:11418623]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-21 is flagged secreted [flag].","caveats":"Single paper, read as abstract only. A CCC tool scoring IL21R alone would miss the gamma(c) requirement.","key_references":[{"PMID":"11418623","why":"IL-21 binds IL-21R without gamma(c); gamma(c) needed for signalling"}],"covers":["LR000890","LR004320"]},"LR009206":{"pair":"IL22 -> IL10RA","headline":"Verified negative: IL-22 does not bind IL10RA according to the curated paper; the stimulatory annotation is not supported.","interaction_type":"conflicting","direction_and_effect":"The abstract states that IL-22 does not bind the IL-10R, and IL-22-responsive cell lines were unresponsive to IL-10 [PMID:10875937].","molecular_requirements":"Not applicable; IL-22 uses CRF2-4 and IL-22R instead [PMID:10875937].","affinity_potency":[],"species_and_systems":"Human, abstract-level reading of one paper [PMID:10875937].","localisation_and_range":"IL-22 is flagged secreted [flag].","caveats":"Our database records shown (BioGRID IL22-IL10RB, Reactome IL22:IL22RA1:JAK1 binding IL10RB:TYK2) concern other chains, not IL10RA [DB:BioGRID][DB:Reactome R-HSA-8854645]. One further row was unresolvable. Abstract only.","key_references":[{"PMID":"10875937","why":"explicit statement that IL-22 does not bind the IL-10R"}],"covers":["LR009206"]},"LR007316":{"pair":"IL24 -> IL20RA:IL20RB","headline":"IL-24 binds the IL20RA:IL20RB heterodimer (type I IL-20R); two abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"IL-24 is a ligand for IL-20R1/IL-20R2, binding transfected COS cells and activating STATs [PMID:11706020]; mda-7 binds the type I complex with STAT3 phosphorylation [PMID:11564763]. GtoPdb lists agonists for each chain [DB:GtoPdb].","molecular_requirements":"Both IL20RA and IL20RB are named as the receptor; IL-24 can also use IL20RB with IL22RA1 [PMID:11706020][PMID:11564763].","affinity_potency":[],"species_and_systems":"Human; COS transfectants, keratinocytes, BHK cells [PMID:11706020].","localisation_and_range":"IL-24 is flagged secreted [flag]. Complex is not flagged by our evidence beyond that.","caveats":"Abstract-only; two further rows were review_only. A structure with chains of IL24 and IL20RB exists [DB:PDB 6DF3].","key_references":[{"PMID":"11706020","why":"IL-24 binding to IL-20R1/IL-20R2"},{"PMID":"11564763","why":"mda-7 binding to type I IL-20R"}],"covers":["LR007316"]},"LR004328":{"pair":"IL24 -> IL20RB","headline":"IL20RB is the shared second chain for IL-24 in both receptor complexes; evidence is complex-level, abstract only.","interaction_type":"functional only","direction_and_effect":"IL-24 signals through IL-20RA/IL-20RB and IL-22R/IL-20RB in reporter, proliferation and STAT assays [PMID:12351624]; IL-24 binds both heterodimers [PMID:11706020]. Agonist per GtoPdb [DB:GtoPdb].","molecular_requirements":"IL20RB is a common chain paired with either IL20RA or IL22RA1 [PMID:20061404]. IL20RB alone binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptors in transfected cells [PMID:11706020]; IL-24 transgenic mice [PMID:20061404].","localisation_and_range":"IL-24 is flagged secreted [flag].","caveats":"Single-chain row inherits complex-level evidence; all papers abstract-only. A structure with chains of IL24 and IL20RB exists [DB:PDB 6DF3].","key_references":[{"PMID":"11706020","why":"IL-24 binds two heterodimers sharing IL-20R2"},{"PMID":"12351624","why":"IL-24 signalling through IL-20RB-containing complexes"},{"PMID":"20061404","why":"soluble IL-20R2 blocks IL-24"}],"covers":["LR000898","LR004328"]},"LR001862":{"pair":"IL33 -> IL1RL1","headline":"IL-33 binds ST2 (IL1RL1) directly (crystal structure) and signals through it; well supported by structure and functional work, mostly read as abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-33 acts as an agonist: it signals via ST2, activating NF-kappaB and MAP kinases and driving Th2-associated cytokines [PMID:16286016]. ST2 siRNA reduced IL-33-dependent IL-8 in lung endothelial and epithelial cells [PMID:20926795]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"ST2 is the primary ligand-binding receptor and IL-1RAcP is the accessory chain; IL-1RAcP cannot bind the ligand directly [PMID:23980170]. UniProt/Reactome describe a 1:1:1 IL33:IL1RL1:IL1RAP complex [DB:UniProt][DB:Reactome]. In pancreatic myofibroblasts, responsiveness needed prior ST2L upregulation [PMID:19996325].","affinity_potency":[],"species_and_systems":"Crystal structure of IL-33 with the ST2 ectodomain at 3.27 A, human [PMID:23980170]; cell assays in human cells [PMID:16286016][PMID:19996325][PMID:20926795]. Mouse pair is ortholog-inferred; no mouse experiment shown.","localisation_and_range":"Ligand flagged secreted [flag]; acts on ST2-expressing cells in paracrine fashion by inference only.","caveats":"All four papers shown were read as abstracts only. No affinity value is reported in our evidence.","key_references":[{"PMID":"23980170","why":"Crystal structure of IL-33:ST2 ectodomain"},{"PMID":"16286016","why":"Original IL-33/ST2 signalling report"},{"PMID":"20926795","why":"ST2 knockdown in human lung cells"}],"covers":["LR001862","LR005207"]},"LR000908":{"pair":"IL34 -> CSF1R","headline":"IL-34 is a CSF1R ligand supported by receptor screening, structures and in vivo genetics; papers read as abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-34 acts as an agonist of CSF1R: a receptor screen identified CSF1R as the receptor for IL-34 [PMID:18467591]; mouse Il34-deficient animals selectively lack Langerhans cells and microglia [PMID:22729249]. GtoPdb lists Agonist [DB:GtoPdb].","molecular_requirements":"CSF1R is a single-chain receptor here; a dimer is described in Reactome [DB:Reactome]. M-CSF plus IL-34 together gave a distinct CSF1R phosphorylation pattern and BIAcore showed M-CSF binds IL-34 [PMID:26095744].","affinity_potency":[],"species_and_systems":"Recombinant screen [PMID:18467591]; human cells [PMID:26095744]; mouse knockout [PMID:22729249]; zebrafish il34/csf1ra mutants [PMID:30205037]. Crystal structure PDB 4DKD [DB:PDB 4DKD]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"All papers read as abstracts. The in vivo papers show dependence, not binding. The zebrafish study concerns csf1ra, not human CSF1R. No affinity reported.","key_references":[{"PMID":"18467591","why":"Receptor screen identifying CSF1R for IL-34"},{"PMID":"22729249","why":"Mouse Il34 knockout phenotype"},{"PMID":"26095744","why":"IL-34 with M-CSF on CSF1R activation"}],"covers":["LR000908","LR004337"]},"LR004337":{"pair":"IL34 -> CSF1R","headline":"IL-34 is a CSF1R ligand supported by receptor screening, structures and in vivo genetics; papers read as abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-34 acts as an agonist of CSF1R: a receptor screen identified CSF1R as the receptor for IL-34 [PMID:18467591]; mouse Il34-deficient animals selectively lack Langerhans cells and microglia [PMID:22729249]. GtoPdb lists Agonist [DB:GtoPdb].","molecular_requirements":"CSF1R is a single-chain receptor here; a dimer is described in Reactome [DB:Reactome]. M-CSF plus IL-34 together gave a distinct CSF1R phosphorylation pattern and BIAcore showed M-CSF binds IL-34 [PMID:26095744].","affinity_potency":[],"species_and_systems":"Recombinant screen [PMID:18467591]; human cells [PMID:26095744]; mouse knockout [PMID:22729249]; zebrafish il34/csf1ra mutants [PMID:30205037]. Crystal structure PDB 4DKD [DB:PDB 4DKD]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"All papers read as abstracts. The in vivo papers show dependence, not binding. The zebrafish study concerns csf1ra, not human CSF1R. No affinity reported.","key_references":[{"PMID":"18467591","why":"Receptor screen identifying CSF1R for IL-34"},{"PMID":"22729249","why":"Mouse Il34 knockout phenotype"},{"PMID":"26095744","why":"IL-34 with M-CSF on CSF1R activation"}],"covers":["LR000908","LR004337"]},"LR006047":{"pair":"IL36G -> IL1RL2","headline":"IL36G binds the IL-36R extracellular domain with micromolar affinity and activates it; direct binding plus functional support.","interaction_type":"direct binding","direction_and_effect":"Agonists including IL-36gamma bind the IL-36R ectodomain; the antagonist IL-36Ra binds with higher affinity and a slower off rate [PMID:29180446]. IL-1epsilon activated NF-kappaB through IL-1Rrp2 [PMID:11466363][PMID:14734551]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Agonists do not detectably bind IL-1RAcP alone; IL-1RAcP binds IL-36R strongly only with IL-36alpha present, so IL-36R-agonist binary complex recruits IL-1RAcP [PMID:29180446].","affinity_potency":[{"value":"micromolar (agonists vs IL-36R ectodomain)","assay":"surface plasmon resonance / direct binding","system":"recombinant human","cite":"PMID:29180446"}],"species_and_systems":"Human recombinant and human cells [PMID:29180446][PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"All abstract-only. The ternary-complex experiment used IL-36alpha. The 74 uM figure is a predicted IL-36R/IL-1RAcP affinity, not ligand binding [PMID:29180446].","key_references":[{"PMID":"29180446","why":"Binding analysis of IL-36 agonists and receptors"},{"PMID":"14734551","why":"IL-1Rrp2-dependent NF-kappaB activation"},{"PMID":"11466363","why":"IL-1epsilon signals via IL-1Rrp2"}],"covers":["LR002805","LR006047"]},"LR007325":{"pair":"IL36RN -> IL1RAP:IL1RL2","headline":"IL-36Ra inhibits IL1RL2/IL1RAP by database assertion only; no usable papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists antagonist records for both subunits [DB:GtoPdb]. UniProt says IL-36Ra inhibits IL-36 by binding IL1RL2 and preventing association with IL1RAP [DB:UniProt].","molecular_requirements":"Binding is to IL1RL2; IL1RAP recruitment is prevented [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"One paper judged abstract-insufficient; support is from databases.","key_references":[],"covers":["LR007325"]},"LR011339":{"pair":"IL37 -> IL18R1:IL18RAP","headline":"Database-asserted only; three papers pending.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist records for IL18R1 and IL18RAP [DB:GtoPdb]; Reactome has IL37 binding IL18R1 and a complex [DB:Reactome].","molecular_requirements":"IL18R1 and IL18RAP as listed members; BioGRID records IL18R1-IL37 [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"No judged papers.","key_references":[],"covers":["LR011339"]},"LR002807":{"pair":"IL37 -> SIGIRR","headline":"SIGIRR (IL-1R8) is genetically required for IL-37 function; direct binding not shown.","interaction_type":"functional only","direction_and_effect":"Silencing IL-1R8 impaired IL-37 anti-inflammatory activity and IL-1R8-deficient IL-37tg mice lost protection [PMID:25729923].","molecular_requirements":"IL-1R8 acts as a co-receptor with IL-18Ralpha; Reactome shows IL37:IL18R1 binding SIGIRR [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human PBMC and mice [PMID:25729923].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Abstract only; IL-37 is not shown to bind SIGIRR alone. Effect labelled antagonist by curator but GtoPdb says Agonist [DB:GtoPdb].","key_references":[{"PMID":"25729923","why":"IL-1R8 requirement for IL-37"}],"covers":["LR002807"]},"LR000917":{"pair":"IL6 -> IL6R","headline":"IL6 binds IL6R directly (Kd 440 pM) and forms a hexamer with gp130; strongly supported.","interaction_type":"direct binding","direction_and_effect":"IL-6 is an agonist at IL6R [DB:GtoPdb]. IL-6 is engaged first by IL-6Ralpha and then presented to gp130 in a hexameric signalling complex [PMID:12829785].","molecular_requirements":"gp130 is required for signalling: the IL-6R cytoplasmic domain lacks a kinase domain [PMID:3136546]. Domain 3 of IL-6R accounts for more than 90% of the binding energy; the N-terminal Ig-like domain is not involved [PMID:14557255]. Hexamer by EM [PMID:15895091].","affinity_potency":[{"value":"Kd 440 pM","assay":"125I-rhIL-6 binding","system":"IL-6R-expressing NIH/3T3 cells","cite":"PMID:1995637"}],"species_and_systems":"Human ligand and receptor; transfected murine NIH/3T3 fibroblasts [PMID:1995637]; crystal and EM structures [PMID:12829785][PMID:15895091].","localisation_and_range":"IL6 flagged secreted [flag]; IL6R flagged transmembrane [flag]. Cell-surface receptor binds soluble IL-6.","caveats":"Abstracts only; affinity from one transfected system.","key_references":[{"PMID":"12829785","why":"Crystal structure of IL-6/IL-6Ralpha/gp130 hexamer"},{"PMID":"1995637","why":"Kd 440 pM for IL-6 binding to IL-6R"},{"PMID":"14557255","why":"D3 domain carries >90% of binding energy"}],"covers":["LR000917"]},"LR004346":{"pair":"IL6 -> IL6ST","headline":"IL6 reaches IL6ST only via IL6R; structural and domain-dissection evidence in human, abstracts only.","interaction_type":"direct binding","direction_and_effect":"IL-6 binds IL-6R and the IL-6:IL-6R complex associates with gp130 [PMID:9694899]; crystal structure and EM show a hexameric IL-6:IL-6Ralpha:gp130 complex [PMID:15895091]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL6R is required: the IL-6R D3 domain alone binds IL-6 but, complexed with IL-6, fails to associate with gp130; the second domain is implicated in gp130 complex formation [PMID:9694899]. UniProt: IL6ST does not interact with IL6 itself [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins; refolded bacterially expressed D3 domain, crystal structure and single-particle EM [PMID:9694899][PMID:15895091]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"Not a direct IL6-IL6ST contact; the pair is mediated by IL6R. Both papers read as abstracts only; one paper note records a 2026-10-12 abstract confirmation.","key_references":[{"PMID":"15895091","why":"gp130:IL-6:IL-6Ralpha structure and EM of full extracellular complex"},{"PMID":"9694899","why":"IL-6R domain dissection: D3 binds IL-6, D2 needed for gp130"}],"covers":["LR000918","LR004346"]},"LR000926":{"pair":"IL9 -> IL2RG","headline":"IL9 signals through IL2RG (common gamma) together with IL9R; one functional human paper, abstract-level.","interaction_type":"functional only","direction_and_effect":"IL-9 acts through the IL-9R complex of IL-9Ralpha and gammac, activating JAK1/JAK3 and STAT-1/3/5 [PMID:9535918]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"gammac is needed with IL-9Ralpha; its membrane-proximal segment and IL-9Ralpha Tyr336 are crucial for signalling [PMID:9535918].","affinity_potency":[],"species_and_systems":"Human; mast cell and T cell lines [PMID:9535918]. Mouse pair ortholog-inferred.","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"Chain-only row; gammac is a co-receptor and does not bind IL-9 alone in our evidence. Abstract only.","key_references":[{"PMID":"9535918","why":"IL-9Ralpha/gammac heteromerization and signalling requirements"}],"covers":["LR000926","LR004349"]},"LR004355":{"pair":"INHBA -> ACVR1B","headline":"Activin A signals through ACVR1B (ALK4) with type II receptors; two verified papers, one abstract-only.","interaction_type":"functional only","direction_and_effect":"Activin A engages ACVR1B to activate Smad2/3 signalling (agonist) [PMID:32515349]. In receptor reconstitution, activin A signals through activin type II receptors plus ALK4, and all activins activate ActRIIA plus ALK4 with various levels of potency [PMID:15196700]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Needs a type II receptor together with ACVR1B; activin A binding to type II receptors is required for signalling through ACVR1B [PMID:32515349]. UniProt lists ACVR1B or ACVR1C as type I partners with ACVR2A, ACVR2B or BMPR2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse receptor reconstitution [PMID:15196700]; human system with HEK293 reporter cells and agonist-only muteins [PMID:32515349].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Evidence is functional signalling; direct binding of activin A to ACVR1B alone is not shown in our evidence. 15196700 was read as abstract only [PMID:15196700]; the 32515349 sentence comes from work focused on ACVR1 [PMID:32515349].","key_references":[{"PMID":"15196700","why":"Activin A signals through type II receptors plus ALK4 in reconstitution."},{"PMID":"32515349","why":"Agonist-only activin A muteins activate ACVR1B Smad2/3 signalling."}],"covers":["LR000932","LR004355"]},"LR008270":{"pair":"INHBA -> ACVR1B:ACVR2A","headline":"Activin A to the ACVR1B:ACVR2A complex is database-supported only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists activin A (INHBA) as agonist at ACVR1B and ACVR2A [DB:GtoPdb]. BioGRID records ACVR2A-INHBA binding (Reconstituted Complex, Affinity Capture-Western) [DB:BioGRID]; Reactome lists activin binding to ACVR2A,B:ACVR1B [DB:Reactome]; PDB 7U5P is a structure with INHBA and a type II receptor chain [DB:PDB 7U5P].","molecular_requirements":"Type I (ACVR1B) plus type II (ACVR2A) receptors; UniProt says INHBA signals through type I and type II receptors [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence.","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"No papers were judged; two were abstract_insufficient. Support rests on database records for single chains.","key_references":[],"covers":["LR008270"]},"LR000935":{"pair":"INHBA -> ENG","headline":"Activin A interacts with endoglin only when type II activin receptors are coexpressed; verified abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Endoglin interacts with activin-A but requires coexpression of the ligand-binding kinase receptor; it does not bind ligands on its own [PMID:9872992].","molecular_requirements":"Association with activin-A is via activin type II receptors ActRII and ActRIIB, regardless of the type I partner [PMID:9872992]. Endoglin acts as an accessory protein, a co-receptor role [PMID:9872992].","affinity_potency":[],"species_and_systems":"Human endothelial and leukaemic cells, affinity labelling [PMID:9872992]; mouse pair projected.","localisation_and_range":"Ligand secreted flag [flag]; endoglin is described as a transmembrane glycoprotein [PMID:9872992].","caveats":"Not independent direct binding; needs type II receptors. Abstract only; both confirmed rows may share this evidence.","key_references":[{"PMID":"9872992","why":"Endoglin interacts with activin-A through ActRII/ActRIIB."}],"covers":["LR000935","LR004358"]},"LR007262":{"pair":"INHBA:INHBB -> ACVR1C:ACVR2A","headline":"Activin A/B ligand complex to ACVR1C:ACVR2A; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists each activin subunit with each receptor chain as agonist interactions [DB:GtoPdb]. UniProt says ACVR1C signals with type II receptors like ACVR2A or BMPR2 [DB:UniProt].","molecular_requirements":"ACVR2A binding is supported by BioGRID records [PMID:9202237] and a structure with activin A [DB:PDB 7U5P]. No record here shows activin A or B acting through ACVR1C.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"No paper-level evidence is held for this pair (only review-only or abstract-insufficient rows), so it rests on database records alone.","key_references":[],"covers":["LR007262"]},"LR004364":{"pair":"INHBB -> ACVR2B","headline":"Activin binds ACVR2B in competition assays in CHO cells; one abstract-level paper that concerns inhibin displacing activin.","interaction_type":"direct binding","direction_and_effect":"Labelled activin bound activin type II receptors, especially type IIB, and inhibin displaced it [PMID:9202237]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Displacement occurred at type II receptors, not type I receptors [PMID:9202237].","affinity_potency":[],"species_and_systems":"Chinese hamster ovary cells; ligand and receptor species not recorded in curator fields [PMID:9202237]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"Abstract only; the paper studies activin versus inhibin and does not name activin B specifically in the abstract [PMID:9202237]. No affinity reported.","key_references":[{"PMID":"9202237","why":"Competition binding at activin type II receptors"}],"covers":["LR000941","LR004364"]},"LR002816":{"pair":"INHBE -> ACVR1C","headline":"Activin E signals through ALK7 (ACVR1C) with good functional support in mouse and cells, but direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Activin E acts through ACVR1C, activating SMAD2/3 signalling and suppressing PPARG target genes and lipolysis in mouse adipose tissue; effects were lost in Acvr1c-null mice and mirrored by anti-ACVR1C antibody [PMID:37523551]. Activin E signalled specifically through ALK7, like activin C, in reporter assays [PMID:38533769]. UniProt also records signalling via ACVR1C [DB:UniProt].","molecular_requirements":"ALK7 is required: both ActE constructs gave no CAGA-luciferase activity in HEK-293T cells until ALK7 was supplied. ActE used activin type II receptors; ActRIIA-Fc inhibited ActE signalling dose-dependently while ActRIIB-Fc had no effect [PMID:38533769]. The mature form acting is not established in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo (AAV overexpression, knockout, neutralising antibody) [PMID:37523551]; HEK-293T reporter cells and mature murine adipocytes with modelling by AlphaFold [PMID:38533769]. Human and mouse pairs are both listed.","localisation_and_range":"Ligand is flagged secreted [flag]. Described as a hepatokine acting on adipose tissue [PMID:37523551].","caveats":"Neither paper measured binding: the first states that future biochemical studies are needed on receptor binding and affinity [PMID:37523551]. Both were read as abstracts by curators, with full-text excerpts present.","key_references":[{"PMID":"37523551","why":"Mouse genetics shows activin E needs ACVR1C to suppress lipolysis"},{"PMID":"38533769","why":"ActE signals specifically via ALK7 and type II activin receptors in reporter assays"}],"covers":["LR002816","LR006056"]},"LR006056":{"pair":"INHBE -> ACVR1C","headline":"Activin E signals through ALK7 (ACVR1C) with good functional support in mouse and cells, but direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Activin E acts through ACVR1C, activating SMAD2/3 signalling and suppressing PPARG target genes and lipolysis in mouse adipose tissue; effects were lost in Acvr1c-null mice and mirrored by anti-ACVR1C antibody [PMID:37523551]. Activin E signalled specifically through ALK7, like activin C, in reporter assays [PMID:38533769]. UniProt also records signalling via ACVR1C [DB:UniProt].","molecular_requirements":"ALK7 is required: both ActE constructs gave no CAGA-luciferase activity in HEK-293T cells until ALK7 was supplied. ActE used activin type II receptors; ActRIIA-Fc inhibited ActE signalling dose-dependently while ActRIIB-Fc had no effect [PMID:38533769]. The mature form acting is not established in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo (AAV overexpression, knockout, neutralising antibody) [PMID:37523551]; HEK-293T reporter cells and mature murine adipocytes with modelling by AlphaFold [PMID:38533769]. Human and mouse pairs are both listed.","localisation_and_range":"Ligand is flagged secreted [flag]. Described as a hepatokine acting on adipose tissue [PMID:37523551].","caveats":"Neither paper measured binding: the first states that future biochemical studies are needed on receptor binding and affinity [PMID:37523551]. Both were read as abstracts by curators, with full-text excerpts present.","key_references":[{"PMID":"37523551","why":"Mouse genetics shows activin E needs ACVR1C to suppress lipolysis"},{"PMID":"38533769","why":"ActE signals specifically via ALK7 and type II activin receptors in reporter assays"}],"covers":["LR002816","LR006056"]},"LR006830":{"pair":"INSL5 -> RXFP3","headline":"INSL5 is a weak, low-affinity RXFP3 antagonist; the main INSL5 receptor is another one.","interaction_type":"direct binding","direction_and_effect":"INSL5 is a weak, low-affinity RXFP3 antagonist [PMID:18582868]. It inhibited 125I-relaxin-3 binding to GPCR135 (RXFP3) with low potency and was a weak antagonist at 1 microm [PMID:15525639]. GtoPdb lists an antagonist [DB:GtoPdb].","molecular_requirements":"A chimera with the RXFP4 N-terminus and EL2 gave INSL5 high affinity but no agonist response, so activation needed RXFP4 transmembrane domains [PMID:18582868].","affinity_potency":[{"value":"Ki 500 nM","assay":"inhibition of 125I-relaxin-3 binding","system":"GPCR135 (RXFP3)","cite":"PMID:15525639"},{"value":"pKi 7.010000228881836","assay":"curator-recorded affinity","system":"RXFP3","cite":"PMID:18582868"}],"species_and_systems":"Receptor-expressing cells and chimeras, human ligand and receptor as recorded by curators [PMID:18582868].","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Both papers are abstract only. INSL5 is a selective RXFP4 agonist [PMID:18582868]; this pair is an antagonist, off-target relationship.","key_references":[{"PMID":"18582868","why":"INSL5 is a weak RXFP3 antagonist and selective RXFP4 agonist"},{"PMID":"15525639","why":"INSL5 weakly inhibits relaxin-3 binding to GPCR135"}],"covers":["LR006830"]},"LR002825":{"pair":"ITGAX -> AGER","headline":"Mac-1 and, less so, p150,95 (ITGAX) interact with RAGE; abstract-level direct binding plus mouse knockouts.","interaction_type":"direct binding","direction_and_effect":"RAGE-dependent leukocyte adhesion involved a direct interaction with Mac-1 and to a lower extent p150,95, not LFA-1 or beta1-integrins [PMID:14623906]. RAGE-deficient mice had impaired leukocyte recruitment [PMID:14623906].","molecular_requirements":"The evidence for ITGAX is as p150,95 (alphaXbeta2), a weaker partner than Mac-1 [PMID:14623906].","affinity_potency":[],"species_and_systems":"Mouse peritonitis models with human-integrin binding assays on transfected cells [PMID:14623906]; the mouse pair is orthology-projected.","localisation_and_range":"Membrane receptors acting in cell adhesion [PMID:14623906].","caveats":"Abstract read; the p150,95 interaction is secondary to Mac-1. No affinity values.","key_references":[{"PMID":"14623906","why":"RAGE interacts directly with Mac-1 and p150,95"}],"covers":["LR002825","LR006063"]},"LR006065":{"pair":"ITGB2 -> AGER","headline":"RAGE interacts directly with Mac-1 (alphaMbeta2); ITGB2 row inherits heterodimer evidence from knockout and binding work.","interaction_type":"direct binding","direction_and_effect":"RAGE acts as an adhesion counter-receptor: leukocyte adhesion to RAGE was blocked by an anti-Mac-1 antibody but not an anti-LFA-1 antibody [PMID:14623906]. RAGE-deficient mice had reduced neutrophil recruitment [PMID:14623906].","molecular_requirements":"Specific to Mac-1; p150,95 weaker; LFA-1 and beta1-integrins did not bind [PMID:14623906]. So beta2 alone is not enough.","affinity_potency":[],"species_and_systems":"Mouse peritonitis models, human cell lines (THP-1, U937) and CHO transfectants [PMID:14623906].","localisation_and_range":"Membrane adhesion between leukocytes and endothelium [PMID:14623906].","caveats":"Abstract plus full-text excerpts; the evidence is complex-level. No affinity reported.","key_references":[{"PMID":"14623906","why":"Mac-1 as RAGE counter-receptor with knockout evidence"}],"covers":["LR002827","LR006065"]},"LR000953":{"pair":"JAG1 -> NOTCH2","headline":"Jagged1 binds and activates Notch2 with measured nanomolar affinity in mouse systems; also human cell-based activation.","interaction_type":"direct binding","direction_and_effect":"Mouse Jagged1 bound mouse Notch2 on cells and as a soluble ectodomain, Ca2+-dependent [PMID:10551863]. Jagged1 bound endogenous Notch2 on BaF3 cells and induced Notch2 cleavage within 15 min, nuclear translocation, hyperphosphorylation and RBP-Jkappa reporter activation (agonist) [PMID:10958687]. In human cell-based assays, ligands other than DLL4 activated NOTCH2 similarly or slightly more than NOTCH1, and MFNG inhibited NOTCH2 activation by JAG1 [PMID:32820046].","molecular_requirements":"The DSL domain of Jagged1 is the minimal binding unit and is indispensable; EGF-like repeats 1 and 2 modulate affinity [PMID:10551863]. Fringe modification affects the response [PMID:32820046].","affinity_potency":[{"value":"Kd 0.4 nM","assay":"Scatchard analysis of mJagged1 binding","system":"BaF3 cells","cite":"PMID:10551863"},{"value":"Kd 0.7 nM","assay":"Scatchard analysis of mJagged1 binding","system":"soluble Notch2 protein","cite":"PMID:10551863"}],"species_and_systems":"Binding and signalling papers used mouse proteins [PMID:10551863][PMID:10958687]; the cell-based activation paper used human proteins [PMID:32820046]. The human pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane [flag].","caveats":"All papers read as abstracts only. The kinetic data are from mouse, not human, proteins. Database records (BioGRID, Reactome) add support [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"10551863","why":"Scatchard Kd values for Jagged1-Notch2"},{"PMID":"10958687","why":"Binding and downstream cleavage and reporter activation"},{"PMID":"32820046","why":"Human cell-based activation and Fringe effects"}],"covers":["LR000953","LR004376"]},"LR010826":{"pair":"JAM2 -> ITGAV:ITGB1","headline":"No supporting paper; only a Reactome record concerning alpha4beta1 appears.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"JAM2 flagged as not secreted [flag].","caveats":"Both judged papers were different_entity or abstract_insufficient. Reactome records concern integrin alpha4beta1, not alphaV beta1 [DB:Reactome].","key_references":[],"covers":["LR010826"]},"LR002834":{"pair":"JAM3 -> ITGAM","headline":"JAM3 binds the integrin Mac-1 (ITGAM/ITGB2) directly; purified-protein and cell-adhesion evidence in human cells, plus database records.","interaction_type":"direct binding","direction_and_effect":"JAM-3 acts as a counterreceptor for Mac-1 on leukocytes: myelo-monocytic cells adhere to immobilised JAM-3, and purified JAM-3 or anti-JAM-3 antibodies block platelet-neutrophil interaction [PMID:12208882]. A second paper reports JAM-C (JAM3) availability regulates alpha(M)beta2-dependent leukocyte adhesion [PMID:16093349].","molecular_requirements":"Evidence is for the Mac-1 heterodimer (alphaM/ITGAM with beta2/ITGB2), not ITGAM alone: binding was strong for Mac-1, weaker for p150.95 (alphaXbeta2), and absent for LFA-1 or beta1-integrins [PMID:12208882]. Adhesion needed a beta2-integrin and was blocked by anti-Mac-1 antibody [PMID:12208882].","affinity_potency":[],"species_and_systems":"Human platelets, U937 cells, K562 transfectants, CHO transfectants and purified proteins [PMID:12208882]; species of the second paper's experiments is not specified [PMID:16093349]. The dossier covers human and mouse entries; the experiments shown are human.","localisation_and_range":"JAM-3 is a type I transmembrane glycoprotein [PMID:12208882], so signalling is contact-dependent (juxtacrine); the entity flags also mark JAM3 as secreted [flag], which the papers do not support.","caveats":"The ITGAM evidence is complex-level, so ITGAM and ITGB2 both inherit it. Both papers were read as abstracts by the curators (the first also has full-text excerpts) [PMID:12208882, PMID:16093349]. The second paper is a functional adhesion study. No affinity reported in our evidence.","key_references":[{"PMID":"12208882","why":"Direct JAM-3/Mac-1 binding with integrin specificity panel"},{"PMID":"16093349","why":"JAM-C availability regulates alphaMbeta2-dependent leukocyte adhesion"}],"covers":["LR002834","LR006071"]},"LR007046":{"pair":"JAM3 -> ITGAM:ITGB2","headline":"JAM3 as ligand of the Mac-1 complex is supported by one functional abstract and by database records.","interaction_type":"functional only","direction_and_effect":"JAM-C (JAM3) released from JAM-B binding becomes available apically to engage its leukocyte counter-receptor alpha(M)beta2 integrin, regulating alphaMbeta2-dependent leukocyte adhesion [PMID:16093349]. UniProt describes JAM3 as a counter-receptor for ITGAM mediating leukocyte-platelet interactions [DB:UniProt].","molecular_requirements":"Receptor is the ITGAM:ITGB2 heterodimer (alphaMbeta2). JAM-C partitions competitively between junctional JAM-B binding and apical alphaMbeta2 binding [PMID:16093349].","affinity_potency":[],"species_and_systems":"Human leukocytes and endothelial junctional complexes, as labelled by the curators; read as abstract only [PMID:16093349].","localisation_and_range":"The paper concerns endothelial junctions and leukocytes; JAM3 is described as an interendothelial junction molecule, so contact-dependent [PMID:16093349]. Entity flags also mark JAM3 as secreted [flag].","caveats":"The only paper is a functional, abstract-read study; direct binding of JAM3 to the complex is recorded by BioGRID (reconstituted complex, ITGAM-JAM3) [DB:BioGRID] and Reactome binding reactions for alphaMbeta2 and alphaXbeta2 [DB:Reactome]. Two other judged papers were not usable (one abstract-insufficient, one different entity).","key_references":[{"PMID":"16093349","why":"Functional link between JAM-C availability and alphaMbeta2 leukocyte adhesion"}],"covers":["LR007046"]},"LR001871":{"pair":"JAML -> CXADR","headline":"JAML binds epithelial CAR (CXADR) directly in human systems and contributes to neutrophil transepithelial migration.","interaction_type":"direct binding","direction_and_effect":"A JAML fusion protein specifically bound epithelial CAR at tight junctions in T84 monolayers and normal human colonic mucosa, and JAML/CAR fusion proteins and antibodies significantly and specifically inhibited PMN transepithelial migration [PMID:15800062].","molecular_requirements":"Binding is mediated by the membrane-distal Ig loop of CAR and the membrane-proximal Ig loop of JAML [PMID:15800062].","affinity_potency":[],"species_and_systems":"Human: T84 epithelial monolayers, human colonic mucosa and neutrophils; abstract-only read [PMID:15800062].","localisation_and_range":"JAML on neutrophils binds CAR at epithelial tight junctions, a contact-dependent interaction [PMID:15800062]. The entity flag marks CXADR secreted [flag], not supported by the paper.","caveats":"Abstract-only read. Neutrophils bound immobilised CAR but not JAML [PMID:15800062]. IntAct (protein array) and Reactome records agree [DB:IntAct, DB:Reactome]. No affinity reported.","key_references":[{"PMID":"15800062","why":"JAML-CAR binding and role in PMN transepithelial migration"}],"covers":["LR001871"]},"LR004382":{"pair":"KISS1 -> KISS1R","headline":"Kisspeptin is a well-supported agonist of KISS1R (GPR54), with nanomolar binding and many functional papers plus structures.","interaction_type":"direct binding","direction_and_effect":"Kisspeptins (KISS1 products) are full agonists of KISS1R/GPR54, stimulating PIP2 hydrolysis, Ca2+ mobilisation, ERK1/2 and p38 phosphorylation and stress fibre formation [PMID:11457843]; metastin was isolated as the endogenous ligand of the orphan receptor [PMID:11385580]. In mice, kisspeptin stimulates GnRH release through GPR54 [PMID:15665093]. MMP cleavage of metastin decapeptide abolished its ligand activity [PMID:12879005].","molecular_requirements":"Processed peptides act: 54-, 14- and 13-residue peptides with an RF-amide C terminus [PMID:11457843]; the decapeptide is active until cleaved at Gly118-Leu119 [PMID:12879005]. Single receptor chain.","affinity_potency":[{"value":"pKi 8.6-10.4","assay":"GtoPdb curated interaction, full agonist","system":"as recorded in GtoPdb","cite":"PMID:11385580"}],"species_and_systems":"Human kisspeptins on rat and human GPR54 in CHO-K1 cells [PMID:11457843]; hOT7T175-transfected CHO cells [PMID:11385580]; mouse hypothalamus and gpr54-/- mice, sheep [PMID:15665093]. Human and mouse entries are not ortholog-inferred. PDB structures 8XGS and 8ZJD show a Q15726 chain with a Q969F8 chain [DB:PDB 8XGS].","localisation_and_range":"KISS1 products are secreted peptides (secreted flag [flag]), acting on cells expressing KISS1R, paracrine or endocrine; the receptor is a GPCR.","caveats":"Most papers were read as abstracts. Kisspeptin-10 also activates NPFFR1 and NPFFR2, so cross-reactivity exists [PMID:24900254]. One paper was judged on a pending row.","key_references":[{"PMID":"11457843","why":"Kisspeptin isolation, low nanomolar binding to GPR54 and signalling"},{"PMID":"11385580","why":"Metastin as endogenous ligand of hOT7T175"},{"PMID":"15665093","why":"Kisspeptin acts through GPR54 on GnRH release in mice"}],"covers":["LR000960","LR004382"]},"LR006074":{"pair":"KISS1 -> NPFFR1","headline":"Kisspeptin-10 binds and activates NPFFR1 in one 2011 study; the pair is ortholog-projected from that evidence.","interaction_type":"direct binding","direction_and_effect":"Kisspeptin-10 showed potent binding and activation of NPFFR1, whereas short GPR54-selective peptide agonists bound with much lower affinity [PMID:24900254]. Reported NPFFR ligands showed negligible affinity for GPR54, i.e. cross-reactivity runs one way [PMID:24900254].","molecular_requirements":"Kisspeptin-10 form specifically; short synthetic agonists were weak at NPFFRs [PMID:24900254].","affinity_potency":[],"species_and_systems":"Human and mouse entries are both ortholog-inferred; the paper's experiment species are labelled human by the curators; abstract-only read [PMID:24900254].","localisation_and_range":"KISS1 is flagged secreted [flag]; the paper suggests secondary kisspeptin targets may lie in the median eminence [PMID:24900254].","caveats":"Single paper, abstract only, with no numbers in the dossier. The canonical kisspeptin receptor is GPR54, so this is a cross-reactivity finding [PMID:24900254]. Not present in any database.","key_references":[{"PMID":"24900254","why":"Kisspeptin-10 binds and activates NPFFR1 and NPFFR2"}],"covers":["LR002838","LR006074"]},"LR002843":{"pair":"KLRG1 -> CDH4","headline":"KLRG1 binds R-cadherin (CDH4) in one paper; thin evidence.","interaction_type":"direct binding","direction_and_effect":"KLRG1 is an inhibitory receptor and binds R-cadherin; the functional inhibition was shown for E-cadherin [PMID:16461340].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The KLRG1 tetramer stained cells transduced with E-, N- or R-cadherins, but not P-, M- or VE-cadherins; mouse KLRG1 tetramer was used [PMID:16461340]. Human pair is ortholog-inferred [flag].","localisation_and_range":"Membrane proteins; localisation flags are available for KLRG1 [flag].","caveats":"One paper only, and no database record. No affinity and no R-cadherin-specific functional result.","key_references":[{"PMID":"16461340","why":"KLRG1 binds E-, N- and R-cadherins"}],"covers":["LR002843","LR006078"]},"LR000962":{"pair":"KNG1 -> BDKRB1","headline":"Kininogen-derived kinins activate B1R; structure and radioligand work, but the active ligand is a kinin peptide, not KNG1.","interaction_type":"direct binding","direction_and_effect":"Des-Arg10-kallidin activates B1R, and a G protein-coupled complex structure of human B1R bound to des-Arg10-kallidin is reported [PMID:34518695]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The acting ligand is a processed kinin peptide released from kininogen; the intact KNG1 protein as the ligand is not tested in our evidence [PMID:34518695][PMID:10422787].","affinity_potency":[{"value":"pKi 9.6-10.0","assay":"GtoPdb full agonist record","system":"not specified in dossier","cite":"PMID:10422787"}],"species_and_systems":"Human B1R in the structure [PMID:34518695]. Cloned rat and human B1R in COS-7 cells with [3H]des-Arg10-kallidin binding [PMID:10422787]. PDB 7EIB [DB:PDB 7EIB].","localisation_and_range":"KNG1 is secreted [flag]; kinins act as peptide hormones at a membrane GPCR [PMID:34518695].","caveats":"KNG1 itself is a precursor, so expression of KNG1 only indicates potential kinin supply after proteolysis. Four papers were abstract_insufficient and four pending. The pKi range is from GtoPdb, not from a paper in our dossier text.","key_references":[{"PMID":"34518695","why":"B1R structure with des-Arg10-kallidin"},{"PMID":"10422787","why":"Rat and human B1R pharmacology"}],"covers":["LR000962","LR004384"]},"LR004391":{"pair":"L1CAM -> CNTN1","headline":"Co-immunoprecipitation from mouse cerebellum shows F3/CNTN1 in a complex with L1; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"F3 (CNTN1) was physically associated in a complex with both L1 and fyn tyrosine kinase in native adult mouse cerebellum [PMID:7595520]. No effect direction is reported.","molecular_requirements":"F3 is GPI-anchored and sits in glycolipid-enriched microdomains that also contain L1 and fyn [PMID:7595520]; whether fyn or other proteins bridge the association is not reported in our evidence. Reactome lists an L1:CNTN1 complex [DB:Reactome R-HSA-443653].","affinity_potency":[],"species_and_systems":"Adult mouse cerebellum tissue, co-IP; human pair is ortholog-inferred [PMID:7595520].","localisation_and_range":"Both membrane-anchored on parallel fibers (cis/contact); CNTN1 is not flagged secreted [flag].","caveats":"Co-IP shows association within a complex, not proven direct binding; abstract only.","key_references":[{"PMID":"7595520","why":"Native-tissue co-IP of F3 with L1 and fyn"}],"covers":["LR000969","LR004391"]},"LR000971":{"pair":"L1CAM -> ERBB2","headline":"Reciprocal co-IP in HEK293 cells shows L1CAM-erbB2 association; one paper, brain co-IP also positive.","interaction_type":"direct binding","direction_and_effect":"L1CAM co-immunoprecipitated with erbB2 and the reverse IP pulled down L1CAM, in HEK293 cells [PMID:22815787]. L1CAM binding to erbB enhances the response to neuregulins; effect labelled agonist [PMID:22815787].","molecular_requirements":"Different Ig-like domains of L1CAM can support erbB interaction [PMID:22815787]. Heterodimer partners of ERBB2 are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human L1CAM and erbB2 in HEK293 cells; L1CAM also co-IPs with erbB2 from brain extracts; mouse and rat tissue used [PMID:22815787]. Mouse pair is ortholog-inferred. BioGRID lists Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"Cell-surface proteins in cis in axons [PMID:22815787]; L1CAM flagged secreted too [flag].","caveats":"Single paper; non-quantitative co-IP, no affinity; abstract-level label but full text excerpted.","key_references":[{"PMID":"22815787","why":"Co-IP of L1CAM with erbB2"}],"covers":["LR000971","LR004393"]},"LR006083":{"pair":"L1CAM -> ITGB3","headline":"L1-Ig6 RGD binds beta3 integrins alphavbeta3 and alphaIIbbeta3; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"L1-Ig6 is a heterophilic ligand for alphavbeta3 and alphaIIbbeta3, supporting HUVEC and platelet adhesion [PMID:9396761].","molecular_requirements":"RGD-dependent; beta3 integrin binding occurs in Ca2+, Mg2+ or Mn2+ [PMID:9396761]. ITGB3 pairs with alphav or alphaIIb; chain-level row.","affinity_potency":[],"species_and_systems":"Human L1-Ig6, HUVEC, platelets [PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion [PMID:9396761].","caveats":"Single paper, no affinity; prefer complex rows for scoring.","key_references":[{"PMID":"9396761","why":"L1-Ig6 binds beta3 integrins"}],"covers":["LR002848","LR006083"]},"LR002852":{"pair":"LAMA1 -> DAG1","headline":"Laminin-1 binds alpha-dystroglycan in an overlay assay in bovine cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Biotin-laminin-1 bound alphaDG on membrane blots, soluble alphaDG blocked endothelial cell adhesion to laminin-1, and glycosaminoglycans inhibited the binding [PMID:10207021]. The interaction record is flagged Stimulatory [flag].","molecular_requirements":"Not reported in our evidence; the ligand tested was laminin-1 as a whole, and a laminin alpha5 globular fragment also bound alphaDG [PMID:10207021].","affinity_potency":[],"species_and_systems":"Bovine aortic endothelial cells and membrane proteins; human and mouse pairs are ortholog-inferred [PMID:10207021].","localisation_and_range":"Ligand flagged secreted; DAG1 flagged transmembrane receptor [flag]. Cell adhesion experiment is to a substrate-coated laminin [PMID:10207021].","caveats":"Abstract only (re-read via protein names), and the ligand is laminin-1, not LAMA1 alone. The abstract is cut off. No affinity reported.","key_references":[{"PMID":"10207021","why":"Laminin-1 overlay shows binding to alphaDG"}],"covers":["LR002852","LR006086"]},"LR000980":{"pair":"LAMA1 -> ITGB1","headline":"Conflicting: LAMA1 fragment binds alpha1/alpha2beta1 integrins, but one full-text paper judged pair absent.","interaction_type":"conflicting","direction_and_effect":"Laminin alpha1 fragment VI/V bound purified alpha1beta1 and alpha2beta1 integrins [PMID:9688542]; alpha7beta1 mediates myoblast migration on laminin-1 [PMID:11278916]. Another paper was judged pair absent [PMID:16413178].","molecular_requirements":"ITGB1 acts within alpha-beta heterodimers (alpha1, alpha2, alpha7 here); the LN module (domain VI) carries the binding site [PMID:9688542].","affinity_potency":[],"species_and_systems":"Recombinant fragments and purified integrins, species unspecified [PMID:9688542]; human transfected myoblasts [PMID:11278916]; human recombinant integrins [PMID:16413178]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor flagged not secreted [flag]; matrix ligand.","caveats":"The curator noted no LAMA1-containing laminin showed detectable binding to ITGB1-containing integrins in Table 1 (ND everywhere) [PMID:16413178]. Two confirmed papers are abstract-only and the pair is a chain of heterodimers and trimers.","key_references":[{"PMID":"9688542","why":"LN module binds alpha1beta1 and alpha2beta1"},{"PMID":"11278916","why":"Alpha7beta1-mediated migration on laminin-1"},{"PMID":"16413178","why":"Table 1 negative verdict"}],"covers":["LR000980","LR004401"]},"LR011078":{"pair":"LAMA3 -> ITGA9:ITGB1","headline":"No paper evidence; only a Reactome record naming a different integrin.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a Reactome binding reaction [DB:Reactome].","molecular_requirements":"Receptor is the alpha9beta1 complex; no experiment on it in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"LAMA3 is flagged secreted and not transmembrane [flag]; laminin acts as a basement-membrane matrix ligand (not stated in the paper text we hold).","caveats":"Rests on database alone. Reactome R-HSA-349626 describes integrin alpha2beta1 binding laminin-332, not alpha9beta1 [DB:Reactome].","key_references":[],"covers":["LR011078"]},"LR006092":{"pair":"LAMA3 -> SDC4","headline":"Syndecan-4-transfected cells adhere to laminin alpha3 LG4; functional evidence only, abstract-level read.","interaction_type":"functional only","direction_and_effect":"293T cells transfected with syndecan-2 or -4, but not glypican-1, specifically adhered to LG4 and the A3G75aR peptide; adhesion was inhibited by heparitinase I treatment [PMID:11373281].","molecular_requirements":"Adhesion mapped to a LG4 peptide (NSFMALYLSKGR); heparan sulfate chains implicated [PMID:11373281].","affinity_potency":[],"species_and_systems":"Transfected 293T cells; species not stated in our evidence [PMID:11373281].","localisation_and_range":"LAMA3 flagged secreted [flag]; SDC4 transmembrane flag not given in dossier.","caveats":"No direct binding assay for syndecan-4 in our evidence (direct binding was shown for syndecan-2). Abstract-only read.","key_references":[{"PMID":"11373281","why":"Syndecan-4 transfectants adhere to LG4"}],"covers":["LR002858","LR006092"]},"LR004409":{"pair":"LAMA4 -> ITGA3","headline":"The laminin alpha4 G domain binds integrin alpha3beta1 with high affinity (recombinant fragment); abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Recombinant G(919-1207) of laminin alpha4 bound alpha3beta1 with high affinity, and endothelial adhesion to it was blocked by integrin antibodies [PMID:12454288]. Interaction record lists a Stimulatory effect [flag].","molecular_requirements":"Receptor tested is the alpha3beta1 heterodimer; the ligand is a G-domain fragment, not full chain [PMID:12454288].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to recombinant G(919-1207) (adhesion, not binding Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Endothelial cells and recombinant protein; species not stated in the abstract [PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted [flag]; component of vessel basement membrane [PMID:12454288].","caveats":"Abstract only; no binding Kd quoted, the 1.4 nM value is an adhesion half-maximum. One further paper was review-only.","key_references":[{"PMID":"12454288","why":"alpha3beta1 and alphavbeta3 bind alpha4 G domain"}],"covers":["LR000990","LR004409"]},"LR002861":{"pair":"LAMA5 -> CD44","headline":"A synthetic laminin alpha5 G-domain peptide pulls down CD44 from mouse melanoma cells; peptide-level evidence only.","interaction_type":"direct binding","direction_and_effect":"Peptide A5G27 (RLVSYNGIIFFLK, residues 2892-2904) from the alpha5 G domain bound a CD44-reactive band by affinity chromatography, and CD44 GAGs mediated attachment to it [PMID:15256450]. Stimulatory per interaction record [flag].","molecular_requirements":"Binding site is a peptide, not intact laminin alpha5; GAG chains of CD44 are implicated [PMID:15256450].","affinity_potency":[],"species_and_systems":"Mouse B16-F10 melanoma cells; human pair is ortholog-inferred [PMID:15256450].","localisation_and_range":"LAMA5 flagged secreted; CD44 flagged transmembrane [flag].","caveats":"Abstract only; peptide, not full chain; no affinity value. Other peptides did not bind a surface protein.","key_references":[{"PMID":"15256450","why":"A5G27 peptide identifies CD44 as receptor"}],"covers":["LR002861","LR006095"]},"LR004418":{"pair":"LAMB1 -> ITGA3","headline":"Laminin-10/11 (beta1-containing) is an integrin alpha3beta1 ligand by binding and adhesion blockade; abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 is a high-affinity ligand for integrin alpha3beta1, and CD151 potentiates the binding [PMID:15677332]. Anti-alpha3 or anti-beta1 antibodies blocked adhesion of A549 cells to laminin-10/11 [PMID:9624186]. Annotated stimulatory.","molecular_requirements":"Needs integrin alpha3 with beta1; CD151 sustains activation [PMID:15677332]. Laminin-10 (alpha5beta1gamma1) is a heterotrimer and LAMB1 was not tested alone.","affinity_potency":[],"species_and_systems":"Human A549 cells for adhesion [PMID:9624186]; system for the binding paper not reported in our evidence. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA3 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers were abstract reads; LAMB1 is inferred from laminin-10/11 composition. Two further papers were review_only. No Kd is given in this dossier for this pair.","key_references":[{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand"},{"PMID":"9624186","why":"Antibody-blocked adhesion to laminin-10/11"}],"covers":["LR000999","LR004418"]},"LR011393":{"pair":"LAMB1 -> ITGA7:ITGB1","headline":"Complex row for laminin beta1 and integrin alpha7beta1; only PDB and similarity-based UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P07942 and a chain of P05556 [DB:PDB 7CEC]; UniProt notes ITGB1 interacts with LAMB1 (by similarity) [DB:UniProt].","molecular_requirements":"Receptor is the ITGA7:ITGB1 heterodimer per the entity record.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB1 is flagged secreted [flag]; the receptor complex is not flagged as a receptor [flag]. Range otherwise not reported in our evidence.","caveats":"Three papers pending, none judged. UniProt note is by similarity and concerns ITGB1; the PDB chains listed do not include ITGA7.","key_references":[],"covers":["LR011393"]},"LR002870":{"pair":"LAMB2 -> ITGB4","headline":"LAMB2 (in laminin-511/521) binds integrin alpha6beta4 at Kd 25 nM; plus an abstract-level binding report.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521, which contains LAMB2, bound recombinant alpha6beta4 in solid-phase assays [PMID:16413178]. Alpha6beta4 was also reported as a receptor for laminin isoforms 1, 2, 4 and 5 in radioligand-binding and adhesion assays [PMID:7721947]. Annotated effect is Stimulatory [flag].","molecular_requirements":"The tested binder is the alpha6beta4 heterodimer and the ligand the assembled laminin heterotrimer; ITGB4 alone was not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 25 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta4 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; 804G rat bladder epithelial cells with laminin of unstated origin [PMID:7721947]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. PMID:7721947 was read as abstract only and its species is ambiguous.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-511/521"},{"PMID":"7721947","why":"alpha6beta4 receptor for several laminins, abstract only"}],"covers":["LR002870","LR006104"]},"LR004427":{"pair":"LAMC1 -> ITGA3","headline":"LAMC1 (in laminin-10/11) is recognised by integrin alpha3beta1 in A549 cell adhesion; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Adhesion to laminin-10/11 coated substrata was inhibited by antibodies to integrin alpha3 or beta1 but not alpha2 or alpha6, indicating recognition by alpha3beta1 [PMID:9624186]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Ligand is the alpha5-containing laminin-10/11 heterotrimer, so LAMC1 acts as one chain; the receptor is the alpha3beta1 heterodimer [PMID:9624186].","affinity_potency":[],"species_and_systems":"Human A549 lung adenocarcinoma cells and purified laminin-10/11; mouse pair is projected from human [PMID:9624186].","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Only an abstract was read. Antibody blocking of adhesion is not direct binding, and LAMC1 cannot be separated from the other chains. One review_only paper is not shown.","key_references":[{"PMID":"9624186","why":"Antibody-blocked A549 adhesion to laminin-10/11, abstract only"}],"covers":["LR001009","LR004427"]},"LR011384":{"pair":"LAMC1 -> ITGA3:ITGB1","headline":"LAMC1 with ITGA3:ITGB1 has only a PDB record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P05556 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Five papers were abstract_insufficient and one different_entity. The PDB entry lists no ITGA3 chain. A functional paper exists for the LAMC1-ITGA3 chain-level row, but it is not credited to this complex row.","key_references":[],"covers":["LR011384"]},"LR011168":{"pair":"LAMC2 -> CD44","headline":"LAMC2 is reported to act through CD44 in triple-negative breast cancer cells; mainly functional, with direct interaction cited from earlier work.","interaction_type":"functional only","direction_and_effect":"CD44 silencing reversed LAMC2-induced migration of TNBC cells, and LAMC2 over-expression activated STAT3 signalling [PMID:38760717]. Recorded effect: stimulatory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human TNBC cell lines (MDA-MB-231) in vitro, and LAMC2 over-expressing xenograft tumours in mice [PMID:38760717].","localisation_and_range":"Direct interaction is described at the cell membrane; CD44 is flagged transmembrane and secreted, LAMC2 secreted [flag].","caveats":"Direct LAMC2-CD44 binding in this paper rests on a citation to earlier work (Sato et al. 2015), not a new binding assay; the data are loss-of-function in cells. The abstract says LAMC2 acts by up-regulating CD44 expression [PMID:38760717].","key_references":[{"PMID":"38760717","why":"CD44 knockdown reverses LAMC2 effects in TNBC"}],"covers":["LR011168"]},"LR011942":{"pair":"LEFTY2 -> NODAL","headline":"Ligand-ligand pair supported only by a Reactome complex record; no papers passed curation.","interaction_type":"database-asserted only","direction_and_effect":"Recorded as inhibitory in the interaction annotation [flag]; no paper evidence is available in our evidence.","molecular_requirements":"Reactome lists a LEFTY1,2:NODAL complex in the extracellular region [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence; the Reactome record is the only support [DB:Reactome].","localisation_and_range":"Both partners are flagged secreted, not transmembrane [flag].","caveats":"Support rests on a database assertion alone; 6 papers were judged abstract_insufficient and none confirmed. This is a ligand-ligand class pair, not a ligand-receptor one [flag].","key_references":[],"covers":["LR011942"]},"LR005219":{"pair":"LGALS1 -> CD69","headline":"Galectin-1 binds CD69 directly and carbohydrate-dependently; function in Th17 regulation, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"SPR and anti-CD69 blocking showed a direct, specific, carbohydrate-dependent interaction; CD69 mediates the negative effect of galectin-1 on Th17 differentiation [PMID:24752896]. UniProt records the same negative role [DB:UniProt].","molecular_requirements":"CD69 extracellular domain fusion proteins were used; galectin-1 was identified on human dendritic cells by pulldown and mass spectrometry [PMID:24752896]. Other subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human dendritic cells and recombinant proteins; functional assays used human and mouse T cells. The mouse pair is ortholog-inferred [PMID:24752896].","localisation_and_range":"Galectin-1 flagged secreted and also a receptor [flag]; present on immature dendritic cells per UniProt [DB:UniProt].","caveats":"Abstract-only read; no affinity values reported. The curator labelled direction antagonist, but the paper describes a negative regulatory effect on Th17 differentiation.","key_references":[{"PMID":"24752896","why":"SPR and blocking show galectin-1/CD69 binding; Th17 role"}],"covers":["LR001877","LR005219"]},"LR006119":{"pair":"LGALS3 -> ITGB4","headline":"Galectin-3 binds beta4 integrin via beta1,6GlcNAc-branched N-glycans, promoting adhesion and migration; abstract only.","interaction_type":"direct binding","direction_and_effect":"Binding of galectin-3 to beta4-integrin via beta1,6GlcNAc-branched N-glycans promoted beta4-integrin-mediated cancer cell adhesion and migration [PMID:29549127].","molecular_requirements":"Glycan dependent: beta1,6GlcNAc branching on beta4-integrin; bisecting GlcNAc suppressed migration and tumorigenesis [PMID:29549127].","affinity_potency":[],"species_and_systems":"Human cutaneous squamous cell carcinoma tissue and transformed keratinocytes [PMID:29549127]. Mouse pair ortholog-inferred.","localisation_and_range":"Galectin-3 flagged secreted; ITGB4 flagged receptor [flag].","caveats":"Abstract-only read; binding is N-glycan dependent, so depends on cell glycosylation; no affinity data.","key_references":[{"PMID":"29549127","why":"Galectin-3/beta4-integrin binding via beta1,6-branched N-glycans"}],"covers":["LR002885","LR006119"]},"LR001880":{"pair":"LGALS3 -> LAG3","headline":"Galectin-3 binds LAG-3 on CD8+ T cells and LAG-3 is needed for galectin-3 suppression of IFN-gamma in vitro.","interaction_type":"functional only","direction_and_effect":"Galectin-3 suppressed CD8+ T cells in a LAG-3-dependent way: wild-type cells showed a 20% reduction in IFN-gamma at 150 ug/mL or higher, while LAG-3 knockout cells did not [PMID:25691328]. PD-1 knockout had minimal effect [PMID:25691328].","molecular_requirements":"Co-immunoprecipitation of LAG-3 with galectin-3 in activated CD8+ T cell lysates, with a cross-linked LAG-3/galectin-3 complex at 150-250 kD; PD-1 did not co-precipitate [PMID:25691328].","affinity_potency":[],"species_and_systems":"Mouse T cells and galectin-3-deficient mice, tumour models; curator lists human [PMID:25691328]. Human pair is ortholog-inferred.","localisation_and_range":"Galectin-3 binds activated CD8+ T cells only in the tumour microenvironment [PMID:25691328]; LAG3 flagged transmembrane [flag].","caveats":"Read depth recorded as abstract only although full-text excerpts exist. Glycan dependence and affinity not reported in our excerpts.","key_references":[{"PMID":"25691328","why":"Galectin-3 binds LAG-3; needed for CD8+ T-cell suppression"}],"covers":["LR001880","LR005222"]},"LR006128":{"pair":"LGALS8 -> ITGA3","headline":"Galectin-8 binds alpha3beta1 integrin from carcinoma and other cells and blocks cell adhesion, inducing apoptosis; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Galectin-8 inhibited adhesion of human 1299 carcinoma cells to plates coated with integrin ligands and induced apoptosis (antagonist of adhesion); effects were not mimicked by galectin-1 or galectin-3, and Mn2+ abolished the inhibition [PMID:10852818].","molecular_requirements":"The integrin identified is alpha3beta1, so both ITGA3 and ITGB1 chains are involved; whether one chain suffices is not reported in our evidence [PMID:10852818].","affinity_potency":[],"species_and_systems":"Human 1299 carcinoma cells; alpha3beta1 also from HeLa and human endothelial cells; mouse pair is ortholog-inferred [PMID:10852818].","localisation_and_range":"Galectin-8 is a secreted protein (secreted flag [flag]); endogenous galectin-8 secreted from 1299 cells forms complexes with surface alpha3beta1 integrin [PMID:10852818].","caveats":"Abstract only. Binding is sugar-dependent (a beta-galactoside lectin reading glycans) [PMID:10852818]. BioGRID lists Affinity Capture-Western and Reconstituted Complex records [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"10852818","why":"Galectin-8 binding to alpha3beta1 integrin inhibits adhesion and induces apoptosis"}],"covers":["LR002898","LR006128"]},"LR002906":{"pair":"LGALS9 -> CLEC7A","headline":"Galectin-9 reported to be ligated by dectin-1 in mouse and human pancreatic cancer; single abstract-based paper.","interaction_type":"direct binding","direction_and_effect":"Dectin 1 can ligate galectin 9 in mouse and human PDA, driving tolerogenic macrophage programming per the curator note [PMID:28394331].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse and human pancreatic ductal adenocarcinoma (PDA); recombinant versus tissue system not stated in our evidence [PMID:28394331].","localisation_and_range":"Galectin-9 is flagged secreted [flag]; receptor localisation is taken from the paper's statement that dectin-1 is on macrophage surfaces [PMID:28394331].","caveats":"One paper, read as abstract only; no affinity, and the binding method is only described as ligand-receptor binding characterisation. No database support.","key_references":[{"PMID":"28394331","why":"Dectin-1 ligates galectin-9 in PDA"}],"covers":["LR002906"]},"LR006137":{"pair":"LIF -> LRP1","headline":"LRP1 binds LIF directly in a chondrocyte ligandome study; single abstract-read paper, no database record.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding was confirmed for LIF among ten ligands [PMID:36028175]. The effect on signalling is not reported in our evidence; the dossier lists the effect as agonist but the study concerns endocytosis, with affinity correlating to endocytosis rate [PMID:36028175].","molecular_requirements":"No co-receptor or chain requirement reported.","affinity_potency":[],"species_and_systems":"Purified LRP1 binding assays, human chondrocytes, and a conditional Lrp1-knockout mouse model; the dossier labels species human [PMID:36028175]. Mouse pair is ortholog-inferred.","localisation_and_range":"LIF is flagged secreted [flag]; LRP1 is an endocytic receptor, so this is clearance rather than classical signalling (the abstract refers to endocytosis).","caveats":"One paper, abstract only; no affinity value for LIF in our evidence. A multi-ligand screen where LIF is one of ten. No database support.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding confirmed for LIF among ten chondrocyte ligands"}],"covers":["LR002911","LR006137"]},"LR004445":{"pair":"LPL -> GPIHBP1","headline":"GPIHBP1 binds LPL and chylomicrons on capillary endothelium; supported by one abstract-only paper plus structural and interaction databases.","interaction_type":"direct binding","direction_and_effect":"Expression of GPIHBP1 in cultured cells conferred binding of both LpL and chylomicrons; Gpihbp1-deficient mice accumulated chylomicrons, with plasma triglycerides as high as 5000 mg/dl [PMID:17403372]. GPIHBP1 acts as a platform for LpL-mediated chylomicron processing [PMID:17403372]. UniProt states that interaction with GPIHBP1 protects LPL against inactivation by ANGPTL4 [DB:UniProt].","molecular_requirements":"UniProt reports a 1:1 stoichiometry between LPL and GPIHBP1 [DB:UniProt]. Reactome describes GPIHBP1 binding an HSPG:LPL dimer [DB:Reactome]. Crystal structures of the two proteins are listed [DB:PDB 6E7K].","affinity_potency":[],"species_and_systems":"Paper labels experiments human; the abstract itself mentions mouse knockouts and cultured cells [PMID:17403372]. The mouse pair is ortholog-inferred.","localisation_and_range":"GPIHBP1 is on the luminal face of capillary endothelium in heart and adipose tissue [PMID:17403372]. LPL is annotated secreted [flag].","caveats":"Paper read as abstract only. Affinity not reported in our evidence. IntAct lists ELISA and affinity-technology records [DB:IntAct].","key_references":[{"PMID":"17403372","why":"GPIHBP1 binds LpL and chylomicrons; knockout mice show chylomicronemia"}],"covers":["LR001031","LR004445"]},"LR002915":{"pair":"LRFN4 -> PTPRF","headline":"LRFN4 (SALM3) binds LAR-family RPTPs including PTPRF in a splice-dependent trans-synaptic interaction; one paper, plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SALM3 interacts with and requires all three LAR-RPTPs (LAR, PTP-sigma, PTP-delta) for presynaptic differentiation [PMID:26321637]. The interaction needs the mini-exon B insert in the LAR-RPTP [PMID:26321637]. Reactome lists SALM3 binding LAR-RPTP [DB:Reactome].","molecular_requirements":"LAR-RPTPs containing meB alone bound SALM3, those with only meA or neither did not; adding meA to meB increased binding. Ig1-3 domains of PTP-delta were sufficient [PMID:26321637].","affinity_potency":[],"species_and_systems":"Paper reports mouse SALM3 and mouse PTP-delta in its assays; dossier species fields say human and the mouse pair is ortholog-inferred [PMID:26321637]. Cell-binding and co-culture assays, plus Salm3 knockout mice [PMID:26321637].","localisation_and_range":"Both flagged transmembrane for the pair, so contact-dependent trans-synaptic adhesion [flag][PMID:26321637].","caveats":"Evidence is family-level for all LAR-RPTPs; pair-specific data for PTPRF are not separated in our evidence. Paper read only as abstract per record, though full-text excerpts are present. Affinity not reported in our evidence.","key_references":[{"PMID":"26321637","why":"SALM3 binds LAR-RPTPs in a meB-dependent manner"}],"covers":["LR002915","LR006140"]},"LR005237":{"pair":"LRFN5 -> LRFN5","headline":"LRFN5 (SALM5) appears to form homomeric complexes; one abstract-only co-IP paper.","interaction_type":"direct binding","direction_and_effect":"SALMs 1-3 co-immunoprecipitated with each other whereas SALMs 4 and 5 did not, suggesting SALM4 and SALM5 mainly form homomeric complexes [PMID:18227064]. The curator notes that in heterologous cells all five SALMs formed both heteromeric and homomeric complexes [PMID:18227064].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in rat brain and heterologous cells [PMID:18227064]. The mouse pair is not ortholog-inferred; the human pair is.","localisation_and_range":"LRFN5 is flagged transmembrane [flag]; a homomeric adhesion-type complex.","caveats":"Abstract only. The homomeric inference is partly from a negative (no co-IP with SALMs 1-3). Direction and functional effect not reported in our evidence; self-pair is not a classical ligand-receptor.","key_references":[{"PMID":"18227064","why":"SALM co-IP showing homomeric complexes of SALM5"}],"covers":["LR001895","LR005237"]},"LR006146":{"pair":"LRIG1 -> VSIR","headline":"LRIG1 binds VISTA (VSIR) directly with nanomolar affinity, and the pair inhibits T cell receptor signalling; evidence comes from one paper.","interaction_type":"direct binding","direction_and_effect":"The paper describes LRIG1 as an inhibitory receptor engaging VISTA and suppressing TCR signalling [PMID:38758807]. T cell-specific LRIG1 deletion in mice gave superior antitumor CTL responses [PMID:38758807]. Curators label the effect antagonist [PMID:38758807].","molecular_requirements":"In the murine T cell line D10.G4.1, VISTA or LRIG1 alone was functionally inert; coexpression of both inhibited phosphorylation of LAT, PLC-gamma, SLP76, AKT S473 and ERK1/2 [PMID:38758807]. The LRIG1 extracellular domain is needed for binding, and cis and trans binding were both seen [PMID:38758807].","affinity_potency":[{"value":"KD 1.20 nM (pH 7.4)","assay":"SPR, recombinant ECDs","system":"murine","cite":"PMID:38758807"},{"value":"KD 3.44 nM (pH 6.0)","assay":"SPR, recombinant ECDs","system":"murine","cite":"PMID:38758807"},{"value":"KD 1.86 nM (pH 7.4)","assay":"SPR, recombinant ECDs","system":"human","cite":"PMID:38758807"},{"value":"KD 0.23 nM (pH 6.0)","assay":"SPR, recombinant ECDs","system":"human","cite":"PMID:38758807"}],"species_and_systems":"Binding was shown by proximity labelling, co-IP, SPR and a luciferase complementation assay, in murine T cells, HEK293 cells and B16.OVA tumours; SPR used murine and human proteins [PMID:38758807]. The mouse pair is listed separately and is not ortholog-inferred.","localisation_and_range":"Both are type-I transmembrane or membrane proteins per annotation [flag]. The paper shows cis (same cell) and trans (APC to T cell) binding, so signalling is contact-dependent [PMID:38758807]. LRIG1 was induced on T cells after anti-CD3/CD28 stimulation and absent on naive cells [PMID:38758807].","caveats":"Only one paper, read as abstract plus excerpts. Our pair lists LRIG1 as ligand and VSIR as receptor, but the paper calls LRIG1 the receptor and VISTA the ligand, so direction is assignment-dependent. Human functional data are correlative (LRIG1 expression and immunotherapy resistance) [PMID:38758807].","key_references":[{"PMID":"38758807","why":"Identifies LRIG1 as a VISTA binding partner, with SPR affinities and T cell function"}],"covers":["LR002921","LR006146"]},"LR002924":{"pair":"LRPAP1 -> IFNAR1","headline":"Secreted LRPAP1 binds IFNAR1 and drives its degradation, helping viruses evade interferon signalling; one 2023 paper plus BioGRID records.","interaction_type":"direct binding","direction_and_effect":"The N-terminus of secreted LRPAP1 binds the IFNAR1 extracellular domain and triggers IFNAR1 ubiquitination and degradation, promoting virus infection in vitro, ex vivo in mouse brain and in newborn mice [PMID:37743411]. Curators label the effect antagonist [PMID:37743411]. Recombinant LRPAP1 reduced cell-surface IFNAR1 [PMID:37743411].","molecular_requirements":"A small peptide from the LRPAP1 N-terminus binds and degrades IFNAR1 [PMID:37743411]. Binding to the IFNAR1 ECD was tested by pull-down and microscale thermophoresis; the MST values are not reported in our excerpts [PMID:37743411].","affinity_potency":[],"species_and_systems":"Human HEK-293T, RD and mouse 4T1 cells, C57BL/6 mouse cerebrum and newborn mice [PMID:37743411]. BioGRID lists affinity capture-Western and reconstituted complex [DB:BioGRID]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted, non-transmembrane [flag]. The paper presents secreted LRPAP1 acting extracellularly on membrane IFNAR1 [PMID:37743411].","caveats":"LRPAP1 is also known as an LDL-receptor-family chaperone; this paper's IFNAR1 effect is virus-induced upregulation, and it is a single paper. Alpha2M as an inhibitor stabilising IFNAR1 is reported in the abstract only [PMID:37743411].","key_references":[{"PMID":"37743411","why":"Secreted LRPAP1 binds IFNAR1 ECD and triggers its degradation"}],"covers":["LR002924","LR006149"]},"LR006155":{"pair":"LRRTM2 -> NRXN1","headline":"LRRTM2 binds neurexin-1 lacking the S4 insert; well supported by binding assays, a crystal structure and knockdown, in several systems.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 acts as a neurexin ligand that promotes excitatory synapse formation; neurexin-1alpha and -1beta bound avidly to LRRTM2 only when lacking an insert at SS#4 [PMID:20064387]. Recombinant neurexin-1beta blocks LRRTM2-promoted presynaptic differentiation [PMID:20064387], and Nrxn1 knockdown abolishes LRRTM2-induced presynaptic differentiation [PMID:20064388]. Truncated NRXN1 and NRXN2 mutants fail to bind LRRTM2 in cell binding assays [PMID:21424692].","molecular_requirements":"Neurexin must lack the S4 insert; binding is Ca2+-dependent and reversed by EGTA [PMID:20064387]. The Nrxn1beta-LRRTM2 structure (3.4 A resolution) shows a calcium ion in the interface; LRRTM2 E348Q and Nrxn1beta D141A mutations abolished or almost abolished binding, and Nrxn1beta binds the LRRTM2 C-terminal cap [PMID:30262834].","affinity_potency":[],"species_and_systems":"Affinity chromatography used rat brain and recombinant Ig-fusions, binding assays used HEK293T cells [PMID:20064387]; the structure used human proteins [PMID:30262834]. Both alpha and beta neurexin-1 bind [PMID:20064387, PMID:20064388].","localisation_and_range":"Both partners are flagged transmembrane [flag]. Papers describe trans-interaction, with LRRTM2 postsynaptic and neurexin presynaptic, producing cell-adhesion junctions [PMID:20064387].","caveats":"No affinity value in our evidence (SPR sensorgrams are mentioned without values). Two of five papers were read as abstracts only [PMID:20519524, PMID:21424692]; the 2011 paper uses the pair only as a readout of mutation effects.","key_references":[{"PMID":"20064387","why":"affinity chromatography and cell binding; S4 dependence, Ca2+ dependence"},{"PMID":"30262834","why":"crystal structure of Nrxn1beta-LRRTM2 complex"},{"PMID":"20064388","why":"Nrxn1 knockdown abrogates LRRTM2 synaptogenic activity"}],"covers":["LR002930","LR006155"]},"LR007343":{"pair":"LRRTM3 -> NRXN3","headline":"Supported only by an IntAct coimmunoprecipitation record; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"One IntAct record, association by anti tag coimmunoprecipitation, from PMID 33961781 [DB:IntAct]. Species is human per the entity record [flag].","localisation_and_range":"Both partners are flagged transmembrane [flag].","caveats":"No curated papers; one review-only row was judged. A co-immunoprecipitation association does not show direct binding or direction.","key_references":[],"covers":["LR007343"]},"LR006164":{"pair":"LRRTM4 -> NRXN1","headline":"LRRTM4 binds neurexin-1 beta directly in cell-free assays, independent of splice site 4; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant LRRTM4-Fc bound Nrx1beta with or without S4, and His-LRRTM4 ectodomain co-precipitated with Nrx1beta(-S4)-Fc in a cell-free assay; the authors conclude LRRTM4 has two binding partners, neurexin and glypican [PMID:23911103]. Signalling effect on neurexin is not reported in our evidence.","molecular_requirements":"Unlike LRRTM2, LRRTM4 binds neurexin independent of S4, so it can bind a broader array of neurexin isoforms [PMID:23911103]. The tested form was Nrx1beta; other NRXN1 isoforms are not reported.","affinity_potency":[],"species_and_systems":"Experiments used recombinant Fc-tagged ectodomains, 293T cells and rat brain homogenate [PMID:23911103]. Species of the recombinant proteins is not stated in the excerpts. UniProt lists LRRTM1-4 interaction for the neurexin entry, by similarity [DB:UniProt].","localisation_and_range":"Both partners flagged membrane-bound [flag], so contact-dependent (juxtacrine) signalling is expected.","caveats":"Only one confirming paper; the headline of that paper is glypican, and neurexin was complementary. The sentence about LPHN3 is a negative control, not evidence about this pair [PMID:23911103]. Mouse pair is projected from human.","key_references":[{"PMID":"23911103","why":"Direct LRRTM4-Nrx1beta binding, S4-independent"}],"covers":["LR002939","LR006164"]},"LR004454":{"pair":"LTA -> TNFRSF1B","headline":"LT alpha binds the 75-kDa TNF receptor, but with lower affinity than TNF and without clear signalling in the one cell system examined.","interaction_type":"direct binding","direction_and_effect":"LT still had approximately half of the affinity to p75R of TNF by Scatchard analysis, yet LT was unable to signal through p75R on U-937 cells in cytotoxicity [PMID:8123048]. The database annotation reads Stimulatory; the paper does not support signalling here.","molecular_requirements":"UniProt says the LTA homotrimer binds TNFR2/TNFBR [DB:UniProt]. Reactome lists LTA trimer binding TNFRSF1A,1B,14 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human U-937 monocytic cells [PMID:8123048]. The expression-cloning paper used a human lung fibroblast library [PMID:2160731].","localisation_and_range":"LTA flagged secreted; the receptor flagged both secreted and transmembrane [flag].","caveats":"Both papers read as abstracts only. No numeric Kd is given in our evidence. The expression-cloning abstract does not name which TNF receptor was cloned [PMID:2160731]. BioGRID lists reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"8123048","why":"Scatchard binding of LT to p75R vs TNF"},{"PMID":"2160731","why":"Cloned TNF receptor family member binds TNF-beta"}],"covers":["LR001041","LR004454"]},"LR002942":{"pair":"LTF -> LRP2","headline":"Lactoferrin binds LRP2/gp330 on blots; one 1992 paper plus UniProt, no signalling evidence.","interaction_type":"direct binding","direction_and_effect":"gp330 from rat kidney membranes bound bovine lactoferrin on nitrocellulose blots; lactoferrin is known to inhibit hepatic clearance of chylomicron remnants [PMID:1464627]. Curator labels antagonist, but the cell-based blocking assay in the abstract was for LRP (LRP1), not gp330 [PMID:1464627].","molecular_requirements":"The 39-kDa RAP protein inhibits binding of all ligands to both LRP and gp330 [PMID:1464627]. UniProt lists lactoferrin among ligands bound by LRP2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Bovine lactoferrin with rat kidney gp330 [PMID:1464627]. The human and mouse pairs are ortholog-inferred.","localisation_and_range":"Lactoferrin flagged secreted [flag]; receptor-mediated uptake not studied here.","caveats":"Single abstract-only paper; no affinity or signalling reported; antagonist effect belongs to LRP1 experiments.","key_references":[{"PMID":"1464627","why":"gp330 and LRP bind bovine lactoferrin"}],"covers":["LR002942","LR006167"]},"LR004463":{"pair":"MADCAM1 -> ITGB7","headline":"MADCAM1 binds integrin alpha4beta7; ITGB7 is the specificity-determining chain, but the pair rests on heterodimer data.","interaction_type":"direct binding","direction_and_effect":"MADCAM1 acts as a stimulatory adhesion ligand; alpha4beta7 is a receptor for MAdCAM-1 [PMID:7687523]. A beta7 region (residues 46-386) accounts for specificity of alpha4beta7 binding to MAdCAM-1, with a MIDAS-like domain at residues 176-250 [PMID:9233649].","molecular_requirements":"ITGB7 needs alpha4 to bind; alpha4beta1 does not bind MAdCAM-1 despite sharing alpha4 [PMID:7687523][PMID:9233649]. Mn2+ activation enhances binding [PMID:7687523].","affinity_potency":[],"species_and_systems":"Human beta7/beta1 chimeric constructs [PMID:9233649]; human lymphocyte lines in the force-spectroscopy study [PMID:29789438]; species unspecified in PMID:7687523. Mouse pair is ortholog-inferred.","localisation_and_range":"MADCAM1 is flagged transmembrane, not secreted [flag]; contact-dependent.","caveats":"Papers other than PMID:29789438 were read as abstracts only. Chain-only entry: the binding entity is the alpha/beta pair (curator note). CCL25 and CXCL10 switch alpha4beta7 between MAdCAM-1 and VCAM-1 preference [PMID:29789438]. A PDB entry has chains of both MADCAM1 and ITGB7 partners [DB:PDB 9P95].","key_references":[{"PMID":"9233649","why":"beta7 domain mapping for MAdCAM-1 binding"},{"PMID":"7687523","why":"alpha4beta7 identified as MAdCAM-1 receptor"},{"PMID":"29789438","why":"chemokine-dependent conformers and single-bond force data"}],"covers":["LR001050","LR004463"]},"LR006173":{"pair":"MDGA1 -> APP","headline":"MDGA1 MAM domain binds APP directly with nanomolar affinity; this is supported by full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"MDGA1 binds APP, and acts as antagonist of synaptic inhibition: MDGA1-mediated disinhibition requires the MAM domain and depends on presynaptic APP [PMID:35074912].","molecular_requirements":"The MDGA1 MAM domain binds the extension domain of APP; binding is extracellular Ca2+-dependent. MDGA1-Fc bound APP and APLP2 but not APLP1 cells, and MDGA2-Fc did not bind APP [PMID:35074912].","affinity_potency":[{"value":"Kd 84.74 nM","assay":"cell-surface binding, Scatchard analysis of MDGA1-Fc","system":"HEK293T cells expressing HA-APP","cite":"PMID:35074912"}],"species_and_systems":"HEK293T cells, purified recombinant proteins, mouse hippocampal neurons and brain membranes; labelled human/human in the curated row [PMID:35074912].","localisation_and_range":"MDGA1 is flagged not secreted; APP flagged secreted and transmembrane [flag]. Trans-synaptic contact (postsynaptic MDGA1, presynaptic APP) [PMID:35074912].","caveats":"Single paper. Overexpression of MDGA1 impaired novel object recognition in mice [PMID:35074912]. No database records.","key_references":[{"PMID":"35074912","why":"MDGA1 MAM-APP binding and trans-synaptic function"}],"covers":["LR002948","LR006173"]},"LR004472":{"pair":"MDK -> LRP1","headline":"LRP (LRP1) binds midkine with Kd 3.5 nM in mouse embryo membrane proteins; LRP is described as a component of a receptor complex.","interaction_type":"direct binding","direction_and_effect":"LRP was isolated by midkine-affinity chromatography; receptor-associated protein (RAP), which interfered with binding, inhibited MK-dependent survival of embryonic neurons [PMID:10772929].","molecular_requirements":"LRP is a component of the receptor complex for MK; NCAM was also in the fraction [PMID:10772929].","affinity_potency":[{"value":"Kd 3.5 nM","assay":"LRP-MK binding","system":"membrane glycoproteins from day 13 mouse embryos","cite":"PMID:10772929"}],"species_and_systems":"Day-13 mouse embryo material; curated ligand human, receptor mouse [PMID:10772929]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine.","caveats":"Single paper, abstract only; paper uses the name LRP. One review-only row was not used. BioGRID lists affinity capture-MS [DB:BioGRID].","key_references":[{"PMID":"10772929","why":"LRP-midkine Kd and RAP inhibition"}],"covers":["LR001059","LR004472"]},"LR002951":{"pair":"MFGE8 -> ITGA8","headline":"Human ITGA8-transfected cells adhere to MFGE8 in an antibody-blockable way; mouse in vivo role also reported; full text.","interaction_type":"direct binding","direction_and_effect":"alpha8-transfected human SW480 cells adhered to Mfge8, and adhesion was blocked by an alpha8 blocking antibody (YZ3) [PMID:27092791]. Ligation of alpha8beta1 by Mfge8 reduced antral smooth muscle contractile force by preventing RhoA activation via PTEN [PMID:27092791].","molecular_requirements":"alpha8 acts with beta1 as alpha8beta1; adhesion was assayed with anti-beta5 ALULA present to block endogenous receptors [PMID:27092791].","affinity_potency":[],"species_and_systems":"Human SW480 cell adhesion with solid-phase binding; mouse smooth muscle deletion and antibody blockade in vivo [PMID:27092791]. Human pair is ortholog-inferred; mouse pair is direct.","localisation_and_range":"Mfge8 is flagged secreted [flag]; the paper calls it a milk protein [PMID:27092791].","caveats":"Binding rests on cell adhesion and solid-phase assay, with no affinity. The excerpt cites earlier work for the YZ3 antibody [PMID:27092791].","key_references":[{"PMID":"27092791","why":"alpha8beta1-Mfge8 adhesion and PTEN/RhoA mechanism"}],"covers":["LR002951","LR006176"]},"LR004481":{"pair":"MFGE8 -> ITGAV","headline":"Functional evidence from two mouse studies shows MFGE8 acts through alphav integrins; abstract-level evidence only.","interaction_type":"functional only","direction_and_effect":"Lack of MFG-E8 eliminated alphavbeta5 downstream signalling (MerTK, peak photoreceptor outer segment phagocytosis) in mouse retina [PMID:17620600]. Mfge8 coordinated fatty acid uptake through alphavbeta3- and alphavbeta5-dependent Akt phosphorylation [PMID:24441829].","molecular_requirements":"alphav pairs with beta3 or beta5 in these studies [PMID:17620600, PMID:24441829].","affinity_potency":[],"species_and_systems":"Mouse knockouts, mouse retinal pigment epithelium and Mfge8-deficient mice on diet-induced obesity [PMID:17620600, PMID:24441829]. Human pair is also recorded in the dossier.","localisation_and_range":"Mfge8 is flagged secreted [flag]; the integrin ligand acts on cells in matrix/tissue contexts [PMID:24441829].","caveats":"Evidence is functional (knockout phenotype and signalling) and abstract-level; direct binding to alphav is not shown in these papers.","key_references":[{"PMID":"17620600","why":"Mfge8 loss abolishes alphavbeta5 signalling in RPE"},{"PMID":"24441829","why":"Mfge8 drives fatty acid uptake via alphavbeta3/beta5-Akt"}],"covers":["LR001068","LR004481"]},"LR006182":{"pair":"MIF -> ACKR3","headline":"MIF is reported as a novel direct ligand of atypical receptor ACKR3 (CXCR7) in one paper, with binding and B-cell functional data.","interaction_type":"direct binding","direction_and_effect":"MIF promoted human CXCR7 internalization up to 40% and acted as an agonist. CXCR7 blockade suppressed MIF-mediated ERK and ZAP-70 activation and fully abrogated primary murine B-cell chemotaxis to MIF but not to CXCL12; Cxcr7-/- B cells lost the MIF transmigration response [PMID:26139098].","molecular_requirements":"CXCR7 forms complexes with CXCR4 and CD74 for MIF, in overexpression and in a human B-cell line, but internalization did not depend on CXCR4 [PMID:26139098]. Whether CXCR7 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CXCR7 internalization and receptor complexes in human cells (including a B-cell line); chemotaxis in primary murine B cells and Cxcr7-/- mice. The mouse pair is inferred from human evidence [PMID:26139098].","localisation_and_range":"MIF carries a secreted flag [flag]; acts as a soluble chemokine-like ligand [PMID:26139098].","caveats":"Binding evidence is competition binding, co-IP and sulfo-SBED crosslinking, described only from the abstract; no affinity reported. Single paper [PMID:26139098].","key_references":[{"PMID":"26139098","why":"MIF engages CXCR7: internalization, direct interaction, B-cell chemotaxis"}],"covers":["LR002957","LR006182"]},"LR005246":{"pair":"MIF -> CXCR4","headline":"MIF activates CXCR4 functionally and competes with cognate ligands, but direct binding is shown only for CXCR2.","interaction_type":"functional only","direction_and_effect":"MIF triggers arrest, chemotaxis, integrin activation and calcium influx through CXCR4 (agonist) and competed with cognate ligands for CXCR4 binding [PMID:17435771].","molecular_requirements":"Not reported in our evidence for CXCR4 specifically; CXCR2 and CD74 form a complex in the same paper [PMID:17435771].","affinity_potency":[],"species_and_systems":"Human monocytes and T cells; mouse in vivo work. Mouse pair is ortholog-inferred [PMID:17435771].","localisation_and_range":"MIF carries a secreted flag [flag]; soluble ligand [PMID:17435771].","caveats":"The abstract states MIF directly bound CXCR2, not CXCR4; here support is competition and signalling. Abstract only, one paper, no affinity [PMID:17435771].","key_references":[{"PMID":"17435771","why":"MIF competes at and signals through CXCR4"}],"covers":["LR001906","LR005246"]},"LR002960":{"pair":"MMP14 -> FLT1","headline":"Protease-substrate binding: MMP14 binds and cleaves VEGFR1 (FLT1); two papers disagree on net pro- versus anti-angiogenic effect.","interaction_type":"conflicting","direction_and_effect":"Two papers report direct binding and cleavage but opposite functional readouts. In mouse, the 59.8-kDa N-terminal VEGFR1 cleavage fragment binds VEGF-A165 and inhibits VEGF-induced endothelial mitogenesis, acting as a VEGF trap (antagonist) [PMID:26284550]. In human, MMP14 increased VEGFA-induced ERK phosphorylation, and loss of vascular MMP14 in mice reduced VEGFA-induced corneal angiogenesis (agonist) [PMID:27327585].","molecular_requirements":"MMP14 acts on FLT1 as a protease; the catalytic domain alone was enough for cleavage, and GM6001 blocked it [PMID:27327585]. MMP14 did not bind or cleave VEGFR2 or VEGFR3 [PMID:27327585]. Cleavage products were about 70, 59.8 and 21 kDa [PMID:27327585].","affinity_potency":[{"value":"KD 2.59 \u00d7 10\u22129 M","assay":"surface plasmon resonance, MMP14 over immobilised rhVEGFR1","system":"recombinant human proteins","cite":"PMID:27327585"}],"species_and_systems":"Mouse recombinant VEGFR1 with recombinant MMP14 and cell proliferation assays [PMID:26284550]. Human recombinant proteins, HUVEC co-immunoprecipitation, and conditional vascular MMP14-deletion mice (aortic ring and corneal micropocket) [PMID:27327585].","localisation_and_range":"MMP14 is not annotated as secreted in the entity flags [flag]. The interaction is proteolytic, so membrane-proximal contact is implied; this is not a classical signalling ligand.","caveats":"This is a protease-substrate relationship, not a signalling ligand-receptor pair. The two papers draw opposite conclusions on net effect. The 2015 paper was read as abstract only [PMID:26284550]; the 2016 curator row was also read as abstract only, but full-text excerpts are available [PMID:27327585].","key_references":[{"PMID":"27327585","why":"Human proteins: selective binding (SPR, co-IP), cleavage, pro-angiogenic effect"},{"PMID":"26284550","why":"Mouse VEGFR1 cleavage fragment acts as VEGF trap"}],"covers":["LR002960","LR006185"]},"LR004490":{"pair":"MMP9 -> LRP1","headline":"MMP-9 (as the MMP-9/TIMP-1 complex) binds LRP, which internalises and degrades it; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"In vitro, the MMP-9.TIMP-1 complex bound LRP with high affinity and the binding determinant appears to reside on MMP-9 [PMID:11279011]. LRP-expressing cells internalised 125I-MMP-9.TIMP-1, while LRP-deficient lines did so poorly, so LRP is a clearance receptor [PMID:11279011].","molecular_requirements":"The species bound was the MMP-9.TIMP-1 complex [PMID:11279011]. Whether free MMP-9 binds is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human MMP-9 with mouse embryonic fibroblasts (mouse LRP) [PMID:11279011]. The mouse pair is not ortholog-inferred in the dossier.","localisation_and_range":"MMP9 is flagged as secreted [flag]; LRP mediates uptake from the extracellular space [PMID:11279011].","caveats":"The affinity is called high but no value is given in the abstract. Abstract only. LRP1 is a scavenger, not a signalling receptor.","key_references":[{"PMID":"11279011","why":"MMP-9/TIMP-1 binding to LRP and LRP-mediated catabolism"}],"covers":["LR001078","LR004490"]},"LR001907":{"pair":"MMRN2 -> CD248","headline":"MMRN2 directly binds CD248 at a region distinct from the CLEC14A/CD93 site; one paper, with a data caveat in the full text.","interaction_type":"direct binding","direction_and_effect":"CD248 directly binds MMRN2; thrombomodulin does not [PMID:28671670]. CD248 binds a distinct, non-competing MMRN2 region, so CLEC14A and CD248 can bind MMRN2 simultaneously, seen at the endothelium-pericyte interface in human pancreatic cancer [PMID:28671670]. UniProt lists the interaction [DB:UniProt].","molecular_requirements":"Binding depends on a predicted long-loop region of the C-type lectin domain [PMID:28671670]. A CD248 chimera in CLEC14A bound MMRN2FL in far western blotting [PMID:28671670].","affinity_potency":[],"species_and_systems":"Human proteins; HEK293T lysates and human pancreatic cancer tissue [PMID:28671670]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMRN2 is a secreted extracellular matrix protein [flag][PMID:28671670]; CD248 is a transmembrane receptor on fibroblasts and pericytes [flag][PMID:28671670].","caveats":"The CD248-GFP fusion was most likely misfolded, so whole-protein binding could not be shown in that experiment; support came from CTLD chimeras [PMID:28671670]. Abstract read only.","key_references":[{"PMID":"28671670","why":"MMRN2 binding to CLEC14A, CD93 and CD248"}],"covers":["LR001907","LR005247"]},"LR006191":{"pair":"MPZ -> MPZ","headline":"Homophilic MPZ Ig-domain oligomerisation shown by structural methods; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Self-association between myelin membranes; the IgMPZ extracellular domain oligomerises and holds apposing myelin membranes together [PMID:37542466].","molecular_requirements":"NMR and SAXS confirm the tetramerisation interface; dimerisation uses a distinct interface not yet identified [PMID:37542466].","affinity_potency":[],"species_and_systems":"Solution NMR/SAXS of human-labelled IgMPZ; the mouse pair is ortholog-inferred. Prior crystal model was from rat protein [PMID:37542466].","localisation_and_range":"Membrane-bound adhesion protein (not secreted) [flag]; acts by contact across myelin membranes [PMID:37542466].","caveats":"Abstract only. Structural oligomerisation, not signalling; whether it acts as a ligand-receptor pair in the signalling sense is not reported in our evidence.","key_references":[{"PMID":"37542466","why":"Structural analysis of MPZ homomeric interfaces"}],"covers":["LR002966","LR006191"]},"LR001079":{"pair":"MST1 -> MST1R","headline":"MSP binds and activates RON; well supported by binding, functional and structural records.","interaction_type":"direct binding","direction_and_effect":"MSP binds RON and induces its autophosphorylation, increasing ciliary beat frequency [PMID:9045873]. MSP induces tyrosine phosphorylation of p185RON; HGF does not activate RON and MSP does not activate the HGF receptor [PMID:8062829].","molecular_requirements":"RON is a disulfide-linked alpha/beta heterodimer (p185RON) at the cell surface; a recombinant protein with only MSP's N-terminal two kringles also activates it [PMID:8062829].","affinity_potency":[{"value":"Kd = 0.5 nM","assay":"binding to RON","system":"normal human bronchial epithelial cells","cite":"PMID:9045873"}],"species_and_systems":"Human cells and tissue (bronchial epithelium, nasal cilia) [PMID:9045873]; mouse pair is ortholog-inferred.","localisation_and_range":"MSP is secreted [flag] and found in the bronchoalveolar space; RON sits on the apical surface of ciliated epithelia [PMID:9045873].","caveats":"Both papers read as abstracts only. Records also include PDB 4QT8, IntAct SPR and Reactome [DB:PDB 4QT8][DB:IntAct]. GtoPdb lists no type or action [DB:GtoPdb].","key_references":[{"PMID":"9045873","why":"Kd 0.5 nM binding and ciliary function"},{"PMID":"8062829","why":"Identifies MSP as RON activator"}],"covers":["LR001079","LR004491"]},"LR001088":{"pair":"NCAM1 -> FGFR2","headline":"Weak support: FGFR2beta/Fc bound NK-92 cells, but CD56-specific confirmation was done only for FGFR1.","interaction_type":"functional only","direction_and_effect":"FGFR2 beta/Fc chimera bound CD56-expressing NK-92 cells in flow cytometry and cell adhesion assays [PMID:12121226].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NK-92 cells with recombinant FGFR2 beta/Fc; mouse pair is ortholog-inferred [PMID:12121226].","localisation_and_range":"NCAM flagged secreted/transmembrane [flag]; cell-surface binding on NK-92 cells [PMID:12121226].","caveats":"Abstract only. Binding is to whole cells, not to purified CD56; immunoprecipitation and the IL-2 costimulation were shown for FGFR1 only. No database records.","key_references":[{"PMID":"12121226","why":"FGFR1/FGFR2 chimeras bind NK-92 cells; CD56 confirmation for FGFR1 only"}],"covers":["LR001088","LR004499"]},"LR001916":{"pair":"NECTIN1 -> CD96","headline":"Nectin-1 binds CD96: direct in vitro for human, and murine CD96 binds nectin-1, with lower affinity than CD155.","interaction_type":"direct binding","direction_and_effect":"Human nectin-1 directly interacts with CD96 in vitro, by ELISA and SPR; nectin-1 overexpression in K562 cells increased NK-92 cytotoxicity [PMID:30759143]. Murine CD96 also binds nectin-1 [PMID:17971293]. The effect of the mouse interaction is not determined [PMID:30759143].","molecular_requirements":"The CD96 binding site lies on the nectin-1 V-domain [PMID:30759143].","affinity_potency":[],"species_and_systems":"Recombinant human CD96 and nectin-1 by SPR and ELISA, K562 and NK-92 cells [PMID:30759143]; mouse binding in 2007 [PMID:17971293].","localisation_and_range":"Nectin-1 is a membrane adhesion molecule flagged secreted [flag]; interaction is contact-mediated.","caveats":"Affinity of nectin-1 for CD96 is lower than for CD155, and lower than for nectin-3 and nectin-1 itself; numbers are not shown in our evidence [PMID:30759143]. On thymocytes mCD155 is the only available mCD96 receptor [PMID:17971293]. Both read as abstracts, 30759143 with excerpts.","key_references":[{"PMID":"30759143","why":"Direct SPR binding of human nectin-1 and CD96"},{"PMID":"17971293","why":"Murine CD96 binds nectin-1"}],"covers":["LR001916","LR005255"]},"LR005255":{"pair":"NECTIN1 -> CD96","headline":"Nectin-1 binds CD96: direct in vitro for human, and murine CD96 binds nectin-1, with lower affinity than CD155.","interaction_type":"direct binding","direction_and_effect":"Human nectin-1 directly interacts with CD96 in vitro, by ELISA and SPR; nectin-1 overexpression in K562 cells increased NK-92 cytotoxicity [PMID:30759143]. Murine CD96 also binds nectin-1 [PMID:17971293]. The effect of the mouse interaction is not determined [PMID:30759143].","molecular_requirements":"The CD96 binding site lies on the nectin-1 V-domain [PMID:30759143].","affinity_potency":[],"species_and_systems":"Recombinant human CD96 and nectin-1 by SPR and ELISA, K562 and NK-92 cells [PMID:30759143]; mouse binding in 2007 [PMID:17971293].","localisation_and_range":"Nectin-1 is a membrane adhesion molecule flagged secreted [flag]; interaction is contact-mediated.","caveats":"Affinity of nectin-1 for CD96 is lower than for CD155, and lower than for nectin-3 and nectin-1 itself; numbers are not shown in our evidence [PMID:30759143]. On thymocytes mCD155 is the only available mCD96 receptor [PMID:17971293]. Both read as abstracts, 30759143 with excerpts.","key_references":[{"PMID":"30759143","why":"Direct SPR binding of human nectin-1 and CD96"},{"PMID":"17971293","why":"Murine CD96 binds nectin-1"}],"covers":["LR001916","LR005255"]},"LR006209":{"pair":"NECTIN3 -> NECTIN1","headline":"Direct trans-interaction with measured 1 nM Kd in human nectins; adhesion pair rather than classic signalling.","interaction_type":"direct binding","direction_and_effect":"Nectin1 and nectin3 trans-interact heterophilically; the interaction is mediated by V-to-V domain contacts, and nectin3 and HSV-1 glycoprotein D compete for the shared site [PMID:12011057]. Direction and signalling effect are not reported in our evidence.","molecular_requirements":"The nectin1 V domain is the major region for trans-heterointeraction with nectin3 [PMID:11544254]; C domains raise affinity [PMID:12011057].","affinity_potency":[{"value":"KD 1 nM","assay":"nectin1/nectin3 trans-interaction affinity","system":"recombinant human nectin ectodomains","cite":"PMID:12011057"}],"species_and_systems":"Human proteins per curator fields; mouse pair is ortholog-projected.","localisation_and_range":"Membrane-bound trans adhesion (cell junction) [DB:Reactome]; nectin1 carries a secreted flag [flag].","caveats":"Abstract only. PMID 11544254 reports it as confirmation of earlier work rather than new data. Nectin1 homophilic KD is 1 microm [PMID:12011057].","key_references":[{"PMID":"12011057","why":"KD of nectin1/nectin3 is 1 nM"},{"PMID":"11544254","why":"Confirms nectin3/nectin1 trans-heterointeraction"}],"covers":["LR002984","LR006209"]},"LR001925":{"pair":"NECTIN4 -> TIGIT","headline":"Nectin4 is a TIGIT-selective ligand that inhibits NK activity; binding and function shown in human systems.","interaction_type":"direct binding","direction_and_effect":"Nectin4 overexpression increased binding of TIGIT-Ig alone, not DNAM1-Ig, CD112R-Ig or CD96-Ig; TIGIT-Nectin4 interaction inhibits NK-cell activity and a Nectin4-blocking antibody enhanced NK killing in vitro and in vivo [PMID:32503945]. TIGIT recognizes the membrane-distal ectodomain of nectin-4 by SPR [PMID:37542773].","molecular_requirements":"Single receptor TIGIT; structure-guided mutagenesis mapped the nectin-4 interface on TIGIT [PMID:37542773]. Nectin4 does not bind DNAM1, CD96 or CD112R [PMID:32503945].","affinity_potency":[],"species_and_systems":"Human NK cells, Raji transfectants, MST and reporter assays [PMID:32503945]; mouse pair is ortholog-projected. The in vivo model is not described in our evidence.","localisation_and_range":"Nectin4 has a secreted flag [flag]; papers describe a cell-surface ligand on tumour cells [PMID:32503945].","caveats":"Abstracts only for curator fields. Affinity described as relatively high, similar to PVR-TIGIT, and weaker than nectin-2 in the other, with no values in the dossier [PMID:32503945] [PMID:37542773]. UniProt lists it [DB:UniProt].","key_references":[{"PMID":"32503945","why":"Discovery of Nectin4 as selective TIGIT ligand"},{"PMID":"37542773","why":"SPR and mutagenesis of TIGIT-nectin-4"}],"covers":["LR001925","LR005264"]},"LR005264":{"pair":"NECTIN4 -> TIGIT","headline":"Nectin4 is a TIGIT-selective ligand that inhibits NK activity; binding and function shown in human systems.","interaction_type":"direct binding","direction_and_effect":"Nectin4 overexpression increased binding of TIGIT-Ig alone, not DNAM1-Ig, CD112R-Ig or CD96-Ig; TIGIT-Nectin4 interaction inhibits NK-cell activity and a Nectin4-blocking antibody enhanced NK killing in vitro and in vivo [PMID:32503945]. TIGIT recognizes the membrane-distal ectodomain of nectin-4 by SPR [PMID:37542773].","molecular_requirements":"Single receptor TIGIT; structure-guided mutagenesis mapped the nectin-4 interface on TIGIT [PMID:37542773]. Nectin4 does not bind DNAM1, CD96 or CD112R [PMID:32503945].","affinity_potency":[],"species_and_systems":"Human NK cells, Raji transfectants, MST and reporter assays [PMID:32503945]; mouse pair is ortholog-projected. The in vivo model is not described in our evidence.","localisation_and_range":"Nectin4 has a secreted flag [flag]; papers describe a cell-surface ligand on tumour cells [PMID:32503945].","caveats":"Abstracts only for curator fields. Affinity described as relatively high, similar to PVR-TIGIT, and weaker than nectin-2 in the other, with no values in the dossier [PMID:32503945] [PMID:37542773]. UniProt lists it [DB:UniProt].","key_references":[{"PMID":"32503945","why":"Discovery of Nectin4 as selective TIGIT ligand"},{"PMID":"37542773","why":"SPR and mutagenesis of TIGIT-nectin-4"}],"covers":["LR001925","LR005264"]},"LR001097":{"pair":"NID1 -> ITGAV","headline":"Entactin RGD site is recognised by integrin alphaVbeta3 in cell attachment assays; two abstract-level papers.","interaction_type":"functional only","direction_and_effect":"The RGD sequence is a major cell attachment site in entactin recognised by alpha v beta 3 [PMID:7797588]. Human mesangial cells use both alpha v beta 3 and a beta 1-containing integrin to bind native entactin [PMID:9686320]. Both are labelled agonist by the curator.","molecular_requirements":"The alphaVbeta3 site was localised to the RGD sequence in the rod/E domain [PMID:9686320]; a second, RGD-independent site is recognised by a beta 1 integrin [PMID:7797588]. The alphaV chain partners with beta3 here.","affinity_potency":[],"species_and_systems":"Cell attachment assays with recombinant mutant entactin; the curator records human for both papers, which used cultured human kidney mesangial cells in the 1998 paper [PMID:9686320]; abstracts only [PMID:7797588]. Human pair is listed and mouse pair is ortholog-inferred.","localisation_and_range":"Entactin is a basement-membrane glycoprotein; NID1 is annotated secreted [flag].","caveats":"Cell attachment and antibody inhibition show functional recognition rather than purified binding. A fourth paper was abstract-insufficient.","key_references":[{"PMID":"7797588","why":"RGD deletion mutants show alpha v beta 3 recognition of entactin"},{"PMID":"9686320","why":"RGD site binds alpha v beta 3 in mesangial cells"}],"covers":["LR001097","LR004508"]},"LR004508":{"pair":"NID1 -> ITGAV","headline":"Entactin RGD site is recognised by integrin alphaVbeta3 in cell attachment assays; two abstract-level papers.","interaction_type":"functional only","direction_and_effect":"The RGD sequence is a major cell attachment site in entactin recognised by alpha v beta 3 [PMID:7797588]. Human mesangial cells use both alpha v beta 3 and a beta 1-containing integrin to bind native entactin [PMID:9686320]. Both are labelled agonist by the curator.","molecular_requirements":"The alphaVbeta3 site was localised to the RGD sequence in the rod/E domain [PMID:9686320]; a second, RGD-independent site is recognised by a beta 1 integrin [PMID:7797588]. The alphaV chain partners with beta3 here.","affinity_potency":[],"species_and_systems":"Cell attachment assays with recombinant mutant entactin; the curator records human for both papers, which used cultured human kidney mesangial cells in the 1998 paper [PMID:9686320]; abstracts only [PMID:7797588]. Human pair is listed and mouse pair is ortholog-inferred.","localisation_and_range":"Entactin is a basement-membrane glycoprotein; NID1 is annotated secreted [flag].","caveats":"Cell attachment and antibody inhibition show functional recognition rather than purified binding. A fourth paper was abstract-insufficient.","key_references":[{"PMID":"7797588","why":"RGD deletion mutants show alpha v beta 3 recognition of entactin"},{"PMID":"9686320","why":"RGD site binds alpha v beta 3 in mesangial cells"}],"covers":["LR001097","LR004508"]},"LR004517":{"pair":"NLGN2 -> NRXN2","headline":"Supported by a general neurexin-binding paper and a mutation study; NRXN2-specific binding not individually shown.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind beta-neurexins [PMID:8576240]. A truncated NRXN2 protein from an ASD patient failed to bind NLGN2 in cell binding assays and to promote synaptic differentiation [PMID:21424692].","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Human cell binding and neuron coculture (curator: human) [PMID:21424692]; species unspecified for 8576240. Mouse pair is not ortholog-inferred; the human pair is.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Abstract only. The mutation paper's evidence is loss-of-binding in a truncated protein, not wild-type NRXN2 binding. 8576240 speaks of beta-neurexins as a class. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to beta-neurexins"},{"PMID":"21424692","why":"Truncated NRXN2 fails to bind NLGN2"}],"covers":["LR001106","LR004517"]},"LR004526":{"pair":"NMU -> NMUR1","headline":"Strongly supported direct agonist-receptor pair: radioligand binding, calcium and signalling assays in recombinant human cells, and Reactome, BioGRID, GtoPdb and PDB records.","interaction_type":"direct binding","direction_and_effect":"NMU is an agonist of NMU1R; it raises intracellular Ca2+ and inositol phosphate and inhibits forskolin-stimulated cAMP in HEK-293 cells [PMID:15292653]. The receptor couples to Galpha(q/11) and Galpha(i) [PMID:15331768]. NMU potently activates FM3 with subnanomolar potency, while neuromedins B, C, K and N are inactive [PMID:10811630].","molecular_requirements":"Single receptor chain is sufficient in recombinant cells; no co-receptor reported. Binding to the receptor is described as essentially irreversible, followed by internalisation [PMID:15331768].","affinity_potency":[{"value":"EC50 0.50 nM","assay":"intracellular Ca2+ release (stated in abstract for NmU isopeptides)","system":"human NmU1R/NmU2R in HEK-293 cells","cite":"PMID:15292653"},{"value":"EC50 1.6 nM","assay":"inositol phosphate formation","system":"human recombinant receptor in HEK-293 cells","cite":"PMID:15292653"}],"species_and_systems":"Human recombinant receptors in HEK-293 cells [PMID:15292653][PMID:15331768]; transient FM3 in HEK-293 [PMID:10811630]; endogenous receptors in isolated rat smooth muscle cells [PMID:15331768]. The mouse pair is inferred from human by orthology.","localisation_and_range":"NMU is flagged secreted and the receptor transmembrane [flag]; the papers do not address range.","caveats":"Almost all papers were read as abstracts only. PMID:10899166 does not state species. PMID:10894543 names no specific binding assay or affinity.","key_references":[{"PMID":"10811630","why":"NMU potently activates FM3 (NMUR1) in HEK-293 cells; other neuromedins inactive"},{"PMID":"15292653","why":"Radioligand binding and signalling of both human receptors"},{"PMID":"15331768","why":"G protein coupling and near-irreversible binding"}],"covers":["LR001115","LR004526"]},"LR007370":{"pair":"NODAL -> ACVR1C:ACVR2B:CFC1","headline":"Only the ACVR1C (ALK7) chain is evidenced; type II chain and CFC1 co-receptor are not shown.","interaction_type":"functional only","direction_and_effect":"ALK7 is a type I receptor for Nodal; Nodal overexpression decreases trophoblast cell number and induces apoptosis, mimicked by constitutively active ALK7 and blocked by kinase-deficient ALK7 and dominant-negative Smad2/3 [PMID:15150278].","molecular_requirements":"Only ACVR1C is addressed; ACVR2B and CFC1 are not named in the abstract [PMID:15150278].","affinity_potency":[],"species_and_systems":"Human trophoblast cells (HTR8/SVneo) and choriocarcinoma cell lines [PMID:15150278].","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"Abstract only; one other paper review-only; BioGRID lists NODAL-ACVR2B [DB:BioGRID]. CFC1 requirement is not supported by our evidence.","key_references":[{"PMID":"15150278","why":"ALK7 mediates Nodal growth inhibition and apoptosis in trophoblasts"}],"covers":["LR007370"]},"LR006218":{"pair":"NODAL -> BMPR2","headline":"Nodal is reported as a high-affinity BMPR2 growth factor in a human in vitro binding survey; no Nodal-specific structure.","interaction_type":"direct binding","direction_and_effect":"Among growth factors tested, the high-affinity BMPR2 ones comprise BMP15, BMP10 and Nodal; effect is agonist as curated [PMID:35643319]. BMPR2 is a type II receptor [PMID:35643319].","molecular_requirements":"BMPR2 binds growth factors at a conserved hydrophobic hot spot, via the ligand knuckle epitope; type I chain requirements for Nodal are not reported in our evidence [PMID:35643319].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, in vitro binding; the crystal structures in the paper are of BMPR2 with activin B and ACVR2A with activin A, not Nodal [PMID:35643319]. Mouse pair is ortholog-inferred.","localisation_and_range":"Nodal is flagged secreted [flag].","caveats":"The Nodal result is one of 14 ligand-receptor combinations; the excerpts shown give no Nodal Kd or assay detail. Full text read, but Nodal-specific numbers are not in the excerpts.","key_references":[{"PMID":"35643319","why":"BMPR2 and ACVR2A growth factor recognition; Nodal among high-affinity BMPR2 ligands"}],"covers":["LR002994","LR006218"]},"LR008414":{"pair":"NOTCH1 -> JAG1","headline":"JAG1 binds and activates NOTCH1: direct Ca2+-dependent binding in human proteins and agonist activity in rat cells; row is stored reversed.","interaction_type":"direct binding","direction_and_effect":"JAG1 is the ligand and NOTCH1 the receptor, though the row is stored reversed. Jagged activated rat Notch1 expressed in myoblasts and blocked muscle differentiation [PMID:7697721]; DSL proteins directly bound soluble Notch1 [PMID:11006133].","molecular_requirements":"Binding is Ca2+-dependent [PMID:11006133]. Complex stoichiometry not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human soluble Notch ectodomain fusions in cell-binding and solid-phase assays [PMID:11006133]; rat cDNA, rat Notch1 in myoblasts [PMID:7697721]. Both abstract only.","localisation_and_range":"JAG1 flagged transmembrane and non-secreted [flag], so signalling is juxtacrine/contact; the binding assays used cell-surface DSL proteins [PMID:11006133].","caveats":"Affinity not quantified in the abstract. The Jagged paper is mostly sequence and expression plus a cell assay [PMID:7697721]. Database records (BioGRID, IntAct, Reactome) agree [DB:Reactome R-HSA-157008].","key_references":[{"PMID":"11006133","why":"Direct Ca2+-dependent binding of Jagged1 to Notch1 ectodomain"},{"PMID":"7697721","why":"Jagged activates Notch1 in cell culture"}],"covers":["LR008414"]},"LR008441":{"pair":"NOTCH4 -> DLL4","headline":"DLL4 is described as a Notch4 ligand only as background in a paper about its effect on VEGF signalling.","interaction_type":"functional only","direction_and_effect":"The paper states Dll4 is a membrane-bound ligand for Notch1 and Notch4; its own results show Dll4 overexpression reduced VEGF-A responses, induced HEY2, and a gamma-secretase inhibitor reversed effects, so signalling goes through Notch generally [PMID:16219802].","molecular_requirements":"Notch4 specifically is not tested in the abstract [PMID:16219802].","affinity_potency":[],"species_and_systems":"Primary human endothelial cells (HUVEC) retrovirally overexpressing Dll4; abstract only [PMID:16219802].","localisation_and_range":"Dll4 is described as membrane-bound [PMID:16219802].","caveats":"The Notch4-DLL4 claim is background, not this paper's result. Reactome lists a DLL4:NOTCH4 complex [DB:Reactome R-HSA-2105041]. Row is reversed (NOTCH4 as ligand).","key_references":[{"PMID":"16219802","why":"Dll4 overexpression in endothelial cells; Notch ligand function"}],"covers":["LR008441"]},"LR010952":{"pair":"NOTUM -> WNT7A","headline":"Only a Notum crystal structure record supports this; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Interaction is annotated Inhibitory [flag]; Notum is described in PDB as a Wnt deacylase [DB:PDB 4UZQ, PMID:25731175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"The PDB entry 4UZQ is Notum with O-palmitoleoyl serine, not with WNT7A; the one paper judged was rated a different entity. Effectively unsupported for WNT7A.","key_references":[],"covers":["LR010952"]},"LR004535":{"pair":"NPFF -> NPFFR2","headline":"NPFF binds and activates NPFFR2 with sub-nanomolar to nanomolar affinity in recombinant cells; well supported by binding papers.","interaction_type":"direct binding","direction_and_effect":"NPFF is an agonist: cells expressing the receptor bind and respond in a concentration-dependent manner [PMID:10851242]; NPFF activated the receptor in several heterologous systems [PMID:11024015]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor-only; no co-receptor requirement reported in our evidence. A short NPGPR isoform lacking exon 2 is described [PMID:12609745].","affinity_potency":[{"value":"Kd 0.37 nM","assay":"specific NPFF binding to cloned receptor","system":"human/rat NPFF2 receptor, heterologous expression","cite":"PMID:11024015"},{"value":"IC50 14.7 nM","assay":"[125I]NPFF displaced by NPFF","system":"cloned full-length human NPGPR","cite":"PMID:12609745"}],"species_and_systems":"Human cloned receptors in cells [PMID:10851242]; human/rat receptors [PMID:11024015]. Mouse pair is projected from human evidence. All papers read as abstracts only.","localisation_and_range":"NPFF is annotated secreted and NPFFR2 transmembrane [flag]; PMID:11024015 reports receptor mRNA and binding sites in spinal dorsal horn and thalamic nuclei.","caveats":"All four papers were read as abstracts only. The full-length NPGPR showed an IC50 about 100-fold weaker than for the shorter NPFF2 form [PMID:12609745]. NPFF is also reported to bind NPFF1 (Kd 1.13 nM) [PMID:11024015], so paralog cross-activity exists. FMRF-amide and related peptides weakly activate the receptor [PMID:10851242].","key_references":[{"PMID":"11024015","why":"Kd for NPFF at NPFF2 with activation in several systems"},{"PMID":"10851242","why":"Cloned human receptor binds and responds to NPFF"},{"PMID":"12609745","why":"Binding of NPFF to full-length NPGPR and isoform"}],"covers":["LR001125","LR004535"]},"LR004544":{"pair":"NPPC -> NPR3","headline":"CNP binds the NPR3 clearance receptor, shown by a crystal structure of the human complex.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of human NPR-C with CNP shows one CNP bound in the dimer interface, with a 20 angstrom closure of the membrane-proximal domains [PMID:11533490]. UniProt says it binds the clearance receptor [DB:UniProt]; PDB 1JDP [DB:PDB 1JDP].","molecular_requirements":"NPR-C functions as a dimer binding a single CNP [PMID:11533490]. The receptor lacks guanylyl cyclase activity per curator note.","affinity_potency":[],"species_and_systems":"Human NPR-C extracellular domain, structure at 2.0 angstroms (complex) [PMID:11533490]; human, bovine, rat preparations [PMID:1309330]. Mouse pair is projected.","localisation_and_range":"CNP annotated secreted [flag].","caveats":"Both papers abstract-only; PMID:1309330 gives a C-receptor affinity rank of ANP greater than CNP greater than BNP, so CNP is not the preferred ligand. Clearance receptor: binding not shown to signal.","key_references":[{"PMID":"11533490","why":"Structure of NPR-C with CNP"},{"PMID":"1309330","why":"Rank order of C-receptor binding"}],"covers":["LR001134","LR004544"]},"LR011906":{"pair":"NPY -> NPY4R2","headline":"Pair rests only on an HGNC receptor name containing 'neuropeptide Y'; no experimental or database evidence.","interaction_type":"database-asserted only","direction_and_effect":"No papers or binding records. The only support is the HGNC name 'neuropeptide Y receptor Y4-2' [DB:HGNC approved name]; the dossier marks a stimulatory effect without evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"A name match only; no binding or functional evidence, and the entity has no annotation flags. Treat as unverified.","key_references":[],"covers":["LR011906"]},"LR004553":{"pair":"NPY -> NPY5R","headline":"NPY is a high-affinity agonist of NPY5R according to one cloning paper plus a family reference; abstract level.","interaction_type":"direct binding","direction_and_effect":"Rat and human Y5 have high affinity for feeding-eliciting peptides such as NPY and low affinity for non-stimulating ones [PMID:8824284]; NPY shows highest affinities at Y1, Y2 and Y5 [PMID:15966750]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor reported.","affinity_potency":[{"value":"pKi 9.1","assay":"curator-recorded affinity from cloning paper","system":"human Y5","cite":"PMID:8824284"}],"species_and_systems":"Receptor cloned from a rat hypothalamus library, human homologue at 88% identity; pharmacology on rat and human Y5 [PMID:8824284]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY5R transmembrane [flag].","caveats":"Both papers are abstract only. The pKi is curator-recorded and not in the abstract. The chimera paper gives only a qualitative statement [PMID:15966750].","key_references":[{"PMID":"8824284","why":"Cloning of Y5 and its NPY pharmacology"},{"PMID":"15966750","why":"NPY highest affinities at Y1/Y2/Y5"}],"covers":["LR001144","LR004553"]},"LR006227":{"pair":"NRCAM -> NFASC","headline":"NRCAM binds neurofascin on axons in one abstract-level coculture paper, plus a Reactome heterodimer record.","interaction_type":"direct binding","direction_and_effect":"An Nr-CAM-Fc fusion bound directly to neurons and clustered and coprecipitated neurofascin on axons; it inhibited Na+ channel and ankyrin G accumulation at the node [PMID:11728309]. Reactome lists an NFASC:NRCAM complex [DB:Reactome R-HSA-373686].","molecular_requirements":"Not reported in our evidence beyond the two partners; which neurofascin isoform is needed is not stated.","affinity_potency":[],"species_and_systems":"DRG neuron-Schwann cell cocultures with an Nr-CAM-Fc fusion; species not stated in the dossier [PMID:11728309]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Membrane-bound cell adhesion molecules on the axon surface (abstract) [PMID:11728309]; NFASC is flagged not secreted [flag]. Juxtacrine/contact signalling.","caveats":"One paper, abstract only; the Fc fusion is a recombinant reagent and the paper frames the interaction as 'possibly' relevant. The Reactome record cites an older paper [DB:Reactome R-HSA-373730]. Ligand-receptor direction is arbitrary for a homophilic-type adhesion pair.","key_references":[{"PMID":"11728309","why":"Nr-CAM-Fc binds and coprecipitates neurofascin on axons"}],"covers":["LR003003","LR006227"]},"LR006236":{"pair":"NRP1 -> NRP1","headline":"NRP1 interacting with NRP1 rests on one abstract-level biosensor paper; homotypic binding is lightly evidenced.","interaction_type":"direct binding","direction_and_effect":"Npn-1 interacts with Npn-1 immobilized on an optical biosensor surface, alongside FGFs and HGF/SF [PMID:15695515]. Effect for this pair is not reported.","molecular_requirements":"Interactions were ionic-strength dependent and heparin-inhibited, suggesting a heparin-mimetic site [PMID:15695515]. BioGRID has a two-hybrid record and IntAct a coimmunoprecipitation record [DB:BioGRID][DB:IntAct].","affinity_potency":[],"species_and_systems":"Optical biosensor, recombinant proteins; species not stated beyond human; human cells used for the FGF-2 potentiation assay [PMID:15695515]. Mouse pair is projected from human.","localisation_and_range":"NRP1 is flagged secreted, receptor and transmembrane [flag].","caveats":"Single paper, abstract only; the NRP1 self-interaction is one item in a list, with no kinetics given for it. Biological relevance and direction not shown; this is homo-oligomerization rather than ligand-receptor signalling.","key_references":[{"PMID":"15695515","why":"Biosensor shows Npn-1 binding to immobilized Npn-1"}],"covers":["LR003012","LR006236"]},"LR004562":{"pair":"NRTN -> GFRA1","headline":"NRTN binds GFRA1 in several 1997-1998 papers, with lower efficiency than GDNF in one.","interaction_type":"direct binding","direction_and_effect":"Neurturin binds either GFRalpha-1 or GFRalpha-2, and both mediate neurturin-induced Ret phosphorylation [PMID:9407096]. NTN bound GFRa1-Fc with similar affinity to GDNF [PMID:9883723].","molecular_requirements":"Ret was used with GFRa1 for signalling; TrnR1-Ret cells responded equivalently to NTN and GDNF [PMID:9182803]. Cells expressing GFRalpha-1 bind GDNF more efficiently than neurturin [PMID:9407096].","affinity_potency":[],"species_and_systems":"Human receptors in transfected cells [PMID:9182803]; Fc-body binding assay [PMID:9883723]; mouse pair is projected from human.","localisation_and_range":"NRTN is annotated secreted, not transmembrane [flag]; GFRA1 is GPI-anchored in the GDNF family [PMID:9182803].","caveats":"Two papers read as abstract only. One row for PMID 9883723 was pair_absent from the abstract alone, but full text reports binding [PMID:9883723]. GFRalpha-1 is the primary GDNF receptor, so NRTN is secondary here [PMID:9407096]. No affinity numbers in our evidence.","key_references":[{"PMID":"9407096","why":"NTN binds GFRalpha-1 or GFRalpha-2"},{"PMID":"9883723","why":"NTN and GDNF bind GFRa1-Fc with similar affinity"},{"PMID":"9182803","why":"TrnR1-Ret responds equivalently to NTN and GDNF"}],"covers":["LR001153","LR004562"]},"LR006245":{"pair":"NRXN1 -> LRRTM4","headline":"Well supported: three papers show direct binding of neurexin-1 forms to LRRTM4, including SS4-independent and heparan sulfate-dependent aspects.","interaction_type":"direct binding","direction_and_effect":"Immobilised Ig-neurexin-1beta captured all LRRTM isoforms (LRRTM1-4) from HEK293 cells [PMID:20064387]. LRRTM4-Fc bound Nrx1beta with or without S4 in a cell-free co-precipitation [PMID:23911103]. Nrx1gamma was identified as a synapse organizer with LRRTM4 as its postsynaptic ligand [PMID:31995730].","molecular_requirements":"Unlike LRRTM2, LRRTM4 binds neurexin-1beta independent of SS4 [PMID:23911103]. LRRTMs require the heparan sulfate modification of neurexin to induce presynaptic differentiation, and binding to the HS is sufficient for LRRTM3 and LRRTM4 [PMID:31995730].","affinity_potency":[],"species_and_systems":"Recombinant proteins in HEK293 and cell-free assays; species unspecified in curation. Human pair is ortholog-inferred.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"Glypican is a major LRRTM4 partner and few neurexin spectra were seen in LRRTM4 affinity chromatography [PMID:23911103]. 31995730 read as abstract only.","key_references":[{"PMID":"23911103","why":"LRRTM4-Fc binds Nrx1beta with or without S4"},{"PMID":"20064387","why":"Ig-neurexin-1beta pull-down of LRRTM1-4"},{"PMID":"31995730","why":"Nrx1gamma/LRRTM4 and HS-dependent organizer function"}],"covers":["LR003021","LR006245"]},"LR008522":{"pair":"NRXN2 -> NLGN1","headline":"Supported only by database records (BioGRID, UniProt); no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID]; UniProt says NLGN1 interacts with neurexins NRXN1, NRXN2 and NRXN3 (by similarity) [DB:UniProt].","localisation_and_range":"Both partners are flagged transmembrane, non-secreted [flag], suggesting contact-mediated signalling.","caveats":"No papers have been judged (three pending). The UniProt statement is by similarity only [DB:UniProt].","key_references":[],"covers":["LR008522"]},"LR006254":{"pair":"NRXN3 -> DAG1","headline":"Alpha-neurexins including neurexin 3alpha bind dystroglycan directly via the second LNS domain, in rat brain extract.","interaction_type":"direct binding","direction_and_effect":"The second LNS domain of neurexin 1alpha, 2alpha and 3alpha forms tight Ca2+-dependent complexes with dystroglycan [PMID:11470830].","molecular_requirements":"A single isolated LNS domain without flanking sequences fully binds; only alpha-neurexins with the second or sixth LNS domain captured dystroglycan [PMID:11470830]. The abstract adds that binding requires dystroglycan glycosylation and is regulated by neurexin alternative splicing [PMID:11470830].","affinity_potency":[],"species_and_systems":"Ig-fusion protein affinity chromatography with rat brain extract and domain deletions [PMID:11470830]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"DAG1 is flagged secreted and transmembrane, NRXN3 transmembrane [flag]; the abstract describes neuronal cell-surface dystroglycan [PMID:11470830].","caveats":"Evidence concerns alpha-neurexin LNS domains; beta-neurexin binding is not reported in the excerpts. Both species rows are projected from rat data.","key_references":[{"PMID":"11470830","why":"Neurexin 3alpha LNS2 binds dystroglycan, Ca2+ dependent"}],"covers":["LR003030","LR006254"]},"LR004571":{"pair":"NTN1 -> ADORA2B","headline":"One 2000 abstract reports A2b as a netrin-1 receptor inducing cAMP; no independent confirmation in our evidence.","interaction_type":"direct binding","direction_and_effect":"A2b is reported as a netrin-1 receptor that induces cAMP accumulation on binding netrin-1 [PMID:11048721]. Curator assay_detail notes a dorsal spinal cord axon outgrowth readout [PMID:11048721].","molecular_requirements":"The abstract says DCC interacts with the adenosine A2b receptor, suggesting a DCC co-receptor context [PMID:11048721].","affinity_potency":[],"species_and_systems":"Species not specified in our evidence; abstract only [PMID:11048721].","localisation_and_range":"NTN1 flagged secreted, ADORA2B transmembrane [flag].","caveats":"Single paper, abstract only, no database records; the curator-listed assay is described as direct binding although the abstract emphasises cAMP signalling.","key_references":[{"PMID":"11048721","why":"A2b as netrin-1 receptor"}],"covers":["LR001162","LR004571"]},"LR001169":{"pair":"NTN3 -> NEO1","headline":"Netrin-3 binds neogenin (abstract) and acts through it in myoblasts, where CDO is also required.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds neogenin [PMID:10366627]. Myoblasts express netrin-3 and neogenin, which stimulate myotube formation and enhance myogenic bHLH- and NFAT-dependent transcription [PMID:15520228].","molecular_requirements":"Neogenin binds CDO in cis, and myoblasts lacking CDO respond poorly to recombinant netrin, so netrin-3/neogenin signalling needs CDO [PMID:15520228].","affinity_potency":[],"species_and_systems":"Murine netrin-3 in binding study [PMID:10366627]; myoblasts in the second paper, which the curation labels human [PMID:15520228]. Reactome lists a Netrin-3:Neogenin complex [DB:Reactome]. Mouse and human pairs are both ortholog-inferred.","localisation_and_range":"Netrin-3 is flagged secreted [flag]. The authors propose an autocrine mechanism in myoblasts [PMID:15520228].","caveats":"The binding paper was read as abstract only and gives no affinity. The myogenesis paper is functional. One abstract_insufficient row is not shown.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds neogenin"},{"PMID":"15520228","why":"Netrin-3 and neogenin promote myotube formation; CDO needed"}],"covers":["LR001169","LR004578"]},"LR006263":{"pair":"NTN4 -> ITGA6","headline":"Netrin-4 binds alpha6beta1 integrin dose-dependently in endothelial cells; one abstract-only paper, no chain-specific data.","interaction_type":"direct binding","direction_and_effect":"Alpha6beta1 integrin binds netrin-4 in a dose-dependent manner; inhibiting alpha6 or beta1 suppresses netrin-4-induced endothelial migration, adhesion, focal adhesion contact and Src-family phosphorylation [PMID:21799154].","molecular_requirements":"The binding is to the alpha6beta1 heterodimer; both the alpha6 and beta1 subunits are needed for the functional effects [PMID:21799154]. Chain-specific binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial and lymphatic endothelial cells; species is not stated in the curation record [PMID:21799154]. Pair is ortholog-inferred for both species.","localisation_and_range":"Netrin-4 is flagged secreted [flag].","caveats":"Abstract only. The ITGA6 pair is a subunit of the complex; CCC tools scoring complexes need both integrin chains.","key_references":[{"PMID":"21799154","why":"Netrin-4 binds and activates endothelial alpha6beta1 integrin"}],"covers":["LR003039","LR006263"]},"LR004580":{"pair":"NTN4 -> UNC5A","headline":"Netrin-4 binds UNC5H1 (UNC5A)-transfected CHO cells via the N-terminal domain; single abstract-only study.","interaction_type":"direct binding","direction_and_effect":"AP4-tagged netrin-4 bound CHO cells transfected with DCC or UNC5 homolog 1 (UNC5H1), and only the N-terminal LNT domain bound [PMID:17174565].","molecular_requirements":"Not reported in our evidence beyond domain mapping; binding may involve other, unidentified neuronal receptors [PMID:17174565].","affinity_potency":[],"species_and_systems":"COS7-derived fusion protein, CHO transfectants, cortical neurons [PMID:17174565]. Reactome lists NTN4:DCC,UNC5A complex [DB:Reactome]. Both pairs ortholog-inferred.","localisation_and_range":"Netrin-4 is secreted and UNC5A is transmembrane [flag].","caveats":"Abstract only, no affinity. The mapping of UNC5H1 to UNC5A is the curators' own; the abstract names only UNC5H1.","key_references":[{"PMID":"17174565","why":"Netrin-4 binds UNC5H1 and DCC transfectants"}],"covers":["LR001171","LR004580"]},"LR001178":{"pair":"NXPH1 -> NRXN3","headline":"Neurexophilin-1 binds neurexin-3 LNS2 with nanomolar affinity; splice insert SS2A raises it about 6-fold.","interaction_type":"direct binding","direction_and_effect":"Nxph1 binds the LNS2SS2- domains of Nrxn1, Nrxn2 and Nrxn3 with similar nanomolar affinities, and Nrxn3 LNS2SS2A+ binds Nxph1 with a ~6-fold higher affinity than LNS2SS2- [PMID:31566781]. The 1998 study found neurexophilins 1 and 3 bind LNS2 of all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 domain is the binding unit. The I401Q mutation reduces Nxph1 affinity for Nrxn3 from the nanomolar to the millimolar range [PMID:31566781].","affinity_potency":[],"species_and_systems":"Mouse Nrxn3 was tested in [PMID:31566781]; recombinant mouse proteins and knockout mice in [PMID:9856994]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag] and membrane neurexin [flag].","caveats":"Absolute affinity numbers are not in our excerpts. The 1998 evidence is abstract-only. The 2019 evidence sentence is not itself a result.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001178","LR004587"]},"LR001187":{"pair":"OSM -> LIFR","headline":"OSM uses LIFR, with human-specific binding and functional evidence plus structural mapping; gp130 is needed for high affinity.","interaction_type":"direct binding","direction_and_effect":"OSM binds the high-affinity but not the low-affinity LIF receptor [PMID:1536831]. The OSM site 3 motif (Phe160/Lys163) is responsible for LIFR and OSMR binding [PMID:10997905]. Human OSM, but not mouse OSM, also acted through LIFR in rat hepatoma cells [PMID:10854424]. OSM signalling was unaffected by deletion of the LIFR N-terminal cytokine binding domain, unlike CNTF [PMID:16051226]. GtoPdb lists OSM as agonist of LIFR [DB:GtoPdb].","molecular_requirements":"gp130 is the converting subunit giving high-affinity OSM binding to the LIFR; gp130 alone gives low-affinity OSM binding [PMID:1542794]. LIFR alone at low affinity does not bind OSM [PMID:1536831].","affinity_potency":[],"species_and_systems":"Human cell lines, COS-7 and rat hepatoma [PMID:1536831][PMID:1542794][PMID:10854424]. The mouse pair is ortholog-inferred.","localisation_and_range":"OSM is flagged secreted [flag]; the LIFR entity has a receptor flag only [flag].","caveats":"All papers read as abstracts only. Mouse OSM does not act through LIFR [PMID:10854424], so the projected mouse pair is doubtful. Structure is of OSM alone [PMID:10997905]. No affinity values in our evidence.","key_references":[{"PMID":"1536831","why":"OSM binds high-affinity LIFR"},{"PMID":"1542794","why":"gp130 converts LIFR to high affinity for OSM"},{"PMID":"10854424","why":"Human-specific LIFR use"}],"covers":["LR001187","LR004596"]},"LR006272":{"pair":"OSTN -> PTPRU","headline":"Osteocrin binds PTPRU by SPR after a CRISPRa screen hit; single full-text paper, no functional effect reported.","interaction_type":"direct binding","direction_and_effect":"OSTN was a hit for PTPRU in a CRISPRa enrichment screen, and SPR showed binding of human PTPRU-ECD (ligand) to human OSTN (analyte) fitted with a 1:1 model [PMID:36178190]. Agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"Only the PTPRU extracellular domain was tested; no co-receptor or subunit requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in SPR with recombinant ectodomain; the screen used cultured cells [PMID:36178190]. Mouse pair is ortholog-inferred only.","localisation_and_range":"OSTN is flagged secreted [flag]; PTPRU is a membrane receptor [flag], so paracrine signalling is plausible but not tested.","caveats":"One paper only. PTPRJ ranked top by initial score but followed a negative trajectory across rounds, so ranking alone was not trusted [PMID:36178190]. SPR affinity value is not given in the excerpts. The mouse pair has no direct evidence.","key_references":[{"PMID":"36178190","why":"CRISPRa screen plus SPR validation of OSTN-PTPRU"}],"covers":["LR003048","LR006272"]},"LR003077":{"pair":"PCDHGB2 -> PCDHGB2","headline":"Mouse gammaB2 shows strictly homophilic trans binding in aggregation assays; biophysics paper also supports it.","interaction_type":"direct binding","direction_and_effect":"Homophilic trans interaction with no heterophilic binding between different isoforms [PMID:20679223][PMID:35253643]. Strictly homophilic across seven gamma-Pcdh isoforms tested, including B2 [PMID:20679223]. No agonist/antagonist effect reported.","molecular_requirements":"Specificity is mediated by EC2 and EC3; gamma-Pcdhs also form cis multimers, and cis-tetramers are proposed as the unit of trans adhesion [PMID:20679223]. Interactions are only partially Ca(2+)-dependent [PMID:20679223].","affinity_potency":[],"species_and_systems":"Mouse proteins: K562 aggregation assays [PMID:20679223] and analytical ultracentrifugation of ectodomain fragments [PMID:35253643]. Human pair inferred by conservation.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent between apposed membranes.","caveats":"The AUC KD range of 9-80 uM in the excerpt appears to describe cis dimerisation of EC3-6 fragments rather than trans binding, so no affinity is listed [PMID:35253643]. The PNAS paper was read as abstract only in the dossier summary but via browser full text by the curator, with an unverified quote [PMID:20679223].","key_references":[{"PMID":"35253643","why":"AUC biophysics: trans homophilic binding precise, no heterophilic interactions."},{"PMID":"20679223","why":"K562 aggregation: gamma-Pcdh trans interactions strictly homophilic."}],"covers":["LR003077","LR006300"]},"LR006308":{"pair":"PCSK1N -> GPR83","headline":"proSAAS-derived PEN peptides activate GPR83 with length-dependent G protein bias; abstract-only paper plus UniProt.","interaction_type":"functional only","direction_and_effect":"PEN activates GPR83 (agonist); PEN22 and PEN20 favour Galphai coupling, while PEN18 and PEN19 favour Galphas coupling, consistent with biased ligands [PMID:35605991]. UniProt also lists PEN peptides as GPR83 activators via Gi and Gs [DB:UniProt].","molecular_requirements":"The active species are processed PEN peptides from proSAAS (PCSK1N), not the full precursor; the length of PEN determines the G protein coupling [PMID:35605991].","affinity_potency":[],"species_and_systems":"Human receptor/ligand labelled in the curated row [PMID:35605991]; mouse pair is ortholog-inferred.","localisation_and_range":"PCSK1N is annotated secreted [flag]; PEN is described as a neuropeptide [PMID:35605991].","caveats":"Abstract only; no affinity for PEN reported in our evidence (high-affinity binding in the abstract concerns proCCK peptides) [PMID:35605991].","key_references":[{"PMID":"35605991","why":"PEN lengths bias GPR83 coupling to Galphai vs Galphas."}],"covers":["LR003085","LR006308"]},"LR003086":{"pair":"PDCD1 -> CD274","headline":"PD-1/PD-L1 binding is well established in databases; the one curated paper shows PD-1 binding triggers PD-L1 intracellular signalling.","interaction_type":"direct binding","direction_and_effect":"In HNSCC models PD-1 binding enhanced PD-L1-driven clonogenicity, motility and invasiveness via ILF2-ILF3 and STAT3; this is signalling into the PD-L1 cell [PMID:37389416]. UniProt describes PDCD1 as delivering inhibitory signals on binding CD274 [DB:UniProt].","molecular_requirements":"Deleting the PD-L1 intracellular domain (delta260-290) disrupted signalling [PMID:37389416]. PD-L1 co-immunoprecipitated with ILF3 but not ILF2 [PMID:37389416].","affinity_potency":[],"species_and_systems":"Human HNSCC cell models and humanized in vivo models with recombinant PD-1 [PMID:37389416]; mouse pair is ortholog-inferred. Structures and binding assays in databases [DB:PDB 4ZQK][DB:IntAct].","localisation_and_range":"PD-L1 is annotated secreted and transmembrane, PD-1 transmembrane [flag]; binding is between membrane proteins (contact).","caveats":"The curated paper is abstract-level support and does not measure binding itself; physical binding rests on databases [DB:BioGRID][DB:Reactome]. Pair is written PD-1 as ligand, PD-L1 as receptor; the paper's bidirectional signalling concerns the PD-L1 side.","key_references":[{"PMID":"37389416","why":"PD-1 binding triggers PD-L1 intracellular signalling in HNSCC."}],"covers":["LR003086","LR006309"]},"LR001196":{"pair":"PDGFB -> PDGFRA","headline":"PDGF-B-containing dimers bind cloned human PDGFRA with high affinity; databases add further support.","interaction_type":"direct binding","direction_and_effect":"The cloned human PDGF A-type receptor in COS cells bound 125I-labelled AA, AB and BB PDGF dimers with high affinity [PMID:2544881]; curated effect is Stimulatory. UniProt/IntAct hold competition-binding and cross-linking records [DB:IntAct].","molecular_requirements":"Binding was to BB homodimer and AB heterodimer forms; no other subunit requirement reported [PMID:2544881].","affinity_potency":[],"species_and_systems":"Human receptor in COS cells, radioligand binding [PMID:2544881]; mouse pair ortholog-inferred.","localisation_and_range":"PDGFB annotated secreted [flag].","caveats":"Single abstract-only paper; no Kd in our evidence. Four review-only rows are not shown.","key_references":[{"PMID":"2544881","why":"Radioligand binding of PDGF dimers to cloned PDGFRA."}],"covers":["LR001196","LR004605"]},"LR004607":{"pair":"PDGFC -> PDGFRA","headline":"PDGFC (cleaved growth factor domain) binds and activates PDGFRA; two papers read as abstracts plus database binding records.","interaction_type":"direct binding","direction_and_effect":"PDGF-C binds to and activates the PDGF alpha-receptor and is activated by proteolysis [PMID:10806482]. Recombinant growth factor domain (PDGF-CC) showed high affinity binding to PDGF receptor-alpha homodimers and alpha/beta heterodimers in competition binding and immunoprecipitation; mitogenic on mesenchymal cells [PMID:11297552].","molecular_requirements":"Proteolytic release of the growth factor domain from the CUB domain is needed for activity [PMID:11297552][PMID:10806482]. PDGFRA homodimers and alpha/beta heterodimers bind [PMID:11297552].","affinity_potency":[],"species_and_systems":"Mouse in vivo: transgenic overexpression drives fibroblast proliferation and Pdgfra-null embryonic kidneys lose mesenchymal cells near PDGF-C expression [PMID:10806482]. Second paper used cells bearing both receptors, recombinant protein, species unspecified, and a diabetic mouse wound model [PMID:11297552]. BioGRID and IntAct binding records exist [DB:BioGRID][DB:IntAct].","localisation_and_range":"PDGFC flagged secreted [flag]; acts as a released growth factor domain after cleavage [PMID:11297552].","caveats":"Both papers read as abstracts only. No numeric affinity in our evidence ('high affinity' only). Mouse pair is ortholog-inferred.","key_references":[{"PMID":"10806482","why":"PDGF-C binds and activates PDGFRA; mouse in vivo support"},{"PMID":"11297552","why":"Competition binding of PDGF-CC to PDGFRA homodimers and alpha/beta heterodimers"}],"covers":["LR001198","LR004607"]},"LR009305":{"pair":"PDGFD -> PDGFRA","headline":"PDGFD -> PDGFRA has only a UniProt statement that points to PDGFRB or the heterodimer; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: PDGFD interacts with PDGFRB homodimers, and with heterodimers formed by PDGFRA and PDGFRB [DB:UniProt]. A PDGFRA homodimer interaction is not stated.","molecular_requirements":"If real, probably requires PDGFRB in a heterodimer, per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"PDGFD flagged secreted; PDGFRA transmembrane [flag].","caveats":"No verified papers (one review-only). The database text does not support PDGFRA alone.","key_references":[],"covers":["LR009305"]},"LR001934":{"pair":"PDPN -> CLEC1B","headline":"PDPN binds CLEC1B (CLEC-2); crystal structure and mouse lung development data support it.","interaction_type":"direct binding","direction_and_effect":"Podoplanin binds CLEC-2, and crystal structures of the complex show binding at the noncanonical side face of CLEC-2 via sialic acid on O-glycan [PMID:25458834]. UniProt: PDPN binding to CLEC1B triggers platelet activation or aggregation [DB:UniProt]. Platelet Clec-2 and podoplanin interaction regulates lung development in mice [PMID:29853539].","molecular_requirements":"Binding depends on O-glycosylation (sialic acid) of podoplanin [PMID:25458834]. CLEC1B acts as a dimer in Reactome complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Structure: PDB 3WSR [DB:PDB 3WSR]. In vivo: murine lung development [PMID:29853539]. Both papers read as abstracts only.","localisation_and_range":"PDPN is flagged non-secreted [flag]; contact between platelet and podoplanin-expressing cell. The CLEC1B secreted flag is an annotation flag [flag].","caveats":"Abstracts only; the lung development abstract is truncated. No affinity in our evidence. Curated experiment species for the mouse paper is recorded as human.","key_references":[{"PMID":"25458834","why":"Crystal structure of CLEC-2 with podoplanin"},{"PMID":"29853539","why":"Platelet Clec-2/podoplanin interaction needed for mouse lung development"}],"covers":["LR001934","LR005272"]},"LR005273":{"pair":"PECAM1 -> CD38","headline":"CD31 (PECAM1) was identified as a CD38 counter-receptor in 1998 and signals in sperm via soluble CD38.","interaction_type":"functional only","direction_and_effect":"Moon-1 antibody-recognised ligand on HUVEC was shown to be CD31; CD31-CD38 interactions modulate heterotypic adhesion, calcium fluxes and cytokine messages [PMID:9551996]. Soluble CD38 increases sperm capacitation via interaction with CD31 on sperm, with Src phosphorylation of CD31 and Erk1/2 activation [PMID:26407101].","molecular_requirements":"Not reported in our evidence beyond CD31 and CD38 themselves.","affinity_potency":[],"species_and_systems":"Human cells: HUVEC and CD31 transfectants [PMID:9551996]; human sperm with a proximity ligation assay [PMID:26407101]. Abstracts plus some full text.","localisation_and_range":"CD38 is soluble in seminal plasma in one paper [PMID:26407101]; membrane-mediated adhesion in the other [PMID:9551996]. Secreted flag on CD38 is an annotation flag [flag].","caveats":"The first paper identifies CD31 by antibody cross-inhibition and precipitation, not a purified-protein binding assay; no affinity in our evidence. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"9551996","why":"Identifies CD31 as counter-receptor of CD38"},{"PMID":"26407101","why":"Soluble CD38 signals through CD31 on human sperm"}],"covers":["LR001935","LR005273"]},"LR004616":{"pair":"PENK -> OPRK1","headline":"PENK-derived C-terminally extended peptides bind kappa receptor with high affinity in COS-1 cells; one abstract-only paper, no database records.","interaction_type":"direct binding","direction_and_effect":"C-terminally extended proenkephalin peptides (Met-Enk-Arg-Gly-Leu, Met-Enk-Arg-Phe), Peptide E, BAM peptides and metorphamide have high affinity for kappa; short Leu- and Met-enkephalin are delta selective [PMID:8624732].","molecular_requirements":"The paper proposes an Arg-X-extended core is needed for kappa [PMID:8624732]. The active peptides are processed forms.","affinity_potency":[],"species_and_systems":"Cloned receptors transiently expressed in COS-1 cells; experiment species recorded as human [PMID:8624732]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"PENK is flagged secreted [flag].","caveats":"Abstract only; no numeric affinities in our evidence. Full-length PENK is not tested; short enkephalins are not kappa-selective.","key_references":[{"PMID":"8624732","why":"Opioid peptide binding to cloned mu, delta, kappa receptors"}],"covers":["LR001207","LR004616"]},"LR006317":{"pair":"PF4 -> CCR1","headline":"CXCL4/PF4 acts as a CCR1 agonist for migration and endocytosis; one full-text paper, but CXCL4 did not compete for CCL3 binding.","interaction_type":"functional only","direction_and_effect":"CXCL4 induced migration of CCR1-expressing L1.2 transfectants and THP-1 cells, CCR1 endocytosis, and CCR1 antagonist-sensitive monocyte chemotaxis; it appears a partial agonist in transfectants [PMID:29930254].","molecular_requirements":"Migration to CXCL4 was ablated by chondroitinase, suggesting cell-surface glycosaminoglycan presentation is required [PMID:29930254].","affinity_potency":[],"species_and_systems":"Human THP-1 cells, human primary monocytes, mouse L1.2 transfectants [PMID:29930254]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"PF4 is flagged secreted [flag]; deposition on endothelium is described in the abstract [PMID:29930254].","caveats":"Binding was not shown: unlabeled CXCL4 failed to compete with radiolabelled CCL3 for CCR1 [PMID:29930254]. Assay_class says direct_binding but the data are functional. UniProt cites the interaction [DB:UniProt]. Effect needs micromolar CXCL4 (1 uM used) [PMID:29930254].","key_references":[{"PMID":"29930254","why":"CXCL4 as CCR1 agonist in monocytes"}],"covers":["LR003094","LR006317"]},"LR003095":{"pair":"PF4 -> FGFR1","headline":"PF4 inhibits FGF-2 binding to FGFR1 cells, apparently by complexing FGF-2; not direct PF4-FGFR1 binding.","interaction_type":"functional only","direction_and_effect":"PF4 inhibited 125I-FGF-2 binding to FGFR-1-transfected CHO cells, concentration dependent but not complete, and inhibited FGF-2 dimerization [PMID:9558385].","molecular_requirements":"The mechanism is complex formation of PF4 with FGF-2, not PF4 binding FGFR1 [PMID:9558385].","affinity_potency":[],"species_and_systems":"Heparan-sulfate-deficient CHO cells expressing FGFR-1 and murine microvascular endothelial cells; ligand and receptor recorded as human [PMID:9558385]. Pair is ortholog-inferred.","localisation_and_range":"PF4 is flagged secreted [flag].","caveats":"Abstract only. This is an indirect antagonism through FGF-2; whether PF4 binds FGFR1 is not reported in our evidence. No database records.","key_references":[{"PMID":"9558385","why":"PF4 inhibits FGF-2 binding to FGFR-1 cells"}],"covers":["LR003095"]},"LR006326":{"pair":"PLA2G2A -> ERBB2","headline":"Interaction of sPLA2-IIa with HER2 is reported as indirect (co-IP context); weak support for direct ligand-receptor status.","interaction_type":"functional only","direction_and_effect":"The paper states sPLA2-IIa binds EGFR and HER3 and only indirectly interacts with HER2 [PMID:28440478]. sPLA2-IIa activates EGFR-family receptors and HER/ERBB signalling in a feedback loop [PMID:28440478]. BioGRID lists Affinity Capture-Western for PLA2G2A-ERBB2 [DB:BioGRID 2524053].","molecular_requirements":"HER2 engagement is likely through EGFR/HER3 partners rather than direct binding, per the curator note [PMID:28440478].","affinity_potency":[],"species_and_systems":"Human lung and prostate cancer cell lines; nude mouse xenografts [PMID:28440478]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted ligand, from the flag on PLA2G2A [flag] and elevated tumour microenvironment levels [PMID:28440478].","caveats":"Abstract only; the direct receptors named are EGFR and HER3, not HER2, so this row is a co-receptor/indirect association [PMID:28440478].","key_references":[{"PMID":"28440478","why":"Only source; states indirect HER2 interaction"}],"covers":["LR003105","LR006326"]},"LR004625":{"pair":"PLAU -> ITGAM","headline":"uPA acts through CD11b/Mac-1 independent of uPAR in mouse I/R neutrophil responses; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Postischemic neutrophil adherence and transmigration were reduced in uPA-deficient mice and by WX-340, but not in uPAR-deficient mice, and were reduced by CD11b/Mac-1 blockade [PMID:21969013]. The authors say the process is regulated via CD11b/Mac-1 and does not require uPAR [PMID:21969013].","molecular_requirements":"Mac-1 is CD11b with its partner chain; the dossier names it as ITGAM:ITGB2 in curator notes [PMID:21969013]. Binding requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cremaster muscle in vivo microscopy and hepatic I/R model [PMID:21969013]; leukocyte-transfer experiments. Mouse pair is also listed as non-inferred.","localisation_and_range":"Secreted uPA per flag [flag]; endothelial uPA promotes adherence and leukocyte uPA promotes transmigration [PMID:21969013].","caveats":"Abstract only; uPA-CD11b physical binding is not demonstrated, and CD11b is described as also serving as a uPAR receptor [PMID:21969013].","key_references":[{"PMID":"21969013","why":"uPA-dependent neutrophil transmigration via CD11b/Mac-1, not uPAR"}],"covers":["LR001222","LR004625"]},"LR006335":{"pair":"PLAUR -> ITGB1","headline":"Direct cell-based binding of soluble uPAR to beta1 (ITGB1) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Binding was to alpha4beta1, alpha6beta1 and alpha9beta1 [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003114","LR006335"]},"LR004634":{"pair":"PLG -> ITGB1","headline":"Same single paper as the ITGA9 row: plasmin binds alpha9beta1; the beta1 chain alone is not tested.","interaction_type":"direct binding","direction_and_effect":"Plasmin specifically interacts with alpha9beta1, inducing alpha9-CHO cell migration dependent on kringle binding and catalytic activity [PMID:15247268].","molecular_requirements":"Evidence is for the alpha9beta1 heterodimer; ITGB1 alone not tested [PMID:15247268].","affinity_potency":[],"species_and_systems":"Human proteins, recombinant CHO cells; abstract only [PMID:15247268].","localisation_and_range":"Ligand flagged secreted; ITGB1 flagged non-secreted [flag].","caveats":"Beta1 pairs with many alpha chains; only alpha9beta1 shown. Active species is plasmin.","key_references":[{"PMID":"15247268","why":"plasmin-alpha9beta1 interaction"}],"covers":["LR001231","LR004634"]},"LR006344":{"pair":"PODXL2 -> SELP","headline":"Endoglycan (PODXL2) from B cells binds P-selectin in a sialylation-dependent way and supports rolling; a single paper.","interaction_type":"direct binding","direction_and_effect":"Immunopurified endoglycan from a B-cell line, a monocyte line and human tonsils bound P-selectin [PMID:18606703]. Introducing intact endoglycan into a B-cell line facilitated rolling on a P-selectin substrate [PMID:18606703].","molecular_requirements":"Binding was divalent cation-dependent and required sialylation; rolling depended on sialic acid and fucose [PMID:18606703]. Activated B cells increase endoglycan while PSGL-1 falls [PMID:18606703].","affinity_potency":[],"species_and_systems":"Human cell lines and tonsils [PMID:18606703]; mouse pair is ortholog-inferred.","localisation_and_range":"Endoglycan flagged transmembrane, not secreted [flag]; contact-dependent adhesion.","caveats":"One paper only, no affinity, no database records. The same paper is the sole support for the E-selectin pair.","key_references":[{"PMID":"18606703","why":"endoglycan binds P-selectin and supports B-cell rolling"}],"covers":["LR003123","LR006344"]},"LR004643":{"pair":"POMC -> MC3R","headline":"POMC-derived melanocortin peptides bind and activate MC3R in binding and functional assays; abstract-level evidence, mostly peptide analogues.","interaction_type":"direct binding","direction_and_effect":"POMC-derived melanocortin peptides act as full agonists at MC3R [PMID:10493100][PMID:10358030]. Radioligand competition shows MC3R prefers desacetyl-alpha-MSH, gamma-MSH and beta-MSH over alpha-MSH [PMID:7774675]. GtoPdb records an agonist action [DB:GtoPdb]. Structures of POMC with MC3R are in the PDB [DB:PDB 8IOC].","molecular_requirements":"MC3R acts as a receptor for POMC-derived peptides; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 396 +/- 65 pmol/l","assay":"[125I][Nle4,D-Phe7]alpha-MSH saturation binding","system":"COS cells expressing MC3R","cite":"PMID:7774675"},{"value":"pKd 8.5","assay":"affinity of gamma-MSH-derived peptide, assay method not explicit","system":"human MC3R","cite":"PMID:10358030"},{"value":"pKi 8.0-8.4","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:10358030"}],"species_and_systems":"Rat MC3R/MC4R [PMID:10493100]; human receptor with synthetic gamma-MSH derivatives [PMID:10358030]; COS cell binding with species unspecified [PMID:7774675]. Mouse pair is ortholog-inferred. All read as abstracts.","localisation_and_range":"POMC flagged secreted, MC3R transmembrane [flag]; range not tested in the papers.","caveats":"Ligands tested are mostly synthetic analogues and individual peptides, not full-length POMC. Rat receptor in one paper despite the human tag [PMID:10493100]. Assay for the pKd value is not explicit [PMID:10358030]. The 396 pmol/l Kd is for the radiolabelled analogue, not a POMC peptide [PMID:7774675].","key_references":[{"PMID":"7774675","why":"Radioligand binding at MC3R with peptide rank order"},{"PMID":"10358030","why":"Peptide determinants of MC3R vs MC4R selectivity"},{"PMID":"10493100","why":"Rat MC3R/MC4R affinity and potency of nine ligands"}],"covers":["LR001241","LR004643"]},"LR004652":{"pair":"PPY -> NPY4R","headline":"Well supported direct agonist pair: PP binds Y4 with high affinity in several cloning and binding studies, plus GtoPdb and a PDB structure.","interaction_type":"direct binding","direction_and_effect":"PP is an agonist at Y4: it decreased cAMP and increased intracellular Ca2+ in Y4-transfected cells [PMID:7592911], is a full agonist in CHO cells [PMID:7493937], and was antisecretory in human and mouse colon mucosa, lost in Y4 knockout mouse tissue [PMID:16807358]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Y4 receptor alone was sufficient in transfected cells; no other subunit or co-receptor is reported in our evidence.","affinity_potency":[{"value":"Kd 2.8 nM","assay":"125I-human PP binding","system":"HEK293 cells stably expressing human receptor","cite":"PMID:8643460"},{"value":"Ki 13.8 pM","assay":"competition binding","system":"cloned human PP1 (Y4) receptor, CHO cells","cite":"PMID:7493937"},{"value":"pKi = 10.25","assay":"displacement of 125I-PYY","system":"transiently expressed human Y4","cite":"PMID:7592911"}],"species_and_systems":"Human PP and human Y4 in transfected HEK293, CHO and LMTK- cells; the colon study also used human and mouse tissue and mouse Y4 [PMID:16807358]. Mouse pair in the database is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY4R transmembrane [flag], consistent with hormone-like paracrine or endocrine action.","caveats":"All four papers were read as abstracts only. PP also binds Y4 alongside PYY and NPY at lower affinity (pKi = 9.06 and 8.68) [PMID:7592911], so Y4 is not exclusive to PP. A structure of the pair exists [DB:PDB 7X9C].","key_references":[{"PMID":"8643460","why":"Human Y4 cloning, Kd 2.8 nM for PP"},{"PMID":"7493937","why":"Y4 cloning, Ki 13.8 pM, cAMP inhibition"},{"PMID":"16807358","why":"Y4 mediates PP responses in human and mouse colon"}],"covers":["LR001251","LR004652"]},"LR001943":{"pair":"PRG4 -> TLR2","headline":"Direct binding of PRG4 to TLR2 by ELISA with inhibitory effect on TLR2 activation; one paper, human recombinant system.","interaction_type":"direct binding","direction_and_effect":"Recombinant and native human PRG4 showed concentration-dependent binding to TLR2 by ELISA, and nhPRG4 inhibited TLR2 activation by its agonist and by OA and RA synovial fluid; the paper classes PRG4 as an antagonist [PMID:26643105]. Immunodepleting PRG4 from synovial fluid increased TLR2 activation [PMID:26643105].","molecular_requirements":"Not reported in our evidence; binding used immobilised receptor protein, and activity was read in receptor-expressing HEK cells [PMID:26643105].","affinity_potency":[],"species_and_systems":"Human recombinant and native PRG4, TLR-overexpressing HEK cells and patient OA/RA synovial fluid [PMID:26643105]. Mouse pair is projected.","localisation_and_range":"PRG4 is flagged secreted [flag] and described as secreted by synovial fibroblasts and chondrocytes [PMID:26643105].","caveats":"One paper only; no affinity value reported in our evidence. Effect is inhibition of agonist-driven activation, not receptor activation.","key_references":[{"PMID":"26643105","why":"PRG4 binds TLR2 and TLR4 and reduces their activation"}],"covers":["LR001943","LR005280"]},"LR006353":{"pair":"PRLH -> NPFFR2","headline":"Weak support: a full-text RF-amide panel reports NPFF2R binding the peptide set at 0.1-10 nM, with no PrRP-specific value in our evidence.","interaction_type":"direct binding","direction_and_effect":"In a binding panel, NPFF2R bound the whole set of RF-amide peptides with affinity constants in the 0.1-10 nM range [PMID:23911743]; the curator marks this as agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptor, receptor-expressing cell membranes with [3H]-FFRF-NH2 [PMID:23911743]. Mouse pair is projected.","localisation_and_range":"PRLH is flagged secreted and NPFFR2 transmembrane [flag].","caveats":"Group statement only; the PRLH (PrRP) value is not given in our evidence, and the paper notes low selectivity among RF-amide peptides [PMID:23911743].","key_references":[{"PMID":"23911743","why":"RF-amide peptide binding profile at five receptors"}],"covers":["LR003132","LR006353"]},"LR001259":{"pair":"PROK2 -> PROKR1","headline":"Well supported agonist-receptor pair: PROK2 activates PROKR1 in transfected cells with pIC50 7.5 reported; abstracts only.","interaction_type":"direct binding","direction_and_effect":"Prokineticin 2 is a cognate ligand of PK-R1 (ZAQ), inducing calcium transients with nanomolar potency in CHO cells [PMID:12054613]. PK2 stimulated Ca2+ responses in PKR1-expressing cells with potency similar to PK1 and PK2beta [PMID:15772293]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence. PK2beta, a proteolytically processed form of the PK2 long splice product, acts with similar potency at PKR1 [PMID:15772293].","affinity_potency":[{"value":"pIC50 7.5","assay":"intracellular Ca2+ response benchmark","system":"human PK2 in PKR1-expressing cells","cite":"PMID:15772293"}],"species_and_systems":"Human ligand and receptor in cell lines [PMID:12054613][PMID:15772293]; mouse pair is ortholog-inferred.","localisation_and_range":"Both PROK2 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"Both papers abstract-only. GtoPdb records the same two papers [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"PK2 as cognate ligand of PK-R1 with calcium flux."},{"PMID":"15772293","why":"PK2 potency at PKR1, pIC50 7.5."}],"covers":["LR001259","LR004659"]},"LR004661":{"pair":"PROS1 -> AXL","headline":"PROS1 binds and activates AXL in glioblastoma stem-like cells; one full-text paper plus a 1995 identification of TAM ligands; one caveat on prior literature.","interaction_type":"direct binding","direction_and_effect":"PROS1 secreted by tumour-associated macrophages/microglia was co-immunoprecipitated with AXL and recombinant PROS1 raised phosphorylated AXL, not total AXL, then p65/NF-kB activation, which BGB324 blocked [PMID:29531161]. Agonist action; the 1995 paper identified protein S and Gas6 as ligands of the Tyro 3/Axl family [PMID:7867073].","molecular_requirements":"Not reported in our evidence for subunits or co-receptors. A PROS1 blocking peptide reduced AXL phosphorylation by macrophage-conditioned medium [PMID:29531161].","affinity_potency":[],"species_and_systems":"Human patient-derived mesenchymal glioma stem-like cells, plus mouse tumour models, for PMID 29531161; 1995 paper used human proteins in vitro [PMID:7867073]. Mouse pair is ortholog-inferred.","localisation_and_range":"PROS1 is annotated secreted [flag]; the 2018 paper shows macrophage/microglia-derived PROS1 acting on tumour cells [PMID:29531161], so paracrine.","caveats":"The 2018 paper itself states that GAS6 was previously the only known AXL ligand, so this is a context-specific report from one lab [PMID:29531161]. The 1995 paper is abstract-only and names both Tyro 3 and Axl without separating them [PMID:7867073]. Co-IP used lysates with His-tagged PROS1, not purified binding.","key_references":[{"PMID":"29531161","why":"PROS1 co-IP with AXL, AXL phosphorylation and NF-kB in glioma stem cells."},{"PMID":"7867073","why":"Protein S and Gas6 identified as Tyro3/Axl family ligands."}],"covers":["LR001261","LR004661"]},"LR005282":{"pair":"PROS1 -> MERTK","headline":"PROS1 activates MER in a reporter-cell system, with context-dependent activation; one abstract-only paper plus Reactome.","interaction_type":"functional only","direction_and_effect":"Each TAM receptor showed a unique pattern of interaction with and activation by GAS6 and PROS1 in chimeric reporter cells; agonist action, modulated by apoptotic cells, phosphatidylserine vesicles and enveloped virus [PMID:25074926]. Reactome describes MERTK binding Gas6 or Protein S [DB:Reactome R-HSA-202710].","molecular_requirements":"Gamma-carboxylation of the ligands is essential for full TAM activation; soluble immunoglobulin-like TAM domains act as specific ligand antagonists [PMID:25074926].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in chimeric-receptor reporter cell lines [PMID:25074926]; mouse pair is ortholog-inferred.","localisation_and_range":"PROS1 annotated secreted and MERTK transmembrane [flag]; activation depends on phosphatidylserine presentation (soluble, apoptotic cell or viral envelope) [PMID:25074926].","caveats":"Single abstract-only paper that covers all three TAM receptors; MER-specific numbers are not reported in our evidence. One further row was review-only.","key_references":[{"PMID":"25074926","why":"Chimeric TAM reporter study of GAS6/PROS1 activation patterns."}],"covers":["LR001946","LR005282"]},"LR006362":{"pair":"PSAP -> M6PR","headline":"Prosaposin precursor is recognised by the mannose-6-phosphate receptor for lysosomal shuttling; supported by one abstract only.","interaction_type":"functional only","direction_and_effect":"The abstract states the SAP precursor can be recognised by the M-6-P receptor and shuttled from the secretory pathway to the lysosome [PMID:9707421]. This is an intracellular sorting route, not signalling.","molecular_requirements":"Not reported in our evidence beyond the receptor name.","affinity_potency":[],"species_and_systems":"Fibroblast uptake assays, human ligand and receptor per curator annotation; the M6PR statement is background in the abstract [PMID:9707421].","localisation_and_range":"Ligand carries a secreted flag [flag]; M6PR acts here on the secretory pathway to the lysosome, not as a cell-surface signalling receptor [PMID:9707421].","caveats":"The paper's own experiments concern LRP and the mannose receptor; M6PR is cited as prior knowledge, no new M6PR data. Abstract only. Evidence is a sorting receptor, not signalling.","key_references":[{"PMID":"9707421","why":"Describes M-6-P receptor, mannose receptor and LRP routes for SAP precursor uptake."}],"covers":["LR003141","LR006362"]},"LR008306":{"pair":"PSG7 -> DSCAM","headline":"SPR in a large human cell-surface interactome screen showed PSG7 binding DSCAM; single paper, binding only.","interaction_type":"direct binding","direction_and_effect":"The paper reports SPR binding of DSCAM to PSG7; no effect or signalling is reported [PMID:32822567].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human ectodomain proteins, SPR with 2-fold analyte dilutions of 16-2,048 nM; no cell system [PMID:32822567].","localisation_and_range":"Receptor flagged transmembrane [flag]; PSGs are described as secreted proteins in placenta context, DCC is expressed in human placenta [PMID:32822567].","caveats":"Binding of recombinant proteins only, no functional readout, no affinity value in our evidence; in vivo relevance unknown. A single screen paper.","key_references":[{"PMID":"32822567","why":"Interactome screen with SPR validation of PSG-DCC/DSCAM binding."}],"covers":["LR008306"]},"LR001268":{"pair":"PSPN -> RET","headline":"Persephin activates RET through GFRalpha4; RET alone is not the binding partner.","interaction_type":"functional only","direction_and_effect":"Persephin cross-links to GFRalpha4 and Ret and promotes Ret autophosphorylation in GFRA4-transfected cells [PMID:11116144]. UniProt states the action is via coreceptor GFRA4 [DB:UniProt].","molecular_requirements":"GFRalpha4 is the ligand-binding subunit needed with RET [PMID:11116144]; RET-only action is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in GFRA4-transfected cells [PMID:11116144].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only. The RET interaction is indirect via the coreceptor; a RET-only expression pattern would be misleading for scoring.","key_references":[{"PMID":"11116144","why":"Cross-linking and Ret phosphorylation by PSPN via GFRalpha4."}],"covers":["LR001268","LR004668"]},"LR004670":{"pair":"PTH2 -> PTH2R","headline":"TIP39 (PTH2 gene product) is a well-supported agonist of PTH2R, with binding and cAMP data in recombinant cells.","interaction_type":"direct binding","direction_and_effect":"TIP39 is an agonist at PTH2R: a PTH1R/PTH2R chimera carrying the PTH2R juxtamembrane domain was fully activated by TIP39 (EC50 = 2.0 nm) [PMID:10854439]. TIP39 stimulates cAMP accumulation in PTH2R-expressing cells but is inactive at PTH1R [PMID:11159842]. TIP-(9-39) inhibited cAMP accumulation stimulated by agonists [PMID:11861531]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The PTH2R juxtamembrane domain specifies TIP39 signalling and binding selectivity over PTH1R [PMID:10854439]. Removing six N-terminal TIP39 residues eliminated PTH2R activation and reduced binding affinity 70-fold [PMID:10854439]. Co-receptors are not reported in our evidence.","affinity_potency":[{"value":"Kd 2.0 nM","assay":"TIP39 binding to wild-type PTH2 receptor","system":"recombinant PTH2R (human, as reported)","cite":"PMID:10854439"},{"value":"EC50 0.54 nM (human TIP39)","assay":"cAMP accumulation","system":"LLCPK1 cells expressing human PTH2 receptor","cite":"PMID:11861531"}],"species_and_systems":"Experiments are human ligand with human receptor in recombinant cells; PMID:11602681 used chimeric human/rat receptors [PMID:11602681]. Mouse pair is projected from human evidence (ortholog-inferred); mouse TIP39 also tested on the human receptor [PMID:11861531].","localisation_and_range":"TIP39 is flagged as secreted and PTH2R as transmembrane [flag]; range is therefore paracrine or endocrine.","caveats":"All four papers were read as abstracts only. TIP39 also binds PTH1R weakly (apparent 243 +/- 52 nM) and acts as an antagonist there [PMID:11159842]; PMID:11602681 mainly concerns PTH rather than TIP39.","key_references":[{"PMID":"10854439","why":"TIP39 binding and activation of PTH2R, juxtamembrane selectivity"},{"PMID":"11861531","why":"Human and mouse TIP39 potency at human PTH2R"},{"PMID":"11159842","why":"TIP39 agonist at PTH2R, antagonist at PTH1R"}],"covers":["LR001270","LR004670"]},"LR003149":{"pair":"PTN -> KDR","headline":"PTN binds VEGFR2 with a reported Kd of 11.6 nM and inhibits VEGFR2 phosphorylation; the effect looks inhibitory.","interaction_type":"direct binding","direction_and_effect":"PTN binds VEGFR2 and inhibits its Tyr1175 phosphorylation; in cells lacking alphavbeta3, PTN decreased VEGFR2 phosphorylation and migration in a VEGFR2-dependent manner [PMID:32681389]. PTN also decreased the stimulatory effect of VEGFA [PMID:32681389]. The curator labels the effect antagonist.","molecular_requirements":"Molecular dynamics suggest PTN binds the same VEGFR2 region as VEGFA, via PTN's N-terminal domain [PMID:32681389]. Interplay with alphavbeta3 determines the cellular outcome [PMID:32681389].","affinity_potency":[{"value":"Kd 11.6 nM","assay":"binding of PTN to VEGFR2 (experimental approaches not detailed in dossier)","system":"human","cite":"PMID:32681389"}],"species_and_systems":"Human ligand and receptor, endothelial cells [PMID:32681389]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. KDR is flagged as transmembrane [flag].","caveats":"Abstract only. Single paper. The dossier modulatory annotation for other PTN pairs says stimulatory, but here PTN inhibits VEGFR2 signalling while still stimulating migration through alphavbeta3 [PMID:32681389].","key_references":[{"PMID":"32681389","why":"PTN binds VEGFR2 (Kd 11.6 nM) and inhibits its signalling"}],"covers":["LR003149","LR006370"]},"LR006371":{"pair":"PTN -> MFRP","headline":"Surface plasmon resonance shows human PTN binds the MFRP ectodomain, from a receptor-deorphanisation screen.","interaction_type":"direct binding","direction_and_effect":"Human PTN binds the MFRP ectodomain by SPR, validating a CRISPRa screen hit [PMID:36178190]. Effect on signalling is not reported in our evidence.","molecular_requirements":"MFRP-ECD was the ligand-side partner in SPR; additional subunits not reported in our evidence [PMID:36178190].","affinity_potency":[],"species_and_systems":"Recombinant human ectodomains in SPR [PMID:36178190]; comparator MDK showed no binding to MFRP and ROR1 [PMID:36178190]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. Soluble ectodomain binding only.","caveats":"Full text read, but affinity values are not in our excerpts. The binding was in vitro with isolated ectodomains; cell-based function is not shown. Part of a large screen paper rather than a focused study.","key_references":[{"PMID":"36178190","why":"SPR binding of PTN to MFRP-ECD"}],"covers":["LR003150","LR006371"]},"LR001277":{"pair":"PTN -> PTPRZ1","headline":"Well supported direct PTN-PTPRZ1 binding plus functional signalling; PTN binding inactivates the phosphatase.","interaction_type":"direct binding","direction_and_effect":"PTN binds PTPRZ1 and inactivates its catalytic activity [PMID:10706604]. Ligand-induced oligomerisation inactivates the receptor, which is active as a monomer, so substrate tyrosine phosphorylation rises (curator annotation: antagonist) [PMID:16814777]. In glioblastoma, macrophage-secreted PTN drives glioma stem cell growth through PTPRZ1, with AKT phosphorylation lost when PTPRZ1 is disrupted [PMID:28569747].","molecular_requirements":"Single chain receptor; oligomerisation is needed for inactivation [PMID:16814777]. Midkine-style binding in the related paper depends on the chondroitin sulfate portion of PTPRZ1 (shown for midkine, with PTN binding competed by soluble PTN) [PMID:10212223]. Reactome lists (PTN,MDK):PTPRZ complexes [DB:Reactome]; UniProt notes a complex with integrin alpha-V/beta-3 in one function annotation [DB:UniProt].","affinity_potency":[{"value":"Kd 0.58 nM (high-affinity site; 3.0 nM low-affinity site)","assay":"solid-phase binding, Scatchard analysis (measured for midkine; PTN binding was equally inhibited by soluble PTN)","system":"human ligand, rat receptor","cite":"PMID:10212223"}],"species_and_systems":"Binding data use human ligand with rat receptor [PMID:10212223]; U373-MG human cells [PMID:10706604]; human glioma stem cells and mouse xenografts [PMID:28569747].","localisation_and_range":"PTN is flagged secreted and PTPRZ1 transmembrane [flag]; PTN acts as a paracrine signal on PTPRZ1-expressing cells [PMID:28569747].","caveats":"Three of four confirmed papers were read as abstracts only. The 0.58 nM value was measured for midkine; our evidence does not give a PTN-specific Kd. Effect is inhibitory for phosphatase activity, though downstream signalling is pro-growth.","key_references":[{"PMID":"10706604","why":"PTN binds and inactivates RPTPbeta/zeta in U373-MG cells"},{"PMID":"16814777","why":"ligand-induced oligomerisation inactivates Ptprz"},{"PMID":"28569747","why":"PTN-PTPRZ1 paracrine signalling in glioma stem cells"}],"covers":["LR001277","LR004677"]},"LR003158":{"pair":"PTPRD -> LRRC4B","headline":"Database-asserted only: Reactome complex of LRRC4B with PTPRF, PTPRS and PTPRD; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction and complex LRRC4B:PTPRF,PTPRS,PTPRD [DB:Reactome]. Direction and effect not reported in our evidence.","molecular_requirements":"The Reactome complex pools three LAR-family receptors, so PTPRD-specific binding is not resolved in our evidence [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; both species pairs ortholog-inferred.","localisation_and_range":"Both partners flagged transmembrane [flag].","caveats":"No papers verified for this pair; judged rows were abstract_insufficient or different_entity. Support comes from a pooled database record only.","key_references":[],"covers":["LR003158","LR006379"]},"LR006380":{"pair":"PTPRD -> NLGN3","headline":"Direct non-canonical NLGN3-PTPdelta interaction reported in one paper with structure and mouse behaviour.","interaction_type":"direct binding","direction_and_effect":"NLGN3 binds PTPdelta splice variants in a non-canonical interaction that competes with neurexin binding [PMID:33758193]. Impairing NLGN3-PTPdelta in mice reduced social behavior and enhanced motor learning [PMID:33758193].","molecular_requirements":"Splicing-dependent: PTPdelta variants lacking the meB peptide act as selective ligands; NLGN3 identified on PTPdelta-bound beads [PMID:33758193].","affinity_potency":[],"species_and_systems":"Mouse and cultured neurons; complex structure [PMID:33758193].","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic.","caveats":"Single paper, abstract-level curation plus excerpts; no affinity in our evidence.","key_references":[{"PMID":"33758193","why":"NLGN3-PTPdelta non-canonical interaction competes with neurexin"}],"covers":["LR003159","LR006380"]},"LR003167":{"pair":"PTPRG -> CNTN6","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN6 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN6 not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. Curator note says the pair is stored four times for one interaction; the CNTN6 evidence is the family-level statement.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003167","LR006388"]},"LR001952":{"pair":"PVR -> CD96","headline":"PVR (CD155) binds CD96 across human and mouse; adhesion/activating on NK cells, but CD96 also competes with CD226 and limits NK function.","interaction_type":"conflicting","direction_and_effect":"CD96/CD155 interaction is preserved between human and mouse, and antibodies block complex formation and T-cell adhesion to CD155 cells [PMID:17971293]. CD96 promotes NK cell adhesion to PVR cells, stimulates cytotoxicity of activated NK cells and mediates acquisition of PVR from target cells [PMID:15034010]. Another paper found CD96 competed with CD226 for CD155 and limited NK cell function by direct inhibition [PMID:24658051].","molecular_requirements":"On thymocytes mCD155 was the only available mCD96 receptor [PMID:17971293]; murine CD96 also binds nectin-1 [PMID:17971293]. CD226 and CD96 compete for the same ligand [PMID:24658051].","affinity_potency":[],"species_and_systems":"Mouse proteins and T cells in the first paper [PMID:17971293]; human NK cells in the second [PMID:15034010]. Curated species for the CD226-competition paper is human, though its abstract describes Cd96-/- mice [PMID:24658051].","localisation_and_range":"Membrane proteins; cell adhesion and trogocytosis of PVR indicate contact-dependent interaction [PMID:15034010].","caveats":"The papers disagree on effect (stimulatory in 15034010, inhibitory in 24658051), so effect depends on context. All abstract-only. No affinity reported in our evidence. PDB structure [DB:PDB 6ARQ] and Reactome record exist.","key_references":[{"PMID":"17971293","why":"CD96/CD155 interaction conserved in man and mouse"},{"PMID":"15034010","why":"CD96 mediates NK adhesion and cytotoxicity via PVR"},{"PMID":"24658051","why":"CD96 competes with CD226 and limits NK function"}],"covers":["LR001952","LR005288"]},"LR003176":{"pair":"PVRIG -> NECTIN2","headline":"PVRIG inhibits human CD8+ T cells via NECTIN2 (PVRL2) in functional assays; direct binding is not shown by this paper.","interaction_type":"functional only","direction_and_effect":"PVRIG is a coinhibitory receptor of the DNAM/TIGIT/CD96 nectin family that binds PVRL2; the inhibitory effect of PVRL2 was mediated by PVRIG and not TIGIT [PMID:30659054]. Blocking PVRIG raised CD8+ T-cell cytokine production and cytotoxicity, and combining with TIGIT or PD-1 blockade increased activation further [PMID:30659054]. Biologically NECTIN2 is the ligand on tumour or myeloid cells and PVRIG the inhibitory receptor on T cells.","molecular_requirements":"Not reported in our evidence. An antibody (COM701) blocking PVRIG-PVRL2 interaction was used [PMID:30659054].","affinity_potency":[],"species_and_systems":"Human CD8+ T cells (pp65-specific) co-cultured with human tumour lines, and human tumour-infiltrating lymphocytes [PMID:30659054]. PDB structures contain chains of both partners [DB:PDB 8X6B][DB:PDB 9E6Y].","localisation_and_range":"PVRIG flag shows not secreted [flag]; PVRL2 was seen on CD45- cells and CD14+ cells in tumours [PMID:30659054]. Signalling is contact-based (cell-surface).","caveats":"This paper's binding statement is background; the excerpt cites an earlier report of 88 nmol/L affinity, which is not this paper's result. Read depth in the dossier row is abstract only although excerpts exist. The pair is written PVRIG -> NECTIN2 (PVRIG as 'ligand'), opposite the biological direction.","key_references":[{"PMID":"30659054","why":"Functional PVRIG-PVRL2 inhibitory axis in CD8+ T cells, distinct from TIGIT-PVR"}],"covers":["LR003176","LR006396"]},"LR007334":{"pair":"RAET1G -> HCST:KLRK1","headline":"RAET1G rests only on database records for NKG2D binding; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states RAET1G binds and activates KLRK1/NKG2D, mediating NK cytotoxicity [DB:UniProt].","molecular_requirements":"Complex row; NKG2D is also listed with HCST. Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct physical associations by fluorescence-activated cell sorting [DB:IntAct]. Species not reported in our evidence.","localisation_and_range":"RAET1G is flagged secreted and transmembrane [flag].","caveats":"No curator-confirmed paper: only one review-only row. Entirely database-based; no affinity reported.","key_references":[],"covers":["LR007334"]},"LR001286":{"pair":"RARRES2 -> CCRL2","headline":"Chemerin binds CCRL2 with low-nanomolar affinity in two full-text papers, but the receptor does not signal; it acts as a binding/concentrating receptor.","interaction_type":"direct binding","direction_and_effect":"Chemerin is a nonsignaling ligand of human and mouse CCRL2; unlike classical silent receptors it is not rapidly internalized, and CCRL2 is proposed to concentrate chemerin for the signaling receptor CMKLR1 [PMID:18794339]. In human receptors, no significant G-protein activation or beta-arrestin recruitment was seen with CCRL2 [PMID:27716822].","molecular_requirements":"Full-length chemerin binds; the C-terminal chemerin-9 nonapeptide did not compete efficiently for CCRL2 binding, and a C-terminal chemerin peptide tracer bound CMKLR1 and GPR1 but not CCRL2 [PMID:27716822].","affinity_potency":[{"value":"EC50 = 1.6 nM","assay":"radioligand competition, human chemerin","system":"mouse CCRL2-HA L1.2 transfectants","cite":"PMID:18794339"},{"value":"EC50 = 0.2 nM","assay":"radioligand competition","system":"human CCRL2 L1.2 transfectants","cite":"PMID:18794339"},{"value":"kD of 1.6 nM","assay":"saturation binding","system":"mouse CCRL2 transfectants","cite":"PMID:18794339"},{"value":"KD of 2.35 nM","assay":"saturation binding, [125I]-chemerin","system":"CHO-K1 cells expressing human CCRL2","cite":"PMID:27716822"}],"species_and_systems":"Recombinant L1.2 and CHO-K1 transfectants and mouse peritoneal mast cells, with human chemerin; mouse in vivo data show CCRL2 on mast cells enhances tissue swelling in passive cutaneous anaphylaxis [PMID:18794339]. Human receptor tested in [PMID:27716822].","localisation_and_range":"Chemerin is flagged secreted; CCRL2 is a transmembrane receptor [flag]. The paper proposes local concentration of chemerin at the CCRL2-expressing cell surface [PMID:18794339].","caveats":"CCRL2 is non-signaling, so effect is not agonism; curators' labels (neutral, antagonist) differ between papers. Both papers were read in full text, but the curated effect_direction is not an actual measured antagonism. UniProt notes lower affinity than for CMKLR1 [DB:UniProt]. One further row is pending.","key_references":[{"PMID":"18794339","why":"Identifies chemerin as nonsignaling CCRL2 ligand; EC50 and kD binding"},{"PMID":"27716822","why":"Compares chemerin binding and signaling at CMKLR1, GPR1 and CCRL2"}],"covers":["LR001286","LR004685"]},"LR010727":{"pair":"RELN -> ITGA3:ITGB1","headline":"Reelin binds the alpha3beta1 integrin complex and inhibits cortical neuron migration; one primary paper in mouse and rat systems.","interaction_type":"direct binding","direction_and_effect":"Reelin inhibited migration of cortical neurons and enabled detachment from radial glia; integrin alpha3beta1-deficient neurons did not respond [PMID:10939329]. Curated as antagonist-like (inhibition of migration) [PMID:10939329].","molecular_requirements":"The alpha3beta1 heterodimer is the receptor unit; Reelin was co-immunoprecipitated by beta1 or alpha3 integrin beads [PMID:10939329]. Reelin is also described as forming a complex with VLDLR and ApoER2 [PMID:10939329]. The 180 kDa Reelin component was prominent in the pull-downs, with faint ~330 kDa fragments [PMID:10939329].","affinity_potency":[],"species_and_systems":"Mouse cortical neurons and in vivo mouse cortex; rat embryonic cortex microsphere assays; recombinant Reelin from 293T cells [PMID:10939329].","localisation_and_range":"RELN is flagged secreted [flag]. Reelin acted on cells it contacted, e.g. on coated microspheres [PMID:10939329].","caveats":"Single paper. Authors say other Reelin receptors exist, and an anti-RBD blockade of other receptors did not abolish the effect [PMID:10939329]. Binding was by co-immunoprecipitation, not a measured affinity.","key_references":[{"PMID":"10939329","why":"Core paper: alpha3beta1 as Reelin receptor, in vitro and in vivo"}],"covers":["LR010727"]},"LR003185":{"pair":"RETN -> TLR4","headline":"Resistin competes with LPS for TLR4 and activates it in human cells; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Resistin co-precipitated with TLR4 and competes with LPS for binding; anti-TLR4 antibodies abolished resistin binding to leucocytes, and TLR4-transfected HEK293 cells responded (agonist) [PMID:19754671].","molecular_requirements":"TLR4-transfected but not MD2/CD14-, TLR2-, or untransfected HEK293 cells responded; TLR4/MyD88 signalling was involved [PMID:19754671].","affinity_potency":[],"species_and_systems":"Human myeloid/epithelial cells, PBMC and HEK293 with recombinant resistin [PMID:19754671]. The mouse pair is ortholog-inferred.","localisation_and_range":"RETN is flagged secreted [flag].","caveats":"Abstract-only reading; no affinity reported; a single paper.","key_references":[{"PMID":"19754671","why":"Resistin competes with LPS for TLR4 binding"}],"covers":["LR003185","LR006405"]},"LR001295":{"pair":"RGMA -> NEO1","headline":"RGM binds neogenin with sub-nanomolar affinity in chick retina work; the paper says RGM, not specifically RGMA.","interaction_type":"direct binding","direction_and_effect":"Expression cloning identified neogenin as an RGM binding site; anti-neogenin antibody and soluble neogenin ectodomain blocked temporal retinal axon avoidance of RGM, and DRG axons gained responsiveness when neogenin was expressed [PMID:15258590]. The annotation is inhibitory [flag], fitting axon repulsion [PMID:15258590].","molecular_requirements":"Of netrin receptors tested only neogenin bound RGM [PMID:15258590]. Other requirements not reported in our evidence.","affinity_potency":[{"value":"sub-nanomolar","assay":"expression cloning binding","system":"chick","cite":"PMID:15258590"}],"species_and_systems":"Chick retinal axons and DRG axons; curator lists human ligand and chicken receptor [PMID:15258590]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"RGMA is flagged secreted [flag]. A Reactome complex NEO1:RGD is recorded on the plasma membrane [DB:Reactome R-HSA-374583].","caveats":"Abstract-only; the abstract says RGM without naming RGMA; no numeric Kd given.","key_references":[{"PMID":"15258590","why":"Neogenin identified as RGM receptor"}],"covers":["LR001295","LR004694"]},"LR006407":{"pair":"RGMB -> CTLA4","headline":"RGMB is reported as a novel CTLA-4 binder that strengthens sCTLA-4 binding to CD80; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"RGMB binds an extracellular domain of CTLA-4 and specifically strengthens binding of monomeric soluble CTLA-4 to CD80, enhancing its suppressive effect on co-stimulation [PMID:31061392].","molecular_requirements":"The enhancement applies to monomeric soluble CTLA-4 with CD80 [PMID:31061392].","affinity_potency":[],"species_and_systems":"Species not stated beyond curator's human entry; the mouse pair is ortholog-inferred [PMID:31061392].","localisation_and_range":"RGMB is not flagged secreted and CTLA4 is transmembrane [flag].","caveats":"Abstract-only; no affinity; mechanism is modulatory of a CTLA4-CD80 interaction, not a classical agonism; single paper.","key_references":[{"PMID":"31061392","why":"RGMB as a novel CTLA-4 binding partner"}],"covers":["LR003187","LR006407"]},"LR012383":{"pair":"RNF43 -> FZD6:LRP6","headline":"RNF43 -> FZD6:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: abstract_insufficient 2, different_entity 1). Some judged rows were a different entity.","key_references":[],"covers":["LR012383"]},"LR005291":{"pair":"ROBO1 -> ROBO1","headline":"ROBO1 homophilic binding through its extracellular domain, shown in one abstract-read paper and one IntAct record.","interaction_type":"direct binding","direction_and_effect":"Extracellular domains of Robo1 and Robo2 are homophilic adhesion molecules [PMID:12504588]; Robo1 expressed in 3T3 cells stimulated neurite outgrowth from Robo-positive neurons, blocked by an antibody to the first Ig domain or soluble Robo-Fc [PMID:12504588]. IntAct lists a polymerization record [DB:IntAct].","molecular_requirements":"The first Ig domain of Robo1/2 is implicated by antibody blockade [PMID:12504588]. Coreceptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo1 and Robo2 transfected into 3T3 cells (cell line species not stated in our evidence); neurons were retinal, olfactory and cerebellar granule cells, species not stated [PMID:12504588]. Mouse pair is ortholog-inferred.","localisation_and_range":"Receptor flagged as transmembrane, not secreted [flag]; homophilic adhesion implies contact-dependent (juxtacrine) signalling.","caveats":"Single paper read as abstract only; direction is meaningless for a homophilic pair. Robo1 also interacts with Robo2 [PMID:12504588].","key_references":[{"PMID":"12504588","why":"Robo1/Robo2 homophilic adhesion and neurite outgrowth"}],"covers":["LR001958","LR005291"]},"LR003194":{"pair":"ROBO3 -> ROBO1","headline":"ROBO3 to ROBO1 heterophilic binding, one abstract-only paper; reverse row of ROBO1 -> ROBO3.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind heterophilically to Robo1 [PMID:16226035]; no effect direction reported.","molecular_requirements":"Isoform Robo3A versus Robo3B involvement not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; orthologs expressed in mouse embryo [PMID:16226035]. Mouse pair listed as not ortholog-inferred, but the dossier shows only human experiments.","localisation_and_range":"Both membrane-bound per flags [flag].","caveats":"Abstract only; no database records.","key_references":[{"PMID":"16226035","why":"Robo3 binds Robo1"}],"covers":["LR003194","LR006414"]},"LR006416":{"pair":"RSPO1 -> KREMEN1","headline":"RSPO1 interacts with KREMEN1 and blocks DKK1/Kremen-mediated LRP6 internalization; functional abstract-only evidence.","interaction_type":"functional only","direction_and_effect":"RSpo1 interferes with DKK1/Kremen-mediated internalization of LRP6 through an interaction with Kremen, raising LRP6 on the cell surface [PMID:17804805]. It does not directly activate LRP6, and its activity depends on canonical Wnt ligands and LRP6. The annotation notes antagonism of Kremen's role [PMID:17804805]; UniProt lists Kremen binding to DKK1 and RSPO1 via FU repeats [DB:UniProt].","molecular_requirements":"Requires canonical Wnt ligands and LRP6 for activity [PMID:17804805].","affinity_potency":[],"species_and_systems":"Human proteins in cell-based assays [PMID:17804805]; mouse pair ortholog-projected.","localisation_and_range":"RSPO1 is secreted per flag [flag].","caveats":"Abstract only; the assay class is functional and the interaction is stated, not measured. No affinity.","key_references":[{"PMID":"17804805","why":"RSpo1-Kremen interaction relieves LRP6 internalization"}],"covers":["LR003196","LR006416"]},"LR004706":{"pair":"RSPO1 -> LGR6","headline":"RSPO1 binds LGR6 according to one paper (abstract only) and GtoPdb/Reactome; less direct than LGR4/5.","interaction_type":"direct binding","direction_and_effect":"Each of the four R-spondins can bind Lgr4, -5 and -6 [PMID:21727895]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR4, -5 or -6 re-expression rescues RSPO1-mediated WNT3A enhancement lost on LGR4 deletion [PMID:21727895].","affinity_potency":[],"species_and_systems":"Mouse gut and intestinal crypt cultures and HEK293 cells; species of the LGR6 result not stated [PMID:21727895].","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Abstract only; LGR6 binding is a family-level claim by mass spectrometry and rescue, not LGR6-specific. One abstract-insufficient and one unresolvable row exist. GtoPdb lists a pIC50 entry without a value [DB:GtoPdb].","key_references":[{"PMID":"21727895","why":"Family-wide R-spondin binding to LGR4/5/6"}],"covers":["LR001309","LR004706"]},"LR004715":{"pair":"RSPO3 -> LGR6","headline":"RSPO3 binding to LGR6 rests on a family-level statement that RSPO2-4 bind LGR4-6, plus databases.","interaction_type":"direct binding","direction_and_effect":"RSPO3 acts as an agonist at LGR6 in GtoPdb [DB:GtoPdb]; the paper reports Fc fusions of RSPO2, RSPO3 and RSPO4 bound specifically to LGR4, LGR5 and LGR6 [PMID:21727895].","molecular_requirements":"LGR4, -5 or -6 re-expression rescued RSPO1-mediated WNT3A signal enhancement in LGR4-removed HEK293 cells [PMID:21727895]. Other subunit needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding assay species not recorded for the RSPO3 row; the paper used mouse gut and HEK293 cells [PMID:21727895]. The human pair is ortholog-inferred, the mouse pair is not.","localisation_and_range":"RSPO3 is flagged secreted and LGR6 transmembrane [flag].","caveats":"The binding sentence for PMID 21727895 comes from a browser read of the main text and is marked as an unverifiable quote with spot-check pending. PMID 29769720 is an RSPO2 paper reporting impaired LGR4/5/6 binding by mutants. No affinity is reported.","key_references":[{"PMID":"21727895","why":"Fc-RSPO3 binds LGR4/5/6"},{"PMID":"29769720","why":"RSPO2 mutants impair LGR4/5/6 binding; not RSPO3-specific"}],"covers":["LR001318","LR004715"]},"LR004724":{"pair":"RTN4 -> RTN4RL1","headline":"Nogo-B is reported to bind NgR3 directly in nasopharyngeal carcinoma cells, but an earlier paper says reticulon-family members do not bind NgR3.","interaction_type":"conflicting","direction_and_effect":"Nogo-B promotes EMT and invasion in NPC by interacting directly with NgR3, and NgR3 siRNA abolished Nogo-B-driven invasion [PMID:35075114].","molecular_requirements":"Not reported for this pair beyond the NPC co-IP [PMID:35075114].","affinity_potency":[],"species_and_systems":"HEK293T co-IP with tagged Nogo-B and NgR3, CNE2 NPC cells and mouse xenografts [PMID:35075114]. The negative paper used cultured cells [PMID:22133682].","localisation_and_range":"RTN4 is flagged non-secreted [flag]; co-IP and colocalisation were reported in the cytoplasm of NPC cells [PMID:35075114].","caveats":"A verified negative states other reticulon family members, to which Nogo-A belongs, do not bind NgR3 [PMID:22133682]. The positive paper uses overexpression co-IP with Nogo-B and cytoplasmic colocalisation, which does not show extracellular ligand binding. No database records.","key_references":[{"PMID":"35075114","why":"Nogo-B co-IP with NgR3 in NPC"},{"PMID":"22133682","why":"Verified negative: reticulon family members do not bind NgR3"}],"covers":["LR001327","LR004724"]},"LR001961":{"pair":"RTN4 -> S1PR2","headline":"Nogo-A-Delta20 binds S1PR2 with KD about 142 nM and signals via G13/RhoA; one abstract-level paper with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Nogo-A-Delta20 acts at S1PR2 to counteract neurite outgrowth and signals via G13, LARG and RhoA; blockade of S1PR2 enhances LTP in wild-type but not Nogo-A-/- mice [PMID:24453941]. The paper describes an inhibitory (repressor) role of the axis, antagonist-labelled by curators.","molecular_requirements":"Nogo-A-Delta20 binds S1PR2 at sites distinct from the S1P pocket [PMID:24453941]. S1P did not change binding (KD MeOH ~192 nM; KD S1P ~202 nM) [PMID:24453941].","affinity_potency":[{"value":"KD ~142 nM","assay":"Bio-Layer interferometry, Nogo-A-ext on S1PR2 membranes","system":"S1PR2-overexpressing membranes","cite":"PMID:24453941"},{"value":"KD ~280 nM","assay":"Microscale thermophoresis, Delta20 to ECL2 peptide","system":"synthetic peptide","cite":"PMID:24453941"},{"value":"KD ~350 nM","assay":"Microscale thermophoresis, Delta20 to ECL3 peptide","system":"synthetic peptide","cite":"PMID:24453941"}],"species_and_systems":"Co-IP from mouse brain extracts (absent in Nogo-A-/- and S1PR2-/- extracts), S1PR2-overexpressing membranes, 3T3 cells [PMID:24453941]. Curators record human ligand and receptor; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Nogo-A is a membrane protein per the paper [PMID:24453941], so contact-dependent or via cleaved fragments; RTN4 flagged non-secreted [flag]. S1PR2 is internalised upon binding, with cell surface levels reduced by ~64% after 30 min [PMID:24453941].","caveats":"Only the Delta20 domain, not RTN4 isoforms generally, is shown to bind. Affinity values are apparent (\"~\") values from the full-text excerpts. No database records support the pair.","key_references":[{"PMID":"24453941","why":"S1PR2 as Nogo-A-Delta20 receptor, KD ~142 nM, repressing LTP"}],"covers":["LR001961","LR005294"]},"LR006425":{"pair":"S100A1 -> AGER","headline":"S100A1 binds the RAGE V domain in an NMR and modelling study (Kd about 6 uM); one paper plus database records.","interaction_type":"direct binding","direction_and_effect":"S100A1 binds the hydrophobic surface of the RAGE V domain, which is described as triggering signalling cascades for cell growth, proliferation and tumorigenesis (stated as background) [PMID:29444082]. S100B binds S100A1 and is modelled to block the S100A1-V domain site, acting as an antagonist; a WST-1 proliferation assay supports this [PMID:29444082]. UniProt lists S100 proteins among RAGE ligands [DB:UniProt].","molecular_requirements":"The RAGE V domain alone was used; residues K39, R48, W51, K52, L53, D93, F97, K110 and V115 map the interface, and the HADDOCK model is a heterotetramer with S100A1 as a dimer, Ca2+-bound [PMID:29444082]. Full-length receptor requirements are not reported.","affinity_potency":[{"value":"Kd 6.13 +/- 1.29 uM","assay":"NMR 1H-15N HSQC titration, S100A1 with RAGE V domain","system":"recombinant proteins","cite":"PMID:29444082"}],"species_and_systems":"Human recombinant S100A1 and RAGE V domain in vitro (NMR, HADDOCK model) [PMID:29444082]. IntAct holds an SPR record for this pair [DB:IntAct].","localisation_and_range":"S100A1 carries a secreted flag, suggesting paracrine signalling to a cell-surface receptor [flag].","caveats":"Isolated V domain, not full-length RAGE; the abstract states the S100A1-RAGE V binding as established background and the structure is a docking model. Kd given as mean over selected residues.","key_references":[{"PMID":"29444082","why":"NMR mapping and Kd of S100A1 with RAGE V domain"}],"covers":["LR003205","LR006425"]},"LR006434":{"pair":"S100A4 -> CXCR3","headline":"No verified paper; support comes only from UniProt text describing the Tag7-S100A4 complex acting via CXCR3.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the PGLYRP1-S100A4 complex promotes lymphocyte migration via CCR5 and CXCR3 [DB:UniProt].","molecular_requirements":"The assertion concerns the complex with PGLYRP1, not S100A4 alone [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence.","localisation_and_range":"S100A4 is flagged secreted and CXCR3 transmembrane [flag].","caveats":"Two papers judged abstract_insufficient; no curator-verified evidence for direct S100A4-CXCR3 binding. Treat as database-asserted.","key_references":[],"covers":["LR003216","LR006434"]},"LR006443":{"pair":"S100A8 -> CD68","headline":"Recombinant rat S100A8 binds CD68 in ELISA and affinity chromatography, glycosylation-dependent; abstract-only.","interaction_type":"direct binding","direction_and_effect":"S100A8 and S100A9 bound CD68 but not CD14; anti-CD68 antibody suppressed S100A8/S100A9 expression and CD68 siRNA reduced macrophage activation by r-S100A8 or r-S100A9 [PMID:27312849].","molecular_requirements":"Less S100A8 bound macrophages after deglycosylation; anti-TLR4 or anti-RAGE antibodies suppressed r-S100A9-induced IL-1beta, so other receptors may cooperate [PMID:27312849].","affinity_potency":[],"species_and_systems":"Recombinant rat proteins and macrophages; human and mouse pairs are both projected [PMID:27312849].","localisation_and_range":"S100A8 is flagged secreted [flag].","caveats":"Abstract only. Both interactions are ortholog-inferred from rat data. No affinity reported.","key_references":[{"PMID":"27312849","why":"S100A8 and S100A9 binding to CD68"}],"covers":["LR003226","LR006443"]},"LR006452":{"pair":"S100A9 -> CD14","headline":"CD14 binds S100A9 by SPR and is required for its endocytosis and cytokine response; works as a TLR4 co-receptor (abstract-only).","interaction_type":"direct binding","direction_and_effect":"Saturable S100A9 binding to CD14 was detected by surface plasmon resonance; the S100A9-induced cytokine response was inhibited in CD14-deficient cells and by CD14 blocking antibodies, and S100A9 was not internalized into CD14-deficient cells [PMID:27228163]. Authors conclude CD14 is a co-receptor of TLR4 [PMID:27228163]. Agonist-like.","molecular_requirements":"CD14 acts with TLR4: stimulation of monocytes by S100A9 was strictly TLR4-dependent, while CD14 mediated binding and endocytosis [PMID:27228163]. Both are needed for signalling in this system.","affinity_potency":[],"species_and_systems":"Human monocytes, CD14- and TLR4-deficient cells; SPR with recombinant proteins; mouse pair is ortholog-inferred [PMID:27228163].","localisation_and_range":"Ligand secreted [flag]; CD14 also flagged secreted [flag] (soluble form possible). S100A9 was seen on membrane subdomains and in early endosomes [PMID:27228163].","caveats":"Abstract only; no Kd reported in our evidence. CD14 is a co-receptor and does not signal alone.","key_references":[{"PMID":"27228163","why":"SPR binding and CD14 requirement for S100A9 responses"}],"covers":["LR003235","LR006452"]},"LR003239":{"pair":"S100A9 -> CD69","headline":"The S100A8/S100A9 complex binds CD69 on human PBMCs; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"The S100A8/S100A9 complex was identified as the natural ligand of CD69 in human PBMCs, confirmed by in vitro binding and competition assay; association was required for SOCS3 up-regulation, inhibited STAT3 signalling and supported Treg differentiation [PMID:26296369]. UniProt records the interaction [DB:UniProt]. Agonist-like.","molecular_requirements":"Complex-level ligand; S100A9 alone is not separated in our evidence. Binding was significantly abolished by peptide-N-glycosidase treatment of CD69, so CD69 glycosylation is required [PMID:26296369].","affinity_potency":[],"species_and_systems":"Human PBMCs and in vitro binding; mouse pair is ortholog-inferred [PMID:26296369].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. CD69 flagged as receptor [flag].","caveats":"Abstract only. UniProt cites the same paper, so is not independent. No affinity.","key_references":[{"PMID":"26296369","why":"S100A8/S100A9 as CD69 ligand"}],"covers":["LR003239","LR006455"]},"LR006461":{"pair":"SCGB1A1 -> CUBN","headline":"CCSP (SCGB1A1) binds cubilin by SPR and is taken up through it; supported by one study.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance showed CCSP binds cubilin, and binding led to uptake and lysosomal degradation of CCSP in cultured cells; cubilin-deficient patients excrete CCSP in urine [PMID:11278724]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Megalin acts as an endocytic co-receptor that associates with cubilin [PMID:11278724].","affinity_potency":[],"species_and_systems":"Human CCSP and cubilin; SPR and cultured cells, plus patient observations. Mouse pair is ortholog-inferred [PMID:11278724].","localisation_and_range":"CCSP is secreted [flag]; cubilin is a peripheral membrane protein on proximal tubular cells [PMID:11278724].","caveats":"Abstract only; no affinity value in our evidence. Role is clearance/uptake rather than classical signalling.","key_references":[{"PMID":"11278724","why":"SPR binding of CCSP to cubilin and uptake"}],"covers":["LR003245","LR006461"]},"LR003248":{"pair":"SCRG1 -> BST1","headline":"SCRG1 is proposed as a ligand of BST1 on human mesenchymal stem cells; one paper, functional plus co-IP, no affinity.","interaction_type":"functional only","direction_and_effect":"SCRG1 acts as an agonist: recombinant SCRG1 drives Akt, ERK and FAK phosphorylation and migration, and BST1 knockdown suppresses the Akt, ERK and FAK responses [PMID:24413464].","molecular_requirements":"BST1 appears to work with beta1 integrin: immunoprecipitated SCRG1-FLAG pulled down beta1 integrin and BST1, suggesting a BST1/beta1-integrin receptor complex. UE7T-13 cells lacked beta2 integrin [PMID:24413464].","affinity_potency":[],"species_and_systems":"Human mesenchymal stem cells (UE7T-13 line), human ligand and receptor, recombinant SCRG1 and siRNA knockdown [PMID:24413464]. Mouse pair is projected from human.","localisation_and_range":"SCRG1 is flagged secreted [flag]; the paper describes it as secreted from hMSCs and autocrine [PMID:24413464].","caveats":"Only one paper, read from abstract plus excerpts. Binding is inferred from co-IP and knockdown, not purified-protein binding; no affinity reported. Not reported in our evidence whether SCRG1 binds BST1 directly without integrin.","key_references":[{"PMID":"24413464","why":"Identifies BST1 as the SCRG1 receptor in hMSCs; knockdown and co-IP"}],"covers":["LR003248","LR006464"]},"LR006470":{"pair":"SDC2 -> ADGRA2","headline":"SDC2 guides were enriched in an ADGRA2 binding-probe CRISPRa screen; one screen, no direct binding test.","interaction_type":"functional only","direction_and_effect":"SDC1 and SDC2 guides were enriched in an ADGRA2 ligand selection, consistent with known ADGRA2-glycosaminoglycan interactions; effect direction is not reported in our evidence [PMID:30477585].","molecular_requirements":"Syndecans are heparan sulfate proteoglycans, so glycosaminoglycan chains may matter [PMID:30477585]; not tested directly.","affinity_potency":[],"species_and_systems":"Genome-wide CRISPRa in cells selected with a recombinant ADGRA2 probe; a single screen per bait [PMID:30477585]. Species not reported in our evidence.","localisation_and_range":"SDC2 is flagged transmembrane and not secreted [flag], so contact-dependent signalling is plausible, but this is from annotation only.","caveats":"Indirect enrichment evidence only; the same sentence covers SDC1 and SDC2. Not validated by a binding assay in our evidence.","key_references":[{"PMID":"30477585","why":"CRISPRa selection enriched SDC1 and SDC2 guides with ADGRA2 probe"}],"covers":["LR003254","LR006470"]},"LR003257":{"pair":"SELENOP -> LRP5","headline":"SELENOP co-immunoprecipitates with LRP5 and LRP6 and amplifies WNT signalling; one paper with full text, interaction shown mainly for LRP6.","interaction_type":"direct binding","direction_and_effect":"SELENOP increased canonical WNT signalling; a SELENOP form lacking residues 258-299 failed to co-immunoprecipitate with FLAG-mLRP5 and decreased the WNT3A-induced TOPFlash effect, so the LRP5/6 interaction contributes to the effect [PMID:37166989]. SELENOP also promoted LRP6 internalization [PMID:37166989].","molecular_requirements":"The SELENOP region U258-U299 mediates LRP5/6 interaction; heparin prevented and HSPG-synthesis inhibition enhanced SELENOP-LRP6 co-IP [PMID:37166989]. LRP5 co-IP was shown with mouse constructs only (supplemental figure) [PMID:37166989].","affinity_potency":[],"species_and_systems":"Mouse SELENOP and mouse LRP5 constructs in 293T cells; mouse Apc-deletion adenoma model and organoids; human scRNA-seq expression [PMID:37166989].","localisation_and_range":"SELENOP is annotated secreted [flag]; paracrine or endocrine action is plausible but the paper mainly addresses epithelial and stromal expression in colon [PMID:37166989].","caveats":"Co-IP and proximity ligation are not affinity measurements; most direct data are for LRP6, with LRP5 shown for the deletion mutant only. Curator notes record the LRP5 row as direct binding, which co-IP alone does not prove. Paper is the sole support; no database records.","key_references":[{"PMID":"37166989","why":"SELENOP-LRP5/6 interaction and WNT signalling in colorectal cancer"}],"covers":["LR003257","LR006473"]},"LR004733":{"pair":"SELPLG -> SELE","headline":"Well supported E-selectin ligand: binding, kinetics and function across several papers; requires sialyl Lewis x glycans.","interaction_type":"direct binding","direction_and_effect":"PSGL-1 serves as an E-selectin ligand under flow [PMID:11402070] [PMID:9128259]. E-selectin-Fc, described as agonistic, protected myeloma cells from melphalan, and PSGL-1 knockdown or blocking antibodies abolished macrophage protection [PMID:22996336].","molecular_requirements":"Needs sialylated, fucosylated core 2 O-glycans; tyrosine sulfation is needed for P- but not E-selectin [PMID:8621728]. Sialyl Lewis x on Thr16 within the first 19 residues suffices, with more than one E-selectin site [PMID:9128259]. Binding needs sialyl Lewis x on O- and N-glycans [PMID:26124272].","affinity_potency":[],"species_and_systems":"Human cells and proteins: CHO transfectants, hematopoietic progenitor cells, SPR with native ligands from extracts, myeloma-macrophage cocultures plus a SCID mouse model [PMID:8621728] [PMID:11402070] [PMID:26124272] [PMID:22996336]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both annotated membrane-bound [flag]; contact-dependent rolling adhesion [PMID:9128259].","caveats":"Glycoform-dependent. Monomeric E-selectin binds with fast on/off rates and dimeric with slow ones [PMID:26124272]. CD44 is a stronger E-selectin ligand on progenitor cells [PMID:11402070]. Most papers read as abstract only; 22996336 does not separate E- from P-selectin in the abstract. Database records: Reactome, IntAct [DB:Reactome] [DB:IntAct].","key_references":[{"PMID":"9128259","why":"PSGL-1 N-terminal determinants for E-selectin rolling"},{"PMID":"26124272","why":"SPR kinetics of E-selectin with native PSGL-1"},{"PMID":"8621728","why":"glycosylation and sulfation requirements"}],"covers":["LR001337","LR004733"]},"LR004742":{"pair":"SEMA3B -> NRP1","headline":"SEMA3B binds NRP1 in binding assays and co-immunoprecipitation; supported by two papers.","interaction_type":"direct binding","direction_and_effect":"SEMA3B (SemA) binds NRP1; in colorectal carcinoma cells SEMA3B competitively inhibits VEGF signalling by binding NRP1 [PMID:37701532]. Interaction class is stimulatory [flag].","molecular_requirements":"Not reported in our evidence beyond NRP1 binding; co-IP showed both SEMA3B and VEGF bind NRP1 but not each other [PMID:37701532].","affinity_potency":[],"species_and_systems":"Colorectal carcinoma cells [PMID:37701532]; AP-fusion binding to mouse NP-1 [PMID:10196546]. Human pair is ortholog-inferred from mouse [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"The 1998 paper uses SemA nomenclature and the quote is browser-read, spot-check pending [PMID:10196546]. No affinity values in our evidence.","key_references":[{"PMID":"10196546","why":"AP-fusion binding of SemA to mouse NP-1"},{"PMID":"37701532","why":"SEMA3B-NRP1 co-IP and VEGF competition in CRC cells"}],"covers":["LR001346","LR004742"]},"LR008027":{"pair":"SEMA3B -> NRP1:PLXNA2:PLXNA4","headline":"Functional silencing data (abstract only) imply a Sema3B receptor complex of plexin-A2, plexin-A4 and one neuropilin.","interaction_type":"functional only","direction_and_effect":"Plexin-A2 silencing completely abolished Sema3B signalling, which also required plexin-A4 and one of the two neuropilins [PMID:25335892]. Effect agonist.","molecular_requirements":"Requires plexin-A2 and plexin-A4 plus either NRP1 or NRP2; this row is the NRP1 variant and the abstract does not say which neuropilin is preferred [PMID:25335892].","affinity_potency":[],"species_and_systems":"Endothelial and glioblastoma cells, labelled human in the dossier [PMID:25335892].","localisation_and_range":"Sema3B is flagged secreted [flag]; receptor is a membrane complex.","caveats":"Single paper read as abstract only; the three-subunit complex is inferred from separate requirements, not shown as an assembled complex.","key_references":[{"PMID":"25335892","why":"Plexin-A2 silencing abolishes Sema3B signalling; A4 and a neuropilin also required"}],"covers":["LR008027"]},"LR001349":{"pair":"SEMA3C -> NRP2","headline":"Single 1997 abstract-level binding paper reports NRP2 does not bind Sema III but binds Sema E, which the curators map to SEMA3C.","interaction_type":"direct binding","direction_and_effect":"The paper reports that neuropilin-2 shows high-affinity binding only to Sema E and Sema IV, not Sema III [PMID:9331348]. The curator labels the effect agonist and maps Sema E to SEMA3C.","molecular_requirements":"Neuropilins are described as receptors or components of receptors; any plexin co-receptor requirement is not reported in our evidence [PMID:9331348].","affinity_potency":[],"species_and_systems":"Human ligand and receptor were recorded for the experiment [PMID:9331348]. Both the human and mouse pair are ortholog-inferred, not tested in mouse.","localisation_and_range":"SEMA3C is annotated as secreted and NRP2 as transmembrane [flag].","caveats":"Abstract-only read; no affinity value in our evidence. The mouse and human pairs are projected from this evidence. Other judged rows (review_only, abstract_insufficient, different_entity) are not shown.","key_references":[{"PMID":"9331348","why":"Identifies NRP2 and its Sema E/Sema IV binding specificity"}],"covers":["LR001349","LR004745"]},"LR003266":{"pair":"SEMA3C -> PLXNA4","headline":"SEMA3C signals through a PlexinA4:PlexinD1 complex without neuropilins in U87MG cells; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"Sema3C induced contraction and repulsion of plexin-D1-expressing U87MG cells with both neuropilins knocked out [PMID:29661844]. The curator labels the effect antagonist.","molecular_requirements":"In the absence of neuropilins, plexin-A4 formed complexes with plexin-D1 and was required in addition to plexin-D1 for Sema3C signal transduction [PMID:29661844]. Plexin-A4 alone is therefore not sufficient. Neuropilins act as enhancers: EC50 was 5.5 times higher without them [PMID:29661844].","affinity_potency":[],"species_and_systems":"Human U87MG glioblastoma cells with recombinant plexin-D1 and CRISPR neuropilin knockout [PMID:29661844]. The mouse pair is ortholog-inferred.","localisation_and_range":"SEMA3C is annotated as secreted [flag], so signalling is expected to be paracrine or autocrine. PLXNA4 is annotated transmembrane [flag].","caveats":"Abstract-only read. No direct PlexinA4 binding to SEMA3C is shown; U87MG cells with class-A plexins overexpressed did not contract to Sema3C without plexin-D1 [PMID:29661844]. Pair is better read as the PlexinA4:PlexinD1 complex.","key_references":[{"PMID":"29661844","why":"Plexin-A4 plus plexin-D1 convey Sema3C signals without neuropilins"}],"covers":["LR003266","LR006482"]},"LR004751":{"pair":"SEMA3F -> PLXNA1","headline":"Weak support: one paper whose evidence sentence is a cited reference title; no direct SEMA3F-PLXNA1 result is shown.","interaction_type":"functional only","direction_and_effect":"The only paper concerns Sema3A signalling through PlexinA1/NP1 and says Sema3F is an NP1 antagonist [PMID:11239433]. No SEMA3F-PLXNA1 interaction result is reported in the shown excerpts.","molecular_requirements":"Not reported in our evidence for SEMA3F. The paper reports PlexinA1 activation depends on NP1 for Sema3A [PMID:11239433].","affinity_potency":[],"species_and_systems":"Curator labelled mouse/mouse [PMID:11239433].","localisation_and_range":"Not reported in our evidence beyond SEMA3F being flagged secreted [flag].","caveats":"Evidence sentence is the title of a cited NRP2 paper (a reference list entry), not a result of this paper. Two further rows were abstract_insufficient.","key_references":[{"PMID":"11239433","why":"only paper; does not test SEMA3F-PLXNA1 directly"}],"covers":["LR001355","LR004751"]},"LR001358":{"pair":"SEMA4A -> PLXND1","headline":"Sema4A acts on Plexin-D1 in endothelial cells and macrophages; binding and functional evidence, but only abstracts read.","interaction_type":"direct binding","direction_and_effect":"Sema4A suppresses VEGF-mediated endothelial migration, proliferation and angiogenesis via Plexin-D1, labelled antagonist by curators [PMID:17318185]. In macrophages, Sema4A acting via PlexinD1 increased migration and enhanced VEGF-A expression, a pro-angiogenic effect [PMID:22442441]. The effect is therefore context-dependent.","molecular_requirements":"Plexin-D1 alone is named as the receptor; no co-receptor is reported in our evidence. Sema4A uses TIM-2 rather than Plexin-D1 in T cells [PMID:17318185].","affinity_potency":[],"species_and_systems":"Endothelial cells (human labels, Sema4a-null mice used) [PMID:17318185]; mouse macrophages and mouse peritonitis and ischemia/reperfusion models [PMID:22442441]. The mouse pair is ortholog-inferred. IntAct lists surface plasmon resonance and solid-phase assays [DB:IntAct]; Reactome has a binding reaction [DB:Reactome].","localisation_and_range":"Ligand flagged both secreted and transmembrane [flag]; paper text does not settle the range.","caveats":"Both papers were read as abstracts only. Opposite functional valences between endothelium and macrophages. Binding in 17318185 is described only as 'binding and functional experiments'.","key_references":[{"PMID":"17318185","why":"Sema4A-Plexin-D1 binding and anti-angiogenic function"},{"PMID":"22442441","why":"Sema4A via PlexinD1 in macrophages"}],"covers":["LR001358","LR004754"]},"LR004760":{"pair":"SEMA4G -> PLXNB2","headline":"Sema4G is a minor Plexin-B2 ligand in cerebellar development; one paper, with limited effect when deleted alone.","interaction_type":"direct binding","direction_and_effect":"Sema4G protein specifically bound Plexin-B2-expressing cerebellar granule cells, and Sema4G elicited migration of wild-type but not Plxnb2-/- granule cell precursors, indicating Plexin-B2 mediation [PMID:21122816].","molecular_requirements":"Plexin-B2 alone named. Sema4C and Sema4G appear to act in parallel as Plexin-B2 ligands [PMID:21122816].","affinity_potency":[],"species_and_systems":"Mouse knockouts and cerebellar cells (dossier labels species human) [PMID:21122816]. Human pair is ortholog-inferred.","localisation_and_range":"Sema4G flagged transmembrane, not secreted [flag].","caveats":"Sema4G deletion alone caused no overt phenotype; double deletion with Sema4C was less severe than Plexin-B2 loss, suggesting other ligands [PMID:21122816]. Binding claim read from abstract plus excerpts. No database support.","key_references":[{"PMID":"21122816","why":"Sema4C and Sema4G as Plexin-B2 ligands"}],"covers":["LR001364","LR004760"]},"LR001367":{"pair":"SEMA6A -> PLXNA4","headline":"Plexin-A4 is reported to bind Sema6A and mediate repulsion independently of neuropilin-1; a cis interaction can also inhibit responses.","interaction_type":"direct binding","direction_and_effect":"Plexin-A4 bound Sema6A (and Sema6B) and mediated their axon-repulsive activity independently of neuropilin-1 [PMID:15814794]. Co-expression of Sema6A and Plexin-A4 hindered binding of exogenous ligand, suggesting a cis interaction that inhibits responsiveness [PMID:20606624].","molecular_requirements":"Neuropilin-1 is not required for the Sema6A response [PMID:15814794]. The Reactome complex also lists PLXNA2 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse knockouts and neurons in the first paper; heterologous cell systems and sympathetic/sensory neurons in the second. Curator species fields say human; the abstracts describe mice, so check.","localisation_and_range":"Membrane-bound ligand [flag]; signals in trans between cells or inhibits in cis on the same cell [PMID:20606624].","caveats":"Both read as abstracts only. The cis interaction is inhibitory, opposite to trans signalling, which affects how co-expression should be interpreted.","key_references":[{"PMID":"15814794","why":"Plexin-A4 binds Sema6A/6B independently of neuropilin-1"},{"PMID":"20606624","why":"Cis Sema6A-Plexin-A4 interaction inhibits response"}],"covers":["LR001367","LR004763"]},"LR001970":{"pair":"SEMA6B -> PLXNA2","headline":"One abstract-only chick study reports Sema6B binding floorplate PlxnA2, with Sema6B acting as the receptor side.","interaction_type":"direct binding","direction_and_effect":"Sema6B binds floorplate-derived plexin A2 for post-crossing commissural axon navigation; a truncated Sema6B lacking the intracellular domain could not rescue, so Sema6B itself signals as a receptor [PMID:25209245]. A separate cis interaction between PlxnA2 and Sema6B on pre-crossing axons may regulate responsiveness [PMID:25209245].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Chick spinal cord commissural neurons per the abstract; curator species fields say human, and the dossier pairs are ortholog-inferred.","localisation_and_range":"Transmembrane semaphorin acting in trans from floorplate to axons, and possibly in cis [PMID:25209245].","caveats":"Abstract only, one paper; the direction is reversed in this system (Sema6B as receptor, PlxnA2 as the cue), and no affinity is reported.","key_references":[{"PMID":"25209245","why":"Sema6B binds floorplate PlxnA2 in chick commissural guidance"}],"covers":["LR001970","LR005300"]},"LR003284":{"pair":"SEMA6C -> PLXNA1","headline":"Mouse abstract states PlexinA1 is the proprioceptive axon receptor for Sema6C; support is functional loss-of-function, abstract only.","interaction_type":"functional only","direction_and_effect":"PlexinA1 is described as a proprioceptive sensory axon-specific receptor for sema6C and sema6D; loss of plexinA1 signalling causes proprioceptive axons to invade the superficial dorsal horn [PMID:17145500].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse plexinA1 mutant spinal cord; human pair is ortholog-inferred, mouse pair is not.","localisation_and_range":"Ligand is not flagged secreted, so likely membrane-associated; the abstract describes sema6C/6D expressed in the dorsal horn [PMID:17145500].","caveats":"Abstract only; no binding or affinity data in our evidence. The Sema6C-specific effect is not separated from Sema6D. Other judged rows were abstract_insufficient.","key_references":[{"PMID":"17145500","why":"PlexinA1 as receptor for sema6C/6D in proprioceptive axon segregation"}],"covers":["LR003284","LR006500"]},"LR009035":{"pair":"SEMA6D -> TREM2","headline":"Database-asserted only, as a member of a larger complex; no paper evidence for a direct SEMA6D-TREM2 interaction.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists SEMA6D binding to PLXNA1:TREM2:DAP12 [DB:Reactome]. UniProt describes SEMA6D receptor function in dendritic cells with PLEXNA1 as coreceptor [DB:UniProt]. Direct SEMA6D-TREM2 binding is not stated in our evidence.","molecular_requirements":"TREM2 appears with PLXNA1 and DAP12 in the Reactome complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human entities; no experiment in our evidence.","localisation_and_range":"Ligand flagged membrane-bound; TREM2 flagged secreted [flag].","caveats":"Class is Receptor-Receptor; support is complex membership only; the one paper row was a different entity.","key_references":[],"covers":["LR009035"]},"LR001376":{"pair":"SERPINE1 -> PLAUR","headline":"Only one functional mouse neuron paper supports PAI-1 acting through PLAUR; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"Mouse PLAUR-positive sensory neurons responded to Serpin E1 with enrichment of itch- and inflammation-related genes and protein release; a Serpin E1 inhibitor reduced MC903-induced itch [PMID:35596683]. The authors call PLAUR a putative receptor and place it with TLR2 in the signalling axis [PMID:35596683].","molecular_requirements":"PLAUR resides in TLR2-positive neurons and the response involves TLR2 and co-signalling proteins [PMID:35596683]; direct binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse sensory neurons and an MC903 atopic-dermatitis-like mouse model, with human skin expression data and human keratinocyte assays [PMID:35596683]. The human pair is ortholog-projected; the mouse pair is not.","localisation_and_range":"PLAUR is flagged secreted, receptor and transmembrane [flag]; neuron-skin paracrine communication is proposed [PMID:35596683].","caveats":"Single abstract-level curated paper; the paper describes PLAUR as putative and states receptors in Serpin E1 itch were not clarified before. One more row is pending.","key_references":[{"PMID":"35596683","why":"Serpin E1 acts on PLAUR-positive sensory neurons in itch"}],"covers":["LR001376","LR004771"]},"LR006506":{"pair":"SERPINE1 -> VLDLR","headline":"uPA:PAI-1 complex binds purified VLDL receptor with high affinity and is internalised; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"uPA complexed with PAI-1 bound purified VLDL receptor with high affinity; VLDLR-expressing fibroblasts internalised and degraded 125I-labelled complexes, while non-infected fibroblasts did not [PMID:7592875].","molecular_requirements":"The bound ligand is the uPA:PAI-1 complex; free PAI-1 is not reported [PMID:7592875].","affinity_potency":[],"species_and_systems":"Purified receptor and mouse embryonic fibroblasts deficient in VLDLR and LRP, rescued with an adenoviral VLDLR vector [PMID:7592875]. Mouse pair is ortholog-projected.","localisation_and_range":"VLDLR is flagged as a receptor and transmembrane [flag]; endocytic clearance.","caveats":"One paper, abstract only; the curated evidence sentence concerns lipoprotein lipase, not PAI-1.","key_references":[{"PMID":"7592875","why":"uPA:PAI-1 binding and internalisation by VLDL receptor"}],"covers":["LR003290","LR006506"]},"LR003293":{"pair":"SFTPA1 -> LRP1","headline":"SP-A collagenous tails bind a calreticulin/CD91 complex and are pro-inflammatory; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Collagenous tails stimulate proinflammatory mediator production and phagocytosis through binding to calreticulin/CD91; agonist-like [PMID:14531999].","molecular_requirements":"The curator notes LRP1/CD91 may need calreticulin as an obligate co-receptor partner, so LRP1 alone may not be the direct binding partner [PMID:14531999].","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; the human and mouse pairs are both ortholog-inferred [PMID:14531999].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"Single abstract-only paper; binding is to a calreticulin/CD91 complex, not demonstrated for LRP1 alone. The paper covers SP-A and SP-D without distinguishing SFTPA1.","key_references":[{"PMID":"14531999","why":"Dual-function collectin model: tails bind calreticulin/CD91"}],"covers":["LR003293","LR006509"]},"LR006515":{"pair":"SFTPD -> TLR2","headline":"SP-D binds the soluble TLR2 extracellular domain via its CRD; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Natural and recombinant SP-D showed specific binding to soluble TLR2 extracellular domain [PMID:16834340]; functional effect is not reported in our evidence.","molecular_requirements":"Binding is concentration- and Ca2+-dependent, including to deglycosylated receptor, and blocked by a CRD-epitope antibody [PMID:16834340]. Reactome lists TLR2:TLR1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Recombinant soluble human TLR2 with natural and recombinant human SP-D; mouse pair is ortholog-inferred [PMID:16834340].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"16834340","why":"SP-D binds sTLR2 and sTLR4 through the CRD"}],"covers":["LR003301","LR006515"]},"LR010880":{"pair":"SHANK1 -> ABCA1","headline":"Database-only protein-protein interaction record; SHANK1 is not a secreted ligand, so a ligand-receptor reading is doubtful.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; the only support is direct interaction by holdup assay [DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system: direct interaction by holdup assay [DB:IntAct]. Species is human per the pair record.","localisation_and_range":"SHANK1 has no secreted flag in the dossier; localisation as a ligand is not reported in our evidence.","caveats":"Rests on database records only; the judged paper rows were assigned to a different entity.","key_references":[],"covers":["LR010880"]},"LR001385":{"pair":"SHH -> BOC","headline":"SHH binds BOC and BOC acts as an SHH receptor in axon guidance and patterning; two abstract-level papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Agonist: Boc and Cdo bind Shh through a high-affinity interaction with a specific fibronectin repeat that is essential for activity [PMID:16647304]; Boc knockdown impairs commissural axon turning toward a Shh source [PMID:17086203].","molecular_requirements":"Binding involves a specific fibronectin repeat [PMID:16647304]. Reactome lists a Hh-Npp:BOC:PTCH1 complex, suggesting PTCH1 involvement [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse genetics and mouse and rat neurons in vitro [PMID:16647304] [PMID:17086203]; the dossier lists the human pair with mouse ortholog-inferred.","localisation_and_range":"SHH is flagged secreted [flag].","caveats":"Both papers abstract-only; no numeric affinity is given though 'high-affinity' is stated. CDO/CDON also binds Shh in both papers.","key_references":[{"PMID":"16647304","why":"Cdo and Boc bind Shh via a fibronectin repeat"},{"PMID":"17086203","why":"Boc as Shh receptor in commissural axon guidance"}],"covers":["LR001385","LR004780"]},"LR001394":{"pair":"SLIT2 -> GPC1","headline":"SLIT2 binds glypican-1 with Kd 80-110 nM; heparan sulfate dependent, supported by two papers and BioGRID/Reactome.","interaction_type":"direct binding","direction_and_effect":"Glypican-1 is a Slit2 ligand-binding partner; Slit proteins were isolated from rat brain on a glypican-Fc matrix [PMID:10364234]. Binding was saturable and reversible [PMID:11375980]. Functional effect on glypican-1-bearing cells is not reported in our evidence.","molecular_requirements":"Binding needs glypican heparan sulfate chains [PMID:10364234]; heparin, heparitinase or chlorate cut binding 80-90% [PMID:11375980]. The glypican core protein binds Slit about an order of magnitude more weakly [PMID:11375980]. The C-terminal Slit2 fragment binds; the larger N-terminal segment binds little [PMID:11375980].","affinity_potency":[{"value":"Kd 80-110 nM","assay":"ELISA, glypican-Fc binding to Slit-2 (full-length and C-terminal fragment)","system":"recombinant human Slit-2, glypican-Fc","cite":"PMID:11375980"}],"species_and_systems":"Rat brain extract with human glypican-Fc [PMID:10364234]; recombinant human Slit-2 and 293-cell co-transfection immunoprecipitation [PMID:11375980]. Mouse pair is ortholog-inferred.","localisation_and_range":"Glypican-1 is a GPI-anchored membrane proteoglycan; the C-terminal Slit2 portion is released from the cell membrane [PMID:11375980]. Colocalisation in embryonic and adult CNS [PMID:11375980]. Interactions also in BioGRID and Reactome [DB:BioGRID][DB:Reactome].","caveats":"Both papers read as abstracts only. Receptor-versus-matrix-binding role of glypican is not resolved in our evidence. One pending row not shown.","key_references":[{"PMID":"11375980","why":"Kd 80-110 nM, fragment and HS dependence"},{"PMID":"10364234","why":"Slit1/2 isolated on glypican-1-Fc"}],"covers":["LR001394","LR004789"]},"LR005318":{"pair":"SLITRK1 -> PTPRS","headline":"SLITRK1-PTPsigma is supported by cell aggregation and knockdown/rescue synapse assays.","interaction_type":"functional only","direction_and_effect":"Slitrk1-expressing cells aggregated with PTPsigma-expressing cells [PMID:23345436]. The intracellular D2 domain of PTPsigma is required for heterologous synapse formation induced by Slitrk1 [PMID:29934346].","molecular_requirements":"PTPsigma intracellular D2 domain is required for Slitrk1-induced synapse formation [PMID:29934346]; extracellular interactions of PTPsigma with Slitrks matter for excitatory synapses [PMID:29934346].","affinity_potency":[],"species_and_systems":"Mouse L cells [PMID:23345436]; cultured rat hippocampal neurons [PMID:29934346]. Mouse pair ortholog-inferred.","localisation_and_range":"Both transmembrane (trans-synaptic contact) [flag][PMID:23345436].","caveats":"Direct binding is not shown in these papers; BioGRID lists a reconstituted complex [DB:BioGRID]. Second paper is abstract only. Four review-only rows not shown.","key_references":[{"PMID":"23345436","why":"Slitrk1 and PTPsigma cell aggregation"},{"PMID":"29934346","why":"PTPsigma D2 required for Slitrk1 synapse induction"}],"covers":["LR001989","LR005318"]},"LR010709":{"pair":"SLURP1 -> CHRNB4","headline":"Synthetic SLURP-1 inhibits alpha3beta4 and alpha4beta4 nAChRs in functional assays; no direct binding shown for this subunit.","interaction_type":"functional only","direction_and_effect":"Synthetic SLURP-1 inhibits human alpha3beta4 and alpha4beta4 nAChRs (antagonist); preferential inhibition of nAChRs co-expressing alpha3 and beta4 was seen. [PMID:29192197]","molecular_requirements":"Tested as heteromers with alpha subunits; beta4 alone is not reported in our evidence [PMID:29192197].","affinity_potency":[],"species_and_systems":"Human receptors expressed heterologously (two-electrode voltage clamp), synthetic human SLURP-1 tested at 10 uM [PMID:29192197].","localisation_and_range":"SLURP1 is flagged secreted [flag]; the paper describes it as a secreted protein that co-localizes with nAChRs [PMID:29192197]. ","caveats":"Curator read abstract level only. The evidence is inhibition of ACh-evoked currents, not binding. Synthetic SLURP-1 did not compete with alpha-bungarotoxin at human alpha7 or muscle-type nAChRs and did not inhibit alpha7 currents without PNU120596; earlier recombinant SLURP-1 with extensions gave conflicting results [PMID:29192197].","key_references":[{"PMID":"29192197","why":"Chemically synthesized human SLURP-1 tested on nAChR subtypes"}],"covers":["LR010709"]},"LR006533":{"pair":"SNCA -> APLP1","headline":"Pathologic alpha-synuclein fibrils bind Aplp1-transfected cells with Kd 430 nM; monomer does not bind; one paper.","interaction_type":"direct binding","direction_and_effect":"Alpha-syn pre-formed fibrils (PFF) bind Aplp1 in a saturable manner in a cell-surface binding assay [PMID:38821932]. Aplp1 interacts with Lag3 and the pair facilitates binding, internalization, transmission and toxicity of pathologic alpha-syn; anti-Lag3 blocks internalization by disrupting Aplp1-Lag3 interaction [PMID:38821932].","molecular_requirements":"The binding ligand is the fibrillar form; the curator note says the monomer does not bind [PMID:38821932]. Aplp1 works together with Lag3 for transmission [PMID:38821932].","affinity_potency":[{"value":"Kd 430 nM","assay":"cell-surface binding assay with biotinylated alpha-syn PFF","system":"Aplp1-transfected SH-SY5Y cells","cite":"PMID:38821932"}],"species_and_systems":"Aplp1-transfected SH-SY5Y cells, in vitro; in vivo knockout models in the same paper [PMID:38821932]. The mouse pair is the directly curated one; the human pair is projected from it.","localisation_and_range":"SNCA is flagged secreted and APLP1 secreted and receptor [flag]. The effect concerns cell-to-cell transmission of fibrils [PMID:38821932].","caveats":"Applies to fibrillar alpha-synuclein only, not the monomer. Binding was measured on cells, not purified proteins. The excerpt writes the constant as '15Kd of 430 nM' [PMID:38821932]. Human pair is ortholog-inferred.","key_references":[{"PMID":"38821932","why":"Aplp1 binds alpha-syn PFF and interacts with Lag3"}],"covers":["LR003326","LR006533"]},"LR005327":{"pair":"SNCA -> LAG3","headline":"LAG3 binds alpha-synuclein pre-formed fibrils with Kd 77 nM; monomer binds minimally; supported by BioGRID.","interaction_type":"direct binding","direction_and_effect":"LAG3 binds alpha-syn PFF; binding initiated PFF endocytosis, transmission and toxicity, and loss of LAG3 delayed PFF-induced dopamine neuron loss in vivo [PMID:27708076].","molecular_requirements":"Fibrillar alpha-syn is the binding form; the monomer showed minimal binding [PMID:27708076]. Other co-receptors are not reported in this abstract.","affinity_potency":[{"value":"Kd 77 nM","assay":"biochemical binding assay (recombinant proteins), per curator","system":"alpha-syn PFF with LAG3","cite":"PMID:27708076"}],"species_and_systems":"Both human and mouse pairs are curated directly; experimental species are not stated in the abstract. Recombinant proteins, cells and in vivo knockout [PMID:27708076].","localisation_and_range":"SNCA is flagged secreted; LAG3 is flagged receptor and transmembrane, so it acts as a membrane receptor [flag]. Cell-to-cell spread is the proposed route [PMID:27708076].","caveats":"Paper read as abstract only. BioGRID lists an affinity capture-Western record from a different paper (34309222) [DB:BioGRID]. Only fibrillar, not monomeric, alpha-syn binds well.","key_references":[{"PMID":"27708076","why":"LAG3 binds alpha-syn PFF with Kd 77 nM and mediates transmission"}],"covers":["LR001999","LR005327"]},"LR003329":{"pair":"SPARC -> STAB1","headline":"SPARC binds the scavenger receptor stabilin-1, which mediates its endocytosis; one abstract-level paper plus a generic Reactome entry.","interaction_type":"direct binding","direction_and_effect":"SPARC interacts with stabilin-1 by phage display and in vitro binding; stabilin-1 internalises SPARC to an endosomal pathway and is required for its endocytosis in human macrophages, followed by degradation [PMID:16670288]. Scavenger/clearance receptor, not a signalling agonist.","molecular_requirements":"Binding is mediated by stabilin-1's extracellular EGF-like region containing the sequence FHGTAC [PMID:16670288].","affinity_potency":[],"species_and_systems":"CHO cells stably transfected with stabilin-1 and human macrophages; clearance was most efficient in IL-4/dexamethasone alternatively activated macrophages, not Th1/Th2 cytokines alone [PMID:16670288]. Mouse pair ortholog-inferred.","localisation_and_range":"SPARC flagged secreted [flag]; cell-surface receptor on macrophages.","caveats":"Abstract only. Reactome records are a generic STAB1 ligand-binding reaction [DB:Reactome]. No affinity.","key_references":[{"PMID":"16670288","why":"SPARC binds stabilin-1; clearance by alternatively activated macrophages"}],"covers":["LR003329","LR006536"]},"LR005336":{"pair":"SPON2 -> ITGB1","headline":"Mindin engages beta1 integrins in DC adhesion and HCC signalling; antibody and knockout evidence, abstract only.","interaction_type":"functional only","direction_and_effect":"DCs lacking beta1 integrin had reduced adhesion to mindin matrix, with reduced Rac1/2 expression and priming capacity [PMID:16917498]. SPON2-alpha4beta1 signalling activated RhoA and Rac1 and promoted M1-like macrophage recruitment [PMID:29440144].","molecular_requirements":"beta1 pairs with alpha4 and alpha5 in these reports [PMID:16917498] [PMID:29440144]. beta1 alone is not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Mouse DCs, including genetic beta1-null DCs [PMID:16917498]; HCC context [PMID:29440144].","localisation_and_range":"Mindin is an extracellular matrix protein [flag].","caveats":"Abstracts only; adhesion is blocked, not binding measured directly. No affinity. The beta1 chain is evidence in complexes with alpha4 or alpha5.","key_references":[{"PMID":"16917498","why":"beta1-null DCs adhere less to mindin"},{"PMID":"29440144","why":"SPON2-alpha4beta1 signalling"}],"covers":["LR002008","LR005336"]},"LR004805":{"pair":"SST -> SSTR1","headline":"Somatostatin binds SSTR1 with high affinity in recombinant cells; well supported by several binding papers.","interaction_type":"direct binding","direction_and_effect":"Somatostatin is an agonist: SSTR1 shows specific somatostatin binding, apparently higher for somatostatin-14 than somatostatin-28 [PMID:1346068]; GtoPdb gives pKi 8.6-9.5 [DB:GtoPdb].","molecular_requirements":"SSTR1 alone is sufficient in transfected cells [PMID:1346068]. SSTR1 belongs to a pharmacological subclass (with hsstr4) reacting poorly with synthetic hexapeptide and octapeptide analogs [PMID:7988476].","affinity_potency":[{"value":"pKi 8.6-9.5","assay":"GtoPdb curated range","system":"not reported","cite":"PMID:7988476"}],"species_and_systems":"Human SSTR1 stably expressed in CHO or CCL39 cells [PMID:1346068][PMID:9650799][PMID:7988476]; mouse pair is ortholog-inferred.","localisation_and_range":"SST flagged secreted [flag]; receptor transmembrane.","caveats":"All abstract-only. PMID:9650799 uses a somatostatin-28 analogue radioligand as control, and PMID:7988476 mainly compares analogs. Four pending, two review-only and one abstract-insufficient rows are not counted.","key_references":[{"PMID":"1346068","why":"Cloning of SSTR1; specific somatostatin binding"},{"PMID":"9650799","why":"Five human SSTRs, SRIF28 analogue control"},{"PMID":"7988476","why":"Cross-subtype analog binding"}],"covers":["LR001410","LR004805"]},"LR006542":{"pair":"SVEP1 -> ITGA4","headline":"SVEP1 binds integrin alpha4beta1 in one 2022 study; support is thin and abstract-level.","interaction_type":"direct binding","direction_and_effect":"SVEP1 was found to directly bind integrin alpha4beta1 [PMID:35802072]. In that study inhibition of SVEP1 or its integrins enhanced vasoconstrictor-induced calcium; UniProt summarises that ITGA4:ITGB1 via SVEP1 represses calcium influx and inhibits vasocontraction [DB:UniProt].","molecular_requirements":"The partner is the alpha4beta1 heterodimer (ITGA4 with ITGB1) [PMID:35802072][DB:UniProt].","affinity_potency":[],"species_and_systems":"Human iPSC-derived vascular smooth muscle cells plus Svep1+/- mouse wire myography [PMID:35802072]. Mouse pair is projected from human.","localisation_and_range":"SVEP1 is flagged secreted [flag], consistent with an extracellular matrix ligand.","caveats":"One paper, read as abstract only; the binding result is a side finding reported as 'additionally found', and the functional effects are not separated by integrin. Only the alpha chain is paired here; the beta1 chain is a separate dossier.","key_references":[{"PMID":"35802072","why":"SVEP1 binds alpha4beta1 and alpha9beta1 and regulates VSMC contraction"}],"covers":["LR003335","LR006542"]},"LR003338":{"pair":"SVEP1 -> PEAR1","headline":"SVEP1 interacts with PEAR1 with high affinity and drives AKT/mTOR signalling; one human genetics and proteomics study, projected to mouse.","interaction_type":"direct binding","direction_and_effect":"The interaction promotes PEAR1 phosphorylation and AKT/mTOR signalling in vascular cells and platelets; exogenous SVEP1 induces PEAR1-dependent platelet activation, and Svep1-lacking mice have reduced platelet activation [PMID:36792666]. UniProt states the same [DB:UniProt].","molecular_requirements":"A PEAR1 missense variant p.D343N in an EGF-like domain of the ectodomain was associated with increased plasma SVEP1 [PMID:36792666]. PEAR1 is required for SVEP1-mediated platelet activation [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human genomic and proteomic data, human cells and platelets, plus mouse platelets [PMID:36792666]. Both human and mouse pairs are marked ortholog-inferred in the dossier.","localisation_and_range":"SVEP1 is flagged secreted and PEAR1 a receptor [flag]; SVEP1 is described as an extracellular matrix protein [PMID:36792666].","caveats":"Single paper read as abstract with excerpts; 'high affinity' is stated without a number in our evidence. The excerpt shown is genetic association rather than binding data.","key_references":[{"PMID":"36792666","why":"SVEP1-PEAR1 interaction, signalling and platelet activation"}],"covers":["LR003338","LR006545"]},"LR004814":{"pair":"Tac2 -> Tacr2","headline":"Mouse Tac2 to Tacr2 is ortholog-inferred; the one cited paper concerns NKA binding to human NK2, and the rest is database records.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a full agonist for TAC2-TACR2 [DB:GtoPdb]. The only paper studies mutants of the human NK2 receptor for neurokinin A binding, with no neurokinin B result in its abstract [PMID:7961636].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 5.0-7.7","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human NK2 receptor mutants [PMID:7961636]; the mouse pair is ortholog-inferred.","localisation_and_range":"Tac2 flagged secreted [flag].","caveats":"The paper is abstract only and is about neurokinin A (TAC1), so it does not directly show Tac2 binding. Most database records shown are labelled TAC1-TACR2 [DB:BioGRID] [DB:Reactome].","key_references":[{"PMID":"7961636","why":"NK2 receptor mutagenesis (neurokinin A, not Tac2)"}],"covers":["LR004814"]},"LR007415":{"pair":"TAFA1 -> GPR1","headline":"FAM19A1 (TAFA1) is reported to bind and signal through GPR1 in neural stem cells, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Agonist-like. Recombinant FAM19A1 suppressed proliferation and self-renewal of neural stem cells, GPR1 was identified as a functional receptor, and soluble GPR1-ND bound FAM19A1 and neutralised these effects [PMID:29799787].","molecular_requirements":"Interaction via the GPR1 N-terminal domain; ROCK/ERK1/2 and ROCK/STAT3 signalling were needed [PMID:29799787].","affinity_potency":[],"species_and_systems":"Recombinant protein and neural stem cells; abstract does not state species beyond the curators' human label [PMID:29799787].","localisation_and_range":"FAM19A1 is described as a classic secretory protein [PMID:29799787].","caveats":"Abstract only; single paper; no affinity reported; no database records.","key_references":[{"PMID":"29799787","why":"Identifies GPR1 as FAM19A1 receptor"}],"covers":["LR007415"]},"LR006551":{"pair":"TAFA2 -> ADGRL1","headline":"TAFA2 directly binds the lectin-like domain of ADGRL1 and is anti-apoptotic via cAMP/PKA/CREB/BCL2; abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. TAFA2 directly binds the lectin-like domain of ADGRL1, activating cAMP/PKA/CREB/BCL2 signalling that prevents cell death; recombinant TAFA2 suppressed apoptosis induced by ADGRL1 overexpression [PMID:37944639].","molecular_requirements":"The Lectin-like domain is required: ADGRL1 delta-Lec did not induce apoptosis or support TAFA2 responses [PMID:37944639].","affinity_potency":[],"species_and_systems":"Co-IP and mass spectrometry in V5 knockin mouse brain lysates, then in vitro and in vivo co-IP and pull-down, with knockout and overexpression cells [PMID:37944639].","localisation_and_range":"TAFA2 flagged secreted and ADGRL1 transmembrane [flag].","caveats":"Abstract only; one paper; no affinity reported; no database records. Species of the cells beyond mouse brain lysates is not reported in our evidence.","key_references":[{"PMID":"37944639","why":"TAFA2 binds ADGRL1 lectin-like domain and signals via cAMP/PKA/CREB"}],"covers":["LR003344","LR006551"]},"LR003347":{"pair":"TAFA2 -> KIR3DL2","headline":"TAFA2 stained KIR3DL2-expressing cells, with SPR also noted for this pair in a screening paper; binding only.","interaction_type":"direct binding","direction_and_effect":"Direction and effect are not reported in our evidence [PMID:36178190].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human TAFA2:SA-647 tetramers at 200 nM on K562 cells expressing FLAG-tagged KIR3DL2 by flow cytometry [PMID:36178190].","localisation_and_range":"TAFA2 flagged secreted; KIR3DL2 flagged transmembrane [flag].","caveats":"The source table lists this pair as a PHA prediction tested by SPR and cell surface staining; the SPR result for KIR3DL2 is not shown in the excerpts [PMID:36178190]. No affinity, no functional readout.","key_references":[{"PMID":"36178190","why":"CRISPRa screen with TAFA2-KIR staining"}],"covers":["LR003347"]},"LR003356":{"pair":"TCN2 -> CD320","headline":"Well-supported: crystal structure and high-affinity binding of holo-transcobalamin to CD320.","interaction_type":"direct binding","direction_and_effect":"CD320 captures transcobalamin (TC) from plasma for cellular vitamin B12 uptake [PMID:27411955]. The crystal structure of human holo-TC with the CD320 extracellular domain shows the interaction chemistry [PMID:27411955]. Reactome lists the TCN2:RCbl:CD320 complex at the plasma membrane [DB:Reactome].","molecular_requirements":"Both CD320 LDLR-A1 and LDLR-A2 interact with the \u03b1 domain of TC; each single domain formed a complex with TC [PMID:27411955]. The complex was 1:1 and was purified with excess cyanocobalamin, i.e. cobalamin-bound TC [PMID:27411955]. Haptocorrin binding is lacking [PMID:27411955].","affinity_potency":[{"value":"KD ~1.5 nM","assay":"solid-phase binding assay","system":"recombinant human TC and CD320","cite":"PMID:27411955"}],"species_and_systems":"Recombinant human proteins [PMID:27411955]; structures PDB 4ZRP and others [DB:PDB 4ZRP]. Mouse pair is projected by orthology.","localisation_and_range":"TCN2 is annotated secreted and CD320 as a transmembrane receptor [flag]; TC is captured from plasma [PMID:27411955].","caveats":"Abstract plus excerpts only; in vivo function not covered by our evidence. IntAct also lists the interaction [DB:IntAct].","key_references":[{"PMID":"27411955","why":"Crystal structure and affinity of TC-CD320"}],"covers":["LR003356","LR006559"]},"LR006560":{"pair":"TENM2 -> ADGRL1","headline":"Well-supported adhesion pair: teneurin-2 (Lasso) and latrophilin-1 co-purify, bind and attract cells; rat brain and HEK293T data.","interaction_type":"direct binding","direction_and_effect":"LPH1 and Lasso (a teneurin-2 splice variant) interact strongly and specifically and are always co-purified from rat brain extracts [PMID:21724987]. Co-culturing LPH1 and Lasso cells led to mutual attraction and junction formation; a C-terminal Lasso fragment induced Ca2+ signals in presynaptic boutons [PMID:21724987]. Pulldown showed Ten2 and Ten4, but not Ten1, binding all Lphn1 constructs [PMID:24273166].","molecular_requirements":"Lectin-like domain of latrophilins is the teneurin-binding region; Lphn1 splicing modulates teneurin binding but not FLRT3 binding [PMID:24273166]. Lasso is a teneurin-2 splice variant [PMID:21724987].","affinity_potency":[],"species_and_systems":"Rat brain purification, cell cocultures, hippocampal neurons [PMID:21724987]; HEK293T-derived teneurin ectodomains and Lphn1-Ig [PMID:24273166]. Human and mouse pairs are ortholog-inferred. UniProt records the ligand role [DB:UniProt].","localisation_and_range":"Both transmembrane [flag]; LPH1 is presynaptic and Lasso postsynaptic, a trans-synaptic contact interaction [PMID:21724987].","caveats":"One key paper was read as abstract only [PMID:21724987]. Affinity values not in our excerpts.","key_references":[{"PMID":"21724987","why":"Purifies Lasso/teneurin-2 as the LPH1 ligand"},{"PMID":"24273166","why":"Pulldowns show Ten2 binding to Lphn1 lectin domain"}],"covers":["LR003357","LR006560"]},"LR003365":{"pair":"TFF2 -> FCRL4","headline":"No verified paper; support rests on IntAct records from a protein-array screen.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records cite one screen paper: protein array and a direct interaction by surface plasmon resonance [DB:IntAct]. Species not stated.","localisation_and_range":"TFF2 is annotated secreted [flag].","caveats":"The one judged read of the paper was abstract-insufficient, so no curator-verified evidence exists. Support is database-only.","key_references":[],"covers":["LR003365"]},"LR005345":{"pair":"TFF3 -> CXCR4","headline":"Functional and modelling evidence that CXCR4 contributes to TFF3-induced migration; no binding data.","interaction_type":"functional only","direction_and_effect":"TFF3 stimulated cell migration in a conjunctival epithelial cell line, completely suppressed by blocking CXCR4 and/or CXCR7 [PMID:26780310]. Proliferation was unaffected by blocking either receptor, and ERK1/2 activation was independent of CXCR4 [PMID:26780310].","molecular_requirements":"Modelling predicted CXCR4 and CXCR7 dimers as possible TFF3 binding partners [PMID:26780310].","affinity_potency":[],"species_and_systems":"Human ocular surface tissues and a conjunctival epithelial cell line; mouse pair is ortholog-inferred [PMID:26780310].","localisation_and_range":"TFF3 is annotated secreted [flag].","caveats":"Abstract only. Blocking was of CXCR4 and/or CXCR7, so the CXCR4 contribution is not separated. Binding is computational prediction only.","key_references":[{"PMID":"26780310","why":"TFF3 migration blocked by CXCR4/CXCR7 inhibition"}],"covers":["LR002017","LR005345"]},"LR004832":{"pair":"TGFA -> ERBB4","headline":"Co-IP of TGF-alpha precursor splice forms with ERBB4 in CHO cells; an intracellular, isoform-specific interaction, not classic extracellular signalling.","interaction_type":"conflicting","direction_and_effect":"Co-immunoprecipitation was seen for the wild-type precursor but not the others; precursor-ErbB signalling effect is not reported in our evidence [PMID:10918572].","molecular_requirements":"Interaction is mediated by the precursor's cytoplasmic C-terminal region, shown with chimeras and mutants [PMID:10918572].","affinity_potency":[],"species_and_systems":"CHO cells overexpressing human TGF-alpha precursors (WT, VaI, VaII); mouse pair is ortholog-inferred [PMID:10918572].","localisation_and_range":"Membrane-anchored precursor with intracellular C-terminal interaction [PMID:10918572]; ligand also annotated secreted [flag].","caveats":"VaI and VaII did not co-immunoprecipitate with ErbB4, so the interaction is splice-variant specific. Co-IP cannot exclude a bridging partner. Abstract only.","key_references":[{"PMID":"10918572","why":"Co-IP of TGFalpha precursor forms with ErbBs"}],"covers":["LR001437","LR004832"]},"LR011672":{"pair":"TGFB1 -> CD109","headline":"No curated papers; support is a UniProt subunit statement only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states TGFB1 interacts with CD109 [DB:UniProt] and that CD109 interacts with TGFB1 and TGFBR1 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptor localisation not reported in our evidence.","caveats":"No papers were judged for this pair; evidence is database annotation only, with no assay, affinity, or effect direction.","key_references":[],"covers":["LR011672"]},"LR001439":{"pair":"TGFB1 -> ITGAV","headline":"Multiple structural and binding papers show alphaV integrins (beta6, beta8) bind latent TGF-beta1; alphaVbeta3 binds weakly.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta8 binds latent TGF-beta1, shown by cryo-EM, and binding is essential for activating it [PMID:31955848]. SLC binds alphaVbeta8, leading to MT1-MMP-dependent release of active TGF-beta [PMID:11970960]. alphaVbeta6 binds a RGDLXXL/I motif in TGF-beta1 prodomain [PMID:25383667]. UniProt: ITGAV:ITGB6 or ITGB8 interaction distorts the latency-associated peptide and releases active TGF-beta-1 [DB:UniProt].","molecular_requirements":"ITGAV pairs with a beta chain: beta6 or beta8 bind latent TGF-beta1 with high specificity [PMID:25383667] [PMID:31955848]. alphaVbeta3 did not bind latent TGF-beta1 strongly [PMID:27033701]. Leu-218 after the RGD motif defines alphaVbeta8 binding [PMID:27033701].","affinity_potency":[],"species_and_systems":"Crystal and cryo-EM structures, recombinant proteins and cells [PMID:25383667] [PMID:31955848]; human proteins in PMID:27033701; species unspecified in PMID:11970960.","localisation_and_range":"TGFB1 is flagged secreted [flag]. Ligand is bound in its latent complex at cell surface integrins.","caveats":"The entity is labelled alphaV beta3 [flag] yet the evidence concerns beta6 and beta8, so scoring should use the correct beta chain. The ligand is latent TGF-beta1, not mature. Three further papers judged abstract-insufficient. Three papers read as abstract only.","key_references":[{"PMID":"31955848","why":"Cryo-EM of alphaVbeta8 with latent TGF-beta"},{"PMID":"25383667","why":"alphaVbeta6 structure with TGF-beta prodomain motif"},{"PMID":"27033701","why":"alphaVbeta8 specificity for latent TGF-beta1"}],"covers":["LR001439","LR004834"]},"LR004841":{"pair":"TGFB2 -> ACVR1","headline":"TGF-beta2 triggers ALK2 phosphorylation and ALK2-dependent endothelial reprogramming in HUVEC; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"TGF-beta2 or BMP4 for 15 min induced ALK2 phosphorylation in HUVECs, and ALK2 siRNA blocked the TGF-beta2-induced rise in FSP-1 and STRO-1 [PMID:21102460].","molecular_requirements":"Not reported in our evidence; whether ALK2 acts alone or with a type II or TGFBR1 partner is not tested in the excerpts.","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVEC, HCMEC) with recombinant ligand; mouse models were used for the ALK2 mutation work, not for this ligand [PMID:21102460]. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand secreted [flag]; range follows from that flag only.","caveats":"Single paper with functional readout; no binding assay. Other judged papers were review-only, abstract-insufficient or a different entity.","key_references":[{"PMID":"21102460","why":"TGF-beta2-induced ALK2 phosphorylation and ALK2-dependent EndMT"}],"covers":["LR001446","LR004841"]},"LR001448":{"pair":"TGFB2 -> TGFBR3","headline":"TGF-beta2 to betaglycan: the cited paper shows betaglycan binds TGF-beta isoforms with two ligand-binding domains; betaglycan acts as co-receptor.","interaction_type":"direct binding","direction_and_effect":"Betaglycan is a coreceptor without kinase activity that presents ligand to TGFBR1/TGFBR2 and matters most for TGF-beta2 (curator note) [PMID:19842711]. 125I-TGF-beta2 labelled the intact receptor and both fragments [PMID:19842711].","molecular_requirements":"Two independent binding domains; either fragment binds ligand but blocks it poorly versus the intact form [PMID:19842711]. Reactome lists TGFB1,TGFB2:TGFBR3 and a TGFB2:pTGFBR3:TGFBR2 complex [DB:Reactome].","affinity_potency":[{"value":"Kd in the low nanomolar range","assay":"SPR, soluble betaglycan, three TGF-beta isoforms","system":"recombinant soluble betaglycan","cite":"PMID:19842711"}],"species_and_systems":"Rat recombinant soluble betaglycan from insect cells; GAG-less membrane betaglycan in COS-1 cells [PMID:19842711].","localisation_and_range":"Ligand secreted, betaglycan membrane-bound with a soluble form [flag][PMID:19842711].","caveats":"The affinity is given for the three isoforms collectively. Annotated stimulatory [flag] although betaglycan is a co-receptor.","key_references":[{"PMID":"19842711","why":"Two ligand binding domains of betaglycan, SPR affinity, TGF-beta2 labelling"}],"covers":["LR001448","LR004843"]},"LR007433":{"pair":"TGFB3 -> ITGAV:ITGB6","headline":"alphaVbeta6 complex row for TGF-beta3 is supported by a PDB structure only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"PDB 4UM9 holds a crystal structure of alphaV beta6 with a peptide, PMID 25383667 [DB:PDB 4UM9].","molecular_requirements":"Both chains in the structure [DB:PDB 4UM9].","affinity_potency":[],"species_and_systems":"No curator-judged papers; three pending.","localisation_and_range":"Annotated secreted ligand, transmembrane complex [flag].","caveats":"Not curator-verified; related alphaVbeta6 papers appear under other rows.","key_references":[],"covers":["LR007433"]},"LR003374":{"pair":"TGFB3 -> ITGB1","headline":"Integrin beta1 chain: alpha8beta1 adheres to LAP-TGF-beta3; evidence is chain-only and concerns the propeptide.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cells adhered to LAP-TGFbeta3 better than mock cells, RGD-dependent [PMID:12415008].","molecular_requirements":"The binder is the alpha8beta1 heterodimer; beta1 alone is not tested [PMID:12415008].","affinity_potency":[],"species_and_systems":"Transfected cells, adhesion assays; species not reported in our evidence.","localisation_and_range":"Ligand flagged secreted and transmembrane [flag].","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Abstract-only.","key_references":[{"PMID":"12415008","why":"alpha8beta1 adhesion to LAP-TGFbeta3"}],"covers":["LR003374","LR006575"]},"LR004850":{"pair":"TGM2 -> ITGA4","headline":"Cell adhesion to tTG through integrin alpha4beta1 in MOLT-3 cells; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"MOLT-3 cells adhere to tTG through alpha(4)beta(1) [PMID:10816592]. Adhesion was blocked by anti-integrin antibodies in the curator's assay description [PMID:10816592].","molecular_requirements":"The functional receptor is the alpha4beta1 heterodimer, so ITGB1 is also required [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human cell lines (MOLT-3, G-361) with tTG [PMID:10816592]. Mouse pair is ortholog-inferred.","localisation_and_range":"tTG is flagged secreted [flag]; the assay is cell adhesion to tTG [PMID:10816592].","caveats":"Cell-adhesion and blocking antibody data only, not direct binding; another integrin judgement was abstract_insufficient.","key_references":[{"PMID":"10816592","why":"tTG as ligand of alpha9beta1 and alpha4beta1"}],"covers":["LR001455","LR004850"]},"LR001457":{"pair":"TGM2 -> ITGB1","headline":"tTG interacts directly with beta1 integrins as an adhesion coreceptor for fibronectin, backed by BioGRID records.","interaction_type":"direct binding","direction_and_effect":"Cell-surface tTG interacts with beta1 and beta3 integrins and mediates their association with the 42-kD gelatin-binding domain of fibronectin [PMID:10684262]. It acts as an integrin-associated coreceptor to promote adhesion and spreading [PMID:10684262].","molecular_requirements":"Adhesive function does not require cross-linking activity but depends on stable noncovalent association with integrins [PMID:10684262].","affinity_potency":[],"species_and_systems":"Human tTG cDNA, cultured cells with co-immunoprecipitation [PMID:10684262]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; complexes form inside the cell and accumulate on the surface and in focal adhesions [PMID:10684262].","caveats":"The role is coreceptor with fibronectin rather than a classical signalling ligand; no affinity for the integrin is reported. BioGRID lists affinity capture-western and reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10684262","why":"tTG as integrin-binding adhesion coreceptor"}],"covers":["LR001457","LR004852"]},"LR007073":{"pair":"THBS1 -> ITGA2B:ITGB3","headline":"Thinly supported: a kidney injury paper links THBS1 to ITGB3, plus database records of the platelet complex.","interaction_type":"functional only","direction_and_effect":"In human HK-2 cells, mouse adriamycin nephropathy and FSGS patient tissue, THBS1/ITGB3 signalling was linked to tubular injury, and cyclo-RGDfK was reported to block TSP-1 binding to ITGB3; IP in HK-2 cells treated with rTSP-1 and colocalisation were shown [PMID:38960036]. BioGRID lists THBS1-ITGB3 reconstituted complex and affinity-capture records [DB:BioGRID]; Reactome lists the alphaIIbbeta3:THBS1 complex [DB:Reactome].","molecular_requirements":"The paper concerns the beta3 chain (ITGB3) only; it does not show the ITGA2B:ITGB3 complex specifically [PMID:38960036]. Reactome and BioGRID records support the alphaIIb-beta3 complex and ITGB3 respectively [DB:Reactome][DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human HK-2 cells and patient tissue, plus ADR-treated mice (THBS1-KO, BALB/c) [PMID:38960036].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"The paper supports ITGB3, not the alphaIIb partner, so it is chain-only evidence for this complex. Mouse experiments were in vivo knockouts and an RGD-mimetic blocker, which are indirect. No affinity reported.","key_references":[{"PMID":"38960036","why":"TSP-1/ITGB3 signalling and cyclo-RGDfK blockade in kidney tubular injury (full text)"}],"covers":["LR007073"]},"LR001466":{"pair":"THBS1 -> ITGA4","headline":"Functional support that alpha4beta1 mediates endothelial responses to THBS1 N-terminal regions; not direct binding data.","interaction_type":"functional only","direction_and_effect":"Alpha4beta1 supports adhesion of venous endothelial cells, but not microvascular endothelial cells, on immobilized THBS1 and its N-terminal regions; it mediates chemotaxis and promotes survival and proliferation (stimulatory), and alpha4beta1 antagonists inhibited angiogenesis in vivo [PMID:14699013]. Reactome lists THBS1 binding alpha3beta1/alpha4beta1 [DB:Reactome].","molecular_requirements":"Acts as the alpha4beta1 heterodimer; the THBS1 N-terminal region containing the alpha4beta1 binding sequence is sufficient [PMID:14699013]. Antagonism of FGF-2-stimulated chemotaxis was not mediated by this region [PMID:14699013].","affinity_potency":[],"species_and_systems":"Endothelial cells (species not specified in our evidence), chick chorioallantoic membrane, and mouse muscle explants, where inhibition was lost in THBS1-null explants [PMID:14699013].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"One paper, read as abstract only; adhesion and chemotaxis are indirect readouts. Cell-type dependent: not active in microvascular endothelial cells. No affinity reported.","key_references":[{"PMID":"14699013","why":"alpha4beta1 mediates endothelial adhesion, chemotaxis and angiogenesis responses to THBS1"}],"covers":["LR001466","LR004861"]},"LR003383":{"pair":"THBS1 -> SCARB2","headline":"THBS1 binds a LIMPII (SCARB2) CD36-homologous peptide in solid-phase assays and plasma-membrane-targeted LIMPII confers adhesion; single abstract.","interaction_type":"direct binding","direction_and_effect":"Purified 125I-TSP1 bound immobilised GST/LIMPII in a time-dependent and saturable manner, and a plasma-membrane-targeted LIMPII chimera let melanoma cells bind TSP1 and adhere to TSP1-coated surfaces [PMID:9478926]. Effect direction not reported beyond adhesion.","molecular_requirements":"Binding was shown with a LIMPII peptide corresponding to the TSP1-binding domain of CD36, as a GST fusion, not full-length SCARB2; the site is conserved with CD36 [PMID:9478926].","affinity_potency":[],"species_and_systems":"Recombinant GST fusion in solid-phase assay; Bowes melanoma cells transfected with a chimeric LIMPII cDNA; the paper's species is not stated in the abstract, though curation labels it human [PMID:9478926]. Both pair species rows are ortholog-inferred.","localisation_and_range":"SCARB2 is a lysosomal membrane protein; surface presentation was achieved only by a plasma-membrane-targeted chimera, and cell surface LIMPII may act as an adhesion receptor only in some circumstances [PMID:9478926].","caveats":"Abstract only; peptide fragment, not full-length receptor; the physiological relevance of surface binding is uncertain. BioGRID reconstituted-complex record [DB:BioGRID].","key_references":[{"PMID":"9478926","why":"LIMPII fusion binds THBS1; chimera confers adhesion"}],"covers":["LR003383","LR006584"]},"LR008801":{"pair":"THBS1 -> TNFRSF11B","headline":"One 2005 abstract reports OPG binding TSP-1 with high avidity by co-immunoprecipitation; OPG is a decoy-type secreted protein.","interaction_type":"direct binding","direction_and_effect":"OPG also binds with high avidity to thrombospondin (TSP-1) [PMID:15799029]. Signalling direction: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVEC), co-immunoprecipitation [PMID:15799029].","localisation_and_range":"Both are secreted-type proteins; OPG is stored in Weibel-Palade bodies and secreted [PMID:15799029]. TNFRSF11B is not flagged receptor in the dossier [flag].","caveats":"Single abstract-only paper focused on OPG/vWF; TSP-1 is a secondary finding. Because OPG is not flagged a receptor, this may be a ligand-ligand association.","key_references":[{"PMID":"15799029","why":"OPG complexes with vWF and TSP-1 in endothelial cells"}],"covers":["LR008801"]},"LR001475":{"pair":"THBS2 -> ITGB1","headline":"Beta1 integrins (alpha6beta1, alpha4beta1) mediate cell responses to the THBS2 N-terminal region; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Alpha6beta1 mediates adhesion and chemotaxis to the TSP-2 N-terminal region [PMID:12909644]; alpha4beta1 mediates venous endothelial adhesion, chemotaxis, survival and proliferation on these regions [PMID:14699013].","molecular_requirements":"Beta1 pairs with alpha6 or alpha4; the N-terminal pentraxin module carries the alpha6beta1 site [PMID:12909644].","affinity_potency":[],"species_and_systems":"Human microvascular endothelial and HT-1080 cells [PMID:12909644]; mouse (chick CAM and mouse explants) [PMID:14699013].","localisation_and_range":"THBS2 flagged secreted; immobilised substrate [flag].","caveats":"Abstracts only; recombinant N-terminal regions, not full-length THBS2; adhesion-based. One row abstract_insufficient. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"12909644","why":"alpha6beta1 recognises TSP-2 N-terminal region"},{"PMID":"14699013","why":"alpha4beta1 responses to TSP-2 N-terminal region"}],"covers":["LR001475","LR004870"]},"LR009341":{"pair":"THBS2 -> NOTCH3","headline":"THBS2, but not THBS1, binds NOTCH3 and enhances Notch3 signalling; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"TSP2 binds directly to Notch3 and enhances the potency of Notch3 signal transduction, with Notch3/Jagged1 potentiation [PMID:19147503]. TSP2 knockout mice show reduced Notch target gene expression [PMID:19147503]. Potentiator/agonist.","molecular_requirements":"Acts together with Jagged1 signalling; TSP1 does not have this effect [PMID:19147503].","affinity_potency":[],"species_and_systems":"Human cell systems and TSP2 knockout mice [PMID:19147503].","localisation_and_range":"THBS2 flagged secreted [flag].","caveats":"Abstract only; no affinity. The effect is modulation of a Notch3/Jagged1 pathway, not a stand-alone agonist.","key_references":[{"PMID":"19147503","why":"TSP2 binds Notch3 and potentiates signalling"}],"covers":["LR009341"]},"LR003392":{"pair":"THY1 -> ITGA5","headline":"Thy-1 binds alpha5beta1 integrin at single-molecule level; cooperates with syndecan-4. Single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Thy-1 independently binds alpha5beta1 integrin and syndecan-4; with both present they bind cooperatively, forming a trimolecular complex with a 'dynamic catch' (force prolongs bond lifetime) [PMID:25216363].","molecular_requirements":"Evidence is for the alpha5beta1 heterodimer; alone binding to alpha5beta1 is sufficient, though both co-receptors together bind cooperatively [PMID:25216363].","affinity_potency":[],"species_and_systems":"Single-molecule force spectroscopy; melanoma cell mechanosignalling; ligand and receptor listed as human [PMID:25216363].","localisation_and_range":"Membrane-bound Thy-1 (not secreted [flag]) on endothelium engaging integrin on cancer cells; contact-dependent [PMID:25216363].","caveats":"Abstract only; no affinity values reported in our evidence.","key_references":[{"PMID":"25216363","why":"Thy-1/alpha5beta1/syndecan-4 dynamic catch"}],"covers":["LR003392","LR006593"]},"LR006605":{"pair":"TIMP2 -> MMP2","headline":"TIMP-2 binds MMP-2 (crystal structure, binding assays), but this is an inhibitor-enzyme interaction rather than classic signalling.","interaction_type":"direct binding","direction_and_effect":"TIMP-2 forms a complex with MMP-2 and, with MT1-MMP, a ternary complex with pro-MMP-2 that permits activation by a neighbouring TIMP-2-free MT1-MMP [PMID:12755684]. Low TIMP-2 levels increased MMP-2 activation and invasion in glioblastoma cells, whereas higher levels inhibited it [PMID:14631378]. A co-crystal structure exists [DB:PDB 1GXD].","molecular_requirements":"Ternary complex with MT1-MMP and pro-MMP-2 [PMID:12755684]. MMP2 is flagged both secreted and receptor, not transmembrane [flag].","affinity_potency":[],"species_and_systems":"Human cell systems (glioblastoma lines, engineered cells and plasma membrane fractions) [PMID:12755684][PMID:14631378]; mouse pair is ortholog-inferred.","localisation_and_range":"MMP2 is flagged secreted, so interaction is extracellular and pericellular [flag]; the ternary complex forms on the cell surface [PMID:12755684].","caveats":"Both papers read as abstracts. Effect is dose-dependent: higher TIMP-2 inhibits MMP-2 activation [PMID:14631378]. Binding is enzyme-inhibitor binding; MMP-2 as a receptor comes from an annotation flag.","key_references":[{"PMID":"12755684","why":"TIMP-2/MT1-MMP/pro-MMP-2 ternary complex"},{"PMID":"14631378","why":"TIMP-2 level effects on MMP-2 activation"}],"covers":["LR003404","LR006605"]},"LR001484":{"pair":"TNC -> ITGA2","headline":"Adhesion of human oral carcinoma cells to tenascin-C involves alpha2 integrin by antibody blocking; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Adhesion of oral SCC cells to tenascin-C involves both alpha2 and alpha(v) integrins, and migration on TN-C was blocked by anti-alpha2 and anti-alpha(v) antibodies [PMID:9219848].","molecular_requirements":"alpha2 is paired with a beta subunit in vivo, but the partner chain is not reported in our evidence for this paper; the abstract names alpha(v)beta6 as the integrin identified [PMID:9219848].","affinity_potency":[],"species_and_systems":"Human oral squamous-cell carcinoma lines HSC-3 and SCC-25 [PMID:9219848].","localisation_and_range":"Ligand flagged secreted [flag]; cells also secrete TN-C into medium [PMID:9219848].","caveats":"Functional antibody-blocking only; abstract-only read. Single-chain (alpha2) entry, so complex requirements are unresolved.","key_references":[{"PMID":"9219848","why":"Antibody-blocked adhesion to TN-C involving alpha2"}],"covers":["LR001484"]},"LR004904":{"pair":"TNF -> TNFRSF1B","headline":"TNF engages TNFR2 according to databases and indirect papers; no quantified TNFR2 binding is reported in our evidence.","interaction_type":"direct binding","direction_and_effect":"Reactome describes TNFA trimer binding TNFR2 and recruitment of further TNFR2 [DB:Reactome]. A TNFR2-selective TNF mutant had no significant effect on feline cardiac myocyte motion, unlike the TNFR1-selective mutant [PMID:7664431].","molecular_requirements":"Reactome lists TNFA trimer:TNFR2 trimer complexes [DB:Reactome]. Receptor-selective TNF mutants binding only TNFR2 were isolated by phage display [PMID:19084540].","affinity_potency":[],"species_and_systems":"Human proteins in the papers [PMID:19084540][PMID:17195449]; feline cardiac myocytes with human TNF mutants [PMID:7664431]. Reconstituted-complex and solid-phase records exist [DB:BioGRID][DB:IntAct]. A PDB structure 3ALQ shows TNF with TNFR2 [DB:PDB 3ALQ]. A mouse pair was projected from human evidence.","localisation_and_range":"TNF and TNFR2 are flagged secreted and transmembrane [flag].","caveats":"The confirming papers are abstract-only and mostly background statements: no Kd for TNF at TNFR2 is given [PMID:17195449][PMID:19084540]. GtoPdb lists no affinity or action [DB:GtoPdb]. The cardiac study shows TNFR2 binding of the mutant but no functional effect there [PMID:7664431].","key_references":[{"PMID":"7664431","why":"Receptor-selective TNF mutants in cardiac myocytes"},{"PMID":"19084540","why":"Phage display of TNFR2-selective TNF mutants"}],"covers":["LR001514","LR004904"]},"LR006614":{"pair":"TNFAIP6 -> LRP1","headline":"TSG6 (TNFAIP6) binds purified LRP1 directly in a chondrocyte ligandome study; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"TSG6 was one of ten ligands whose direct LRP1 binding was confirmed, with a correlation between LRP1 affinity and endocytosis rate [PMID:36028175]. LRP1 acts as an endocytic receptor, so LRP1 clears TSG6 from the extracellular space [PMID:36028175]. Agonist versus other effect is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Direct binding assays with purified LRP1, validation in LRP1-deficient fibroblasts and human chondrocytes, and a conditional Lrp1 knockout mouse [PMID:36028175]. The curator lists both ligand and receptor as human. A mouse pair was projected from human evidence.","localisation_and_range":"TNFAIP6 is flagged secreted; LRP1 flagged as a receptor [flag].","caveats":"Only the abstract was read and no affinity value is given for TSG6; it is one of ten ligands in a screen [PMID:36028175]. No database records are present.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding of TSG6 in cartilage ligandome"}],"covers":["LR003413","LR006614"]},"LR008621":{"pair":"TNFRSF8 -> TNFSF8","headline":"CD30 and CD30 ligand: the ligand was expression-cloned using a CD30-Ig probe; database binding records agree.","interaction_type":"direct binding","direction_and_effect":"A CD30 extracellular domain fused to immunoglobulin heavy chains was used to expression-clone the ligand from a mouse T cell clone; the ligand is a 239 amino acid type II membrane protein homologous to TNF family members [PMID:8391931]. Recombinant human ligand enhances proliferation of CD3-activated T cells and induces differential responses, including cell death, in several CD30+ lymphoma-derived clones [PMID:8391931]. The pair is stored receptor-to-ligand.","molecular_requirements":"Not reported in our evidence beyond a single receptor ectodomain being sufficient as a probe [PMID:8391931].","affinity_potency":[],"species_and_systems":"Murine cloning from T cell clone 7B9 and human recombinant ligand tests [PMID:8391931]. Database records: BioGRID reconstituted complex [DB:BioGRID], IntAct solid phase assay [DB:IntAct], Reactome binding reaction [DB:Reactome], UniProt receptor annotation [DB:UniProt].","localisation_and_range":"TNFSF8 is a type II membrane protein [PMID:8391931] and flagged not secreted [flag], so signalling is likely contact-dependent.","caveats":"Abstract-only read; no affinity reported in our evidence.","key_references":[{"PMID":"8391931","why":"Expression cloning of CD30 ligand with a CD30-Ig probe"}],"covers":["LR008621"]},"LR001493":{"pair":"TNFSF10 -> TNFRSF10B","headline":"TRAIL binds DR5 (TNFRSF10B) and induces apoptosis; supported by a crystal structure, binding and many database records.","interaction_type":"direct binding","direction_and_effect":"TRAIL binds recombinant cell-surface TRAIL-R2 (DR5), and TRAIL-induced apoptosis is inhibited by a TRAIL-R2-Fc fusion [PMID:9311998]. DR5 has a death domain and engages caspase-dependent apoptosis [PMID:9311998]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"The crystal structure shows three receptors in crevices between pairs of monomers of the homotrimeric ligand, with two interface patches [PMID:10549288]. TRAIL receptors DR4 and DR5 trigger apoptosis by oligomerising death domains [PMID:10549288].","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:9311998]. Databases include PDB 1D0G, 1D4V, 1DU3 and 4N90 [DB:PDB 1D0G], BioGRID, IntAct, Reactome and UniProt.","localisation_and_range":"TRAIL is flagged secreted and transmembrane [flag].","caveats":"Papers conflict on adaptor use: DR5 mediates apoptosis via FADD/MORT1 [PMID:9311998], whereas another paper says DR5 engages apoptosis independent of FADD [PMID:9325248]. All papers were read as abstracts. GtoPdb shows an affinity unit (pKd) without a value in our dossier [DB:GtoPdb].","key_references":[{"PMID":"10549288","why":"Crystal structure of Apo2L/TRAIL with DR5"},{"PMID":"9311998","why":"Cloning of TRAIL-R2 and binding to TRAIL"},{"PMID":"9242610","why":"Identifies DR5 as a death domain receptor for TRAIL"}],"covers":["LR001493"]},"LR005354":{"pair":"TOR2A -> ATP5F1B","headline":"Salusin-beta (TOR2A) was reported to bind ATP synthase beta chain using native-membrane proteoliposomes; single paper.","interaction_type":"direct binding","direction_and_effect":"ATP synthase beta chain is identified as a cell surface receptor for salusin-beta; salusin-beta inhibited cell surface ATP synthase activity and prevented sarcoma cell-induced angiogenesis in an in vivo mouse air sac model, acting as an angiogenesis inhibitor [PMID:30552345].","molecular_requirements":"Beta chain of ATP synthase; the alpha chain is the angiostatin target in other work, and its role here not reported in our evidence.","affinity_potency":[],"species_and_systems":"Liposomes with endogenous membrane proteins from animal tissues; mouse air sac model [PMID:30552345]. Both pairs are ortholog-inferred.","localisation_and_range":"Described as a cell surface receptor [PMID:30552345]. ATP5F1B carries no transmembrane or secretion flag here; the ligand is flagged secreted [flag].","caveats":"Single paper, abstract-level evidence in the dossier. Detergent-based techniques identified a beta-actin-profilin complex instead and failed to identify this receptor [PMID:30552345]. An ATP synthase subunit is normally mitochondrial, so surface function rests on this report.","key_references":[{"PMID":"30552345","why":"Proteoliposome identification of ATP synthase beta chain as salusin-beta receptor"}],"covers":["LR002026","LR005354"]},"LR006623":{"pair":"TSKU -> FZD3","headline":"Tsukushi binds Fzd3 with Kd 2.7 x 10-10 M in vitro; one browser-read Results sentence, spot-check pending.","interaction_type":"direct binding","direction_and_effect":"Fzd3 binds TSK with high affinity in vitro, suggesting TSK modulates Wnt signaling in the SVZ; TSK deficiency causes hydrocephalus and dysregulated Wnt signaling in mice [PMID:33790026]. Agonist or antagonist action at Fzd3 not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[{"value":"Kd 2.7 x 10-10 M","assay":"in vitro binding (Fig. 7B)","system":"Fzd3 with TSK","cite":"PMID:33790026"}],"species_and_systems":"Mouse model (TSK knockout) and in vitro binding; the human pair is ortholog-inferred, mouse is not [PMID:33790026].","localisation_and_range":"TSKU flagged secreted; TSK acts in cerebrospinal fluid and at the ventricular surface [PMID:33790026].","caveats":"The binding sentence is from a browser read and the curator marked it unverifiable pending spot-check; the abstract does not mention Fzd3. Paralog Fzd4 evidence is separate.","key_references":[{"PMID":"33790026","why":"Fzd3-TSK binding, TSK role in SVZ and hydrocephalus"}],"covers":["LR003422","LR006623"]},"LR008405":{"pair":"TXLNA -> STX1A","headline":"Database-asserted only: Reactome/UniProt/BioGRID report alpha-taxilin binding syntaxins; not a secreted ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: TXLNA binds the C-terminal coiled coil region of syntaxin family members STX1A, STX3A and STX4A, but not when complexed with SNAP25, VAMP2 or STXBP1 [DB:UniProt]. Reactome has the binding reaction [DB:Reactome].","molecular_requirements":"Free syntaxin, not the SNARE complex, binds TXLNA [DB:UniProt].","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID]; cell system not reported in our evidence.","localisation_and_range":"Intracellular proteins; no secretion or receptor flags support extracellular signalling [flag].","caveats":"No papers were judged; the single curated row was classed different_entity. This looks like an intracellular protein-protein interaction, not cell-cell communication.","key_references":[],"covers":["LR008405"]},"LR004913":{"pair":"UCN -> CRHR2","headline":"Urocortin 1 binds CRF2 receptor with high affinity as an agonist in several abstract-level binding studies.","interaction_type":"direct binding","direction_and_effect":"Agonist: human urocortin binds CRF receptor types 1, 2 alpha and 2 beta and stimulates cAMP in transfected cells [PMID:8612563]; GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the CRF2alpha and CRF2beta receptor variants being tested separately [PMID:9423932]. Non-peptide CRF antagonists had no measurable affinity at CRF2 receptors [PMID:9423932].","affinity_potency":[{"value":"Kd 0.18-0.31 nM","assay":"[3H]-rat urocortin binding, range reported across the recombinant receptors and cerebellum","system":"stably transfected cell homogenates","cite":"PMID:9423932"},{"value":"Ki 1 to 2 nM","assay":"competition with 125I-labelled radioligands, reported for all receptors","system":"CHO cells overexpressing CRF-R1 or CRF-R2","cite":"PMID:9918582"},{"value":"pKd 8.6 to 9.4","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:11123370"}],"species_and_systems":"Human CRF2alpha [PMID:11123370], rat CRF2alpha and CRF2beta recombinant receptors with rat urocortin [PMID:9423932], CHO cells (species unspecified) [PMID:9918582]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"All papers read as abstracts only. Potency rank order at CRF2 receptors was urocortin > sauvagine > urotensin 1 > CRF [PMID:9423932]; urocortin also binds CRF1, so it is not subtype-selective [PMID:8612563].","key_references":[{"PMID":"8612563","why":"Human urocortin binds CRF2 alpha/beta and raises cAMP"},{"PMID":"9423932","why":"Kd and rank order at CRF2 receptors"},{"PMID":"9918582","why":"Ki of 1 to 2 nM in CHO cells"}],"covers":["LR001523","LR004913"]},"LR003428":{"pair":"UMOD -> TRPM6","headline":"Uromodulin physically interacts with the TRPM6 channel and raises its surface abundance; one abstract-level mouse and cell study.","interaction_type":"direct binding","direction_and_effect":"UMOD enhances TRPM6 cell-surface abundance and current density from the extracellular space and impairs dynamin-dependent TRPM6 endocytosis, so effect is stabilising/increasing channel activity rather than classical agonism [PMID:30139743].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Umod-knockout mice (reduced apical Trpm6 staining in the distal convoluted tubule) plus biotinylation and whole-cell patch-clamp assays [PMID:30139743]; cell species not reported in the abstract. The mouse pair is ortholog-inferred; the human pair is the dossier's primary.","localisation_and_range":"Ligand flagged secreted [flag]; the paper reports urinary UMOD secretion rising on a low-magnesium diet in mice [PMID:30139743], acting from the extracellular space.","caveats":"Read as an abstract only. The physical interaction is stated, but the binding method and any affinity are not reported in our evidence. TRPM6 is an ion channel, not a classical receptor, and no receptor annotation flag is given beyond is_receptor.","key_references":[{"PMID":"30139743","why":"UMOD interacts with TRPM6 and increases its surface abundance"}],"covers":["LR003428","LR006629"]},"LR006632":{"pair":"UNC5A -> FLRT3","headline":"Extracellular binding of UNC5A and FLRT3 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5A is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5A stripes gave no attractive or repulsive neuronal response (n=257/257, 100% permissive) [PMID:26633812]. UniProt lists the extracellular-domain interaction, partly by similarity [DB:UniProt].","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003431","LR006632"]},"LR003437":{"pair":"UNC5C -> FLRT2","headline":"UNC5C and FLRT2 show complementary expression and mutual repulsion of mouse retinal neurons; binding is supported only by the wider screen.","interaction_type":"functional only","direction_and_effect":"Neurons repelled by Unc5C stripes expressed FLRT2 (n=26/26), and neurons repelled by FLRT2 stripes expressed Unc5C (n=30/30) [PMID:26633812]. FLRT2-transfected neurons were repelled by Unc5C stripes [PMID:26633812]. The authors propose mutual repulsion through bidirectional signalling, and describe Unc5C as a repulsive ligand for the FLRT2 receptor [PMID:26633812].","molecular_requirements":"Not reported in our evidence; full-length FLRT2 was expressed in the gain-of-function assay [PMID:26633812].","affinity_potency":[],"species_and_systems":"Mouse retinal neurons in ex vivo stripe assays and in vivo staining; the human pair is ortholog-inferred [PMID:26633812].","localisation_and_range":"Unc5C is annotated as a transmembrane receptor and FLRT2 as secreted and transmembrane [flag]. Their laminar patterns are complementary: Unc5C in S1/3/5 and FLRT2 in S2/4 of the inner plexiform layer [PMID:26633812].","caveats":"This row was judged on the abstract, with excerpts, and rests on expression and repulsion, not a binding measurement for this pair. Only a minority of neurons (5-18%) responded to stripes [PMID:26633812].","key_references":[{"PMID":"26633812","why":"FLRT2-Unc5C expression and repulsion in mouse retina"}],"covers":["LR003437","LR006638"]},"LR006641":{"pair":"UNC5D -> FLRT2","headline":"UNC5D-FLRT2 is well supported by binding and by repulsive guidance of cortical neurons, in mouse systems.","interaction_type":"direct binding","direction_and_effect":"Unc5D binds specifically to FLRT2; shed FLRT2/3 ectodomains act as repulsive guidance molecules for axons and somata of Unc5-positive neurons [PMID:21673655]. Deleting FLRT2 or Unc5D makes a subset of SVZ-derived neurons migrate early to the cortical plate, and Unc5D overexpression has the opposite effect [PMID:21673655]. A second paper found FLRT2-Unc5D binding in an ELISA-based screen (mean Abs650nm value = 2.14 for all FLRT x Unc5 pairs) [PMID:26633812]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"The shed ectodomain of FLRT2 is the active form [PMID:21673655]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cortex in vivo (abstract-level) and mouse recombinant proteins in vitro [PMID:21673655, PMID:26633812]; the human pair is ortholog-inferred.","localisation_and_range":"FLRT2 ectodomains are shed from neurons and act at a distance as chemorepellents [PMID:21673655]; Unc5D is a membrane receptor [flag].","caveats":"The 2011 paper was read as abstract only. No Kd or other affinity is given.","key_references":[{"PMID":"21673655","why":"Unc5D binds FLRT2; shed FLRT2 repels Unc5D neurons in cortex"},{"PMID":"26633812","why":"ELISA and titration binding of all FLRT x Unc5 pairs"}],"covers":["LR003440","LR006641"]},"LR001529":{"pair":"VCAM1 -> ITGAD","headline":"alphaD beta2 binds VCAM-1 in human transfectants and with soluble protein and I domain; one confirmed paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"Expression of alphaDbeta2 in a lymphoid cell lacking alpha4 integrins confers binding to VCAM-1; soluble alphaDbeta2 binds VCAM-1 and recombinant alphaD I domain binds specifically [PMID:10438935]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alphaD I domain contains the binding site; VCAM-1 aspartate D40 is needed; alphaDbeta2 is the functional heterodimer [PMID:10438935].","affinity_potency":[],"species_and_systems":"Human transfectants and recombinant proteins; adhesion under flow comparable to alpha4beta1 [PMID:10438935]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-surface VCAM-1 (flagged secreted and transmembrane) [flag].","caveats":"Single abstract-level paper; the stored partner is ITGAD alone although beta2 is required. BioGRID: reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10438935","why":"alphaDbeta2 and its I domain bind VCAM-1"}],"covers":["LR001529","LR004918"]},"LR004922":{"pair":"VCAN -> CD44","headline":"Versican binds CD44 through its chondroitin sulfate chains in solid-phase assays; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Human ACHN-derived versican binds CD44, mediated by its chondroitin sulfate chain [PMID:10950950]. Direction or signalling effect not reported in our evidence.","molecular_requirements":"CS chain of versican engages CD44; CD44 binding was inhibited by hyaluronic acid and several chondroitin sulfates but not heparan sulfate [PMID:10950950]. Cross-blocking shows CD44 recognises a site separate from selectins [PMID:10950950].","affinity_potency":[],"species_and_systems":"Human versican from a renal adenocarcinoma line, soluble CD44, solid-phase [PMID:10950950]. Mouse pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted; CD44 flagged secreted, receptor and transmembrane [flag].","caveats":"Glycan-mediated binding, not protein-protein. Single abstract-level paper. BioGRID: reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10950950","why":"versican CS chains bind CD44, L- and P-selectin"}],"covers":["LR001533","LR004922"]},"LR007442":{"pair":"VEGFA -> FLT1:KDR","headline":"VEGFA-stabilised FLT1-KDR heterodimer shown by one abstract-only binding paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Soluble FLT-1 forms a VEGF-stabilised complex with the KDR extracellular domain in vitro; the authors suggest sFLT-1 could form a dominant-negative complex with full-length KDR [PMID:8806634].","molecular_requirements":"Both FLT1 and KDR chains are required for the heterodimer; the evidence concerns the soluble FLT-1 and KDR ectodomain. For scoring, both subunits matter [PMID:8806634].","affinity_potency":[],"species_and_systems":"Human HUVEC conditioned medium and purified ectodomains [PMID:8806634].","localisation_and_range":"Complex members are flagged transmembrane receptors [flag]; the paper's FLT-1 was a soluble form.","caveats":"Single paper, read as abstract only, and it used the soluble FLT-1, not the full-length receptor. Database records mostly describe VEGFA with FLT1 or KDR separately (Reactome, IntAct, GtoPdb, PDB) rather than the heterodimer [DB:Reactome].","key_references":[{"PMID":"8806634","why":"VEGF-stabilised sFLT-1/KDR ectodomain complex"}],"covers":["LR007442"]},"LR001538":{"pair":"VEGFA -> GPC1","headline":"VEGF165 binds glypican-1 with sub-nanomolar apparent Kd via heparan sulfate; a presenting co-receptor, one paper.","interaction_type":"direct binding","direction_and_effect":"Glypican-1 from rat myoblasts binds VEGF165 but not VEGF121, and the authors describe it as an extracellular chaperone that potentiates VEGF165 binding to KDR [PMID:10196157].","molecular_requirements":"Binding is mediated by glypican-1 heparan sulfate chains: heparinase abolishes it and excess heparin or heparan sulfate inhibits it [PMID:10196157].","affinity_potency":[{"value":"Kd 3 x 10(-10) M","assay":"solid-phase binding, apparent dissociation constant","system":"rat myoblast glypican-1","cite":"PMID:10196157"}],"species_and_systems":"Human VEGF165 with rat myoblast glypican-1; human endothelial cell glypican-1 also bound [PMID:10196157].","localisation_and_range":"Glypican-1 is GPI-anchored per the abstract [PMID:10196157]; GPC1 is flagged secreted in the entity record [flag].","caveats":"One paper, abstract only. The interaction is carbohydrate-mediated, so it is not a classic signalling receptor. VEGF121 does not bind. BioGRID lists the same paper [DB:BioGRID].","key_references":[{"PMID":"10196157","why":"Glypican-1 binding to VEGF165 and chaperone role"}],"covers":["LR001538","LR004927"]},"LR004931":{"pair":"VEGFA -> NRP1","headline":"VEGFA, especially VEGF165, binds neuropilin-1 directly and NRP1 acts as a VEGFR2 coreceptor; well supported.","interaction_type":"direct binding","direction_and_effect":"NRP1 was identified as the isoform-specific VEGF165 receptor, binding VEGF165 but not VEGF121, and it enhances VEGF165 binding to KDR and chemotaxis [PMID:9529250]. VEGF binding to NRP1 is essential for endothelial migration, NRP1-VEGFR2 complex formation and FAK signalling [PMID:21653826]. VEGF189 also binds NRP1 and promotes neuronal responses [PMID:25519242].","molecular_requirements":"Binding localises to the intact b1b2 domain; neither b1 nor b2 alone binds, and heparin enhances binding [PMID:11986311]. NRP1 acts with VEGFR2; point mutants Y297A and D320A abolish VEGF binding [PMID:21653826]. NRP1 glycosaminoglycan modification changes VEGF responsiveness in ECs versus SMCs [PMID:16763549].","affinity_potency":[],"species_and_systems":"Mostly human cells and recombinant domains; mouse neurodevelopment for VEGF189 [PMID:25519242]; bovine endothelial cells for PGI2 [PMID:15637071]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGF is secreted and NRP1 a membrane receptor; heparin-binding isoforms are the NRP1 binders [PMID:11986311].","caveats":"Isoform dependent (VEGF121 fails to bind). No affinity values in our evidence. Several papers are abstract-only; PMID 15695515 uses VEGF165 binding only as a positive control.","key_references":[{"PMID":"9529250","why":"Identification of NRP1 as VEGF165 receptor"},{"PMID":"11986311","why":"Mapping of binding to NRP1 b1b2 domain"},{"PMID":"21653826","why":"NRP1 mutants lacking VEGF binding"}],"covers":["LR001542","LR004931"]},"LR001547":{"pair":"VEGFC -> ITGA9","headline":"VEGF-C binds integrin alpha9beta1 in a solid-phase assay, but only one paper and the evidence is for the alpha9beta1 heterodimer.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-C bound purified alpha9beta1 integrin in a dose- and cation-dependent fashion; alpha9beta1-expressing cells adhered and migrated on VEGF-C, blocked by a function-blocking antibody [PMID:15590642].","molecular_requirements":"The evidence is for the alpha9beta1 heterodimer, so ITGA9 alone is not shown to suffice; ITGB1 is the partner chain [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant human proteins; mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells are used [PMID:15590642]. Both listed interactions are ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted [flag]; integrins are membrane receptors, but this dossier carries no receptor flag for ITGA9.","caveats":"Single abstract-read paper; no affinity reported; no database records in this dossier.","key_references":[{"PMID":"15590642","why":"VEGF-C binds alpha9beta1 integrin"}],"covers":["LR001547","LR004936"]},"LR004940":{"pair":"VIM -> CD44","headline":"Direct binding reported between soluble CD44 and cell-surface vimentin in one human study; single paper, abstract-level curation but full text excerpts support it.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD44 hyaluronan-binding domain (CD44HABD) and a non-HA-binding triple mutant (CD443MUT) pulled down recombinant vimentin and bound vimentin's N-terminal head domain; binding is independent of hyaluronan [PMID:22216242]. Vimentin-knockout mouse lung endothelial cells did not internalise CD44HABD/CD443MUT, so vimentin is required for CD44 endocytosis there [PMID:22216242]. Net effect on signalling is not reported in our evidence.","molecular_requirements":"Vimentin N-terminal head domain binds CD44HABD [PMID:22216242]. Full-length CD44 standard isoform (Flag-tagged) co-immunoprecipitated vimentin-Myc in MCF-7 cells [PMID:22216242]. Stoichiometry in SPR was about 6 mol/mol [PMID:22216242].","affinity_potency":[{"value":"Kd 12-37 nM","assay":"SPR, CD443MUT binding vimentin in solution","system":"recombinant human proteins","cite":"PMID:22216242"},{"value":"Kd 74 nM","assay":"ITC / immobilised vimentin","system":"recombinant human proteins","cite":"PMID:22216242"}],"species_and_systems":"Human proteins (HUVEC, MCF-7 cells, recombinant); internalisation tested in lung endothelial cells from wild-type vs vimentin-null mice [PMID:22216242].","localisation_and_range":"CD44 is flagged secreted and transmembrane, vimentin is not flagged secreted [flag]. The paper describes soluble CD44 binding vimentin exposed on the endothelial cell surface [PMID:22216242]; range is therefore likely contact or paracrine, but this is the paper's framing, not a flag.","caveats":"Single paper. A minor fraction of vimentin co-precipitated with CD44 from HUVEC, and anti-vimentin IP did not detect CD44 [PMID:22216242]. Affinity measured with a mutant domain (CD443MUT), not full-length native CD44. The paper says the exact binding mode, and whether it overlaps the HA site, is not known [PMID:22216242]. Mouse pair is projected from human evidence.","key_references":[{"PMID":"22216242","why":"Only primary paper: direct binding, affinity and vimentin-dependent uptake"}],"covers":["LR001551","LR004940"]},"LR001556":{"pair":"VIP -> VIPR2","headline":"Established direct VIP agonist action at VPAC2, supported by many human recombinant binding and cAMP studies; shares VIP with VPAC1.","interaction_type":"direct binding","direction_and_effect":"VIP acts as an agonist at human VPAC2, binding and stimulating cAMP in CHO transfectants [PMID:16930633] [PMID:10801840]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"VPAC2 N-terminal residue E24A abolished 125I-VIP binding, with I31A and T274A reducing it [PMID:9454823]. C-terminal helical structure of ligands is needed for VIP2 recognition among related peptides [PMID:9928018].","affinity_potency":[{"value":"Ki 16 nM","assay":"competitive inhibition of 125I-VIP binding","system":"CHO transfectants, human VIPR2","cite":"PMID:9152366"},{"value":"pEC50 7.3","assay":"cAMP","system":"CHO cells, human VPAC2","cite":"PMID:16930633"},{"value":"pEC50 9.3","assay":"adenylyl cyclase stimulation","system":"cells expressing human VPAC2","cite":"PMID:10801840"}],"species_and_systems":"Human recombinant receptors in CHO and Cos cells; some papers also tested rat receptors [PMID:9437714].","localisation_and_range":"VIP is flagged secreted and VIPR2 transmembrane [flag].","caveats":"Most rows are analogue/selectivity studies using VIP as the reference, abstracts only. VIP binds VPAC1 and VPAC2 with similar potency, so it is not subtype-selective. Mouse pair is ortholog-inferred. Reactome and UniProt records also describe VIP receptors binding VIP [DB:Reactome R-HSA-420233] [DB:UniProt].","key_references":[{"PMID":"10801840","why":"Alanine scan of VIP on VPAC1 and VPAC2"},{"PMID":"9152366","why":"VIP Ki at VPAC2 in CHO transfectants"},{"PMID":"16930633","why":"VIP potency at VPAC2 in cAMP and calcium assays"}],"covers":["LR001556","LR004945"]},"LR003446":{"pair":"VSIR -> SELPLG","headline":"VISTA binds PSGL-1 in an acid-pH-dependent way, with histidines on the VISTA rim mediating binding; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"VISTA engages and suppresses T cells selectively at acidic pH; antibodies that block the VISTA-PSGL-1 interaction at acidic pH reversed VISTA-mediated immune suppression in vivo [PMID:31645726]. VISTA acts as the inhibitory partner on T cells.","molecular_requirements":"Multiple histidine residues along the rim of the VISTA extracellular domain mediate binding to PSGL-1 [PMID:31645726].","affinity_potency":[],"species_and_systems":"Human protein experiments; in vivo antibody reversal reported [PMID:31645726].","localisation_and_range":"Both are flagged non-secreted transmembrane [flag]; contact-dependent signalling is implied by flags only.","caveats":"No affinity value in this dossier. Binding is strongly pH-dependent, so measured affinity at neutral pH may differ; neutral-pH values not reported in our evidence. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"31645726","why":"Histidine-dependent, acid-pH VISTA binding to PSGL-1"}],"covers":["LR003446","LR006647"]},"LR007082":{"pair":"VTN -> ITGAV:ITGB3","headline":"Vitronectin acts through alphaVbeta3 in cell adhesion and in human monocytes; two functional abstract-level papers, no direct affinity.","interaction_type":"functional only","direction_and_effect":"Anti-beta3 and anti-CD47 antibodies suppressed vitronectin binding and function in human monocytes, but not fibronectin, and vitronectin is stated not to be a CD47 ligand [PMID:10037797]. In human ovarian cancer cells, alphaVbeta3-mediated adhesion to vitronectin down-regulated uPA and uPAR promoter and Rel activity and raised PAI-1 [PMID:11331280].","molecular_requirements":"The receptor is the alphaVbeta3 complex; both chains named. CD47 associates with it but is not the ligand receptor [PMID:10037797].","affinity_potency":[],"species_and_systems":"Human monocytes [PMID:10037797] and human ovarian cancer cells OV-MZ-6 [PMID:11331280]; both abstract-level.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Both papers are functional readouts, not binding assays. One further paper was review only. The CD47 paper concerns sCD23 signalling; its vitronectin statements are about antibody blockade [PMID:10037797].","key_references":[{"PMID":"10037797","why":"Antibodies to beta3 block vitronectin but not fibronectin binding in monocytes"},{"PMID":"11331280","why":"alphaVbeta3-vitronectin adhesion changes uPA and PAI-1 expression"}],"covers":["LR007082"]},"LR001565":{"pair":"VTN -> ITGB8","headline":"No paper supports this chain-only pair; Reactome assertion only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. Reactome lists vitronectin binding to alphaVbeta3, alphaVbeta5 and alphaVbeta8 [DB:Reactome].","molecular_requirements":"ITGB8 would act as alphaVbeta8 per Reactome [DB:Reactome]; not tested in our papers.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"All 6 judged abstracts were insufficient; no curator-verified paper. Support rests on database records [DB:Reactome].","key_references":[],"covers":["LR001565","LR004954"]},"LR006650":{"pair":"VWC2L -> CD36","headline":"VWC2L binds CD36 on transfected cells by flow cytometry in a CRISPRa screen paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Tetramerised VWC2L bound full-length CD36-transfected 293F cells by flow cytometry; the paper observed binding of LY6H, NRN1, VW2CL and SCRG1 to CD36 [PMID:36178190]. Agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"CD36 alone in transfected cells was sufficient for tetramer staining; other requirements are not reported in our evidence [PMID:36178190].","affinity_potency":[],"species_and_systems":"Human proteins; 400 nM SA-647 tetramers on 293F cells, n=3 [PMID:36178190]. The mouse pair is ortholog-inferred.","localisation_and_range":"VWC2L is flagged secreted and CD36 transmembrane [flag]; the paper calls the ligands secreted [PMID:36178190].","caveats":"Cell surface staining only, no SPR or Kd for this pair. CD36 is a multifunctional scavenger receptor binding several ligands, and VWC2L was one of several related hits [PMID:36178190].","key_references":[{"PMID":"36178190","why":"CRISPRa screen identified CD36 as VWC2L receptor; flow cytometry confirmation"}],"covers":["LR003449","LR006650"]},"LR008540":{"pair":"VWF -> GP1BA:GP1BB:GP5:GP9","headline":"No paper supports the four-chain complex as judged; it rests on database records mostly about GP1BA-VWF.","interaction_type":"database-asserted only","direction_and_effect":"Curated effect is stimulatory. Reactome lists GPIb:IX:V binding VWF multimer:collagen [DB:Reactome]. Structures show GP1BA with VWF [DB:PDB 1M10] [DB:PDB 1SQ0].","molecular_requirements":"The structural and interaction records are between GP1BA and VWF only [DB:BioGRID] [DB:IntAct], so the contribution of GP1BB, GP5 and GP9 is not shown in our evidence.","affinity_potency":[],"species_and_systems":"No curated paper; one review-only row was not used. Records are for human proteins.","localisation_and_range":"Not reported in our evidence.","caveats":"Support comes from databases alone; the complex membership is asserted, while binding evidence is for GP1BA.","key_references":[],"covers":["LR008540"]},"LR003455":{"pair":"VWF -> ITGB1","headline":"Only the VWF propolypeptide has been shown to support beta1 integrin (alpha4beta1, alpha9beta1) adhesion; functional only.","interaction_type":"functional only","direction_and_effect":"pp-vWF promoted cell adhesion through alpha9beta1 or alpha4beta1 in G-361 or MOLT-3 cells, blocked by anti-alpha9 or anti-alpha4 antibody [PMID:10816592].","molecular_requirements":"beta1 pairs with alpha4 or alpha9; the evidence is on alpha-chain antibody blocking, not beta1 alone [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human cells, G-361, MOLT-3 and SW480 transfectants [PMID:10816592]. Both pairs are ortholog-inferred.","localisation_and_range":"Beta1 is flagged non-secreted and a receptor [flag].","caveats":"Ligand is the propolypeptide, not mature VWF. Cell adhesion only; beta1-specific evidence is not reported in our evidence.","key_references":[{"PMID":"10816592","why":"pp-vWF supports alpha4beta1 and alpha9beta1 adhesion"}],"covers":["LR003455","LR006655"]},"LR010961":{"pair":"WIF1 -> WNT7A","headline":"WIF1-WNT7A rests on two IntAct SPR records; no verified paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"The interaction is annotated as inhibitory [DB:IntAct]; no verified paper describes the mechanism in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists two surface plasmon resonance records, with PMIDs 22986341 and 26342861 [DB:IntAct]; the species is not stated.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane; WIF1 is flagged non-receptor and non-transmembrane [flag].","caveats":"No curator-verified paper: other judged rows were different_entity or abstract_insufficient. The inhibitory label is annotation only. WIF1 is flagged as not a receptor [flag].","key_references":[{"PMID":"22986341","why":"IntAct SPR record (not curator-verified)"},{"PMID":"26342861","why":"IntAct SPR record (not curator-verified)"}],"covers":["LR010961"]},"LR010718":{"pair":"WNT1 -> FZD10:LRP6","headline":"WNT1 to FZD10:LRP6 rests on database records only (BioGRID, Reactome, UniProt); no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt]. BioGRID lists LRP6-WNT1 as a reconstituted complex [DB:BioGRID]. Reactome complexes use Frizzled-1, not FZD10 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Both judged rows are review_only. The FZD10 member is not covered by any listed record; the records concern LRP6-WNT1 or Frizzled-1 complexes.","key_references":[],"covers":["LR010718"]},"LR008117":{"pair":"WNT1 -> FZD1:LRP5","headline":"WNT1 to FZD1:LRP5 rests on database records only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states FZD1 is activated by WNT1, among others [DB:UniProt]. An LRP5 subunit note says its interaction is enhanced by WNT1 or WNT3A [DB:UniProt]. Reactome lists WNT:FZD complex records [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Both judged rows are review_only; no curator-verified paper. Records are generic WNT:FZD or LRP5 notes rather than a measured WNT1-FZD1-LRP5 complex.","key_references":[],"covers":["LR008117"]},"LR001574":{"pair":"WNT1 -> FZD5","headline":"WNT1 signals through FZD5 in a HEK293 reporter knockout-panel study; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Wnt1, Wnt8a, Wnt7b, Wnt8b and Wnt10a induced signalling via FZD5 and FZD8 in the FZD knockout reporter system [PMID:28733458]. The pair is annotated stimulatory.","molecular_requirements":"FZD5 and FZD8 are both named for Wnt1; whether either alone suffices is not reported in our evidence [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human HEK293 reporter cells with multiplex CRISPR FZD knockouts; the mouse pair is ortholog-inferred [PMID:28733458].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Functional readout only; no binding data. FZD8 is an alternative in the same statement.","key_references":[{"PMID":"28733458","why":"Wnt1 signals via FZD5 and FZD8 in knockout reporter cells"}],"covers":["LR001574","LR004963"]},"LR010682":{"pair":"WNT1 -> FZD6:LRP6","headline":"WNT1 to FZD6:LRP6 rests on database records only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt states LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt]; BioGRID lists a reconstituted LRP6-WNT1 complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Both judged rows are review_only. Reactome records are Wnt1:Frizzled1 complexes, not FZD6 [DB:Reactome].","key_references":[],"covers":["LR010682"]},"LR003464":{"pair":"WNT10A -> FZD10","headline":"WNT10A is implied as a FZD10 ligand by knockdown in lung mesenchymal cells; no binding data.","interaction_type":"functional only","direction_and_effect":"Fzd10 knockdown reduced Wnt7b- and Wnt10a-induced Wnt/beta-catenin activation, implying they may be Fzd10 ligands [PMID:29844390].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Lung-resident mesenchymal stem cells and bleomycin fibrosis model; the excerpts refer to mouse lung tissue, abstract plus excerpts [PMID:29844390]. The human pair is projected from mouse.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"The authors hedge ('may be the ligands'); binding is not shown.","key_references":[{"PMID":"29844390","why":"Fzd10 knockdown reduces Wnt10a signalling"}],"covers":["LR003464","LR006664"]},"LR005363":{"pair":"WNT10B -> FZD7","headline":"One abstract identifies FZD7 as the cognate WNT10B receptor for trophoblast migration; functional, human cells.","interaction_type":"functional only","direction_and_effect":"WNT10B signalling stimulated cytoskeletal remodelling via Rac1, and FZD7 was identified as the cognate receptor for WNT10B to up-regulate cell migration; SFRP3 blocks the FZD7-WNT10B interaction and decreases BeWo migration [PMID:29979633].","molecular_requirements":"Not reported in our evidence; LRP co-receptor not discussed.","affinity_potency":[],"species_and_systems":"Human BeWo and JAR trophoblast cells [PMID:29979633]; mouse entry is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; decidual cells secrete the antagonist SFRP3 acting in a paracrine way in coculture [PMID:29979633].","caveats":"Abstract only; how FZD7 was identified (binding or knockdown) is not reported in our evidence.","key_references":[{"PMID":"29979633","why":"FZD7 as cognate WNT10B receptor; SFRP3 blocks it"}],"covers":["LR002037","LR005363"]},"LR003473":{"pair":"WNT11 -> FZD5","headline":"WNT11 activation of FZD5 is supported functionally in cardiac fibroblasts; direct binding was not shown.","interaction_type":"functional only","direction_and_effect":"Recombinant Wnt11 increased FZD5 expression, ERK/p38 activation and EGFR phosphorylation in cardiac fibroblasts; si-FZD5 reversed Wnt11-induced fibrotic marker expression, so FZD5 mediates the effect (agonist direction annotated) [PMID:34564708].","molecular_requirements":"FZD5 crosstalk with EGFR was needed for the fibrotic response; whether Wnt11 binds FZD5 directly, or recruits EGFR, is stated as needing future study [PMID:34564708].","affinity_potency":[],"species_and_systems":"Neonatal rat cardiac fibroblasts treated with recombinant rat Wnt11, plus a mouse TAC pressure-overload model; the dossier labels species as human, and the human pair is ortholog-inferred [PMID:34564708].","localisation_and_range":"Wnt11 is flagged secreted [flag]; the paper shows Wnt11 secreted from cardiomyocytes and fibroblasts acting on fibroblasts [PMID:34564708].","caveats":"Authors note few studies report a Wnt11-FZD5 interaction [PMID:34564708]. No binding assay; no affinity.","key_references":[{"PMID":"34564708","why":"Si-FZD5 blocks Wnt11 pro-fibrotic effects in cardiac fibroblasts"}],"covers":["LR003473","LR006673"]},"LR001583":{"pair":"WNT2 -> FZD9","headline":"Functional evidence: only Wnt-2 among Wnts tested activated rat Frizzled-9 in TCF transcription in 293T cells.","interaction_type":"functional only","direction_and_effect":"Of several Wnt members transfected with Rfz9, only Wnt-2 activated Rfz9 in TCF-dependent transcription [PMID:12138115]. Deleting the Wnt-binding domain caused loss of Wnt-2-dependent TCF transcription [PMID:12138115].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat Frizzled-9 in 293T cells; the human and mouse pairs are projected from this by orthology [PMID:12138115].","localisation_and_range":"WNT2 is annotated as secreted [flag].","caveats":"Rat receptor, not human. No direct binding measured; abstract read only [PMID:12138115].","key_references":[{"PMID":"12138115","why":"Only Wnt-2 activated rat Fz9 in TCF reporter"}],"covers":["LR001583","LR004972"]},"LR008144":{"pair":"WNT2B -> FZD4:LRP5","headline":"No paper evidence; rests on UniProt notes about the WNT2B-FZD4 interaction.","interaction_type":"database-asserted only","direction_and_effect":"UniProt notes that TSKU competes with WNT2B for binding to FZD4, inhibiting Wnt signalling [DB:UniProt].","molecular_requirements":"Nothing reported on the complex or on LRP5 in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated; UniProt accession Q61088 is cited [DB:UniProt].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"No curator-verified paper; only database text, and it concerns TSKU competition, not LRP5 [DB:UniProt].","key_references":[],"covers":["LR008144"]},"LR010844":{"pair":"WNT2B -> FZD7:LRP6","headline":"Supported only through the FZD7 subunit; LRP6 not tested.","interaction_type":"direct binding","direction_and_effect":"Fzd7 binds Wnt2b by co-immunoprecipitation of epitope-tagged proteins in HEK293T cells, extending an earlier Wnt3 finding [PMID:25892522]. Conditional Fzd7 deletion causes intestinal stem cell loss in vivo [PMID:25892522].","molecular_requirements":"Evidence covers FZD7 only; LRP6 is not reported in the excerpts [PMID:25892522].","affinity_potency":[],"species_and_systems":"HEK293T co-IP and mouse knockouts [PMID:25892522].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Complex is inferred from the FZD7 result; no data on LRP6 [PMID:25892522].","key_references":[{"PMID":"25892522","why":"Fzd7 binds Wnt2b"}],"covers":["LR010844"]},"LR003482":{"pair":"WNT2B -> FZD8","headline":"Weak evidence: WNT2B transferred much less efficiently to FZD8-CRD than to FZD3/FZD6 in a preprint.","interaction_type":"direct binding","direction_and_effect":"WNT2B was much less efficiently transferred to FZD8-CRD than to FZD3-CRD and FZD6-CRD [PMID:39229119].","molecular_requirements":"Cysteine-rich domain was tested; carriers SFRP2 or GPC4 [PMID:39229119].","affinity_potency":[],"species_and_systems":"Purified human proteins [PMID:39229119].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"The paper presents FZD8 as a poor acceptor, so this reads as a weak or contrasting result rather than a clear pairing. Preprint, no affinity [PMID:39229119].","key_references":[{"PMID":"39229119","why":"FZD8-CRD is a poor acceptor for WNT2B"}],"covers":["LR003482"]},"LR008045":{"pair":"WNT3A -> FZD10:LRP6","headline":"No curated paper confirms this complex; support is limited to database records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for this complex.","molecular_requirements":"Receptor is a complex of FZD10 and LRP6.; whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our verified evidence. BioGRID lists LRP6-WNT3A Affinity Capture-Western [DB:BioGRID] [PMID:19910923]; IntAct lists co-immunoprecipitation and bio-layer interferometry records for an LRP6-WNT3A accession pair [DB:IntAct] [PMID:22726442] [PMID:21944579]; Reactome has a WNT3A:FZD:LRP5/6 complex [DB:Reactome].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"These records concern LRP6 and WNT3A, not FZD10 specifically. Only review articles or abstracts too thin to judge were found (outcome counts show review_only and abstract_insufficient), so no primary evidence is verified.","key_references":[],"covers":["LR008045"]},"LR003491":{"pair":"WNT3A -> FZD4","headline":"WNT3A activating FZD4 is supported by binding and functional papers; one cited binding is only from full text of a different study.","interaction_type":"direct binding","direction_and_effect":"WNT-3A activated the WNT-beta-catenin pathway (LRP6 phosphorylation, beta-catenin stabilization) through FZD4 in 32D cells [PMID:25605717]. FZD4-G protein complex dissociates on WNT-3A stimulation [PMID:27458145]. Wnt3/Wnt3a induced signaling via all FZDs in a CRISPR FZD-mutant system [PMID:28733458].","molecular_requirements":"Binding was to purified FZD cysteine-rich domains by bio-layer interferometry [PMID:25605717]. Canonical signaling involved LRP6 phosphorylation [PMID:25605717]; in HEK293T cells lacking FZD1,2,4,5,7,8, Wnt3 could not induce beta-catenin signaling [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in all papers; 32D cells [PMID:25605717], HEK293 cells [PMID:30304675, PMID:27458145], HEK293T CRISPR mutants [PMID:28733458]. Human and mouse versions of the pair are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"PMID:25605717 and PMID:27458145 were read as abstracts only. PMID:28733458 states the FZD finding generically across FZDs. In PMID:30304675 WNT3A binding to FZD4 was a positive control, not the study's focus. Affinity values for FZD4 are not given in our evidence.","key_references":[{"PMID":"25605717","why":"Binding mapping plus 32D cell canonical activation via FZD4"},{"PMID":"30304675","why":"WNT3A bound sFZD4-Fc and cell-surface SNAP-FZD4"},{"PMID":"28733458","why":"Functional FZD rescue map; Wnt3a signals via all FZDs"}],"covers":["LR003491","LR006691"]},"LR008081":{"pair":"WNT3A -> FZD6:LRP6","headline":"No curated paper for this complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"UniProt says LRP6 interacts via beta-propeller regions 3 and 4 with WNT3A [DB:UniProt]; FZD6 contribution comes only from the separate GtoPdb record [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records include BioGRID [DB:BioGRID], IntAct [DB:IntAct] and Reactome complexes with FZD unspecified [DB:Reactome]. Papers were review_only or abstract_insufficient.","key_references":[],"covers":["LR008081"]},"LR008090":{"pair":"WNT3A -> FZD7:LRP6","headline":"No curated paper for this complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"UniProt says LRP6 interacts via beta-propeller regions 3 and 4 with WNT3A [DB:UniProt]. FZD7 contribution rests on an IntAct record [DB:IntAct].","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Records include BioGRID [DB:BioGRID], IntAct including bio-layer interferometry [DB:IntAct] and Reactome complexes with FZD unspecified [DB:Reactome]. Papers were review_only.","key_references":[],"covers":["LR008090"]},"LR011276":{"pair":"WNT3A -> FZD9:LRP5","headline":"No curated paper for this complex; only UniProt notes.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Complex requirement is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Only UniProt subunit notes, which say an interaction is enhanced in the presence of GSK3B and WNT1 or WNT3A [DB:UniProt]; FZD9 is not addressed. Papers were review_only or abstract_insufficient.","key_references":[],"covers":["LR011276"]},"LR001592":{"pair":"WNT3A -> RYK","headline":"RYK acts as a Wnt co-receptor with Frizzled and is required for Wnt-3a induced neurite outgrowth; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Ryk is required for neurite outgrowth induced by Wnt-3a and activates the canonical pathway via Dishevelled; effect is stimulatory [PMID:15454084].","molecular_requirements":"Ryk works as a co-receptor along with Frizzled and binds Dishevelled [PMID:15454084].","affinity_potency":[],"species_and_systems":"Mouse DRG explants and Ryk siRNA transgenic mice; Wnt-3a conditioned medium [PMID:15454084]. Human pair is ortholog-inferred; mouse pair is direct.","localisation_and_range":"Not reported in our evidence beyond ligand flag as secreted [flag].","caveats":"Single paper; no direct binding of Wnt-3a to Ryk is reported in our evidence, and Ryk depends on Frizzled.","key_references":[{"PMID":"15454084","why":"Ryk as Wnt co-receptor needed for Wnt-3a neurite outgrowth"}],"covers":["LR001592","LR004981"]},"LR008162":{"pair":"WNT4 -> FZD6:LRP5","headline":"No curator-verified paper for the FZD6 plus LRP5 complex; only GtoPdb records for WNT4-FZD6.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists WNT4-FZD6 as an agonist interaction [DB:GtoPdb].","molecular_requirements":"The complex with LRP5 is not shown directly in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"All papers were review-only or abstract-insufficient. GtoPdb entries are for FZD6 alone, not the complex.","key_references":[],"covers":["LR008162"]},"LR006704":{"pair":"WNT5A -> APP","headline":"Wnt5a binds APP's cysteine-rich domain in one paper (co-IP) and drives its lysosomal targeting; single-study support.","interaction_type":"direct binding","direction_and_effect":"Wnt5a binds APP and promotes APP targeting to lysosomal compartments, reducing full-length APP levels, the opposite of Wnt3a, which promotes recycling and stability [PMID:34515635].","molecular_requirements":"The conserved extracellular cysteine-rich domain (CRD) of APP is required for Wnt binding; deleting it abrogates the effects [PMID:34515635]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-IP of Wnt5a-myc with human APP-flag and mouse APP-flag, with reciprocal co-IP, in transfected cells; trafficking and Bafilomycin-A rescue in mouse embryonic primary cortical neurons [PMID:34515635]. Fly APPL also binds Wnt5 in the same paper.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation. APP is annotated as transmembrane and secreted [flag].","caveats":"Only one paper supports this pair, and the curator read it as abstract only, though full-text excerpts were available. No affinity is reported. The binding experiments are co-IP of tagged, overexpressed proteins.","key_references":[{"PMID":"34515635","why":"Co-IP shows Wnt5a binds APP via its CRD; opposite trafficking outcome to Wnt3a"}],"covers":["LR003504","LR006704"]},"LR008054":{"pair":"WNT5A -> FZD2:LRP6","headline":"No paper-level evidence for WNT5A with the FZD2:LRP6 complex; only database records on single chains.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no confirmed paper for this complex. BioGRID records FZD2 - WNT5A and LRP6 - WNT5A Affinity Capture-Western [DB:BioGRID]; Reactome lists WNT5A binding FZD and ROR receptors [DB:Reactome].","molecular_requirements":"The complex combines FZD2 and LRP6; the database records concern individual chains, not the assembled complex. ","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone. Curators judged only review-only or abstract-insufficient papers, with none confirmed. A single-chain record does not show that both subunits are needed.","key_references":[],"covers":["LR008054"]},"LR003509":{"pair":"WNT5A -> TLR4","headline":"WNT5A binds TLR4 directly (SPR, pulldown, co-localisation) and signals through it; one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Wnt5a acts as a TLR4 ligand; TNF-alpha induction in mouse cells was entirely TLR4-dependent, and in human cells IL-10 induction relied on TLR2/4-MyD88 [PMID:31098409].","molecular_requirements":"Signalling is MyD88-dependent in part (partially in mouse); TLR4 with MD2 was also tested by SPR [PMID:31098409]. Need for other subunits: not reported in our evidence.","affinity_potency":[{"value":"KD ~27 nM","assay":"SPR, saturable binding, as stated in the text (TLR4/MD2 ~45 nM)","system":"recombinant proteins","cite":"PMID:31098409"}],"species_and_systems":"Human and mouse myeloid cells; Wnt5a and hTLR4-GFP co-localised and capped in NIH3T3 cells [PMID:31098409].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Single paper curated from the abstract. Wnt5a effects are opposite in species: pro-inflammatory in mouse, anti-inflammatory in human myeloid cells [PMID:31098409]. Polymyxin B blocked part of the response but TLR-blocking antibodies did not, so the binding mode differs from LPS [PMID:31098409].","key_references":[{"PMID":"31098409","why":"SPR, pulldown, co-localisation and species-divergent signalling"}],"covers":["LR003509","LR006709"]},"LR005372":{"pair":"WNT5B -> FZD2","headline":"WNT5B binds the FZD2 CRD weakly in vitro, but FZD2 mediates WNT-5B-induced CXCL8 in human lung fibroblasts.","interaction_type":"direct binding","direction_and_effect":"Stimulatory: WNT-5B-induced CXCL8 release was mediated primarily via Frizzled-2 and TAK1, independent of canonical beta-catenin signalling [PMID:27036869].","molecular_requirements":"Only FZD2 and TAK1 are named; LRP co-receptor need not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc, weak binding","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Binding with mouse proteins [PMID:25605717]; function in human lung fibroblasts (MRC-5, COPD and control primary cells) with recombinant WNT-5B [PMID:27036869].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding is weak (KD > 40 nm) yet function is clear in fibroblasts, and the functional paper was curated from the abstract only [PMID:25605717, PMID:27036869].","key_references":[{"PMID":"25605717","why":"FZD2 CRD binding by WNT-5B"},{"PMID":"27036869","why":"FZD2-dependent WNT-5B signalling in human lung fibroblasts"}],"covers":["LR002046","LR005372"]},"LR006713":{"pair":"WNT5B -> FZD4","headline":"WNT5B binds the FZD4 CRD only weakly in a single BLI mapping study.","interaction_type":"direct binding","direction_and_effect":"Binding only: WNT-5B showed weak binding (KD > 40 nm) to FZD1/2/4 CRDs [PMID:25605717].","molecular_requirements":"CRD only; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read.","key_references":[{"PMID":"25605717","why":"BLI mapping of WNT-FZD CRD binding"}],"covers":["LR003513","LR006713"]},"LR008171":{"pair":"WNT5B -> FZD8:LRP5","headline":"Only a FZD8 docking study exists; LRP5 is not addressed.","interaction_type":"computational prediction only","direction_and_effect":"Direction not reported; docking of hWnt5b to hFzd isoforms gave the highest binding affinity with hFzd8 [PMID:31285641].","molecular_requirements":"FZD8 only is addressed; LRP5 requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human homology models, docking only [PMID:31285641].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Computational and abstract only; no measured affinity in our evidence. Others were review-only or insufficient.","key_references":[{"PMID":"31285641","why":"docking of hWnt5b against hFzd isoforms"}],"covers":["LR008171"]},"LR012455":{"pair":"WNT6 -> FZD1","headline":"No verified paper; the only database line says FZD1 is apparently not activated by WNT6.","interaction_type":"database-asserted only","direction_and_effect":"Direction not reported. UniProt says FZD1 is apparently not activated by WNT6 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"No paper confirmed the pair; the sole database record is a negative statement [DB:UniProt].","key_references":[],"covers":["LR012455"]},"LR003518":{"pair":"WNT6 -> LRP6","headline":"Functional support only: anti-LRP6 antibody blockade inhibits WNT6 signalling; no direct WNT6 binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Wnt1-specific anti-LRP6 Fab fragments inhibited signalling by a class of Wnt proteins that includes Wnt6, in a SuperTopFlash reporter assay [PMID:20713706]. LRP6 acts as a Wnt co-receptor and the antibodies bind its first propeller [PMID:20713706].","molecular_requirements":"Wnt6 is inferred to depend on LRP6 propeller 1, from antibody blockade; whether other receptor chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells (HEK293 reporter assay); the mouse pair is projected from human evidence [PMID:20713706].","localisation_and_range":"WNT6 is flagged secreted and LRP6 transmembrane [flag]; a secreted ligand acting on a membrane receptor.","caveats":"Evidence is indirect (antibody inhibition, not binding of WNT6 to LRP6); the curator row was read in a browser and the quote is unverified; the dossier holds one paper.","key_references":[{"PMID":"20713706","why":"Anti-LRP6 antibodies block Wnt6-class signalling"}],"covers":["LR003518","LR006718"]},"LR008018":{"pair":"WNT7A -> ADGRA2:FZD5:LRP5:RECK","headline":"Only the RECK-WNT7 half of this four-chain complex is supported, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Gpr124 and Reck enable brain endothelial cells to respond selectively to Wnt7, an agonist effect [PMID:30026314]. Reck-bound Wnt7 is made available to Frizzled signalling via Gpr124-Dishevelled, which recruits Wnt7 into Wnt/Frizzled/Lrp5/6 signalosomes [PMID:30026314].","molecular_requirements":"Complex-level: the abstract-only paper shows Reck binds the Wnt7 linker region and Gpr124 plus Reck confer Wnt7 selectivity; FZD5 and the LRP5 co-receptor are not named in the abstract [PMID:30026314]. PDB 8TZP holds a structure with chains of O00755 and O95980 [DB:PDB 8TZP].","affinity_potency":[{"value":"low micromolar","assay":"Reck binding to the Wnt7 linker region (abstract)","system":"brain endothelial cells","cite":"PMID:30026314"}],"species_and_systems":"Human proteins and brain endothelial cells per the curator row [PMID:30026314].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; ADGRA2 and LRP5 are flagged transmembrane [flag]; signalling is cell-surface.","caveats":"Abstract only. FZD5 and LRP5 are not shown as bound; UniProt notes ADGRA2 interacts with FZD5-related partners and RECK selectivity for Wnt7 [DB:UniProt]. A complex needs all four chains to be expressed.","key_references":[{"PMID":"30026314","why":"Reck binds Wnt7 with low micromolar affinity; Gpr124:Reck decode Wnt7"}],"covers":["LR008018"]},"LR006722":{"pair":"WNT7A -> FZD7","headline":"WNT7A C-terminal linker binds FZD7 in one abstract-only study.","interaction_type":"direct binding","direction_and_effect":"The linker region in WNT7A's C-terminus binds the FZD7 receptor but does not activate non-canonical signalling; the hairpin region does [PMID:36420144]. Both regions can activate canonical signalling [PMID:36420144].","molecular_requirements":"Binding maps to the WNT7A linker region; the hairpin drives non-canonical output [PMID:36420144].","affinity_potency":[],"species_and_systems":"Human proteins per curator row; myogenic cells [PMID:36420144]. Mouse pair projected.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; FZD7 is the receptor in skeletal muscle per the paper background [PMID:36420144].","caveats":"Abstract only; the binding is of a WNT7A fragment, not full-length. Two other abstracts were insufficient.","key_references":[{"PMID":"36420144","why":"WNT7A linker binds FZD7"}],"covers":["LR003522","LR006722"]},"LR008036":{"pair":"WNT7B -> FZD1:LRP6","headline":"WNT7B-FZD1:LRP6 is supported only by a FZD1/LRP5 abstract and a conflicting UniProt note.","interaction_type":"conflicting","direction_and_effect":"Wnt7b bound Fzd1 on the cell surface and cooperatively activated canonical signalling with LRP5 [PMID:15923619]. UniProt says FZD1 is apparently not activated by WNT7B [DB:UniProt].","molecular_requirements":"The paper names LRP5, not LRP6 [PMID:15923619].","affinity_potency":[],"species_and_systems":"Cell-surface binding assay; species not stated in this row [PMID:15923619].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only; LRP6 untested in cited paper; conflicting UniProt statement.","key_references":[{"PMID":"15923619","why":"Wnt7b-Fzd1 binding, LRP5 cooperation"}],"covers":["LR008036"]},"LR001619":{"pair":"WNT7B -> LRP5","headline":"WNT7B requires LRP5 as co-receptor for canonical signalling with Fzd1/Fzd10; LRP5 effect shown functionally, not by direct binding.","interaction_type":"functional only","direction_and_effect":"Wnt7b activates canonical Wnt signalling cooperatively with Fzd1 and Fzd10 in the presence of LRP5 (agonist, stimulatory) [PMID:15923619].","molecular_requirements":"LRP5 acts as a required co-receptor with Fzd1/Fzd10. LRP5 but not LRP6 expression is seen in vascular smooth muscle including the aorta, while both are expressed in airway epithelium [PMID:15923619].","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in transfected cells; expression analysis in developing lung and vasculature [PMID:15923619].","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Abstract only. Direct binding was shown for Fzd1 and Fzd10, not for LRP5; the LRP5 role is inferred from co-receptor function [PMID:15923619]. Two further judged papers were abstract_insufficient.","key_references":[{"PMID":"15923619","why":"Wnt7b signals via Fzd1/Fzd10 with LRP5 co-receptor"}],"covers":["LR001619","LR005008"]},"LR005381":{"pair":"WNT8A -> FZD8","headline":"WNT8A induces signalling via FZD8 (and FZD5) in a FZD-knockout reporter map; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 [PMID:28733458]; it acts through a restricted set of FZD genes [PMID:28733458].","molecular_requirements":"FZD8 alone sufficed in the rescue setup; co-receptor need is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in HEK293 reporter cells with FZD knockouts [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map in HEK293 cells; promiscuous FZD5/FZD8 (about 70% homology) may be redundant [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR002055","LR005381"]},"LR006731":{"pair":"WNT8A -> LRP6","headline":"WNT8A-LRP6 has two papers: Xenopus competition binding with Wise (Wnt8 not resolved to a paralog) and a neuron pull-down.","interaction_type":"direct binding","direction_and_effect":"Wise physically interacts with LRP6 and competes with Wnt8 for LRP6 binding [PMID:12900447]. In neurons, endogenous LRP6 was pulled down in Wnt8A-myc transfected cells but not mock cells (data not shown); Wnt8A promotes synaptogenesis via LRP6 [PMID:24316074].","molecular_requirements":"LRP6 acts as co-receptor for canonical Wnt ligands [PMID:24316074]; Frizzled requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus for [PMID:12900447]; HEK cells and dissociated neuron cultures for [PMID:24316074]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"[PMID:12900447] is abstract-only and refers to 'Wnt8' generically, so paralog identity is unresolved. The pull-down in [PMID:24316074] is 'data not shown', background to a synapse study. Three further papers were abstract_insufficient.","key_references":[{"PMID":"12900447","why":"Wise competes with Wnt8 for LRP6 binding"},{"PMID":"24316074","why":"Wnt8A pulls down LRP6 and promotes synaptogenesis via LRP6"}],"covers":["LR003531","LR006731"]},"LR008072":{"pair":"WNT8B -> FZD5:LRP6","headline":"WNT8B activates FZD5 signalling in a reporter-cell rescue map; one functional paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT8B induced canonical (TCF/Wnt-reporter) signalling via FZD5, i.e. ligand-to-receptor agonism in a functional readout [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD5 plus LRP6; the paper's statement names only the Frizzled, and a requirement for LRP6 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008072"]},"LR006740":{"pair":"WNT9A -> FZD8","headline":"WNT9A-FZD8 is supported by a single prostate-cancer abstract; binding is stated but not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Castration enhanced FZD8 binding to Wnt9A and mediated cellular plasticity by activating the non-canonical Wnt (FZD8/FYN/STAT3) pathway [PMID:37771187].","molecular_requirements":"Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Prostate cancer cells (species not stated in the abstract) [PMID:37771187]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Abstract only; the binding assay is not described. The effect is non-canonical signalling after YY1-driven FZD8 transcription, so the evidence is context-specific. A second judged row was abstract_insufficient.","key_references":[{"PMID":"37771187","why":"Reports enhanced FZD8-Wnt9A binding and FZD8/FYN/STAT3 signalling in prostate cancer cells."}],"covers":["LR003540","LR006740"]},"LR008126":{"pair":"WNT9B -> FZD10:LRP5","headline":"Complex rests on a single functional reporter study of WNT9B with FZD10; the LRP5 co-receptor was not tested.","interaction_type":"functional only","direction_and_effect":"WNT9B induced canonical signalling with FZD10 in a FZD rescue reporter map; effect is activating (canonical) [PMID:28733458].","molecular_requirements":"The cited study tested FZD receptors in rescue assays and does not report LRP5 as a tested subunit of this complex in our excerpts; the complex is a combination of the pair FZD10 and LRP5 not evaluated as a unit.","affinity_potency":[],"species_and_systems":"Human reporter cells, HEK293 FZD multiplex-knockout panel with rescue; full text read [PMID:28733458].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Evidence is for the Frizzled chain alone; LRP5 is not shown to be required. Functional readout only, no binding measured. Other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR008126"]},"LR003545":{"pair":"WNT9B -> FZD6","headline":"WNT9B changes FZD6 membrane mobility in a FRAP assay; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-9B, along with WNT-1, -2, 3A, -4, -5A, -7A and -10B, affected FZD6 surface mobility and thus acts on this receptor; curators label it agonist [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility relate to putative precoupling to Gi/o proteins (sensitive to pertussis toxin and NEM); no co-receptor reported for WNT9B here [PMID:24873871].","affinity_potency":[],"species_and_systems":"HEK293T/17 cells expressing FZD6-GFP, recombinant human WNT proteins; mouse pair is ortholog-inferred [PMID:24873871].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"FRAP mobility is an indirect readout of interaction, not binding or signalling output; no affinity or potency reported for WNT9B.","key_references":[{"PMID":"24873871","why":"FRAP assay showing WNT-9B effects on FZD6 mobility"}],"covers":["LR003545","LR006745"]},"LR008180":{"pair":"WNT9B -> FZD8:LRP5","headline":"Complex rests on a single functional reporter study of WNT9B with FZD8; the LRP5 co-receptor was not tested.","interaction_type":"functional only","direction_and_effect":"WNT9B induced canonical signalling with FZD8 in a FZD rescue reporter map; effect is activating (canonical) [PMID:28733458].","molecular_requirements":"The cited study tested FZD receptors in rescue assays and does not report LRP5 as a tested subunit of this complex in our excerpts; the complex is a combination of the pair FZD8 and LRP5 not evaluated as a unit.","affinity_potency":[],"species_and_systems":"Human reporter cells, HEK293 FZD multiplex-knockout panel with rescue; full text read [PMID:28733458].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Evidence is for the Frizzled chain alone; LRP5 is not shown to be required. Functional readout only, no binding measured. Other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR008180"]},"LR012365":{"pair":"ZNRF3 -> FZD10:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD10 partner is not named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012365"]},"LR012149":{"pair":"ZNRF3 -> FZD5:LRP5","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; BioGRID records FZD5 - ZNRF3: Proximity Label-MS [DB:BioGRID]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD5 partner is named in the UniProt statement; LRP5 evidence is limited to the UniProt statement or absent [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012149"]},"LR004085":{"pair":"FGF21 -> FGFR4","headline":"Single functional mitogenesis study shows FGF21 activity on FGFR4-expressing cells; no direct binding or database support in our evidence.","interaction_type":"functional only","direction_and_effect":"Stimulatory: FGFs 19, 21 and 23 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 in a BaF3 mitogenic assay [PMID:16597617].","molecular_requirements":"Not reported in our evidence for FGF21 specifically; the paper notes FGF signalling is modulated by cofactors such as heparan sulfate proteoglycans [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cell lines engineered to express FGFRs; ligand and receptor species unspecified [PMID:16597617]. A mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"The readout is mitogenic activity, not binding; the abstract describes it as a semiquantitative receptor-specificity readout. One paper only, and no database records.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenesis map of FGF receptor specificity"}],"covers":["LR000601","LR004085"]},"LR004238":{"pair":"IAPP -> RAMP1","headline":"Amylin acts as an agonist at RAMP1-containing amylin receptors; supported by two abstract-read papers plus databases.","interaction_type":"direct binding","direction_and_effect":"Rat amylin binding was induced by cotransfecting RAMP1 with the human calcitonin receptor in COS-7 cells [PMID:10385705]. Human and rat amylin activate the calcitonin receptor alone and the AMY complexes, measured by cAMP [PMID:24169554]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"RAMP1 does not act alone: it pairs with the calcitonin receptor (CALCR) to form the AMY1 complex [PMID:10385705][PMID:24169554][DB:UniProt]. A CCC score should include CALCR.","affinity_potency":[],"species_and_systems":"COS-7 and HEK293S cells; recombinant human calcitonin receptor with rat amylin radioligand [PMID:10385705][PMID:24169554]. Mouse pair is projected from human evidence.","localisation_and_range":"Amylin is annotated as secreted [flag]; RAMP1 is a receptor component [flag].","caveats":"Both papers were read as abstracts only. GtoPdb potency values are database-reported and not quoted here. The binding paper also shows a second paper-level abstract was insufficient. Structures with both chains exist (e.g. PDB 9BLW) [DB:PDB 9BLW].","key_references":[{"PMID":"10385705","why":"RAMP1 or RAMP3 with CT receptor induces amylin binding"},{"PMID":"24169554","why":"Amylin activates calcitonin receptor and AMY1-3 complexes by cAMP"}],"covers":["LR000780","LR004238"]}};